-- بيانات مقرر كيمياء 1 (المقرر 2، قيد الإعداد) — الجزء 2 من 5. نفّذ الأجزاء بالترتيب.
-- مولّد آليًا بواسطة scripts/build-chem1-seed.js — لا تعدّله يدويًا.
begin;
insert into public.questions (objective_id, type, number, stem, stimulus, options, thinking_level, question_kind, difficulty, source_ref, status, origin)
select (select id from public.objectives where code = 'K1-C1-L4-O02'), v.type, v.number, v.stem, v.stimulus::jsonb, v.options::jsonb, v.tl, v.qk, v.diff, v.src, 'generated', 'ai_generated'
from (values
('mcq', 1, 'أراد طالب تحضير محلول مخفف من حمض في المختبر. ما الإجراء الصحيح؟', null, '["إضافة الماء إلى الحمض دفعة واحدة","صب الحمض والماء معًا في الكأس بسرعة","إضافة الحمض إلى الماء ببطء","إضافة الماء إلى الحمض ببطء"]'::jsonb, 'تطبيق', 'تطبيق قاعدة سلامة', 'سهل', 'الكتاب ص 29 — الجدول 1-2 (بند 22)'),
('mcq', 2, 'في ما يأتي ما يلبسه أربعة طلاب عند دخول المختبر. أيّ الطلاب التزم بتعليمات السلامة الخاصة باللباس؟', '{"headers":["الطالب","ما يلبسه"],"rows":[["أحمد","معطف مختبر، نظارة واقية، حذاء مغلق الأصابع"],["خالد","معطف مختبر، نظارة واقية، صندل مفتوح"],["فهد","معطف مختبر، عدسات لاصقة تحت النظارة الواقية، حذاء مغلق الأصابع"],["ماجد","معطف مختبر، نظارة واقية، حذاء مغلق الأصابع، شماغ متدلٍّ"]]}'::jsonb, '["أحمد","خالد","فهد","ماجد"]'::jsonb, 'تحليل', 'تحليل مواقف', 'متوسط', 'الكتاب ص 29 — الجدول 1-2 (بنود 4، 5، 6)'),
('mcq', 3, 'أخذ طالب من عبوة كمية أكبر مما يحتاج إليه في تجربته. ماذا يفعل بالمتبقي؟', null, '["يعيده إلى العبوة الأصلية ليحافظ على نظافة المكان","يصبه في عبوة مادة أخرى","يتركه في الكأس على طاولة العمل","يتخلص منه كما يطلب المعلم"]'::jsonb, 'تطبيق', 'تطبيق قاعدة سلامة', 'متوسط', 'الكتاب ص 29 — الجدول 1-2 (بنود 12، 13، 21)'),
('mcq', 4, 'متى يجب على الطالب قراءة بطاقة عبوة المادة الكيميائية؟', null, '["مرة واحدة قبل فتح العبوة فقط","قبل حمل العبوة وفي أثنائه وبعد إرجاعها إلى مكانها","بعد الانتهاء من التجربة فقط","عند أول استعمال للمادة فقط"]'::jsonb, 'تذكر', 'تذكر إجراء', 'سهل', 'الكتاب ص 29 — الجدول 1-2 (بند 11)'),
('mcq', 5, 'عند تسخين مادة في أنبوب اختبار، كيف يوجّه الطالب فوهة الأنبوب؟', null, '["بعيدًا عن جسمه وعن أي شخص آخر، دون النظر في فوهته","نحو جسمه قليلًا ليتمكن من رؤية محتواه","نحو زميله بعد تحذيره","نحو الأعلى مع النظر في فوهته ليراقب التسخين"]'::jsonb, 'تطبيق', 'تطبيق قاعدة سلامة', 'سهل', 'الكتاب ص 29 — الجدول 1-2 (بند 18)'),
('mcq', 6, 'لامست مادة كيميائية جلد طالب أثناء التجربة. ما الإجراء الصحيح؟', null, '["تجفيف الجلد بمنديل ثم متابعة التجربة","الانتظار حتى نهاية الحصة قبل إخبار المعلم","غسل الجلد بكميات كبيرة من الماء وإخبار المعلم عن طبيعة المادة","غسل الجلد بقليل من الماء ثم متابعة العمل"]'::jsonb, 'تطبيق', 'تطبيق إجراء طارئ', 'متوسط', 'الكتاب ص 29 — الجدول 1-2 (بند 10)'),
('mcq', 7, 'لماذا لا يجوز لبس العدسات اللاصقة في المختبر حتى تحت النظارة الواقية؟', null, '["لأنها تعيق رؤية ألوان المحاليل","لأنها قد تمتص الأبخرة ويصعب إزالتها","لأن النظارة الواقية لا تتسع لها","لأنها تتفاعل مع الزجاج الساخن"]'::jsonb, 'فهم', 'تعليل قاعدة سلامة', 'متوسط', 'الكتاب ص 29 — الجدول 1-2 (بند 5)'),
('essay', 1, 'تتطلب خطوات تجربة تحضير محلول إضافة حجمين من الحمض إلى حجم واحد من الماء، وبدأ طالب بـ 30 mL من الماء. احسب حجم الحمض اللازم، ثم صف كيف يضيفه، واذكر قطعتين من تجهيزات السلامة التي يجب أن يلبسهما.', null, null, 'تطبيق', 'حساب مع تطبيق إجراء سلامة', 'متوسط', 'الكتاب ص 39 — سؤال 43، ص 29 — الجدول 1-2 (بنود 4، 22)'),
('essay', 2, 'دخل طالب المختبر وهو يحمل شطيرة ويلبس عدسات لاصقة، وبدأ العمل بمفرده دون إذن المعلم، وبعد أن أخذ كمية زائدة من مادة كيميائية أعادها إلى العبوة الأصلية. حدّد أربعة من هذه التصرفات الخاطئة وبيّن الإجراء الصحيح في كل حالة.', null, null, 'تطبيق', 'تحليل مواقف مخالفة للسلامة', 'صعب', 'الكتاب ص 29 — الجدول 1-2 (بنود 2، 5، 7، 13)'),
('essay', 3, 'لخّص السبب وراء كل مما يأتي في المختبر: (أ) لبس المعطف والنظارة الواقية. (ب) عدم إعادة المواد الكيميائية غير المستعملة إلى العبوة الأصلية. (ج) عدم لبس العدسات اللاصقة. (د) عدم لبس ملابس فضفاضة أو أشياء متدلية مثل الشماغ.', null, null, 'تطبيق', 'تعليل قواعد السلامة', 'متوسط', 'الكتاب ص 33 — سؤال 23، ص 29')
) as v(type, number, stem, stimulus, options, tl, qk, diff, src)
where not exists (select 1 from public.questions x where x.objective_id = (select id from public.objectives where code = 'K1-C1-L4-O02') and x.type = v.type and x.number = v.number);
insert into public.question_answers (question_id, correct_index, explanation, distractor_notes, model_answer, answer_elements, solution_steps, marks, rubric, common_errors, auto_check)
select x.id, v.ci::int, v.ex::text, v.dn::jsonb, v.ma::text, v.ae::jsonb, v.ss::jsonb, v.mk::jsonb, v.rb::jsonb, v.ce::jsonb, v.ac::jsonb
from (values
('mcq', 1, 2, 'عند تحضير محاليل الأحماض يُضاف الحمض دائمًا إلى الماء ببطء؛ فالإجراء الصحيح هو «إضافة الحمض إلى الماء ببطء».', '["إضافة الماء إلى الحمض ترتيب خاطئ، ودفعة واحدة تزيد الخطر.","الصب السريع معًا لا يتيح التحكم في العملية ويعرّض الطالب للخطر.","","الترتيب في هذا البديل معكوس؛ فالصحيح إضافة الحمض إلى الماء."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (20%)"}],"at":"2026-10-18T03:32:48.142Z"}'::jsonb),
('mcq', 2, 0, 'أحمد لبس معطف المختبر والنظارة الواقية وحذاءً مغلق الأصابع، وهذا ما تقتضيه تعليمات السلامة؛ فالطالب الملتزم هو أحمد.', '["","خالد لبس صندلًا مفتوحًا، والمطلوب حذاء مغلق الأصابع.","فهد لبس عدسات لاصقة، وهي ممنوعة في المختبر حتى تحت النظارة لأنها قد تمتص الأبخرة.","ماجد لبس شماغًا متدليًا، وتُمنع الأشياء المتدلية والملابس الفضفاضة في المختبر."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (5%)"}],"at":"2026-10-18T03:32:48.142Z"}'::jsonb),
('mcq', 3, 3, 'لا تُعاد المواد غير المستعملة إلى العبوة الأصلية لئلا تتلوث، وإنما يُتخلص منها بالطريقة التي يحددها المعلم؛ فالإجراء الصحيح هو «يتخلص منه كما يطلب المعلم».', '["إعادة المتبقي إلى العبوة الأصلية قد تلوث المادة الأصلية، فهي ممنوعة.","صب المادة في عبوة أخرى قد يسبب تفاعلات خطرة وتلوثًا.","ترك المادة على الطاولة دون تخلص منها يعرّض الآخرين للخطر.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (7%)"}],"at":"2026-10-18T03:32:48.142Z"}'::jsonb),
('mcq', 4, 1, 'تُقرأ البطاقة ثلاث مرات: قبل حمل العبوة، وفي أثناء حملها، وبعد إرجاعها إلى مكانها؛ فالصحيح «قبل حمل العبوة وفي أثنائه وبعد إرجاعها إلى مكانها».', '["القراءة مرة واحدة لا تكفي؛ فالمطلوب قراءتها ثلاث مرات.","","القراءة بعد التجربة فقط تفوّت فرصة معرفة الخطر قبل التعامل مع المادة.","القراءة عند أول استعمال فقط لا تحقق الاحتياط المطلوب في كل مرة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (6%)"}],"at":"2026-10-18T03:32:48.142Z"}'::jsonb),
('mcq', 5, 0, 'قد تتطاير المادة الساخنة من الأنبوب، لذا توجَّه فوهته بعيدًا عن الجسم وعن الآخرين ولا يُنظر فيها؛ فالإجراء الصحيح هو «بعيدًا عن جسمه وعن أي شخص آخر، دون النظر في فوهته».', '["","توجيه الفوهة نحو الجسم يعرّضه لتطاير المادة الساخنة.","توجيه الفوهة إلى شخص آخر خطر عليه حتى بعد تحذيره.","النظر في فوهة الأنبوب أثناء التسخين خطر على العينين والوجه."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (6%)"}],"at":"2026-10-18T03:32:48.143Z"}'::jsonb),
('mcq', 6, 2, 'عند ملامسة مادة كيميائية للجلد تُغسل المنطقة بكميات كبيرة من الماء ويُخبَر المعلم عن طبيعة المادة؛ فالإجراء الصحيح هو «غسل الجلد بكميات كبيرة من الماء وإخبار المعلم عن طبيعة المادة».', '["التجفيف بالمنديل لا يزيل المادة، وقد يُبقيها على الجلد.","تأخير إبلاغ المعلم يؤخر الإسعاف المناسب لطبيعة المادة.","","الغسل بقليل من الماء لا يكفي لإزالة المادة، والمطلوب كميات كبيرة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (20%)"}],"at":"2026-10-18T03:32:48.143Z"}'::jsonb),
('mcq', 7, 1, 'العدسات اللاصقة قد تمتص الأبخرة الكيميائية ويصعب إزالتها، لذلك لا تُلبس في المختبر حتى تحت النظارة الواقية.', '["لا علاقة للعدسات بتمييز ألوان المحاليل، وليس هذا سبب المنع.","","السبب ليس ضيق النظارة، فالنظارة لا تمنع الأبخرة من الوصول إلى العدسة.","العدسات لا تتفاعل مع الزجاج الساخن؛ والخطر في امتصاصها الأبخرة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (15%)"}],"at":"2026-10-18T03:32:48.143Z"}'::jsonb),
('essay', 1, null::int, null, null, 'النسبة حجمان من الحمض لكل حجم من الماء، فحجم الحمض = 2 × 30 mL = 60 mL. يُضاف الحمض إلى الماء ببطء (وليس العكس). ويجب أن يلبس الطالب نظارة واقية ومعطف مختبر (ويمكن إضافة القفازات).', '["حجم الحمض = 60 mL","إضافة الحمض إلى الماء ببطء","نظارة واقية","معطف مختبر أو قفازات"]'::jsonb, '["النسبة 2 : 1 (حمض : ماء)","حجم الحمض = 2 × 30 mL = 60 mL","يُضاف الحمض إلى الماء ببطء"]'::jsonb, '[{"element":"حساب حجم الحمض 60 mL","marks":2},{"element":"إضافة الحمض إلى الماء ببطء","marks":1},{"element":"تجهيزان للسلامة (درجة لكل تجهيز)","marks":2}]'::jsonb, '[{"level":"5 درجات","description":"حساب صحيح وطريقة إضافة صحيحة وتجهيزان صحيحان"},{"level":"3–4 درجات","description":"حساب صحيح مع نقص في الطريقة أو التجهيزات"},{"level":"1–2 درجة","description":"جزء صحيح فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["إضافة الماء إلى الحمض","حساب الحجم 15 mL بقسمة 30 على 2","الاكتفاء بتجهيز واحد للسلامة"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (9%)"}],"at":"2026-10-18T03:32:48.144Z"}'::jsonb),
('essay', 2, null::int, null, null, '1) إدخال الطعام إلى المختبر خطأ؛ والصحيح عدم إدخال الطعام والشراب ولا الأكل فيه أبدًا. 2) لبس العدسات اللاصقة خطأ؛ والصحيح عدم لبسها حتى تحت النظارة لأنها قد تمتص الأبخرة. 3) العمل بمفرده ودون إذن خطأ؛ والصحيح عدم إجراء التجارب دون إذن المعلم وعدم العمل بمفرده أبدًا. 4) إعادة المادة إلى العبوة الأصلية خطأ؛ والصحيح عدم إعادة المواد غير المستعملة إليها، والتخلص منها كما يطلب المعلم، وأخذ كميات قليلة فقط.', '["الطعام: عدم إدخاله","العدسات: عدم لبسها","العمل بمفرده ودون إذن: يمنع","إعادة المادة إلى العبوة: تمنع"]'::jsonb, '[]'::jsonb, '[{"element":"تحديد الخطأ الأول مع الإجراء الصحيح","marks":1.5},{"element":"تحديد الخطأ الثاني مع الإجراء الصحيح","marks":1.5},{"element":"تحديد الخطأ الثالث مع الإجراء الصحيح","marks":1.5},{"element":"تحديد الخطأ الرابع مع الإجراء الصحيح","marks":1.5}]'::jsonb, '[{"level":"6 درجات","description":"أربعة أخطاء محددة مع الإجراء الصحيح لكل منها"},{"level":"3–4.5 درجات","description":"ثلاثة أخطاء أو أقل مع إجراءاتها الصحيحة"},{"level":"1.5 درجة","description":"تحديد خطأ واحد مع إجرائه الصحيح"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["ذكر الخطأ دون تصحيحه","القول إن إعادة المادة إلى العبوة تحافظ على الاقتصاد","اعتبار العدسات مقبولة مع النظارة الواقية"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (6 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (13%)"}],"at":"2026-10-18T03:32:48.144Z"}'::jsonb),
('essay', 3, null::int, null, null, '(أ) لحماية العينين والجلد والملابس من المواد الكيميائية التي قد تتناثر أو تنسكب. (ب) لئلا تتلوث المادة في العبوة الأصلية. (ج) لأنها قد تمتص الأبخرة ويصعب إزالتها. (د) لأن الملابس الفضفاضة والأشياء المتدلية قد تعلق بالأدوات أو تلامس المواد الكيميائية أو اللهب فتسبب حوادث.', '["حماية العينين والجلد والملابس","منع تلوث العبوة الأصلية","العدسات تمتص الأبخرة","الأشياء المتدلية قد تعلق أو تلامس المواد واللهب"]'::jsonb, '[]'::jsonb, '[{"element":"سبب (أ)","marks":1},{"element":"سبب (ب)","marks":1},{"element":"سبب (ج)","marks":1},{"element":"سبب (د)","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"أربعة أسباب صحيحة"},{"level":"2–3 درجات","description":"سببان أو ثلاثة صحيحة"},{"level":"1 درجة","description":"سبب واحد صحيح"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["إعادة صياغة القاعدة دون ذكر سببها","القول إن المعطف للزينة أو للتمييز فقط","القول إن عدم إعادة المادة سببه توفير الوقت"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (15%)"}],"at":"2026-10-18T03:32:48.144Z"}'::jsonb)
