from (values
('mcq', 1, 3, 'تتيح الكيمياء الراحة والرفاهية بوسائل منها التبريد، كما في المكيفات التي تُستعمل في المنازل والمدارس وأماكن العمل؛ فالجواب «المكيفات في المنازل والمدارس وأماكن العمل».', '["الغيوم الجليدية ظاهرة جوية تحدث عند انخفاض الحرارة، وليست وسيلة راحة.","تناقص الأوزون مشكلة بيئية وليس فائدة للكيمياء.","ارتفاع تركيز CFCs في الجو وصف لحالة بيئية، وليس وسيلة راحة.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (31%)"}],"at":"2026-10-18T03:32:48.145Z"}'::jsonb),
('mcq', 2, 1, 'تُعنى الكيمياء بصناعة الكريمات التي تُستعمل في الوقاية من بعض أشعة الشمس الضارة؛ فالجواب «الكريمات الواقية من الشمس».', '["الثلاجات تحفظ الأطعمة من التلف بالتبريد، ولا تقي من أشعة الشمس.","","المكيفات تبرّد أماكن المعيشة والعمل، ولا تقي الجلد من الأشعة.","ألياف النايلون تُستعمل في الأنسجة والمظلات، ولا تُعد كريمًا واقيًا من الشمس."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (7%)"}],"at":"2026-10-18T03:32:48.145Z"}'::jsonb),
('mcq', 3, 2, 'يشارك الكيميائيون في حل مشكلة تآكل (تناقص) طبقة الأوزون التي تسرّع مركبات CFCs تفككه؛ فالجواب «تناقص غاز الأوزون في الستراتوسفير».', '["مركبات CFCs لا ترتبط بزيادة غاز النيتروجين في الجو.","مركبات CFCs لا تسبب انخفاض نسبة الأكسجين في الغلاف الجوي.","","نضوب الماء الجوفي مشكلة لا ترتبط بدراسة مركبات CFCs."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (6%)"}],"at":"2026-10-18T03:32:48.145Z"}'::jsonb),
('mcq', 4, 0, 'يشارك الكيميائيون في اكتشاف أدوية ولقاحات لأمراض منها الإيدز والأنفلونزا؛ فالجواب «أدوية ولقاحات لبعض هذه الأمراض».', '["","أجهزة قياس الأوزون تُستعمل في مراقبة طبقة الأوزون لا في علاج الأمراض.","مركبات CFCs ليست علاجًا للأمراض، وأصبحت ممنوعة لأثرها في الأوزون.","أنابيب التفريغ الكهربائي أدوات لدراسة الأشعة، وليست علاجًا للأمراض."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (5%)"}],"at":"2026-10-18T03:32:48.145Z"}'::jsonb),
('mcq', 5, 1, 'الهواء المضغوط يتمدد فيدفع المكابس التي تحرك السيارة، فلا تتسرب ملوثات إلى الجو؛ فالجواب «لا تُسرّب ملوثات إلى الجو».', '["السيارة لا تنتج غاز الأوزون ولا تعوّض النقص فيه.","","السيارة لا تنتج غازات من هذا النوع، فالمطلوب ألا تصدر ملوثات أصلًا.","السيارة العاملة بالهواء المضغوط لا تحرق وقودًا، فلا يصدر عنها دخان."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (6%)"}],"at":"2026-10-18T03:32:48.145Z"}'::jsonb),
('mcq', 6, 3, 'الغواصة الصغيرة التي لا يتجاوز طولها 4 mm يمكن أن تُستعمل في اكتشاف الأمراض والتشوهات في الجسم البشري وإصلاحها؛ فالجواب «اكتشاف الأمراض والتشوهات في الجسم البشري وإصلاحها».', '["قياس سمك طبقة الأوزون يتم بأجهزة تُستعمل في الستراتوسفير وليس بغواصة صغيرة.","الغواصة الصغيرة تُستعمل في الجسم البشري لا في تنظيف اللوحات الفنية.","حجمها (4 mm) لا يسمح بنقل الركاب.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (5%)"}],"at":"2026-10-18T03:32:48.145Z"}'::jsonb),
