('mcq', 7, 3, 'نتيجة غير متوقعة أدت إلى مادة نافعة تمثل اكتشافًا غير مقصود، كاكتشاف البنسلين والنايلون؛ فالجواب «اكتشاف علمي غير مقصود».', '["الاكتشاف المخطط له يتوقع صاحبه نتيجته مسبقًا، وهذا غير ما حدث.","القانون العلمي علاقة في الطبيعة تدعمها تجارب عدة، وليس نتيجة واحدة غير متوقعة.","النظرية فرضية تدعمها تجارب كثيرة، وليست نتيجة واحدة غير متوقعة.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (4%)"}],"at":"2026-10-18T03:32:48.147Z"}'::jsonb),
('essay', 1, null::int, null, null, 'الاكتشاف غير المقصود اكتشاف علمي يحدث دون قصد ولم يكن متوقعًا. ومن أمثلته اكتشاف فلمنج للبنسلين حين لاحظ منطقة خالية من البكتيريا حول فطر أخضر، واكتشاف النايلون حين سحب جوليان هيل أليافًا طويلة من قضيب زجاجي غمسه في مخلوط محاليل.', '["تعريف: يحدث دون قصد ولم يكن متوقعًا","مثال البنسلين","مثال النايلون"]'::jsonb, '[]'::jsonb, '[{"element":"التعريف","marks":2},{"element":"المثال الأول","marks":1},{"element":"المثال الثاني","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"تعريف صحيح ومثالان صحيحان"},{"level":"2–3 درجات","description":"تعريف صحيح مع مثال واحد، أو مثالان دون تعريف"},{"level":"1 درجة","description":"جزء من التعريف أو مثال واحد"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["القول إنه اكتشاف ناتج عن بحث مخطط له","ذكر الأشعة السينية أو CFCs مثالًا على الاكتشاف غير المقصود"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (22%)"}],"at":"2026-10-18T03:32:48.147Z"}'::jsonb),
('essay', 2, null::int, null, null, 'كان فلمنج يعمل بأطباق مزروعة ببكتيريا ستافيلوكوكس، فوجد أن أحد الأطباق تلوث بفطر أخضر عُرف لاحقًا بفطر البنسلين. راقب الطبق باهتمام ولاحظ وجود منطقة خالية حول الفطر ماتت فيها البكتيريا. واستنتج أن مادة كيميائية من الفطر (البنسلين) سببت قتل البكتيريا.', '["طبق بكتيريا ستافيلوكوكس تلوث بفطر أخضر","ملاحظة منطقة خالية ماتت فيها البكتيريا","استنتاج: مادة من الفطر (البنسلين) قتلت البكتيريا","الاكتشاف جاء دون قصد"]'::jsonb, '[]'::jsonb, '[{"element":"وصف تلوث الطبق بالفطر","marks":1},{"element":"الملاحظة: منطقة خالية من البكتيريا","marks":1.5},{"element":"الاستنتاج: مادة البنسلين قتلت البكتيريا","marks":1.5}]'::jsonb, '[{"level":"4 درجات","description":"وصف كامل للموقف والملاحظة والاستنتاج"},{"level":"2–3 درجات","description":"وصف جزئي مع ملاحظة أو استنتاج"},{"level":"1 درجة","description":"ذكر اسم العالم أو الفطر فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["القول إن البكتيريا نمت أكثر حول الفطر","نسبة الاكتشاف إلى هيل","الاستنتاج أن الفطر يتحول إلى بكتيريا"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (5%)"}],"at":"2026-10-18T03:32:48.147Z"}'::jsonb),
('essay', 3, null::int, null, null, 'في عام 1931م قام جوليان هيل بغمس قضيب زجاجي ساخن في مخلوط من المحاليل، فسحب بشكل غير متوقع أليافًا طويلة. تابع هيل وزملاؤه تطوير هذه الألياف إلى حرير اصطناعي يتحمل درجات الحرارة العالية، حتى تم تطوير النايلون عام 1934م. وفي أثناء الحرب العالمية الثانية استُعمل النايلون بديلًا للحرير في المظلات، ويُستعمل اليوم في صناعة الأنسجة وبعض أنواع البلاستيك وأشرطة التثبيت.', '["1931م: سحب هيل ألياف طويلة بشكل غير متوقع","تطوير الألياف إلى حرير اصطناعي يتحمل الحرارة","تطوير النايلون عام 1934م","بديل الحرير في المظلات","استعمالاته اليوم"]'::jsonb, '[]'::jsonb, '[{"element":"اكتشاف الألياف عام 1931م بشكل غير متوقع","marks":1.5},{"element":"تطويرها إلى حرير اصطناعي وتطوير النايلون 1934م","marks":1.5},{"element":"استعماله بديلًا للحرير في المظلات","marks":1},{"element":"استعمال اليوم (الأنسجة أو البلاستيك أو أشرطة التثبيت)","marks":1}]'::jsonb, '[{"level":"5 درجات","description":"تسلسل كامل صحيح"},{"level":"3–4 درجات","description":"تسلسل صحيح مع نقص في التطوير أو الاستعمالات"},{"level":"1–2 درجة","description":"ذكر جزء من القصة فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["الخلط بين 1931م و1934م","نسبة اكتشاف النايلون إلى فلمنج","القول إن النايلون اكتُشف عن قصد"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (7%)"}],"at":"2026-10-18T03:32:48.147Z"}'::jsonb)
