('mcq', 5, 0, 'السيارة العاملة بالهواء المضغوط والغواصة الصغيرة منتجان تقنيان ناتجان عن تطبيق المعرفة العلمية؛ فالجواب «سيارة بالهواء المضغوط وغواصة صغيرة».', '["","ثقب الأوزون وطبقة الستراتوسفير ظاهرتان في الجو وليسا منتجين تقنيين.","الفرضية والقانون من مفاهيم الطريقة العلمية وليسا منتجين تقنيين.","البيانات النوعية والكمية أنواع من المعلومات وليست منتجات تقنية."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (25%)"}],"at":"2026-10-18T03:32:48.148Z"}'::jsonb),
('mcq', 6, 1, 'التقنية هي التطبيق العملي للمعرفة العلمية، أما البحث الذي يهدف إلى المعرفة فيحصّلها؛ فالعبارة الصحيحة هي الثانية بنصها «التقنية تطبّق المعرفة العلمية عمليًّا، والبحث العلمي يحصّل المعرفة».', '["الدوران معكوسان في هذه العبارة.","","الفرق قائم؛ فالتقنية تطبيق عملي، والبحث تحصيل للمعرفة.","حب الاستطلاع دافع البحث النظري لا التقنية، فالعبارة معكوسة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (24%)"}],"at":"2026-10-18T03:32:48.148Z"}'::jsonb),
('mcq', 7, 2, 'استعمال الأشعة في التشخيص الطبي تطبيق عملي لمعرفة أنتجها بحث نظري، فهو تقنية؛ والجواب «تقنية ناتجة عن تطبيق معرفة حصل عليها بحث نظري».', '["الاستعمال الطبي تطبيق عملي وليس دراسة جديدة للأنابيب.","الفرضية توقع قابل للاختبار، أما الاستعمال الطبي فتطبيق قائم.","","البيانات الكمية أرقام ناتجة عن القياس، وليست تطبيقًا عمليًّا."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (6%)"}],"at":"2026-10-18T03:32:48.148Z"}'::jsonb),
('essay', 1, null::int, null, null, 'التقنية هي التطبيق العملي للمعرفة العلمية. ومن المنتجات التقنية: السيارة العاملة بالهواء المضغوط التي لا تسرّب ملوثات إلى الجو، والغواصة الصغيرة (4 mm) التي تُستعمل في اكتشاف الأمراض والتشوهات في الجسم وإصلاحها، والمكيفات التي توفر الراحة بالتبريد، وألياف النايلون المستعملة في الأنسجة.', '["التقنية: التطبيق العملي للمعرفة العلمية","منتج تقني أول","منتج تقني ثانٍ","منتج تقني ثالث"]'::jsonb, '[]'::jsonb, '[{"element":"تعريف التقنية","marks":1},{"element":"المنتج الأول","marks":1},{"element":"المنتج الثاني","marks":1},{"element":"المنتج الثالث","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"تعريف صحيح وثلاثة منتجات صحيحة"},{"level":"2–3 درجات","description":"تعريف صحيح مع منتج أو منتجين، أو ثلاثة منتجات دون تعريف"},{"level":"1 درجة","description":"تعريف فقط أو منتج واحد فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["تعريف التقنية بأنها المعرفة نفسها","ذكر ظاهرة طبيعية كمنتج تقني","ذكر مشكلة بيئية مثل ثقب الأوزون منتجًا"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (8%)"}],"at":"2026-10-18T03:32:48.149Z"}'::jsonb),
('essay', 2, null::int, null, null, 'التقنية تطبيق عملي للمعرفة العلمية التي تنتجها الأبحاث. فالأشعة السينية اكتُشفت عندما كان العلماء يدرسون أنابيب التفريغ الكهربائي بحثًا نظريًّا، ثم اكتُشف أنها تُستعمل في التشخيص الطبي، فصارت تطبيقًا عمليًّا مفيدًا. أما السيارة العاملة بالهواء المضغوط فتطبّق معرفة بأن الهواء المضغوط عند تمدده يدفع المكابس التي تحرك السيارة، فلا تسرّب ملوثات إلى الجو، وهي منتج تقني نتج عن دراسة المادة.', '["التقنية تطبيق عملي للمعرفة","الأشعة السينية: بحث نظري ثم تشخيص طبي","السيارة: الهواء المضغوط عند تمدده يدفع المكابس","فائدة السيارة: لا تسرّب ملوثات"]'::jsonb, '[]'::jsonb, '[{"element":"تعريف التقنية بأنها تطبيق المعرفة","marks":1},{"element":"مثال الأشعة السينية (بحث نظري ثم تشخيص طبي)","marks":2},{"element":"مثال السيارة وفائدتها البيئية","marks":2}]'::jsonb, '[{"level":"5 درجات","description":"تعريف صحيح ومثالان مشروحان"},{"level":"3–4 درجات","description":"تعريف مع مثال مشروح ومثال ناقص"},{"level":"1–2 درجة","description":"ذكر المثالين دون شرح"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["القول إن الأشعة السينية اكتُشفت لغرض التشخيص الطبي","عدم ذكر فائدة السيارة البيئية","الخلط بين المنتج التقني والمعرفة العلمية"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (6%)"}],"at":"2026-10-18T03:32:48.149Z"}'::jsonb),
('essay', 3, null::int, null, null, 'التقنية تطبيق عملي للمعرفة العلمية، وغالبًا تنتج عن البحوث التطبيقية التي تُجرى لحل مشكلة محددة أو تلبية حاجة، كتطوير سيارة تعمل بالهواء المضغوط لتقليل الملوثات. ومع ذلك قد تنتج التقنية أيضًا من معرفة أنتجها بحث نظري أُجري من أجل المعرفة نفسها ثم طُبّقت عمليًّا، كالأشعة السينية التي اكتُشفت بحثًا نظريًّا ثم استُعملت في التشخيص الطبي. فالتقنية ناتجة عن النوعين، لأنها تطبيق عملي للمعرفة بغض النظر عن مصدرها.', '["التقنية: تطبيق عملي للمعرفة","تنتج غالبًا عن البحث التطبيقي لحل مشكلة","قد تنتج عن معرفة بحث نظري ثم تُطبَّق","مثال داعم"]'::jsonb, '[]'::jsonb, '[{"element":"تعريف التقنية بأنها تطبيق عملي للمعرفة","marks":1},{"element":"ربطها بالبحث التطبيقي (حل مشكلة محددة)","marks":1},{"element":"بيان أن المعرفة النظرية قد تتحول إلى تقنية","marks":1},{"element":"مثال داعم صحيح","marks":1},{"element":"وجهة نظر واضحة ومبررة","marks":1}]'::jsonb, '[{"level":"5 درجات","description":"موقف واضح مبرر بالتعريفين ومدعوم بمثال"},{"level":"3–4 درجات","description":"موقف مبرر جزئيًّا أو بلا مثال"},{"level":"1–2 درجة","description":"موقف دون تبرير كاف"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["القول إن التقنية بحث علمي لا منتج","إهمال دور المعرفة النظرية في نشأة بعض التقنيات","ذكر الموقف دون مثال أو تبرير"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (11%)"}],"at":"2026-10-18T03:32:48.149Z"}'::jsonb)
