('mcq', 2, 3, 'الحجم 500 mL = 0.500 L، والتركيز = 100 mg ÷ 0.500 L = 200 mg/L، وهو أكبر من 180 mg/L؛ فالعينة «ماء عسر جدًا».', '["ينتج عن قسمة 100 على 500 دون تحويل الحجم إلى لتر (0.2)، وهو خطأ في وحدة الحجم.","ينتج عن عدّ الكتلة 100 mg تركيزًا دون القسمة على الحجم؛ والتركيز الصحيح 200 mg/L.","التركيز 200 mg/L يتجاوز حد فئة عسر (180 mg/L).",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (50%)"}],"at":"2026-10-18T03:32:48.150Z"}'::jsonb),
('mcq', 3, 2, '0.50 g = 500 mg، والتركيز = 500 mg ÷ 4.0 L = 125 mg/L، وهو بين 121 و180 mg/L؛ فالماء «ماء عسر».', '["ينتج عن قسمة 0.50 على 4.0 دون تحويل الغرام إلى ملّيغرام (0.125 mg/L).","التركيز 125 mg/L يزيد عن الحد الأعلى للماء المتوسط وهو 120 mg/L.","","عسر جدًا يعني أكثر من 180 mg/L، والتركيز الصحيح 125 mg/L فقط."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (8%)"}],"at":"2026-10-18T03:32:48.150Z"}'::jsonb),
('mcq', 4, 0, 'تركيز A = 9.0 mg ÷ 0.060 L = 150 mg/L وهو بين 121 و180 mg/L فهي عسر؛ أما B فتركيزها 30 mg/L، وC 110 mg/L، وD 120 mg/L.', '["","B تركيزها 15 mg ÷ 0.500 L = 30 mg/L، فهي ماء يسر.","C تركيزها 22 mg ÷ 0.200 L = 110 mg/L، فهي ماء متوسط.","D تركيزها 12 mg ÷ 0.100 L = 120 mg/L، وهو الحد الأعلى للماء المتوسط."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (13%)"}],"at":"2026-10-18T03:32:48.150Z"}'::jsonb),
('mcq', 5, 1, 'الحد الأعلى للماء اليسر 60 mg/L، فالكتلة = 60 mg/L × 0.20 L = 12 mg.', '["ينتج عن عدّ الحجم 20 mL بدل 200 mL (60 × 0.020).","","ينتج عن استعمال الحد الأعلى للماء المتوسط 120 mg/L بدل 60 mg/L.","ينتج عن قسمة 60 على 0.20 بدل ضربهما."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (15%)"}],"at":"2026-10-18T03:32:48.150Z"}'::jsonb),
('mcq', 6, 1, 'كتلة الكالسيوم = 300 mg/L × 0.100 L = 30 mg، والحجم الكلي 0.300 L، فالتركيز = 30 mg ÷ 0.300 L = 100 mg/L؛ فالخليط «ماء متوسط».', '["يكون الماء يسرًا لو انخفض التركيز إلى 60 mg/L أو أقل، لكن التركيز الناتج 100 mg/L.","","التركيز 150 mg/L ناتج عن أخذ متوسط 300 و0 رغم اختلاف الحجمين، وهو خطأ.","يبقى الماء عسرًا جدًا لو بقي التركيز 300 mg/L، لكن إضافة الماء المقطر خفضته."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (29%)"}],"at":"2026-10-18T03:32:48.150Z"}'::jsonb),
('mcq', 7, 3, 'العينة س تركيزها 45 mg/L (ماء يسر) والعينة ص 130 mg/L (ماء عسر)، والماء اليسر ينتج رغوة أكثر؛ فالصحيح «ارتفاع رغوة العينة س أكبر لأنها ماء يسر».', '["العينة ص تركيزها 130 mg/L فهي ماء عسر وليست ماء يسر.","ارتفاع تركيز الكالسيوم يقلل الرغوة ولا يزيدها.","تساوي الحجم لا يلغي أثر اختلاف التركيز في ارتفاع الرغوة.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (23%)"}],"at":"2026-10-18T03:32:48.151Z"}'::jsonb),
('essay', 1, null::int, null, null, 'الحجم = 250 mL = 0.250 L. التركيز = 55 mg ÷ 0.250 L = 220 mg/L. وبما أن 220 mg/L أكبر من 180 mg/L فالعينة ماء عسر جدًا.', '["تحويل الحجم إلى 0.250 L","التركيز 220 mg/L","التصنيف: عسر جدًا"]'::jsonb, '["250 mL = 0.250 L","التركيز = 55 mg ÷ 0.250 L = 220 mg/L","220 mg/L > 180 mg/L فالعينة عسر جدًا"]'::jsonb, '[{"element":"تحويل الحجم إلى لتر","marks":1},{"element":"حساب التركيز 220 mg/L","marks":1},{"element":"التصنيف الصحيح مع التبرير","marks":1}]'::jsonb, '[{"level":"3 درجات","description":"حل صحيح كامل"},{"level":"2 درجتان","description":"حساب صحيح مع خطأ في التصنيف أو التحويل"},{"level":"1 درجة","description":"خطوة صحيحة واحدة"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["قسمة الكتلة على 250 دون تحويل الحجم إلى لتر","الخطأ في حدود الفئات","نسيان الوحدة mg/L"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (3 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (30%)"}],"at":"2026-10-18T03:32:48.151Z"}'::jsonb),
('essay', 2, null::int, null, null, 'العينة A: 150 mL = 0.150 L، والتركيز = 12.6 mg ÷ 0.150 L = 84 mg/L، وهو بين 61 و120 mg/L فهي ماء متوسط. العينة B: 100 mL = 0.100 L، والتركيز = 4.2 mg ÷ 0.100 L = 42 mg/L، وهو بين 0 و60 mg/L فهي ماء يسر. والماء اليسر ينتج رغوة أكثر من العسر، فالعينة B هي التي تنتج رغوة أكثر.', '["A: 84 mg/L ماء متوسط","B: 42 mg/L ماء يسر","B رغوتها أكثر لأن الماء اليسر ينتج رغوة أكثر"]'::jsonb, '["A: 150 mL = 0.150 L، التركيز = 12.6 ÷ 0.150 = 84 mg/L (متوسط)","B: 100 mL = 0.100 L، التركيز = 4.2 ÷ 0.100 = 42 mg/L (يسر)","الماء الأقل عسرًا ينتج رغوة أكثر فالعينة B"]'::jsonb, '[{"element":"تركيز A مع تصنيفها","marks":2},{"element":"تركيز B مع تصنيفها","marks":2},{"element":"تحديد B بأنها تنتج رغوة أكثر مع التعليل","marks":1}]'::jsonb, '[{"level":"5 درجات","description":"حل صحيح كامل"},{"level":"3–4 درجات","description":"حسابان صحيحان مع خطأ في التصنيف أو التعليل"},{"level":"1–2 درجة","description":"حساب صحيح لإحدى العينتين"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["عدم تحويل mL إلى L","الاعتقاد أن الماء العسر ينتج رغوة أكثر","الخلط بين حدود المتوسط واليسر"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (21%)"}],"at":"2026-10-18T03:32:48.152Z"}'::jsonb),
('essay', 3, null::int, null, null, '(أ) المتغير المستقل: نوع عينة الماء (تركيز الكالسيوم والماغنسيوم فيها)، والمتغير التابع: ارتفاع الرغوة. (ب) من العوامل الثابتة: حجم العينة (20 mL)، وكمية سائل التنظيف (قطرة)، ومدة الرج (30 s). (ج) الأنبوب D فيه ماء مقطر لا يحتوي كالسيوم ولا ماغنسيوم، فهو مرجع للمقارنة (عينة ضابطة). (د) العينة A ماء يسر لأن رغوتها (3.6 cm) قريبة من رغوة الماء المقطر وكبيرة، والعينة B ماء عسر لأن رغوتها (0.8 cm) قليلة؛ فالماء اليسر ينتج رغوة أكثر من الماء العسر.', '["المستقل: نوع عينة الماء","التابع: ارتفاع الرغوة","عاملان ثابتان من: الحجم، كمية السائل، مدة الرج","D مرجع للمقارنة","A يسر وB عسر مع التعليل بارتفاع الرغوة"]'::jsonb, '[]'::jsonb, '[{"element":"المتغير المستقل","marks":1},{"element":"المتغير التابع","marks":1},{"element":"عاملان ثابتان","marks":2},{"element":"دور الأنبوب D","marks":1},{"element":"تصنيف A وB مع التعليل","marks":2}]'::jsonb, '[{"level":"7 درجات","description":"إجابة كاملة صحيحة للفروع الأربعة"},{"level":"4–6 درجات","description":"معظم الفروع صحيحة مع نقص أو خطأ جزئي"},{"level":"1–3 درجات","description":"فرع أو فرعان صحيحان"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["عدّ ارتفاع الرغوة متغيرًا مستقلًّا","عكس تصنيف A وB","ذكر عامل متغير على أنه ثابت"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (7 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (23%)"}],"at":"2026-10-18T03:32:48.152Z"}'::jsonb)
) as v(type, number, ci, ex, dn, ma, ae, ss, mk, rb, ce, ac)
join public.questions x on x.objective_id = (select id from public.objectives where code = 'K1-C1-L4-O06') and x.type = v.type and x.number = v.number
