from (values
('mcq', 1, 'أيّ العبارات الآتية تصف الماء النقي وصفًا صحيحًا؟', null, '["مخلوط تختلف كميات مكوناته من عينة إلى أخرى","مادة كيميائية نقية ثابتة التركيب مكوّنة من الهيدروجين والأكسجين","عنصر يتكون من نوع واحد فقط من الذرات","محلول يحتوي على معادن ومواد ذائبة أخرى"]'::jsonb, 'تذكر', 'تذكر وصف مادة', 'سهل', 'الكتاب ص 44 — المواد الكيميائية النقية'),
('mcq', 2, 'لماذا يُعدّ ماء البحر مادة غير نقية؟', null, '["لأنه يوجد في الحالة السائلة عند درجة حرارة الغرفة","لأنه يتكون من عنصري الهيدروجين والأكسجين فقط بنسبة ثابتة","لأن لونه ورائحته تتغيران عند نقله من وعاء إلى آخر","لأن تركيبه يختلف من موقع إلى آخر بسبب المعادن والمواد الذائبة فيه"]'::jsonb, 'فهم', 'تفسير', 'سهل', 'الكتاب ص 44 — المواد الكيميائية النقية'),
('mcq', 3, 'يعرض الجدول خواص عينتين سائلتين عديمتي اللون، إحداهما ماء نقي والأخرى ماء بحر، قيست عند ضغط جوي واحد. أيّ الاستنتاجات الآتية صحيح؟', '{"headers":["العينة","درجة التجمد (°C)","درجة الغليان (°C)","الكثافة (g/cm³)"],"rows":[["س","0.0","100.0","1.00"],["ص","-2.0","100.6","1.03"]]}'::jsonb, '["العينة س ماء نقي، والعينة ص ماء بحر","العينة س ماء بحر، والعينة ص ماء نقي","العينتان ماء نقي لأن كلتيهما عديمة اللون","العينتان ماء بحر لأن كثافتيهما متقاربتان"]'::jsonb, 'تطبيق', 'تفسير بيانات', 'متوسط', 'المحتوى المكمّل (ليس في الكتاب) — خواص الماء النقي وماء البحر'),
('mcq', 4, 'أُخذت عينتان من ماء البحر من موقعين مختلفين وحُلّلتا. ما النتيجة المتوقعة؟', null, '["تركيب العينتين متطابق تمامًا","تحتويان على الكمية نفسها من المعادن","تحتويان على كميات مختلفة من المواد الذائبة","تتكون كل منهما من الهيدروجين والأكسجين فقط"]'::jsonb, 'فهم', 'توقع نتيجة', 'سهل', 'الكتاب ص 44 — المواد الكيميائية النقية'),
('mcq', 5, 'يمكن الحصول على الماء النقي من ماء البحر بالتقطير، أي بغلي ماء البحر وتكثيف البخار المتصاعد. ما الذي يفسر نجاح هذه الطريقة؟', null, '["الملح يتبخر عند درجة حرارة أقل من الماء فيفصل أولًا","الماء يتبخر ويبقى الملح وبعض المواد الذائبة","الماء والملح يتبخران معًا ثم ينفصلان عند التكثيف","الملح يتحول إلى ماء عند التسخين"]'::jsonb, 'تطبيق', 'تفسير طريقة فصل', 'صعب', 'المحتوى المكمّل (ليس في الكتاب) — فصل الماء النقي عن ماء البحر بالتقطير'),
('mcq', 6, 'أيّ العبارات الآتية تصنّف الماء النقي وماء البحر تصنيفًا صحيحًا؟', null, '["كلاهما مادة نقية لأن كلًّا منهما شفاف","كلاهما مخلوط لأن كلًّا منهما سائل","الماء النقي مخلوط وماء البحر مادة نقية","الماء النقي مادة نقية وماء البحر مخلوط متجانس"]'::jsonb, 'فهم', 'تصنيف', 'متوسط', 'الكتاب ص 44 — المواد الكيميائية النقية؛ والمحتوى المكمّل (ليس في الكتاب) — ماء البحر مخلوط متجانس'),
('mcq', 7, 'قال طالب: «ماء البحر ماء نقي لأنه شفاف». ما الخطأ في قوله؟', null, '["الشفافية لا تدل على النقاء؛ فماء البحر يحتوي مواد ذائبة تتغير كمياتها","الماء النقي لا يكون شفافًا أبدًا بل يكون معتمًا دائمًا","ماء البحر مركب ثابت التركيب مثل الماء النقي تمامًا","الشفافية دليل على أن الماء مخلوط غير متجانس التركيب"]'::jsonb, 'تحليل', 'تحليل ادعاء', 'صعب', 'الكتاب ص 44 — المواد الكيميائية النقية'),
('essay', 1, 'قارن بين الماء النقي وماء البحر من حيث: (أ) تصنيف كل منهما (مادة نقية أم مخلوط)، (ب) ثبات التركيب، (ج) درجة التجمد ودرجة الغليان.', null, null, 'فهم', 'مقارنة', 'متوسط', 'الكتاب ص 44 — المواد الكيميائية النقية؛ والمحتوى المكمّل (ليس في الكتاب) — خواص الماء النقي وماء البحر'),
('essay', 2, 'أُخذت عينتان من ماء البحر من موقعين مختلفين، فتجمدت الأولى عند -1.8°C وتجمدت الثانية عند -2.3°C، بينما يتجمد الماء النقي عند 0°C. (أ) فسّر اختلاف درجتي تجمد العينتين. (ب) هل يمكن عدّ ماء البحر مادة كيميائية نقية؟ علّل. (ج) اقترح طريقة للحصول على ماء نقي من إحدى العينتين.', null, null, 'تطبيق', 'تفسير بيانات وتطبيق', 'صعب', 'المحتوى المكمّل (ليس في الكتاب) — خواص ماء البحر والتقطير؛ والكتاب ص 44 — المواد الكيميائية النقية'),
('essay', 3, 'قال زميل لك: «ماء الشرب هو ماء نقي لأنه صالح للشرب». قيّم هذا الادعاء، موضحًا الفرق بين الماء النقي وماء الشرب، ثم بيّن كيف يختلف ماء البحر عن الماء النقي.', null, null, 'تقويم', 'تقويم ادعاء', 'صعب', 'الكتاب ص 44 — المواد الكيميائية النقية؛ والمحتوى المكمّل (ليس في الكتاب) — خواص ماء البحر')
) as v(type, number, stem, stimulus, options, tl, qk, diff, src)
