select x.id, v.ci::int, v.ex::text, v.dn::jsonb, v.ma::text, v.ae::jsonb, v.ss::jsonb, v.mk::jsonb, v.rb::jsonb, v.ce::jsonb, v.ac::jsonb
from (values
('mcq', 1, 1, 'الماء النقي مادة كيميائية نقية ذات تركيب ثابت، وهو مكوّن من الهيدروجين والأكسجين (H₂O).', '["هذا وصف ماء البحر أو ماء الشرب؛ فالماء النقي تركيبه ثابت ولا يختلف من عينة إلى أخرى.","","الماء النقي مركب لأنه يتكون من عنصرين متحدين (الهيدروجين والأكسجين)، وليس عنصرًا.","وجود المعادن والمواد الذائبة يجعل الماء غير نقي، كما في ماء البحر."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (45%)"}],"at":"2026-10-18T03:32:48.152Z"}'::jsonb),
('mcq', 2, 3, 'العينات المأخوذة من أماكن مختلفة من البحر تحتوي على كميات مختلفة من المعادن والمواد الذائبة، فتركيبه غير ثابت، وهذا ما يجعله غير نقي.', '["الحالة السائلة لا تحدد النقاء؛ فالماء النقي أيضًا سائل عند درجة حرارة الغرفة.","تكوّن المادة من الهيدروجين والأكسجين بنسبة ثابتة صفة الماء النقي، وليس ماء البحر.","نقل الماء من وعاء إلى آخر لا يغير لونه ولا رائحته، وليس هذا سبب عدم نقائه.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (14%)"}],"at":"2026-10-18T03:32:48.153Z"}'::jsonb),
('mcq', 3, 0, 'الماء النقي يتجمد عند 0°C ويغلي عند 100°C وكثافته 1.00 g/cm³، وهذه قيم العينة س. أما العينة ص فتتجمد عند درجة أقل، وتغلي عند درجة أعلى، وهي أكثف، كما هو متوقع لماء يحتوي على أملاح ذائبة، فهي ماء بحر.', '["","الماء النقي هو الذي يتجمد عند 0°C ويغلي عند 100°C، وهذا ما تظهره العينة س لا ص.","اللون وحده لا يدل على النقاء؛ فالعينتان تختلفان في درجتي التجمد والغليان والكثافة.","تقارب الكثافة لا يعني التطابق؛ فالفرق في درجتي التجمد والغليان يدل على اختلاف التركيب."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (7%)"}],"at":"2026-10-18T03:32:48.153Z"}'::jsonb),
('mcq', 4, 2, 'ماء البحر غير نقي؛ لذلك تحتوي العينات المأخوذة من أماكن مختلفة على كميات مختلفة من المعادن والمواد الذائبة الأخرى.', '["تطابق التركيب صفة المواد النقية، أما ماء البحر فيختلف تركيبه من موقع إلى آخر.","الكميات من المعادن تختلف من موقع إلى آخر ولا تكون متساوية.","","ماء البحر يحتوي إضافة إلى الماء على معادن ومواد ذائبة، فلا يقتصر على الهيدروجين والأكسجين."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (17%)"}],"at":"2026-10-18T03:32:48.153Z"}'::jsonb),
('mcq', 5, 1, 'ماء البحر مخلوط من الماء وأملاح ومواد ذائبة؛ وعند غليه يتبخر الماء ويبقى الملح، وعند تكثيف البخار نحصل على ماء نقي.', '["الملح لا يتبخر عند درجة غليان الماء، وهو الذي يبقى بعد تبخر الماء.","","لو تبخر الملح مع الماء لما حصلنا على ماء نقي؛ فالملح يبقى ولا يصعد مع البخار.","الملح لا يتحول إلى ماء؛ فكل مادة في المخلوط تحتفظ بخواصها."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (14%)"}],"at":"2026-10-18T03:32:48.153Z"}'::jsonb),
('mcq', 6, 3, 'الماء النقي مادة كيميائية نقية تركيبها ثابت، أما ماء البحر فمخلوط متجانس من الماء وأملاح ومعادن وغازات ذائبة، وتركيبه غير ثابت.', '["الشفافية لا تدل على النقاء؛ فماء البحر شفاف لكنه يحتوي مواد ذائبة.","كون المادة سائلة لا يجعلها مخلوطًا؛ فالماء النقي سائل وهو مادة نقية.","التصنيف معكوس؛ فالماء النقي هو المادة النقية وماء البحر هو المخلوط.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (45%)"}],"at":"2026-10-18T03:32:48.153Z"}'::jsonb),
('mcq', 7, 0, 'النقاء يتحدد بثبات التركيب لا بالمظهر؛ وماء البحر يحتوي على معادن ومواد ذائبة تختلف كمياتها من عينة إلى أخرى، فهو غير نقي رغم شفافيته.', '["","الماء النقي شفاف عديم اللون، فالشفافية ليست دليلًا على أن الماء غير نقي.","ماء البحر ليس مركبًا ثابت التركيب، فتركيبه يتغير من موقع إلى آخر.","الشفافية لا تدل على نوع المخلوط؛ وماء البحر مخلوط متجانس لا غير متجانس."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (19%)"}],"at":"2026-10-18T03:32:48.154Z"}'::jsonb),
('essay', 1, null::int, null, null, 'الماء النقي مادة كيميائية نقية مكونة من الهيدروجين والأكسجين (H₂O)، وتركيبه ثابت لا يتغير من عينة إلى أخرى. أما ماء البحر فمخلوط متجانس من الماء وأملاح ومعادن وغازات ذائبة، وتركيبه غير ثابت إذ تختلف كميات المواد الذائبة من موقع إلى آخر. ويتجمد الماء النقي عند 0°C ويغلي عند 100°C، بينما يتجمد ماء البحر عند درجة أقل من 0°C ويغلي عند درجة أعلى من 100°C بسبب المواد الذائبة فيه.', '["الماء النقي مادة نقية وماء البحر مخلوط","تركيب الماء النقي ثابت (H₂O) وتركيب ماء البحر يختلف من عينة إلى أخرى","الماء النقي يتجمد عند 0°C وماء البحر عند درجة أقل","الماء النقي يغلي عند 100°C وماء البحر عند درجة أعلى"]'::jsonb, '[]'::jsonb, '[{"element":"تصنيف الماءين تصنيفًا صحيحًا","marks":1},{"element":"المقارنة في ثبات التركيب","marks":1},{"element":"المقارنة في درجة التجمد","marks":1},{"element":"المقارنة في درجة الغليان","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"مقارنة صحيحة في التصنيف وثبات التركيب والتجمد والغليان"},{"level":"2–3 درجات","description":"مقارنة صحيحة في محورين أو ثلاثة"},{"level":"1 درجة","description":"مقارنة صحيحة في محور واحد فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["عدّ ماء البحر مادة نقية لأنه شفاف","القول إن درجة غليان ماء البحر أقل من 100°C","الاكتفاء بالتصنيف دون مقارنة ثبات التركيب"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (16%)"}],"at":"2026-10-18T03:32:48.154Z"}'::jsonb),
('essay', 2, null::int, null, null, '(أ) تختلف درجتا التجمد لأن تركيب العينتين مختلف؛ فكمية الأملاح والمواد الذائبة في كل عينة تختلف عن الأخرى، والعينة الأقل تجمدًا تحتوي على مواد ذائبة أكثر. (ب) لا؛ لأن ماء البحر مخلوط يحتوي على كميات مختلفة من المعادن والمواد الذائبة، وتركيبه غير ثابت، بينما المادة النقية ثابتة التركيب. (ج) التقطير: يُغلى ماء البحر فيتبخر الماء ويبقى الملح، ثم يُكثَّف البخار فنحصل على ماء نقي.', '["اختلاف التركيب (كمية المواد الذائبة) يسبب اختلاف درجة التجمد","ماء البحر ليس مادة نقية لأن تركيبه غير ثابت","التعليل بوجود كميات مختلفة من المعادن والمواد الذائبة","التقطير: تبخير الماء ثم تكثيفه"]'::jsonb, '[]'::jsonb, '[{"element":"تفسير اختلاف درجتي التجمد باختلاف كمية المواد الذائبة","marks":1},{"element":"الجواب بأن ماء البحر ليس مادة نقية","marks":1},{"element":"تعليل عدم النقاء بعدم ثبات التركيب","marks":1},{"element":"اقتراح التقطير مع توضيح مبدئه","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"تفسير صحيح لاختلاف التجمد، وحكم معلل بعدم النقاء، وطريقة فصل صحيحة"},{"level":"2–3 درجات","description":"إجابة صحيحة عن بندين أو ثلاثة من الأربعة"},{"level":"1 درجة","description":"إجابة صحيحة عن بند واحد"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["تفسير اختلاف التجمد باختلاف لون العينتين","القول إن ماء البحر نقي لأن تركيبه ثابت","اقتراح الترشيح لفصل الملح الذائب"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (17%)"}],"at":"2026-10-18T03:32:48.154Z"}'::jsonb),
('essay', 3, null::int, null, null, 'الادعاء غير صحيح. الماء النقي مادة كيميائية نقية مكونة من الهيدروجين والأكسجين فقط، وتركيبه ثابت. أما ماء الشرب فغير نقي، لأن العينات المأخوذة منه من أماكن مختلفة تحتوي على كميات مختلفة من المعادن والمواد الذائبة الأخرى، وكونه صالحًا للشرب لا يعني أنه مادة نقية. وكذلك ماء البحر مخلوط يحتوي على الماء وأملاح ومعادن وغازات ذائبة بكميات تختلف من موقع إلى آخر، فتختلف خواصه عن خواص الماء النقي؛ إذ يتجمد عند درجة أقل من 0°C ويغلي عند درجة أعلى من 100°C.', '["الادعاء غير صحيح","الماء النقي مكون من الهيدروجين والأكسجين فقط وثابت التركيب","ماء الشرب يحتوي على كميات مختلفة من المعادن والمواد الذائبة","ماء البحر مخلوط تختلف خواصه عن الماء النقي (تجمد أقل وغليان أعلى)"]'::jsonb, '[]'::jsonb, '[{"element":"الحكم بعدم صحة الادعاء","marks":1},{"element":"وصف الماء النقي (مكوناته وثبات تركيبه)","marks":1},{"element":"تعليل عدم نقاء ماء الشرب بالمواد الذائبة","marks":2},{"element":"بيان اختلاف ماء البحر عن الماء النقي","marks":1}]'::jsonb, '[{"level":"5 درجات","description":"حكم صحيح بتعليل كامل، ووصف الماء النقي، وبيان اختلاف ماء البحر"},{"level":"3–4 درجات","description":"حكم صحيح بتعليل ناقص أو إغفال مقارنة ماء البحر"},{"level":"1–2 درجة","description":"حكم صحيح دون تعليل كافٍ"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["الخلط بين «صالح للشرب» و«نقي كيميائيًّا»","القول إن الماء الشفاف عديم الرائحة نقي دائمًا","عدّ ماء البحر نقيًّا لأنه يتكون من الماء"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (19%)"}],"at":"2026-10-18T03:32:48.154Z"}'::jsonb)
) as v(type, number, ci, ex, dn, ma, ae, ss, mk, rb, ce, ac)
