from (values
('mcq', 1, 2, 'يمكن تصنيف جميع المواد الموجودة في الطبيعة ضمن ثلاث حالات هي الصلبة والسائلة والغازية، وتسمى حالات المادة.', '["حالتان فقط لا تكفيان؛ إذ تُهمل هذه المجموعة الحالة الغازية.","البلازما حالة مميزة أخرى للمادة، لكنها ليست من الحالات الثلاث الشائعة، ولا تضم هذه المجموعة الحالة الصلبة.","","هذه المجموعة تُهمل الحالة السائلة وتضم البلازما، وهي ليست من الحالات الثلاث الشائعة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (8%)"}],"at":"2026-10-18T03:32:48.155Z"}'::jsonb),
('mcq', 2, 0, 'المادة الصلبة حالة من حالات المادة لها شكل وحجم محددان، لأن جسيماتها مترّاصة بإحكام.', '["","السائل حجمه ثابت لكنه يأخذ شكل الوعاء الذي يوضع فيه، فشكله غير محدد.","الغاز يأخذ شكل الإناء الذي يملؤه وحجمه، فلا يكون لهما قيمة محددة.","البلازما غاز متأين، فلا شكل محددًا لها ولا حجم."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (27%)"}],"at":"2026-10-18T03:32:48.155Z"}'::jsonb),
('mcq', 3, 1, 'السائل حالة من حالات المادة له صفة الجريان، حجمه ثابت ولكنه يأخذ شكل الوعاء الذي يوضع فيه.', '["المادة الصلبة لها شكل ثابت ولا تأخذ شكل الوعاء الذي توضع فيه.","","الغاز يأخذ شكل الإناء وحجمه معًا، فحجمه غير ثابت.","البلازما غاز متأين، وهي لا تتصف بحجم ثابت."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (27%)"}],"at":"2026-10-18T03:32:48.156Z"}'::jsonb),
('mcq', 4, 3, 'البلازما حالة مميزة للمادة يمكن وصفها بأنها غاز متأين تكون فيه الإلكترونات حرة وغير مرتبطة بالذرة أو الجزيء.', '["جسيمات الغاز متباعدة جدًّا لا متراصة، والبلازما ليست غازًا مضغوطًا بل غاز متأين.","البلازما ليست سائلًا؛ فهي في الحالة الغازية المتأينة.","تحول الصلب إلى بخار عملية تغير حالة، وليس تعريفًا للبلازما.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (17%)"}],"at":"2026-10-18T03:32:48.156Z"}'::jsonb),
('mcq', 5, 2, 'الماء والدم والزئبق من السوائل، فهي تجري وتأخذ شكل الوعاء الذي توضع فيه ولها حجم ثابت.', '["الخشب والحديد والسكر جميعها أمثلة على المواد الصلبة.","الهواء والأكسجين والنيتروجين توجد في الحالة الغازية.","","الحديد صلب والهواء غاز، فالمجموعة لا تضم سوائل فقط."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (4%)"}],"at":"2026-10-18T03:32:48.156Z"}'::jsonb),
('mcq', 6, 0, 'تُميّز كل حالة من حالات المادة من خلال الطريقة التي تملأ بها الوعاء الذي توضع فيه: شكل وحجم محددان للصلب، وحجم ثابت وشكل الوعاء للسائل، وشكل الوعاء وحجمه للغاز.', '["","القساوة واللين لا تحددان الحالة؛ فالأسمنت قاس والشمع لين وكلاهما صلب.","اللون والرائحة خاصيتان فيزيائيتان للمادة ولا تحددان حالتها.","الكتلة تعتمد على كمية المادة ولا تحدد حالتها."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (17%)"}],"at":"2026-10-18T03:32:48.156Z"}'::jsonb),
('mcq', 7, 3, 'توجد البلازما في لوحات إعلانات النيون وفي المصابيح الكهربائية وشاشات التلفاز، وكذلك في معظم مكونات النجوم.', '["الماء البارد سائل.","الهواء في البالون غاز غير متأين، وليس بلازما.","الحديد مادة صلبة.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (18%)"}],"at":"2026-10-18T03:32:48.156Z"}'::jsonb),
('essay', 1, null::int, null, null, 'حالات المادة هي الأشكال التي توجد عليها المواد في الطبيعة، ويمكن تمييز كل حالة من خلال الطريقة التي تملأ بها المادة الوعاء الذي توضع فيه. الحالة الصلبة: لها شكل وحجم محددان. الحالة السائلة: حجمها ثابت وتأخذ شكل الوعاء الذي توضع فيه. الحالة الغازية: تأخذ شكل الإناء الذي تملؤه وحجمه. والحالة الرابعة هي البلازما: غاز متأين تكون فيه الإلكترونات حرة.', '["تعريف حالات المادة بأنها الأشكال التي توجد عليها المادة وتتميز بطريقة ملء الوعاء","ذكر الحالات الأربع: الصلبة والسائلة والغازية والبلازما","الصلبة: شكل وحجم محددان","السائلة: حجم ثابت وتأخذ شكل الوعاء","الغازية: تأخذ شكل الإناء وحجمه"]'::jsonb, '[]'::jsonb, '[{"element":"تعريف حالات المادة","marks":1},{"element":"ذكر الحالات الأربع","marks":1},{"element":"وصف الحالة الصلبة","marks":1},{"element":"وصف الحالتين السائلة والغازية","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"تعريف صحيح، وأربع حالات صحيحة، ووصف صحيح للحالات الثلاث"},{"level":"2–3 درجات","description":"إجابة صحيحة عن ثلاثة بنود أو بندين"},{"level":"1 درجة","description":"ذكر الحالات دون وصف أو تعريف"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["ذكر ثلاث حالات فقط وإغفال البلازما","القول إن السائل له شكل محدد","الخلط بين حجم السائل (ثابت) وحجم الغاز (يأخذ حجم الإناء)"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (9%)"}],"at":"2026-10-18T03:32:48.156Z"}'::jsonb),
('essay', 2, null::int, null, null, '(أ) الحالة الصلبة. (ب) الحالة السائلة. (ج) الحالة الغازية. (د) البلازما.', '["(أ) الصلبة","(ب) السائلة","(ج) الغازية","(د) البلازما"]'::jsonb, '[]'::jsonb, '[{"element":"تسمية الحالة في (أ)","marks":1},{"element":"تسمية الحالة في (ب)","marks":1},{"element":"تسمية الحالة في (ج)","marks":1},{"element":"تسمية الحالة في (د)","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"تسمية الحالات الأربع تسمية صحيحة"},{"level":"2–3 درجات","description":"تسمية صحيحة لحالتين أو ثلاث"},{"level":"1 درجة","description":"تسمية صحيحة لحالة واحدة"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["عكس الوصفين الخاصين بالصلب والسائل","تسمية الغاز المتأين غازًا عاديًّا","إجابة (ج) بالسائلة لأن الغاز يأخذ شكل الإناء"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (26%)"}],"at":"2026-10-18T03:32:48.156Z"}'::jsonb),
('essay', 3, null::int, null, null, 'الحديد: صلب؛ لأن له شكلًا وحجمًا محددين وجسيماته متراصة بإحكام. الدم: سائل؛ لأنه يجري ويأخذ شكل الوعاء الذي يوضع فيه وحجمه ثابت. الهواء الذي نتنفسه: غاز؛ لأنه يأخذ شكل الإناء الذي يملؤه وحجمه وجسيماته متباعدة جدًّا. الغاز المضيء في لوحة النيون: بلازما؛ لأنه غاز متأين تكون فيه الإلكترونات حرة.', '["الحديد صلب (شكل وحجم محددان)","الدم سائل (يأخذ شكل الوعاء وحجمه ثابت)","الهواء غاز (يملأ الإناء)","الغاز في لوحة النيون بلازما (غاز متأين)"]'::jsonb, '[]'::jsonb, '[{"element":"الحديد مع المبرر","marks":1},{"element":"الدم مع المبرر","marks":1},{"element":"الهواء مع المبرر","marks":1},{"element":"لوحة النيون مع المبرر","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"تصنيف المواد الأربع تصنيفًا صحيحًا مع مبرر لكل منها"},{"level":"2–3 درجات","description":"تصنيف صحيح لمادتين أو ثلاث مع مبرراتها"},{"level":"1 درجة","description":"تصنيف صحيح لمادة واحدة، أو تصنيف دون مبررات"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["عدّ الدم مادة صلبة لأنه ثقيل","عدّ غاز لوحة النيون غازًا عاديًّا لا بلازما","ذكر الحالة دون تبرير"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (11%)"}],"at":"2026-10-18T03:32:48.156Z"}'::jsonb)
