('mcq', 1, 'أيّ العبارات الآتية تميّز الحالة السائلة عن الحالة الصلبة؟', null, '["للسائل شكل محدد أما للصلب فشكله يتغير بتغير الوعاء","السائل قابل للانضغاط بسهولة أما الصلب فغير قابل له","جسيمات السائل أكثر تراصًّا من جسيمات الصلب","جسيمات السائل قادرة على الحركة وتجاوز بعضها بخلاف جسيمات الصلب"]'::jsonb, 'فهم', 'مقارنة', 'سهل', 'الكتاب ص 45 — المواد الصلبة والسوائل'),
('mcq', 2, 'وُضع حجر في وعاء زجاجي، ثم وُضع في وعاء مماثل مقدار من الماء. أيّ العبارات الآتية تصف ما يحدث؟', null, '["كل من الحجر والماء يأخذ شكل الوعاء","الماء يأخذ شكل الوعاء والحجر يحتفظ بشكله","الحجر يأخذ شكل الوعاء والماء يحتفظ بشكله","كل من الحجر والماء يحتفظ بشكله الأصلي"]'::jsonb, 'فهم', 'تطبيق على موقف', 'سهل', 'الكتاب ص 45 — المواد الصلبة والسوائل'),
('mcq', 3, 'ما الخاصية المشتركة بين المادة الصلبة والمادة السائلة؟', null, '["كلاهما يأخذ شكل الوعاء الذي يوضع فيه","كلاهما يُضغط بسهولة إلى حجم أصغر","كلاهما غير قابل للانضغاط ويتمدد بالتسخين","كلاهما له شكل وحجم محددان"]'::jsonb, 'فهم', 'تحديد خاصية مشتركة', 'متوسط', 'الكتاب ص 45 — المواد الصلبة والسوائل'),
('mcq', 4, 'ما التفسير الصحيح لعدم احتفاظ السائل بشكل ثابت عند صبه في أوعية مختلفة؟', null, '["جسيماته أقل تراصًّا من جسيمات الصلب وغير ثابتة في أماكنها فتتحرك وتتجاوز بعضها","جسيماته متراصة بإحكام كجسيمات الصلب فتنزلق مع الوعاء","جسيماته متباعدة جدًّا عن بعضها فتملأ الوعاء كله","جسيماته ثابتة في أماكنها ولا تتحرك أبدًا"]'::jsonb, 'فهم', 'تفسير على مستوى الجسيمات', 'متوسط', 'الكتاب ص 45 — السوائل'),
('mcq', 5, 'الأسمنت مادة قاسية والشمع مادة لينة. ما حالة كل منهما عند درجة حرارة الغرفة؟', null, '["الأسمنت صلب والشمع سائل لأنه لين","الأسمنت سائل والشمع صلب لأنه متماسك","كلاهما سائل لأن الصلابة تعني القساوة فقط","كلاهما صلب لأن الحالة الصلبة لا تتحدد بالقساوة أو التماسك"]'::jsonb, 'تطبيق', 'تصحيح تصور خاطئ', 'متوسط', 'الكتاب ص 45 — المواد الصلبة'),
('mcq', 6, 'أيّ الأزواج الآتية يتكوّن من مادة سائلة ثم مادة صلبة على الترتيب؟', null, '["الزئبق، الهواء","الدم، الحديد","الماء، الأكسجين","السكر، الزئبق"]'::jsonb, 'فهم', 'تصنيف أمثلة', 'سهل', 'الكتاب ص 45 — المواد الصلبة والسوائل'),
('mcq', 7, 'صُبّ 50 mL من سائل في وعاء سعته 100 mL، ثم نُقل إلى وعاء أوسع سعته 250 mL. ما حجم السائل في الحالتين؟', null, '["50 mL ثم 100 mL لأنه يتمدد ليملأ الوعاء","100 mL ثم 250 mL لأنه يملأ كل وعاء","50 mL في الحالتين مع تغير شكله بحسب الوعاء","50 mL ثم 25 mL لأنه ينضغط في الوعاء الأوسع"]'::jsonb, 'تطبيق', 'تطبيق على موقف', 'صعب', 'الكتاب ص 45 — السوائل'),
('essay', 1, 'قارن بين المادة الصلبة والمادة السائلة من حيث: (أ) الشكل، (ب) الحجم، (ج) ترتيب الجسيمات، (د) قابلية الانضغاط، مع ذكر مثالين لكل منهما.', null, null, 'فهم', 'مقارنة', 'متوسط', 'الكتاب ص 45 — المواد الصلبة والسوائل'),
('essay', 2, 'قال طالب: «الشمع لين، فهو ليس مادة صلبة، أما الأسمنت فقاس فهو صلب». قيّم هذا الادعاء، مبيّنًا على أي أساس تُحدَّد الحالة الصلبة، ثم اذكر خاصيتين تجمعان الأسمنت والشمع.', null, null, 'تحليل', 'تقويم ادعاء وتبرير', 'صعب', 'الكتاب ص 45 — المواد الصلبة'),
