('mcq', 1, 3, 'جسيمات السائل أقل تراصًّا من جسيمات الصلب وليست ثابتة في مكانها، فتستطيع الحركة وتجاوز بعضها بعضًا، أما جسيمات الصلب فمتراصة بإحكام.', '["العكس صحيح؛ فللصلب شكل محدد، أما السائل فيأخذ شكل الوعاء.","كل من السائل والصلب غير قابل للانضغاط.","جسيمات السائل أقل تراصًّا من جسيمات الصلب وليست أكثر.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (18%)"}],"at":"2026-10-18T03:32:48.157Z"}'::jsonb),
('mcq', 2, 1, 'الماء سائل يأخذ شكل الوعاء الذي يوضع فيه، أما الحجر فمادة صلبة جسيماتها متراصة بإحكام فتحتفظ بشكلها المحدد ولا تأخذ شكل الوعاء.', '["الحجر مادة صلبة لا تأخذ شكل الوعاء الذي توضع فيه.","","العكس هو الصحيح؛ فالسائل هو الذي يأخذ شكل الوعاء.","السائل يأخذ شكل الوعاء ولا يحتفظ بشكل ثابت."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (13%)"}],"at":"2026-10-18T03:32:48.158Z"}'::jsonb),
('mcq', 3, 2, 'الصلب والسائل كلاهما غير قابل للانضغاط، وكلاهما يتمدد عند التسخين؛ بسبب الطريقة التي ترتبط بها جسيماتهما.', '["الصلب فقط لا يأخذ شكل الوعاء؛ فهذه الخاصية للسائل وليست مشتركة.","تُضغط الغازات بسهولة، أما الصلب والسائل فلا يمكن ضغطهما إلى حجم أصغر.","","للصلب وحده شكل وحجم محددان، أما السائل فشكله يتغير بتغير الوعاء."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (25%)"}],"at":"2026-10-18T03:32:48.158Z"}'::jsonb),
('mcq', 4, 0, 'جسيمات السائل أقل تراصًّا من جسيمات الصلب وليست ثابتة في أماكنها؛ فهي قادرة على الحركة وتجاوز بعضها بعضًا، وهذا يسمح للسائل بالجريان وأخذ شكل الوعاء.', '["","لو كانت جسيمات السائل متراصة بإحكام كالصلب لما جرى السائل ولاحتفظ بشكله.","تباعد الجسيمات الشديد صفة الغاز، أما السائل فحجمه ثابت وقد لا يملأ الوعاء كله.","ثبات الجسيمات في أماكنها صفة الصلب، أما جسيمات السائل فتتحرك."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (5%)"}],"at":"2026-10-18T03:32:48.158Z"}'::jsonb),
('mcq', 5, 3, 'المادة الصلبة لا تُحدَّد بمدى تماسكها أو قساوتها؛ فالأسمنت قاس والشمع لين وكلاهما مادة صلبة لأن لكل منهما شكلًا وحجمًا محددين.', '["لين الشمع لا يعني أنه سائل؛ فالشمع له شكل وحجم محددان كالأسمنت.","قساوة المادة لا تحدد حالتها، والأسمنت صلب والشمع كذلك.","الربط بين الصلابة والقساوة خطأ؛ فالمادة القاسية والمادة اللينة قد تكونان صلبتين معًا.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (9%)"}],"at":"2026-10-18T03:32:48.159Z"}'::jsonb),
('mcq', 6, 1, 'الدم سائل والحديد صلب، فهذا هو الزوج الوحيد الذي يبدأ بسائل وينتهي بصلب.', '["الزئبق سائل لكن الهواء غاز وليس صلبًا.","","الماء سائل لكن الأكسجين غاز وليس صلبًا.","السكر صلب والزئبق سائل، فترتيب الحالتين معكوس."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (11%)"}],"at":"2026-10-18T03:32:48.159Z"}'::jsonb),
('mcq', 7, 2, 'حجم السائل ثابت بغض النظر عن حجم الوعاء الذي يحتويه، لذلك يبقى 50 mL في الوعاءين، أما شكله فيتغير بحسب الوعاء، ولا ينضغط لأنه غير قابل للانضغاط.', '["السائل لا يتمدد ليملأ الوعاء؛ فهذه صفة الغاز، أما السائل فحجمه ثابت.","السائل لا يملأ الوعاء بالضرورة؛ فحجمه ثابت وقد لا يملأ الوعاء كله.","","السائل غير قابل للانضغاط، فلا يقل حجمه عند نقله."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (8%)"}],"at":"2026-10-18T03:32:48.159Z"}'::jsonb),
('essay', 1, null::int, null, null, 'المادة الصلبة لها شكل محدد، أما السائل فيأخذ شكل الوعاء الذي يوضع فيه. حجم كل منهما ثابت. جسيمات الصلب متراصة بإحكام وثابتة في أماكنها، أما جسيمات السائل فأقل تراصًّا وغير ثابتة في أماكنها فتتحرك وتتجاوز بعضها. كل من الصلب والسائل غير قابل للانضغاط. أمثلة الصلب: الخشب والحديد، وأمثلة السائل: الماء والدم.', '["الصلب له شكل محدد والسائل يأخذ شكل الوعاء","حجم كل منهما ثابت","جسيمات الصلب متراصة بإحكام وجسيمات السائل أقل تراصًّا وتتحرك","كل منهما غير قابل للانضغاط","مثالان صحيحان لكل من الصلب والسائل"]'::jsonb, '[]'::jsonb, '[{"element":"المقارنة في الشكل","marks":1},{"element":"المقارنة في الحجم","marks":1},{"element":"المقارنة في ترتيب الجسيمات","marks":1},{"element":"المقارنة في الانضغاط","marks":1},{"element":"مثالان صحيحان لكل منهما","marks":1}]'::jsonb, '[{"level":"5 درجات","description":"مقارنة صحيحة في المحاور الأربعة مع أمثلة صحيحة"},{"level":"3–4 درجات","description":"مقارنة صحيحة في ثلاثة محاور أو أربعة مع نقص في الأمثلة"},{"level":"1–2 درجة","description":"مقارنة صحيحة في محور واحد أو محورين"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["القول إن السائل قابل للانضغاط","القول إن حجم السائل يتغير بتغير الوعاء","عدّ الأمثلة اللينة (كالشمع) سوائل"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (25%)"}],"at":"2026-10-18T03:32:48.159Z"}'::jsonb),
('essay', 2, null::int, null, null, 'الادعاء غير صحيح؛ فالمادة الصلبة لا تُحدَّد بمدى تماسكها أو قساوتها، فالأسمنت قاس والشمع لين وكلاهما مادة صلبة. تُحدَّد الحالة الصلبة بأن للمادة شكلًا وحجمًا محددين، وأن جسيماتها متراصة بإحكام. ويشترك الأسمنت والشمع في أن لكل منهما شكلًا وحجمًا محددين، وأنهما غير قابلين للانضغاط (ولا يأخذان شكل الوعاء الذي يوضعان فيه).', '["الادعاء غير صحيح","الحالة الصلبة لا تحدد بالقساوة أو التماسك","الصلب له شكل وحجم محددان وجسيماته متراصة بإحكام","خاصيتان مشتركتان صحيحتان (شكل محدد، حجم محدد، عدم الانضغاط)"]'::jsonb, '[]'::jsonb, '[{"element":"الحكم بعدم صحة الادعاء مع التعليل","marks":1},{"element":"أساس تحديد الحالة الصلبة","marks":1},{"element":"خاصيتان مشتركتان صحيحتان","marks":2}]'::jsonb, '[{"level":"4 درجات","description":"حكم معلل صحيح، وأساس صحيح للحالة الصلبة، وخاصيتان مشتركتان صحيحتان"},{"level":"2–3 درجات","description":"إجابة صحيحة عن بندين أو ثلاثة"},{"level":"1 درجة","description":"إجابة صحيحة عن بند واحد"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["ربط الحالة الصلبة بالقساوة","عدّ الشمع سائلًا لأنه يلين بالتسخين","ذكر خاصية مميزة للسائل كخاصية مشتركة"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (10%)"}],"at":"2026-10-18T03:32:48.160Z"}'::jsonb),
('essay', 3, null::int, null, null, '(أ) جسيمات الحجر (المادة الصلبة) متراصة بإحكام فلا تتحرك من أماكنها فيبقى شكله ثابتًا، أما جسيمات الماء (السائل) فأقل تراصًّا وغير ثابتة في أماكنها، فتتحرك وتتجاوز بعضها بعضًا، فيجري الماء ويأخذ شكل الوعاء. (ب) لأن جسيمات الماء متقاربة بعضها من بعض بحيث لا توجد بينها فراغات كبيرة يمكن أن تقترب فيها الجسيمات، ولذلك لا يمكن ضغطه إلى حجم أصغر.', '["جسيمات الصلب متراصة بإحكام فيثبت الشكل","جسيمات السائل أقل تراصًّا وتتحرك وتتجاوز بعضها","السائل يجري فيأخذ شكل الوعاء","تقارب جسيمات السائل يجعله غير قابل للانضغاط"]'::jsonb, '[]'::jsonb, '[{"element":"تفسير ثبات شكل الحجر بتراص جسيماته","marks":1},{"element":"تفسير أخذ الماء شكل الوعاء بحركة جسيماته وتجاوزها","marks":1},{"element":"تفسير عدم انضغاط الماء","marks":2}]'::jsonb, '[{"level":"4 درجات","description":"تفسير صحيح لثبات شكل الصلب ولجريان السائل ولعدم انضغاطه"},{"level":"2–3 درجات","description":"تفسير صحيح لبندين أو ثلاثة"},{"level":"1 درجة","description":"تفسير صحيح لبند واحد"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["القول إن جسيمات السائل متباعدة جدًّا","القول إن جسيمات الصلب لا تتجاور","ذكر الوصف دون ربطه بترتيب الجسيمات"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (10%)"}],"at":"2026-10-18T03:32:48.160Z"}'::jsonb)
