('mcq', 1, 'أيّ العبارات الآتية تميّز «البخار» عن «الغاز»؟', null, '["هو الحالة الغازية لمادة تكون صلبة أو سائلة في درجات الحرارة العادية","هو حالة رابعة للمادة تختلف عن الحالة الغازية","هو مادة جسيماتها متراصة بإحكام كالمواد الصلبة","هو غاز لا يأخذ شكل الإناء الذي يوضع فيه"]'::jsonb, 'فهم', 'تمييز مفهومين', 'سهل', 'الكتاب ص 46 — الغازات'),
('mcq', 2, 'لماذا يُسمّى الأكسجين في الهواء «غازًا» بينما يُسمّى الماء في الحالة الغازية «بخار ماء»؟', null, '["لأن الأكسجين عنصر والماء مركب","لأن جسيمات بخار الماء متراصة أكثر من جسيمات الأكسجين","لأن الأكسجين يوجد غازًا في درجات الحرارة العادية بينما الماء يوجد سائلًا","لأن الأكسجين لا يأخذ شكل الإناء الذي يوضع فيه"]'::jsonb, 'فهم', 'تفسير', 'سهل', 'الكتاب ص 46 — الغازات'),
('mcq', 3, 'أيّ مما يأتي يُسمّى بخارًا؟', null, '["الأكسجين الموجود في الهواء","الزئبق السائل عند تحوله إلى الحالة الغازية","النيتروجين المضغوط في أسطوانة","الهيدروجين في بالون"]'::jsonb, 'فهم', 'تصنيف أمثلة', 'متوسط', 'الكتاب ص 46 — الغازات'),
('mcq', 4, 'يبين الجدول حالة أربع مواد عند 25°C. أيّ هذه المواد تسمّى حالتها الغازية «غازًا» وليس «بخارًا» عند 25°C؟', '{"headers":["المادة","الحالة عند 25°C"],"rows":[["الماء","سائل"],["الزئبق","سائل"],["كلوريد الصوديوم","صلب"],["الأكسجين","غاز"]]}'::jsonb, '["الماء السائل","الزئبق السائل","كلوريد الصوديوم الصلب","الأكسجين الغازي"]'::jsonb, 'تطبيق', 'تطبيق على بيانات', 'متوسط', 'الكتاب ص 46 — الغازات'),
('mcq', 5, 'ما الصفة المشتركة بين الغاز والبخار؟', null, '["كلاهما في الحالة الغازية وجسيماته متباعدة جدًّا","كلاهما يوجد سائلًا في درجات الحرارة العادية","كلاهما غير قابل للانضغاط","كلاهما له شكل وحجم محددان"]'::jsonb, 'فهم', 'تحديد صفة مشتركة', 'متوسط', 'الكتاب ص 46 — الغازات'),
('mcq', 6, 'أيّ العبارات الآتية تصف الغاز وصفًا صحيحًا؟', null, '["جسيماته متراصة بإحكام في أماكن ثابتة","لا يملأ الإناء الذي يوضع فيه بل يستقر في قاعه","يأخذ شكل الإناء وحجمه ويُضغط بسهولة","حجمه ثابت مهما كان حجم الإناء"]'::jsonb, 'فهم', 'تحديد وصف صحيح', 'سهل', 'الكتاب ص 46 — الغازات'),
('mcq', 7, 'تصاعد من إبريق يغلي الماء في حالته الغازية، وعُبّئ غاز النيتروجين في أسطوانة. ما الاسم الأنسب للمادة الغازية في كل حالة على الترتيب؟', null, '["غاز، غاز","بخار، غاز","بخار، بخار","غاز، بخار"]'::jsonb, 'تطبيق', 'تطبيق على موقف', 'صعب', 'الكتاب ص 46 — الغازات'),
('essay', 1, 'وضّح الفرق بين «الغاز» و«البخار» مع ذكر مثال على كل منهما، ثم بيّن لماذا يسمى بخار الماء بخارًا.', null, null, 'فهم', 'مقارنة', 'متوسط', 'الكتاب ص 46 — الغازات'),
('essay', 2, 'حدّد في كلٍّ مما يأتي هل يُسمّى «غازًا» أم «بخارًا» مع التعليل، علمًا أن حالة المادة المذكورة عند درجة حرارة الغرفة: (أ) الهيليوم (غاز عند درجة حرارة الغرفة)، (ب) الحالة الغازية للماء (سائل عند درجة حرارة الغرفة)، (ج) الحالة الغازية للزئبق (سائل عند درجة حرارة الغرفة)، (د) النيتروجين (غاز عند درجة حرارة الغرفة).', null, null, 'تطبيق', 'تصنيف مع تعليل', 'متوسط', 'الكتاب ص 46 — الغازات'),
