from (values
('mcq', 1, 0, 'كلمة بخار تشير إلى الحالة الغازية لمادة توجد عادة بشكل صلب أو سائل في درجات الحرارة العادية، أما الغاز فمادة توجد في الحالة الغازية في درجات الحرارة العادية.', '["","البخار ليس حالة رابعة؛ فهو الحالة الغازية نفسها لمادة تكون صلبة أو سائلة عادة.","جسيمات البخار متباعدة جدًّا كجسيمات الغاز، وليست متراصة.","البخار كالغاز يأخذ شكل الإناء الذي يملؤه وحجمه."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (38%)"}],"at":"2026-10-18T03:32:48.161Z"}'::jsonb),
('mcq', 2, 2, 'يوجد الأكسجين في الحالة الغازية في درجات الحرارة العادية فيسمى غازًا، أما الماء فيوجد سائلًا في هذه الدرجات، فتسمى حالته الغازية بخارًا.', '["التسمية لا تعتمد على كون المادة عنصرًا أو مركبًا، بل على حالتها في درجات الحرارة العادية.","جسيمات بخار الماء متباعدة جدًّا كجسيمات الغاز، وليست متراصة.","","الأكسجين يأخذ شكل الإناء وحجمه كأي غاز، وهذه ليست أساس التسمية."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (17%)"}],"at":"2026-10-18T03:32:48.161Z"}'::jsonb),
('mcq', 3, 1, 'الزئبق مادة توجد سائلة في درجات الحرارة العادية، فتسمى حالته الغازية بخارًا. أما الأكسجين والنيتروجين والهيدروجين فتوجد غازات في درجات الحرارة العادية.', '["الأكسجين يوجد في الحالة الغازية في درجات الحرارة العادية، فيسمى غازًا.","","النيتروجين يوجد في الحالة الغازية في درجات الحرارة العادية، فيسمى غازًا.","الهيدروجين يوجد في الحالة الغازية في درجات الحرارة العادية، فيسمى غازًا."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (15%)"}],"at":"2026-10-18T03:32:48.161Z"}'::jsonb),
('mcq', 4, 3, 'الأكسجين مادة توجد في الحالة الغازية عند 25°C (درجة حرارة عادية)، فتسمى «غازًا». أما الماء والزئبق وكلوريد الصوديوم فتوجد سائلة أو صلبة عند 25°C، فتسمى حالتها الغازية «بخارًا».', '["الماء سائل عند 25°C، فتسمى حالته الغازية بخارًا.","الزئبق سائل عند 25°C، فتسمى حالته الغازية بخارًا.","كلوريد الصوديوم صلب عند 25°C، فتسمى حالته الغازية بخارًا.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (14%)"}],"at":"2026-10-18T03:32:48.161Z"}'::jsonb),
('mcq', 5, 0, 'الغاز والبخار كلاهما في الحالة الغازية، وجسيمات كل منهما متباعدة جدًّا، ويختلفان فقط في الحالة التي توجد عليها المادة في درجات الحرارة العادية.', '["","الغاز يوجد غازًا في درجات الحرارة العادية، وليس سائلًا.","كلاهما في الحالة الغازية فينضغط بسهولة.","الغاز والبخار يأخذان شكل الإناء وحجمه، فلا يكون لهما شكل أو حجم محددان."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (11%)"}],"at":"2026-10-18T03:32:48.162Z"}'::jsonb),
('mcq', 6, 2, 'جسيمات الغاز متباعدة جدًّا عن بعضها، لذلك يأخذ شكل الإناء الذي يملؤه وحجمه، وينضغط بسهولة.', '["هذا وصف الحالة الصلبة، أما جسيمات الغاز فمتباعدة جدًّا.","الغاز يملأ الإناء كله ولا يستقر في قاعه.","","حجم السائل هو الثابت، أما الغاز فيأخذ حجم الإناء."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (38%)"}],"at":"2026-10-18T03:32:48.163Z"}'::jsonb),
('mcq', 7, 1, 'الماء يوجد سائلًا في درجات الحرارة العادية فتسمى حالته الغازية بخارًا، أما النيتروجين فيوجد غازًا في درجات الحرارة العادية فيسمى غازًا؛ فالترتيب: بخار، غاز.', '["الماء سائل في درجات الحرارة العادية، فتسمى حالته الغازية بخارًا لا غازًا.","","النيتروجين يوجد غازًا في درجات الحرارة العادية، فلا يسمى بخارًا.","الترتيب معكوس؛ فالماء بخار والنيتروجين غاز."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (13%)"}],"at":"2026-10-18T03:32:48.163Z"}'::jsonb),
('essay', 1, null::int, null, null, 'الغاز كلمة تشير إلى مادة توجد في الحالة الغازية في درجات الحرارة العادية، ومثاله الأكسجين. أما البخار فيشير إلى الحالة الغازية لمادة توجد عادة بشكل صلب أو سائل في درجات الحرارة العادية، ومثاله بخار الماء. ويسمى بخار الماء بخارًا لأن الماء يوجد بشكل سائل في درجات الحرارة العادية.', '["الغاز: مادة توجد في الحالة الغازية في درجات الحرارة العادية","البخار: الحالة الغازية لمادة توجد عادة صلبة أو سائلة","مثال صحيح على الغاز","مثال صحيح على البخار مع تعليل تسمية بخار الماء بأن الماء سائل عادة"]'::jsonb, '[]'::jsonb, '[{"element":"تعريف الغاز","marks":1},{"element":"تعريف البخار","marks":1},{"element":"مثال صحيح لكل منهما","marks":1},{"element":"تعليل تسمية بخار الماء","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"تعريف صحيح للغاز والبخار، ومثالان صحيحان، وتعليل صحيح للتسمية"},{"level":"2–3 درجات","description":"إجابة صحيحة عن بندين أو ثلاثة"},{"level":"1 درجة","description":"إجابة صحيحة عن بند واحد"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["اعتبار الغاز والبخار شيئًا واحدًا","التمييز بينهما بحسب تراص الجسيمات","القول إن بخار الماء ليس في الحالة الغازية"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (17%)"}],"at":"2026-10-18T03:32:48.163Z"}'::jsonb),
('essay', 2, null::int, null, null, '(أ) غاز؛ لأن الهيليوم يوجد في الحالة الغازية في درجات الحرارة العادية. (ب) بخار؛ لأن الماء يوجد سائلًا في درجات الحرارة العادية. (ج) بخار؛ لأن الزئبق يوجد سائلًا في درجات الحرارة العادية. (د) غاز؛ لأن النيتروجين يوجد في الحالة الغازية في درجات الحرارة العادية.', '["الهيليوم غاز","الحالة الغازية للماء بخار","الحالة الغازية للزئبق بخار","النيتروجين غاز","التعليل بحالة المادة في درجات الحرارة العادية"]'::jsonb, '[]'::jsonb, '[{"element":"(أ) التسمية مع التعليل","marks":1},{"element":"(ب) التسمية مع التعليل","marks":1},{"element":"(ج) التسمية مع التعليل","marks":1},{"element":"(د) التسمية مع التعليل","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"تسمية صحيحة للحالات الأربع مع تعليل لكل منها"},{"level":"2–3 درجات","description":"تسمية صحيحة معللة لحالتين أو ثلاث"},{"level":"1 درجة","description":"تسمية صحيحة معللة لحالة واحدة، أو تسمية دون تعليل"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["تسمية الحالة الغازية للماء غازًا","التعليل بكون المادة عنصرًا أو مركبًا","ذكر التسمية دون ربطها بحالة المادة في درجة الحرارة العادية"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (15%)"}],"at":"2026-10-18T03:32:48.164Z"}'::jsonb),
('essay', 3, null::int, null, null, 'جسيمات الغاز متباعدة جدًّا بعضها عن بعض بالمقارنة بجسيمات المواد الصلبة والسائلة، لذلك يمكن تقريبها من بعضها فتنضغط الغازات بسهولة. أما السوائل فجسيماتها متقاربة وترتبط بطريقة تجعلها غير قابلة للانضغاط. وينطبق ذلك على بخار الماء؛ لأنه الماء في الحالة الغازية، فجسيماته متباعدة جدًّا مثل جسيمات أي غاز، فهو يأخذ شكل الإناء وحجمه وينضغط بسهولة.', '["جسيمات الغاز متباعدة جدًّا فتنضغط بسهولة","جسيمات السائل متقاربة فلا ينضغط","بخار الماء في الحالة الغازية فينضغط كالغاز","التعليل بتباعد جسيمات بخار الماء"]'::jsonb, '[]'::jsonb, '[{"element":"تفسير انضغاط الغاز بتباعد جسيماته","marks":1},{"element":"تفسير عدم انضغاط السائل بتقارب جسيماته","marks":1},{"element":"الحكم بأن بخار الماء ينضغط","marks":1},{"element":"تعليل ذلك بأنه في الحالة الغازية وجسيماته متباعدة","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"تفسير صحيح للغاز والسائل، وحكم صحيح معلل لبخار الماء"},{"level":"2–3 درجات","description":"إجابة صحيحة عن بندين أو ثلاثة"},{"level":"1 درجة","description":"إجابة صحيحة عن بند واحد"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["القول إن البخار سائل فلا ينضغط","الخلط بين تراص الجسيمات في الصلب وتباعدها في الغاز","ذكر النتيجة دون تفسير"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (17%)"}],"at":"2026-10-18T03:32:48.164Z"}'::jsonb)
