('mcq', 3, 3, 'اللون والرائحة والقساوة خواص يمكن ملاحظتها أو قياسها دون تغيير تركيب العينة، فهي جميعًا فيزيائية.', '["الكثافة فيزيائية، لكن تكوّن الصدأ خاصية كيميائية.","اللون فيزيائي، لكن تغير لون النحاس بالتفاعل مع الهواء خاصية كيميائية.","الرائحة فيزيائية، لكن تكوّن مركب جديد عند الاتحاد مع حمض خاصية كيميائية.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (15%)"}],"at":"2026-10-18T03:32:48.165Z"}'::jsonb),
('mcq', 4, 0, 'المادة النقية ذات تركيب منتظم وثابت، فتكون خواصها الفيزيائية ثابتة ويمكن تسجيلها واستعمالها في تعرّف المواد.', '["","تركيب المادة النقية لا يتغير من عينة إلى أخرى.","الكتلة تعتمد على كمية المادة فتتغير بتغير حجم العينة.","درجة الحرارة قد تغير حالة المادة وبعض خواصها، وليست هذه علة ثبات الخواص."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (36%)"}],"at":"2026-10-18T03:32:48.165Z"}'::jsonb),
('mcq', 5, 1, 'الشكل واللون والوزن تُلاحظ أو تُقاس دون تغيير في تركيب القلم، فهي خواص فيزيائية.', '["ملاحظة الشكل واللون والوزن لا تغير تركيب القلم؛ فهي ليست كيميائية.","","تصنيف الخاصية لا يعتمد على كون المادة نقية فقط، وهذه الخواص فيزيائية لا كيميائية.","هذه خواص حقيقية للمادة، وهي خواص فيزيائية."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (9%)"}],"at":"2026-10-18T03:32:48.165Z"}'::jsonb),
('mcq', 6, 3, 'قياس الكتلة وملاحظة اللون لا يغيران تركيب العينة، فهما قياس لخاصيتين فيزيائيتين.', '["الحرق يغير تركيب الخشب وتتكون مواد جديدة، فهو يبين خاصية كيميائية.","تكوّن الصدأ ينتج عن اتحاد الحديد بالأكسجين، فهو يغير التركيب ويبين خاصية كيميائية.","تكوّن مركب جديد يعني تغير تركيب العينة، فهو خاصية كيميائية.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (17%)"}],"at":"2026-10-18T03:32:48.166Z"}'::jsonb),
('mcq', 7, 2, 'تكون المادة سائلة عند 25°C إذا كانت درجة انصهارها أقل من 25°C ودرجة غليانها أعلى من 25°C، وهذا ينطبق على الزئبق (انصهاره -39°C وغليانه 357°C).', '["درجة غليان الأكسجين -183°C أقل من 25°C، فهو غاز عند 25°C.","درجة انصهار كلوريد الصوديوم 801°C أعلى من 25°C، فهو صلب عند 25°C.","","درجة انصهار السكر 185°C أعلى من 25°C، فهو صلب عند 25°C."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (16%)"}],"at":"2026-10-18T03:32:48.166Z"}'::jsonb),
('essay', 1, null::int, null, null, 'الخاصية الفيزيائية هي خاصية يمكن ملاحظتها أو قياسها دون التغير في تركيب العينة. ومن أمثلتها: الكثافة، واللون، والرائحة، والقساوة، ودرجة الانصهار، ودرجة الغليان.', '["الخاصية الفيزيائية يمكن ملاحظتها أو قياسها","دون تغير تركيب العينة","ثلاثة أمثلة صحيحة"]'::jsonb, '[]'::jsonb, '[{"element":"ذكر أن الخاصية تُلاحظ أو تُقاس","marks":1},{"element":"ذكر شرط عدم تغير تركيب العينة","marks":1},{"element":"ذكر ثلاثة أمثلة صحيحة (مثالان صحيحان على الأقل لنيل الدرجتين، ومثال واحد لنيل درجة)","marks":2}]'::jsonb, '[{"level":"4 درجات","description":"تعريف كامل وثلاثة أمثلة صحيحة"},{"level":"2–3 درجات","description":"تعريف ناقص أو أمثلة ناقصة"},{"level":"1 درجة","description":"ذكر جزء من التعريف أو مثال واحد فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["إغفال شرط عدم تغير التركيب","ذكر خاصية كيميائية (كالصدأ) مثالًا على الخاصية الفيزيائية","الخلط بين الخاصية الفيزيائية والتغير في التركيب"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (9%)"}],"at":"2026-10-18T03:32:48.166Z"}'::jsonb),
('essay', 2, null::int, null, null, 'تصف الخواص الفيزيائية المواد النقية لأن المادة النقية ذات تركيب منتظم وثابت، فتكون خواصها ثابتة لا تتغير من عينة إلى أخرى. ولذلك يسجل العلماء خواص المواد مثل الكثافة واللون والرائحة والقساوة ودرجتي الانصهار والغليان، ثم يقارنون خواص مادة مجهولة بالخواص المسجلة لتعرّفها.', '["المادة النقية ذات تركيب منتظم وثابت","خواصها الفيزيائية ثابتة","العلماء يسجلون هذه الخواص","يستعملونها في تعرّف المواد بالمقارنة"]'::jsonb, '[]'::jsonb, '[{"element":"تعليل ثبات الخواص بثبات التركيب","marks":2},{"element":"ذكر أن العلماء يسجلون الخواص","marks":1}]'::jsonb, '[{"level":"3 درجات","description":"تعليل صحيح لثبات الخواص مع توضيح استعمالها في تعرّف المواد"},{"level":"درجتان","description":"تعليل صحيح دون توضيح الاستعمال"},{"level":"1 درجة","description":"ذكر أن الخواص تستعمل في تعرّف المواد دون تعليل"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["القول إن تركيب المادة النقية يتغير","الاقتصار على ذكر أمثلة الخواص دون تعليل","الخلط بين المادة النقية والمخلوط"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (3 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (36%)"}],"at":"2026-10-18T03:32:48.166Z"}'::jsonb),
('essay', 3, null::int, null, null, 'الخواص الفيزيائية: (1) بني محمر لامع، (2) قابلة للسحب والطرق، (4) كثافتها 8.96 g/cm³؛ لأن كلًّا منها يمكن ملاحظته أو قياسه دون تغير في تركيب النحاس. أما (3) و(5) فليستا فيزيائيتين؛ لأن كلًّا منهما يحدث عند تفاعل النحاس مع مادة أخرى فيتكوّن مركب جديد ويتغير التركيب، فهما خاصيتان كيميائيتان.', '["(1) و(2) و(4) فيزيائية","(3) و(5) غير فيزيائية (كيميائية)","المعيار: ملاحظة أو قياس دون تغير التركيب","(3) و(5) تتضمنان تكوّن مركب جديد"]'::jsonb, '[]'::jsonb, '[{"element":"تصنيف (1) و(2) و(4) فيزيائية","marks":1},{"element":"تصنيف (3) و(5) غير فيزيائية","marks":1},{"element":"ذكر معيار التصنيف (دون تغير التركيب)","marks":1},{"element":"تعليل (3) و(5) بتكوّن مركب جديد","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"تصنيف صحيح للخواص الخمس مع المعيار والتعليل"},{"level":"2–3 درجات","description":"تصنيف صحيح لمعظم الخواص مع نقص في المعيار أو التعليل"},{"level":"1 درجة","description":"تصنيف صحيح لخاصية أو خاصيتين فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["عدّ تغير اللون بالتفاعل مع الهواء خاصية فيزيائية","عدّ تكوّن المحلول الأزرق مع الأمونيا خاصية فيزيائية","التصنيف دون ذكر معيار"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (7%)"}],"at":"2026-10-18T03:32:48.167Z"}'::jsonb)
