('mcq', 1, 0, 'الكثافة خاصية مميزة لأنها لا تعتمد على كمية المادة الموجودة، أما الكتلة والحجم والطول فخواص غير مميزة لأنها تعتمد على الكمية.', '["","الكتلة تتغير بتغير كمية المادة، فهي غير مميزة.","الحجم يتغير بتغير كمية المادة، فهو غير مميز.","الطول يتغير بتغير كمية المادة، فهو غير مميز."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (20%)"}],"at":"2026-10-18T03:32:48.167Z"}'::jsonb),
('mcq', 2, 3, 'الخواص المميزة (كالكثافة ودرجتي الانصهار والغليان) لا تعتمد على كمية المادة، أما الخواص غير المميزة (كالكتلة والطول والحجم) فتعتمد على كمية المادة الموجودة.', '["هذا عكس الصحيح؛ فغير المميزة هي التي تعتمد على الكمية.","الخاصية المميزة لا تعتمد على الكمية، وإلا لما صلحت لتعرّف المادة.","الخاصية المميزة لا تتغير بتغير الحجم أو الكمية، أما غير المميزة فتتغير بتغيرهما.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (20%)"}],"at":"2026-10-18T03:32:48.168Z"}'::jsonb),
('mcq', 3, 2, 'الكتلة (27.0 g و135 g) والحجم (2.00 cm³ و10.0 cm³) تغيرا بتغير كمية العينة، فهما غير مميزتين، بينما بقيت الكثافة 13.5 g/cm³ في العينتين، فهي خاصية مميزة.', '["الكتلة اختلفت بين العينتين (27.0 g و135 g)، فهي غير مميزة.","الحجم اختلف بين العينتين (2.00 cm³ و10.0 cm³)، فهو غير مميز.","","كلتاهما تغيرت بتغير كمية العينة، فلا تصلحان لتعرّف المادة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (20%)"}],"at":"2026-10-18T03:32:48.168Z"}'::jsonb),
('mcq', 4, 1, 'كتلة القطعة تعتمد على كمية المادة فتصبح النصف بعد القسمة، أما الكثافة ودرجتا الانصهار والغليان فخواص مميزة لا تعتمد على الكمية فلا تتغير.', '["الكثافة خاصية مميزة ثابتة عند درجة حرارة وضغط ثابتين مهما كانت الكمية.","","درجة الانصهار خاصية مميزة لا تعتمد على كمية المادة.","درجة الغليان خاصية مميزة لا تعتمد على كمية المادة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (12%)"}],"at":"2026-10-18T03:32:48.168Z"}'::jsonb),
('mcq', 5, 0, 'كثافة مادة ما عند درجة حرارة وضغط ثابتين هي نفسها مهما كانت كمية المادة الموجودة؛ ولذلك هي خاصية مميزة.', '["","الكثافة لا تزداد بزيادة الكمية؛ فعند زيادة الكتلة يزداد الحجم أيضًا فتبقى النسبة ثابتة.","الكثافة لا تقل بزيادة الكمية؛ فهي نسبة الكتلة إلى الحجم وتبقى ثابتة.","الكثافة لا تعتمد على الحجم وحده؛ فهي نسبة كتلة الجسم إلى حجمه وتبقى ثابتة للمادة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (3%)"}],"at":"2026-10-18T03:32:48.168Z"}'::jsonb),
('mcq', 6, 2, 'الرائحة خاصية مميزة لا تعتمد على كمية المادة، وقد تكفي خاصية مميزة واحدة لتحديد المادة، كما في تعرّف التوابل من روائحها.', '["الرائحة لا تعتمد على كمية التابل في تعرّفه، فهي مميزة لا غير مميزة.","شم الرائحة لا يغير تركيب المادة؛ فهي خاصية فيزيائية.","","الرائحة لا تحددها الكتلة؛ فهي خاصية مميزة للمادة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (6%)"}],"at":"2026-10-18T03:32:48.169Z"}'::jsonb),
('mcq', 7, 3, 'الطول يعتمد على كمية المادة فهو خاصية غير مميزة، أما درجة الغليان فلا تعتمد على الكمية فهي خاصية مميزة؛ فالتصنيف: غير مميزة، مميزة.', '["التصنيف معكوس؛ فالطول غير مميز ودرجة الغليان مميزة.","الطول يعتمد على كمية المادة، فهو غير مميز.","درجة الغليان لا تعتمد على كمية المادة، فهي مميزة.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (3%)"}],"at":"2026-10-18T03:32:48.169Z"}'::jsonb),
('essay', 1, null::int, null, null, 'الخواص غير المميزة تعتمد على كمية المادة الموجودة، ومن أمثلتها الكتلة والطول والحجم، ولا تصلح وحدها لتعرّف المادة لأنها تتغير بتغير الكمية. أما الخواص المميزة فلا تعتمد على كمية المادة، ومن أمثلتها الكثافة ودرجة الانصهار ودرجة الغليان، ويمكن تعرّف المادة بخواصها المميزة، وقد تكفي خاصية مميزة واحدة لتحديد المادة.', '["غير المميزة تعتمد على كمية المادة والمميزة لا تعتمد","أمثلة غير المميزة: الكتلة والطول والحجم","أمثلة المميزة: الكثافة ودرجتا الانصهار والغليان","المميزة تستعمل في تعرّف المادة"]'::jsonb, '[]'::jsonb, '[{"element":"المقارنة في الاعتماد على الكمية","marks":1},{"element":"مثالان صحيحان على الخواص غير المميزة","marks":1},{"element":"مثالان صحيحان على الخواص المميزة","marks":1},{"element":"بيان استعمال المميزة في تعرّف المادة","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"مقارنة صحيحة في الاعتماد على الكمية، وأمثلة صحيحة للنوعين، وبيان الاستعمال في التعرّف"},{"level":"2–3 درجات","description":"إجابة صحيحة عن بندين أو ثلاثة"},{"level":"1 درجة","description":"إجابة صحيحة عن بند واحد"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["عكس تعريف المميزة وغير المميزة","عدّ الكتلة أو الحجم خاصية مميزة","عدّ الكثافة خاصية تعتمد على الكمية"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (20%)"}],"at":"2026-10-18T03:32:48.169Z"}'::jsonb),
('essay', 2, null::int, null, null, 'كثافة العينة الأولى = الكتلة ÷ الحجم = 40.5 g ÷ 3.00 cm³ = 13.5 g/cm³. كثافة العينة الثانية = 94.5 g ÷ 7.00 cm³ = 13.5 g/cm³. الكتلة والحجم تغيرا من عينة إلى أخرى لأنهما يعتمدان على كمية المادة فهما غير مميزتين، أما الكثافة فبقيت ثابتة في العينتين (13.5 g/cm³) فهي خاصية مميزة. وبما أن الكثافة تساوي كثافة الزئبق (13.5 g/cm³) والسائل فضي، فيمكن أن تكون المادة زئبقًا.', '["كثافة العينة الأولى 13.5 g/cm³","كثافة العينة الثانية 13.5 g/cm³","الكتلة والحجم غير مميزتين لاعتمادهما على الكمية","الكثافة مميزة لثباتها","المادة يمكن أن تكون زئبقًا لتطابق الكثافة"]'::jsonb, '["الكثافة = الكتلة ÷ الحجم","العينة الأولى: 40.5 g ÷ 3.00 cm³ = 13.5 g/cm³","العينة الثانية: 94.5 g ÷ 7.00 cm³ = 13.5 g/cm³","الكتلة والحجم يختلفان بين العينتين فهما غير مميزتين، والكثافة ثابتة فهي مميزة","الكثافة المحسوبة تطابق كثافة الزئبق 13.5 g/cm³ فيمكن أن تكون المادة زئبقًا"]'::jsonb, '[{"element":"حساب كثافة العينة الأولى بالقيمة والوحدة الصحيحتين","marks":1},{"element":"حساب كثافة العينة الثانية بالقيمة والوحدة الصحيحتين","marks":1},{"element":"تصنيف الكتلة والحجم غير مميزتين والكثافة مميزة مع التعليل","marks":2},{"element":"الاستنتاج بأن المادة يمكن أن تكون زئبقًا","marks":1}]'::jsonb, '[{"level":"5 درجات","description":"حساب صحيح للكثافتين بالوحدة، وتصنيف معلل للخواص الثلاث، واستنتاج صحيح"},{"level":"3–4 درجات","description":"حساب صحيح مع نقص في التعليل أو الاستنتاج"},{"level":"1–2 درجة","description":"حساب صحيح لإحدى العينتين أو تصنيف دون حساب"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["قسمة الحجم على الكتلة بدل الكتلة على الحجم","نسيان وحدة الكثافة g/cm³","عدّ الكتلة خاصية مميزة لأن قيمتها ثابتة لكل عينة"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (13%)"}],"at":"2026-10-18T03:32:48.170Z"}'::jsonb),
('essay', 3, null::int, null, null, 'الكتلة (5.0 g لكل منهما) والمظهر الأبيض متساويان في العينتين فلا يميزان بينهما؛ والكتلة خاصية غير مميزة تعتمد على كمية المادة، واللون أبيض للمادتين. أما درجة الانصهار فتختلف (185°C للسكر و801°C لكلوريد الصوديوم)، وهي خاصية مميزة لا تعتمد على كمية المادة، لذا هي الأنسب للتمييز بين المادتين، إذ تنصهر العينة التي تنصهر عند 185°C وهي السكر، ولا تنصهر عند هذه الدرجة العينة الأخرى.', '["الكتلة غير مميزة وهي متساوية في العينتين فلا تفيد","اللون أبيض في المادتين فلا يفيد","درجة الانصهار تختلف بين المادتين (185°C و801°C)","الخاصية الأنسب هي درجة الانصهار لأنها مميزة لا تعتمد على الكمية"]'::jsonb, '[]'::jsonb, '[{"element":"بيان عدم فائدة الكتلة مع التعليل","marks":1},{"element":"بيان عدم فائدة اللون في التمييز","marks":1},{"element":"اختيار درجة الانصهار خاصية مناسبة","marks":1},{"element":"تعليل الاختيار بأنها مميزة ومختلفة بين المادتين","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"تقويم صحيح للخواص الثلاث، واختيار درجة الانصهار مع تعليل صحيح"},{"level":"2–3 درجات","description":"تقويم صحيح لخاصيتين أو اختيار صحيح بتعليل ناقص"},{"level":"1 درجة","description":"اختيار صحيح دون تعليل"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["الاعتماد على الكتلة للتمييز لأن قيمتها محددة","عدّ اللون كافيًا لتحديد المادة","ذكر درجة الانصهار دون بيان أنها مميزة"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (13%)"}],"at":"2026-10-18T03:32:48.170Z"}'::jsonb)
) as v(type, number, ci, ex, dn, ma, ae, ss, mk, rb, ce, ac)
join public.questions x on x.objective_id = (select id from public.objectives where code = 'K1-C2-L1-O06') and x.type = v.type and x.number = v.number
