select (select id from public.objectives where code = 'K1-C2-L1-O07'), v.type, v.number, v.stem, v.stimulus::jsonb, v.options::jsonb, v.tl, v.qk, v.diff, v.src, 'generated', 'ai_generated'
from (values
('mcq', 1, 'ما المقصود بالخاصية الكيميائية للمادة؟', null, '["صفة يمكن ملاحظتها أو قياسها دون تغيير في تركيب المادة","صفة تعتمد على كمية المادة الموجودة كالكتلة والحجم","قدرة المادة على الاتحاد مع غيرها أو التحول إلى مادة أخرى","قدرة المادة على الانتقال من حالة فيزيائية إلى حالة أخرى"]'::jsonb, 'تذكر', 'تذكر تعريف', 'سهل', 'الكتاب ص 48 — الخواص الكيميائية للمادة'),
('mcq', 2, 'ما التفسير الصحيح لكون تكوّن الصدأ خاصية كيميائية للحديد؟', null, '["لأن الحديد يتحد مع أكسجين الهواء الرطب فتتكون مادة جديدة","لأن الحديد ينصهر عند تسخينه فيتغير شكله","لأن لون الحديد يتغير دون أن يتغير تركيبه","لأن الحديد يذوب في الماء الموجود في الهواء الرطب"]'::jsonb, 'تذكر', 'تذكر مثال', 'سهل', 'الكتاب ص 48 — الخواص الكيميائية للمادة (الصدأ)'),
('mcq', 3, 'أيّ مما يأتي خاصية كيميائية للنحاس؟', null, '["قابليته للسحب والطرق وتشكيله أسلاكًا","كثافته 8.96 g/cm³ عند الظروف العادية","درجة انصهاره 1085°C ودرجة غليانه 2562°C","تكوينه محلولًا شديد الزرقة عند تفاعله مع الأمونيا"]'::jsonb, 'تذكر', 'تذكر مثال', 'متوسط', 'الكتاب ص 48 — الجدول 2-2 خواص النحاس'),
('mcq', 4, 'تغيّر لون صفيحة النحاس من الأحمر إلى الأخضر بعد تعرضها للهواء الرطب مدة طويلة. ماذا يمثل هذا التغير؟', null, '["خاصية فيزيائية؛ لأن اللون صفة يمكن ملاحظتها دون قياس","خاصية كيميائية؛ لأن النحاس يتفاعل مع مواد في الهواء فتتكون مادة جديدة","خاصية فيزيائية؛ لأن النحاس ما زال محتفظًا بتركيبه بعد التغير","خاصية غير مميزة؛ لأن اللون يتوقف على كمية النحاس الموجودة"]'::jsonb, 'فهم', 'تفسير مثال', 'متوسط', 'الكتاب ص 48 — الشكل 2-6 والجدول 2-2 (تحول النحاس إلى الأخضر)'),
('mcq', 5, 'وُضعت قطعة حديد في غاز النيتروجين عند درجة حرارة الغرفة فلم يحدث تغيير كيميائي. ماذا يعني ذلك؟', null, '["أن الحديد لا يملك أي خاصية كيميائية","أن عدم التفاعل خاصية فيزيائية للحديد","أن عدم قدرة الحديد على التغير إلى مادة أخرى خاصية كيميائية أيضًا","أن الحديد يتفاعل مع النيتروجين عند رفع الضغط فقط"]'::jsonb, 'فهم', 'تفسير مفهوم', 'صعب', 'الكتاب ص 48 — الخواص الكيميائية للمادة'),
('mcq', 6, 'تظهر الخواص الكيميائية للمادة عندما:', null, '["يتغير تركيبها باتحادها مع مادة أخرى أو تعرضها لمؤثر كالحرارة","تتغير حالتها من الصلبة إلى السائلة عند ارتفاع درجة الحرارة","يتغير شكلها أو حجمها دون أن يتغير تركيبها","تُقاس كثافتها ودرجتا انصهارها وغليانها في ظروف ثابتة"]'::jsonb, 'تذكر', 'تذكر حقيقة', 'سهل', 'الكتاب ص 48 — الخواص الكيميائية للمادة'),
('mcq', 7, 'تُظهر المادة خاصية كيميائية عندما تتفاعل. أيّ المصطلحات الآتية يشير إلى حدوث تفاعل كيميائي؟', null, '["الانصهار","الاحتراق","التجمد","التكثف"]'::jsonb, 'فهم', 'تمييز مصطلح', 'متوسط', 'الكتاب ص 51 — التغيرات الكيميائية (المصطلحات الدالة على التفاعل الكيميائي)'),
('essay', 1, 'عرّف الخاصية الكيميائية للمادة، ثم اذكر مثالين عليها.', null, null, 'تذكر', 'تعريف وتمثيل', 'سهل', 'الكتاب ص 48 — الخواص الكيميائية للمادة'),
('essay', 2, 'فسّر لماذا يُعدّ تكوّن الصدأ على الحديد خاصية كيميائية، محددًا المواد المتفاعلة، وموضحًا ما يدل على تكوّن مادة جديدة.', null, null, 'فهم', 'تفسير ظاهرة', 'متوسط', 'الكتاب ص 48 و51 — الصدأ مثال على خاصية كيميائية'),
('essay', 3, 'وُضعت قطعة حديد في غاز النيتروجين عند درجة حرارة الغرفة فلم يحدث أي تغيير كيميائي. هل يُعدّ ذلك خاصية كيميائية للحديد؟ علّل إجابتك، ثم قارن بين سلوك الحديد مع النيتروجين وسلوكه في الهواء الرطب.', null, null, 'تحليل', 'تعليل ومقارنة', 'صعب', 'الكتاب ص 48 — الخواص الكيميائية للمادة (الحديد والنيتروجين)')
) as v(type, number, stem, stimulus, options, tl, qk, diff, src)
where not exists (select 1 from public.questions x where x.objective_id = (select id from public.objectives where code = 'K1-C2-L1-O07') and x.type = v.type and x.number = v.number);
insert into public.question_answers (question_id, correct_index, explanation, distractor_notes, model_answer, answer_elements, solution_steps, marks, rubric, common_errors, auto_check)
select x.id, v.ci::int, v.ex::text, v.dn::jsonb, v.ma::text, v.ae::jsonb, v.ss::jsonb, v.mk::jsonb, v.rb::jsonb, v.ce::jsonb, v.ac::jsonb
from (values
('mcq', 1, 2, 'الخاصية الكيميائية تصف قدرة المادة على الاتحاد مع غيرها أو التحول إلى مادة أخرى، وتظهر عندما يتغير تركيب المادة.', '["هذا تعريف الخاصية الفيزيائية، فهي تُلاحَظ أو تُقاس دون تغيير تركيب المادة.","هذا وصف الخواص غير المميزة (فيزيائية) كالكتلة والحجم، وليس الخاصية الكيميائية.","","الانتقال بين الحالات تغير فيزيائي لا يغيّر تركيب المادة، فلا يمثل خاصية كيميائية."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (29%)"}],"at":"2026-10-18T03:32:48.171Z"}'::jsonb),
('mcq', 2, 0, 'يتكوّن الصدأ عند اتحاد الحديد مع أكسجين الهواء الرطب، فيتغير تركيب المادة وتنتج مادة جديدة؛ لذلك يُعدّ تكوّنه خاصية كيميائية للحديد.', '["","الانصهار تغير فيزيائي، ولا علاقة له بتكوّن الصدأ.","تغير اللون دون تغير التركيب يكون فيزيائيًّا، أما الصدأ فمادة جديدة تتكوّن باتحاد الحديد مع الأكسجين.","الصدأ لا ينتج عن ذوبان الحديد في الماء، بل عن اتحاده مع الأكسجين."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (21%)"}],"at":"2026-10-18T03:32:48.171Z"}'::jsonb),
('mcq', 3, 3, 'تفاعل النحاس مع الأمونيا يكوّن مادة جديدة (محلولًا شديد الزرقة)، فهو خاصية كيميائية؛ أما السحب والطرق والكثافة ودرجتا الانصهار والغليان فخواص فيزيائية.', '["قابلية السحب والطرق خاصية فيزيائية، إذ لا يتغير تركيب النحاس عند تشكيله.","الكثافة خاصية فيزيائية تُقاس دون تغيير تركيب المادة.","درجتا الانصهار والغليان خاصيتان فيزيائيتان لا تغيّران تركيب النحاس.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (18%)"}],"at":"2026-10-18T03:32:48.171Z"}'::jsonb),
('mcq', 4, 1, 'يتفاعل النحاس مع المواد الموجودة في الهواء الرطب فتتكون مادة جديدة خضراء، أي يتغير تركيب المادة؛ لذلك فهي خاصية كيميائية.', '["الاعتماد على اللون وحده لا يكفي؛ فاللون هنا تغير لأن مادة جديدة تكوّنت.","","النحاس لا يحتفظ بتركيبه هنا؛ فقد اتحد مع مواد في الهواء وتكوّنت مادة جديدة.","الخواص غير المميزة هي المعتمدة على الكمية كالكتلة والطول، وتغير اللون هنا لا يتعلق بالكمية."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (3%)"}],"at":"2026-10-18T03:32:48.171Z"}'::jsonb),
('mcq', 5, 2, 'عدم قدرة مادة على التغير إلى مادة أخرى في ظروف معينة خاصية كيميائية أيضًا؛ فالحديد لا يتفاعل مع النيتروجين عند درجة حرارة الغرفة.', '["للحديد خواص كيميائية، منها اتحاده مع الأكسجين في الهواء الرطب، وعدم تفاعله مع النيتروجين خاصية كيميائية كذلك.","عدم التفاعل لا يُلاحَظ بقياس الخواص الفيزيائية، بل يتعلق بقدرة المادة على التغير إلى مادة أخرى، فهو كيميائي.","","لا شيء في المعطيات يدل على تفاعل الحديد مع النيتروجين عند رفع الضغط؛ والمقصود أن عدم التفاعل نفسه خاصية كيميائية."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (44%)"}],"at":"2026-10-18T03:32:48.172Z"}'::jsonb),
('mcq', 6, 0, 'تظهر الخاصية الكيميائية عندما يتغير تركيب المادة، وذلك باتحادها مع مادة أخرى أو بتعرضها لمؤثر كالطاقة الحرارية أو الكهربائية.', '["","تغير الحالة تغير فيزيائي لا يغيّر تركيب المادة، فلا يُظهر خاصية كيميائية.","تغير الشكل أو الحجم دون تغير التركيب يرتبط بالخواص الفيزيائية.","قياس الكثافة ودرجتي الانصهار والغليان يتعلق بخواص فيزيائية مميزة، ولا يتطلب تغير التركيب."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (29%)"}],"at":"2026-10-18T03:32:48.172Z"}'::jsonb),
('mcq', 7, 1, 'الاحتراق يشير إلى تفاعل كيميائي تتكوّن فيه مواد جديدة، أما الانصهار والتجمد والتكثف فمصطلحات تشير إلى تغيرات في حالة المادة.', '["الانصهار تغير في الحالة (من صلب إلى سائل) ولا يغيّر تركيب المادة.","","التجمد تغير في الحالة (من سائل إلى صلب) لا يتكوّن فيه مادة جديدة.","التكثف تغير في الحالة (من غاز إلى سائل) لا يتكوّن فيه مادة جديدة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (13%)"}],"at":"2026-10-18T03:32:48.172Z"}'::jsonb),
('essay', 1, null::int, null, null, 'الخاصية الكيميائية قدرة المادة على الاتحاد مع غيرها أو التحول إلى مادة أخرى، وتظهر عندما يتغير تركيب المادة باتحادها مع مادة أخرى أو بتعرضها لمؤثر كالطاقة الحرارية أو الكهربائية. ومن أمثلتها: تكوّن الصدأ عند اتحاد الحديد مع أكسجين الهواء الرطب، وتحول النحاس إلى اللون الأخضر عند تفاعله مع مواد في الهواء الرطب.', '["تعريف الخاصية الكيميائية: قدرة المادة على الاتحاد مع غيرها أو التحول إلى مادة أخرى","تظهر عند تغير تركيب المادة باتحادها مع مادة أخرى أو تعرضها لمؤثر كالحرارة أو الكهرباء","المثال الأول: تكوّن الصدأ عند اتحاد الحديد مع الأكسجين في الهواء الرطب","المثال الثاني: تحول النحاس إلى الأخضر في الهواء الرطب"]'::jsonb, '[]'::jsonb, '[{"element":"تعريف الخاصية الكيميائية","marks":2},{"element":"ذكر متى تظهر الخاصية الكيميائية","marks":1},{"element":"المثال الأول","marks":1},{"element":"المثال الثاني","marks":1}]'::jsonb, '[{"level":"5 درجات","description":"تعريف كامل، وبيان متى تظهر الخاصية، ومثالان صحيحان"},{"level":"3–4 درجات","description":"تعريف صحيح مع نقص في بيان وقت ظهورها أو في أحد المثالين"},{"level":"1–2 درجة","description":"تعريف جزئي أو مثال واحد صحيح فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["تعريف الخاصية الكيميائية بأنها صفة تُلاحَظ دون تغير التركيب، وهذا تعريف الخاصية الفيزيائية","ذكر أمثلة فيزيائية كاللون أو الكثافة بوصفها خواص كيميائية","إغفال أن الخاصية الكيميائية ترتبط بتغير تركيب المادة"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (20%)"}],"at":"2026-10-18T03:32:48.172Z"}'::jsonb),
('essay', 2, null::int, null, null, 'المادتان المتفاعلتان هما الحديد وأكسجين الهواء الرطب، وعند اتحادهما يتغير التركيب فيتكوّن الصدأ؛ وهو مادة بنية تميل إلى البرتقالي على هيئة مسحوق. ويدل على أنه مادة جديدة اختلاف خواصه عن خواص الحديد والأكسجين، فالصدأ لا ينجذب إلى المغناطيس بينما ينجذب إليه الحديد. ولأن قدرة الحديد على الاتحاد مع الأكسجين وتكوين مادة جديدة تصف سلوكه الكيميائي، فتكوّن الصدأ خاصية كيميائية.', '["المتفاعلات: الحديد وأكسجين الهواء الرطب","اتحادهما يغيّر التركيب فتتكوّن مادة جديدة هي الصدأ","الدليل: اختلاف خواص الصدأ (مسحوق بني، لا ينجذب إلى المغناطيس) عن خواص الحديد والأكسجين","الاستنتاج: قدرة الحديد على الاتحاد مع الأكسجين خاصية كيميائية"]'::jsonb, '[]'::jsonb, '[{"element":"تحديد المتفاعلات","marks":1},{"element":"بيان تغير التركيب وتكوّن مادة جديدة","marks":1},{"element":"ذكر دليل اختلاف الخواص عن المتفاعلات","marks":1},{"element":"الاستنتاج بأنها خاصية كيميائية","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"تحديد المتفاعلات، وتفسير تكوّن مادة جديدة، وذكر دليل، واستنتاج صحيح"},{"level":"2–3 درجات","description":"تفسير صحيح مع إغفال الدليل أو الاستنتاج أو تحديد المتفاعلات"},{"level":"1 درجة","description":"ذكر أن الصدأ مادة جديدة دون تفسير"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["القول إن الحديد يتحول إلى صدأ بالتسخين فقط وإغفال دور أكسجين الهواء الرطب","عدّ تغير لون الحديد فقط دليلًا دون ذكر تكوّن مادة جديدة","الخلط بين الصدأ وانصهار الحديد"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (21%)"}],"at":"2026-10-18T03:32:48.172Z"}'::jsonb),
('essay', 3, null::int, null, null, 'نعم، يُعدّ ذلك خاصية كيميائية؛ لأن الخواص الكيميائية تشمل قدرة المادة على التغير إلى مادة أخرى، كما تشمل عدم قدرتها على ذلك، فالحديد لا يتفاعل مع غاز النيتروجين عند درجة حرارة الغرفة. أما في الهواء الرطب فيتحد الحديد مع الأكسجين فيتكوّن الصدأ. فالحديد يتفاعل مع الأكسجين ولا يتفاعل مع النيتروجين في الظروف نفسها، أي أن الخاصية الكيميائية تتوقف على نوع المادة التي يتعرض لها.', '["نعم، عدم القدرة على التغير إلى مادة أخرى خاصية كيميائية أيضًا","الحديد لا يتفاعل مع النيتروجين عند درجة حرارة الغرفة","في الهواء الرطب يتحد الحديد مع الأكسجين فيتكوّن الصدأ","الخاصية الكيميائية تتوقف على نوع المادة الأخرى والظروف"]'::jsonb, '[]'::jsonb, '[{"element":"الحكم بأنها خاصية كيميائية مع التعليل","marks":1},{"element":"عدم تفاعل الحديد مع النيتروجين","marks":1},{"element":"تفاعل الحديد مع أكسجين الهواء الرطب وتكوّن الصدأ","marks":1},{"element":"استنتاج أن السلوك الكيميائي يختلف باختلاف المادة المتفاعلة","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"حكم صحيح مع تعليل، ومقارنة كاملة بين السلوكين، واستنتاج"},{"level":"2–3 درجات","description":"حكم صحيح مع تعليل ومقارنة ناقصة"},{"level":"1 درجة","description":"حكم صحيح دون تعليل"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["الاعتقاد بأن الخاصية الكيميائية لا تكون إلا عند حدوث تفاعل","عدّ عدم التفاعل خاصية فيزيائية","إغفال المقارنة مع تفاعل الحديد مع الأكسجين"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (44%)"}],"at":"2026-10-18T03:32:48.173Z"}'::jsonb)
