('mcq', 4, 2, 'دون 0°C يصبح الماء صلبًا كثافته 0.92 g/cm³، وهي أقل من كثافة الماء السائل 1.00 g/cm³؛ لذلك تطفو الجبال الجليدية.', '["لو كانت كثافة الجليد أكبر من كثافة الماء السائل لغاص فيه، لكن كثافته أقل.","عدم قابلية الجسم للانضغاط لا يحدد الطفو، فالسائل أيضًا غير قابل للانضغاط، والمعيار هو الكثافة.","","الجليد يتكوّن عند درجات حرارة منخفضة (دون 0°C)، ولا يطفو لارتفاع حرارته."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (24%)"}],"at":"2026-10-18T03:32:48.174Z"}'::jsonb),
('mcq', 5, 1, 'الكثافة 0.0006 g/cm³ كثافة غاز؛ والماء يكون غازًا عند درجات حرارة أعلى من 100°C عند ضغط 1 atm.', '["عند 25°C و1 atm يكون الماء سائلًا كثافته 1.00 g/cm³.","","عند درجات أقل من 0°C يكون الماء صلبًا كثافته 0.92 g/cm³.","عند 0°C يكون الماء صلبًا أو سائلًا (كثافته 0.92 أو 1.00 g/cm³) وليس غازًا."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (5%)"}],"at":"2026-10-18T03:32:48.175Z"}'::jsonb),
('mcq', 6, 3, 'تعتمد حالة المادة على درجة حرارة الوسط وضغطه؛ لذلك تتحول معظم المواد من حالة إلى أخرى عندما تتغير درجة الحرارة.', '["تغير الحالة تغير فيزيائي، ولا يعني بالضرورة تغير التركيب الكيميائي.","لا تتغير كتلة المادة بتغير حالتها الفيزيائية.","حالة المادة تتأثر بدرجة الحرارة، فلا تبقى ثابتة عند تغيرها.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (7%)"}],"at":"2026-10-18T03:32:48.175Z"}'::jsonb),
('mcq', 7, 2, 'سلوك الماء الكيميائي اختلف باختلاف درجة الحرارة (غير نشط عند 25°C وسريع التفاعل فوق 100°C)، مما يدل على أن الخواص الكيميائية تعتمد على الظروف كما تعتمد الخواص الفيزيائية.', '["تغير نشاط الماء الكيميائي بتغير الحرارة يدل على أن الخواص الكيميائية تتأثر أيضًا.","تحول الماء إلى غاز تغير في الحالة لا في التركيب؛ والمثال يبين اختلاف خواصه الكيميائية بين الظروف.","","المثال يناقض ذلك، فالماء غير نشط عند 25°C ويتفاعل بسرعة فوق 100°C."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (14%)"}],"at":"2026-10-18T03:32:48.175Z"}'::jsonb),
('essay', 1, null::int, null, null, '(أ) عند 25°C و1 atm يكون الماء سائلًا كثافته 1.00 g/cm³. (ب) عند 120°C و1 atm يكون غازًا كثافته 0.0006 g/cm³. (ج) عند -5°C و1 atm يكون صلبًا (جليدًا) كثافته 0.92 g/cm³. يجب تحديد الضغط ودرجة الحرارة لأن حالة المادة وخواصها الفيزيائية والكيميائية تعتمد على هذه الظروف؛ فالماء نفسه يتغير شكله وكثافته وسلوكه عند تغيرها.', '["عند 25°C و1 atm: سائل كثافته 1.00 g/cm³","عند 120°C و1 atm: غاز كثافته 0.0006 g/cm³","عند -5°C و1 atm: صلب كثافته 0.92 g/cm³","الخواص الفيزيائية والكيميائية تعتمد على الضغط ودرجة الحرارة","تغير الظروف يغيّر حالة المادة وخواصها كالكثافة"]'::jsonb, '[]'::jsonb, '[{"element":"الحالة والكثافة عند 25°C و1 atm","marks":1},{"element":"الحالة والكثافة عند 120°C و1 atm","marks":1},{"element":"الحالة والكثافة عند -5°C و1 atm","marks":1},{"element":"التعليل بأن الخواص تعتمد على الضغط ودرجة الحرارة","marks":2}]'::jsonb, '[{"level":"5 درجات","description":"الحالات والكثافات الثلاث صحيحة مع تعليل كامل"},{"level":"3–4 درجات","description":"حالتان أو ثلاث صحيحة مع تعليل ناقص، أو ثلاث صحيحة دون تعليل"},{"level":"1–2 درجة","description":"ذكر حالة واحدة أو حالتين فقط دون تعليل"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["عكس كثافتي الماء السائل (1.00 g/cm³) والجليد (0.92 g/cm³)","عدّ الماء عند 120°C سائلًا","القول إن الظروف تؤثر في الخواص الفيزيائية فقط"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (32%)"}],"at":"2026-10-18T03:32:48.176Z"}'::jsonb),
('essay', 2, null::int, null, null, 'عند انخفاض درجة الحرارة دون 0°C يتحول الماء السائل إلى الحالة الصلبة (جليد). كثافة الماء السائل 1.00 g/cm³ بينما كثافة الجليد 0.92 g/cm³، أي أن الجليد أقل كثافة من الماء السائل؛ ولذلك تطفو الجبال الجليدية فوق سطح المحيط.', '["دون 0°C يتحول الماء إلى جليد (حالة صلبة)","كثافة الماء السائل 1.00 g/cm³","كثافة الجليد 0.92 g/cm³","الجليد أقل كثافة من الماء السائل فيطفو"]'::jsonb, '[]'::jsonb, '[{"element":"أثر انخفاض الحرارة دون 0°C في حالة الماء","marks":1},{"element":"كثافة الماء السائل 1.00 g/cm³","marks":1},{"element":"كثافة الجليد 0.92 g/cm³","marks":1},{"element":"الربط بين انخفاض الكثافة والطفو","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"تفسير كامل بالكثافتين وأثر الحرارة والربط بالطفو"},{"level":"2–3 درجات","description":"تفسير صحيح مع نقص في الأرقام أو في أثر الحرارة"},{"level":"1 درجة","description":"ذكر أن الجليد أقل كثافة دون تعليل"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["القول إن الجليد يطفو لأنه أخف وزنًا دون مقارنة الكثافتين","الخلط بين كثافة الجليد وكثافة الماء السائل","إغفال أثر انخفاض درجة الحرارة في تحول الماء إلى صلب"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (24%)"}],"at":"2026-10-18T03:32:48.176Z"}'::jsonb),
('essay', 3, null::int, null, null, 'العبارة غير صحيحة؛ فخواص المادة الفيزيائية والكيميائية تعتمد على الظروف التي تُلاحَظ عندها ومنها الضغط ودرجة الحرارة. فالماء مثلًا سائل كثافته 1.00 g/cm³ عند 25°C و1 atm، لكنه عند درجات أعلى من 100°C غاز كثافته 0.0006 g/cm³ ويتفاعل بسرعة مع عدة مواد، وعند درجات أقل من 0°C صلب كثافته 0.92 g/cm³. لذلك يجب تحديد الظروف عند وصف الخواص.', '["الحكم: العبارة غير صحيحة","الخواص الفيزيائية والكيميائية تعتمد على الضغط ودرجة الحرارة","مثال: الماء سائل عند 25°C وغاز فوق 100°C وصلب دون 0°C","تتغير الكثافة وغيرها من الخواص بتغير الظروف"]'::jsonb, '[]'::jsonb, '[{"element":"الحكم الصحيح على العبارة","marks":1},{"element":"ذكر أن الخواص تعتمد على الضغط ودرجة الحرارة","marks":1},{"element":"مثال من خواص الماء بحالتين على الأقل","marks":2}]'::jsonb, '[{"level":"4 درجات","description":"حكم صحيح وتعليل كامل ومثال بحالتين أو أكثر"},{"level":"2–3 درجات","description":"حكم صحيح مع تعليل أو مثال ناقص"},{"level":"1 درجة","description":"حكم صحيح دون تعليل"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["تصديق العبارة والقول إن الخواص ثابتة للمادة دائمًا","حصر تأثير الظروف في الحالة دون الخواص الأخرى كالكثافة","ذكر مثال دون أرقام أو دون ربطه بتغير الظروف"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (15%)"}],"at":"2026-10-18T03:32:48.176Z"}'::jsonb)
