('mcq', 1, 1, 'المادة الكيميائية النقية هي المادة ذات التركيب المنتظم والثابت، ولها دائمًا التركيب والخواص نفسها.', '["هذا وصف المخلوط وليس المادة النقية؛ فتركيب المادة النقية لا يتغير.","","المادة النقية خواصها ثابتة في كل العينات لأن تركيبها ثابت.","حالة المادة (صلبة أو سائلة أو غازية) لا تحدد كونها نقية؛ فالماء النقي سائل."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (15%)"}],"at":"2026-10-18T03:32:48.177Z"}'::jsonb),
('mcq', 2, 3, 'يتكوّن ملح الطعام دائمًا من كلوريد الصوديوم بنسبة 100%، ولا يتغير تركيبه من عينة إلى أخرى.', '["تركيب ملح الطعام لا يتغير بتغير مصدره؛ فهو كلوريد الصوديوم فقط.","ملح الطعام لا يحتوي على ماء بنسبة ثابتة؛ تركيبه كلوريد الصوديوم بنسبة 100%.","الصوديوم أحد مكوّني كلوريد الصوديوم، لكن الملح مركب يتكوّن من الصوديوم والكلور معًا.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (17%)"}],"at":"2026-10-18T03:32:48.177Z"}'::jsonb),
('mcq', 3, 0, 'الماء النقي مادة كيميائية نقية مكوّنة من هيدروجين وأكسجين بتركيب ثابت؛ أما ماء الشرب وماء البحر فيحتويان على معادن ومواد ذائبة أخرى بكميات مختلفة.', '["","ماء البحر يحتوي على كميات مختلفة من المعادن والمواد الذائبة، فتركيبه غير ثابت.","ماء الشرب يحتوي على كميات مختلفة من المعادن والمواد الذائبة بحسب المصدر، فليس نقيًّا.","الهواء مزيج من غازات مختلفة، فليس مادة نقية."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (30%)"}],"at":"2026-10-18T03:32:48.177Z"}'::jsonb),
('mcq', 4, 2, 'ملح الطعام مادة كيميائية نقية؛ لذلك له دائمًا التركيب والخواص نفسها، سواء استُخرج من البحر أو من المنجم.', '["تركيب المادة النقية ثابت ولا يتغير من عينة إلى أخرى.","كلتا العينتين كلوريد الصوديوم بنسبة 100%.","","الخواص ثابتة في المادة النقية مهما اختلف مصدرها."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (13%)"}],"at":"2026-10-18T03:32:48.177Z"}'::jsonb),
('mcq', 5, 2, 'عينات ماء الشرب من أماكن مختلفة تحتوي كميات مختلفة من المعادن والمواد الذائبة الأخرى، فتركيبه غير ثابت؛ ولذلك لا يُعدّ نقيًّا.', '["الماء النقي أيضًا سائل، فحالة المادة لا تحدد كونها نقية.","الهيدروجين والأكسجين هما مكوّنا الماء النقي، وليس هذا سبب عدم نقاء ماء الشرب.","","قيمة الكثافة لا تحدد نقاء المادة؛ والسبب اختلاف تركيب العينات."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (27%)"}],"at":"2026-10-18T03:32:48.177Z"}'::jsonb),
('mcq', 6, 0, 'الماء النقي مادة كيميائية نقية مكوّنة من الهيدروجين والأكسجين.', '["","الكلور ليس من مكونات الماء، ويدخل في تركيب كلوريد الصوديوم.","الكربون ليس من مكونات الماء، ويدخل في تركيب ثاني أكسيد الكربون.","النيتروجين ليس من مكونات الماء."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (17%)"}],"at":"2026-10-18T03:32:48.178Z"}'::jsonb),
('mcq', 7, 1, 'تكون المادة نقية إذا كان تركيبها منتظمًا وثابتًا؛ وثاني أكسيد الكربون يتكوّن دائمًا من الكربون والأكسجين بنسبة ثابتة.', '["الحالة الغازية لا تجعل المادة نقية، فالهواء غاز أيضًا وهو مزيج.","","اللون والرائحة خاصيتان فيزيائيتان لا تحددان نقاء المادة.","وجود الغاز في الهواء مع غازات أخرى لا يعني أنه غير نقي؛ فالنقاء يتعلق بتركيب الغاز نفسه."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (30%)"}],"at":"2026-10-18T03:32:48.178Z"}'::jsonb),
('essay', 1, null::int, null, null, 'من المواد الكيميائية النقية: ملح الطعام (كلوريد الصوديوم)، والماء النقي (هيدروجين وأكسجين)، وثاني أكسيد الكربون (كربون وأكسجين). وتُعدّ مواد نقية لأن كلًّا منها ذو تركيب منتظم وثابت لا يتغير من عينة إلى أخرى، فله دائمًا التركيب والخواص نفسها.', '["مثال أول صحيح كملح الطعام","مثال ثانٍ صحيح كالماء النقي","مثال ثالث صحيح كثاني أكسيد الكربون","التعليل: التركيب منتظم وثابت ولا يتغير من عينة إلى أخرى"]'::jsonb, '[]'::jsonb, '[{"element":"المثال الأول","marks":1},{"element":"المثال الثاني","marks":1},{"element":"المثال الثالث","marks":1},{"element":"تعليل النقاء بثبات التركيب وانتظامه","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"ثلاثة أمثلة صحيحة مع تعليل صحيح"},{"level":"2–3 درجات","description":"مثالان أو ثلاثة أمثلة مع تعليل ناقص"},{"level":"1 درجة","description":"مثال واحد صحيح فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["ذكر ماء البحر أو ماء الشرب بوصفهما مادتين نقيتين","ذكر مخاليط كالهواء مثالًا على مادة نقية","تعليل النقاء بالحالة أو اللون بدل ثبات التركيب"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (25%)"}],"at":"2026-10-18T03:32:48.178Z"}'::jsonb),
('essay', 2, null::int, null, null, 'المادة الكيميائية النقية ذات تركيب منتظم وثابت، أي أن تركيبها نفسه في كل عينة منها. فملح الطعام يتكوّن دائمًا من كلوريد الصوديوم بنسبة 100%، ولا يتغير تركيبه سواء استُخرج من البحر أو من المنجم، وله دائمًا التركيب والخواص نفسها.', '["المادة النقية: تركيب منتظم وثابت","ملح الطعام يتكوّن دائمًا من كلوريد الصوديوم بنسبة 100%","لا يتغير التركيب من عينة إلى أخرى سواء من البحر أو المنجم","الخواص ثابتة بثبات التركيب"]'::jsonb, '[]'::jsonb, '[{"element":"تعريف المادة النقية بالتركيب المنتظم الثابت","marks":1},{"element":"تركيب الملح كلوريد الصوديوم بنسبة 100%","marks":1},{"element":"عدم تغير التركيب بتغير المصدر","marks":1},{"element":"ثبات الخواص","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"توضيح كامل بالمثال: التركيب والنسبة وعدم تغير المصدر والخواص"},{"level":"2–3 درجات","description":"توضيح صحيح مع إغفال عنصر أو عنصرين"},{"level":"1 درجة","description":"ذكر أن الملح مادة نقية دون توضيح"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["القول إن ملح البحر يختلف في تركيبه عن ملح المنجم","الخلط بين المادة النقية والعنصر","إغفال نسبة كلوريد الصوديوم 100%"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (15%)"}],"at":"2026-10-18T03:32:48.178Z"}'::jsonb),
('essay', 3, null::int, null, null, 'الماء النقي مادة كيميائية نقية؛ لأنه مكوّن من هيدروجين وأكسجين بتركيب منتظم وثابت في كل العينات. أما ماء البحر فليس مادة نقية؛ لأن العينات المأخوذة من أماكن مختلفة تحتوي كميات مختلفة من المعادن والمواد الذائبة الأخرى، فتركيبه غير ثابت.', '["الماء النقي مادة نقية","تركيبه من هيدروجين وأكسجين منتظم وثابت","ماء البحر ليس مادة نقية","يحتوي كميات مختلفة من المعادن والمواد الذائبة بحسب المكان فتركيبه غير ثابت"]'::jsonb, '[]'::jsonb, '[{"element":"الحكم بأن الماء النقي مادة نقية","marks":1},{"element":"تعليل ذلك بثبات التركيب (هيدروجين وأكسجين)","marks":1},{"element":"الحكم بأن ماء البحر ليس نقيًّا","marks":1},{"element":"تعليل ذلك باختلاف المواد الذائبة بين العينات","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"حكمان صحيحان مع تعليل كامل لكل منهما"},{"level":"2–3 درجات","description":"حكمان صحيحان مع تعليل ناقص"},{"level":"1 درجة","description":"حكم واحد صحيح دون تعليل"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["عدّ ماء البحر مادة نقية لأنه ماء","التعليل بكون الماء سائلًا بدل ثبات التركيب","إغفال أن اختلاف تركيب العينات هو سبب عدم النقاء"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (18%)"}],"at":"2026-10-18T03:32:48.178Z"}'::jsonb)
