('mcq', 1, 0, 'ميّز العلماء حالة رابعة للمادة تسمى البلازما.', '["","البخار هو الحالة الغازية لمادة توجد صلبة أو سائلة في درجات الحرارة العادية، وليس حالة رابعة.","الغاز المضغوط يبقى في الحالة الغازية، وليس حالة رابعة.","السائل المتجمد مادة صلبة أو سائلة، وليس حالة رابعة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (6%)"}],"at":"2026-10-18T03:32:48.179Z"}'::jsonb),
('mcq', 2, 2, 'البلازما غاز متأين تكون فيه الإلكترونات حرة وغير مرتبطة بالذرة أو الجزيء.', '["البلازما ليست سائلًا؛ فجسيمات السائل مرتبطة معًا، أما في البلازما فالإلكترونات حرة.","البلازما غاز متأين، وليست غازًا متعادلًا.","","البلازما ليست مادة صلبة، والإلكترونات فيها حرة وغير مرتبطة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (11%)"}],"at":"2026-10-18T03:32:48.179Z"}'::jsonb),
('mcq', 3, 3, 'توجد البلازما في لوحات إعلانات النيون وفي المصابيح الكهربائية وشاشات التلفاز وفي معظم مكونات النجوم.', '["الماء السائل في درجة حرارة الغرفة سائل، وليس بلازما.","الحديد الصلب مادة صلبة جسيماتها متراصة بإحكام، وليس بلازما.","الهواء في الغرفة غاز عادي غير متأين، وليس بلازما.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (18%)"}],"at":"2026-10-18T03:32:48.179Z"}'::jsonb),
('mcq', 4, 1, 'النجوم في درجات حرارة عالية تجعل المادة غازًا متأينًا إلكتروناته حرة، أي في حالة البلازما.', '["النجوم شديدة الحرارة وليست باردة، والبرودة تقرّب المادة من الحالة الصلبة.","","المواد الصلبة المترابطة بإحكام ليست بلازما، فالبلازما غاز متأين.","ثبات الجسيمات في أماكنها صفة المادة الصلبة، لا البلازما."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (17%)"}],"at":"2026-10-18T03:32:48.179Z"}'::jsonb),
('mcq', 5, 0, 'البلازما غاز متأين تكون فيه الإلكترونات حرة وغير مرتبطة بالذرة أو الجزيء، بينما الغاز العادي غير متأين.', '["","الشكل والحجم المحددان صفة المادة الصلبة، وليسا صفة البلازما.","تتكوّن البلازما عند درجات الحرارة العالية، لا المنخفضة.","جسيمات البلازما حرة كجسيمات الغاز وليست متراصة بإحكام."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (14%)"}],"at":"2026-10-18T03:32:48.180Z"}'::jsonb),
('mcq', 6, 2, 'قد تبدو البلازما غير شائعة على الأرض، لكن معظم المواد في الكون في حالة البلازما؛ كمعظم مكونات النجوم، كما توجد في لوحات النيون والمصابيح الكهربائية وشاشات التلفاز.', '["العكس صحيح؛ فمعظم المواد في الكون بلازما.","البلازما توجد في النجوم وفي أجهزة كثيرة، وليست مقصورة على المختبرات.","","البلازما توجد أيضًا في لوحات النيون والمصابيح الكهربائية وشاشات التلفاز على الأرض."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (11%)"}],"at":"2026-10-18T03:32:48.180Z"}'::jsonb),
('mcq', 7, 0, 'البلازما غاز متأين إلكتروناته حرة؛ لذلك يعني تحول النيون إلى بلازما أنه تأين فتحررت إلكترونات ذراته.', '["","التجمد يحول المادة إلى صلب، والبلازما غاز متأين لا تترتب جسيماته بإحكام.","اتحاد الذرات في جزيئات لا يكوّن بلازما؛ فالبلازما تتميز بإلكترونات حرة.","الانصهار يحول الصلب إلى سائل، ولا علاقة له بتكوّن البلازما من الغاز."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (5%)"}],"at":"2026-10-18T03:32:48.180Z"}'::jsonb),
('essay', 1, null::int, null, null, 'البلازما حالة مميزة من حالات المادة، وهي غاز متأين تكون فيه الإلكترونات حرة وغير مرتبطة بالذرة أو الجزيء. ومن أمثلتها: معظم مكونات النجوم عند درجات الحرارة العالية، ولوحات إعلانات النيون، والمصابيح الكهربائية، وشاشات التلفاز.', '["البلازما حالة رابعة مميزة للمادة","غاز متأين","الإلكترونات حرة وغير مرتبطة بالذرة أو الجزيء","ثلاثة أمثلة: النجوم، لوحات النيون، المصابيح الكهربائية أو شاشات التلفاز"]'::jsonb, '[]'::jsonb, '[{"element":"وصف البلازما بأنها غاز متأين","marks":1},{"element":"الإلكترونات حرة وغير مرتبطة بالذرة أو الجزيء","marks":1},{"element":"ثلاثة أمثلة صحيحة (درجة لكل مثال)","marks":3}]'::jsonb, '[{"level":"5 درجات","description":"وصف كامل وثلاثة أمثلة صحيحة"},{"level":"3–4 درجات","description":"وصف صحيح مع مثالين، أو ثلاثة أمثلة مع وصف ناقص"},{"level":"1–2 درجة","description":"وصف جزئي أو مثال واحد صحيح"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["وصف البلازما بأنها سائل شديد الحرارة","عدّ البخار حالة رابعة للمادة","ذكر أمثلة من الحالات الثلاث الأخرى"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (13%)"}],"at":"2026-10-18T03:32:48.180Z"}'::jsonb),
('essay', 2, null::int, null, null, 'في الغاز العادي تبقى الإلكترونات مرتبطة بالذرة أو الجزيء. أما البلازما فغاز متأين تكون فيه الإلكترونات حرة وغير مرتبطة بالذرة أو الجزيء. وتوجد المادة في حالة البلازما عند درجات الحرارة العالية كما في النجوم.', '["الغاز العادي: الإلكترونات مرتبطة بالذرة أو الجزيء","البلازما: غاز متأين إلكتروناته حرة وغير مرتبطة","البلازما توجد عند درجات حرارة عالية كما في النجوم"]'::jsonb, '[]'::jsonb, '[{"element":"حالة الإلكترونات في الغاز العادي","marks":1},{"element":"حالة الإلكترونات في البلازما (غاز متأين)","marks":2},{"element":"ذكر ظرف مناسب لوجود البلازما","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"مقارنة صحيحة كاملة مع ذكر ظرف مناسب"},{"level":"2–3 درجات","description":"وصف صحيح للبلازما مع نقص في وصف الغاز أو في الظرف"},{"level":"1 درجة","description":"ذكر أن البلازما غاز دون بيان الفرق"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["القول إن الغاز العادي إلكتروناته حرة","عدّ البلازما والغاز حالة واحدة بلا فرق","ربط البلازما بدرجات الحرارة المنخفضة"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (18%)"}],"at":"2026-10-18T03:32:48.180Z"}'::jsonb),
('essay', 3, null::int, null, null, 'العبارة غير صحيحة؛ فللمادة حالة رابعة مميزة هي البلازما، وهي غاز متأين تكون فيه الإلكترونات حرة وغير مرتبطة بالذرة أو الجزيء. وليست البلازما نادرة، فمعظم المواد في الكون في حالة البلازما، مثل معظم مكونات النجوم عند درجات الحرارة العالية، كما توجد في لوحات إعلانات النيون والمصابيح الكهربائية وشاشات التلفاز.', '["الحكم: العبارة غير صحيحة","البلازما حالة رابعة: غاز متأين إلكتروناته حرة","معظم المواد في الكون في حالة البلازما","أمثلة: النجوم ولوحات النيون والمصابيح الكهربائية وشاشات التلفاز"]'::jsonb, '[]'::jsonb, '[{"element":"الحكم بعدم صحة العبارة","marks":1},{"element":"تصحيح عدد الحالات وبيان أن البلازما حالة رابعة","marks":1},{"element":"تصحيح أن معظم المواد في الكون بلازما","marks":1},{"element":"ذكر مثالين صحيحين","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"تقويم صحيح وتصحيح الجزأين مع مثالين"},{"level":"2–3 درجات","description":"تصحيح جزء واحد فقط أو مثال ناقص"},{"level":"1 درجة","description":"حكم صحيح دون تصحيح"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["تصديق أن البلازما نادرة لأنها غير مألوفة على الأرض","حصر البلازما في النجوم فقط","عدّ البلازما نوعًا من الغاز العادي"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (8%)"}],"at":"2026-10-18T03:32:48.181Z"}'::jsonb)
