('mcq', 2, 'عينة صلبة بيضاء كتلتها 31.8 g وحجمها 20.0 cm³. أيّ المواد المعروضة في البيانات تطابق كثافتها كثافة العينة؟', '{"headers":["المادة","الحالة عند 25°C","الكثافة (g/cm³)"],"rows":[["السكر","صلب أبيض","1.59"],["كلوريد الصوديوم","صلب أبيض","2.17"],["الماء","سائل","1.00"],["الزئبق","سائل","13.5"]]}'::jsonb, '["السكر (صلب أبيض)","كلوريد الصوديوم (صلب أبيض)","الماء (سائل)","الزئبق (سائل)"]'::jsonb, 'تطبيق', 'حساب الكثافة وتعرّف مادة', 'صعب', 'الكتاب ص 47 — الكثافة خاصية مميزة (الجدول 2-1)'),
('mcq', 3, 'عيّن طالب كتلة عينة من سائل فضي فوجدها 67.5 g وحجمها 5.00 cm³. ما كثافة هذه العينة؟', null, '["0.0741 g/cm³","62.5 g/cm³","337.5 g/cm³","13.5 g/cm³"]'::jsonb, 'تطبيق', 'حساب الكثافة', 'متوسط', 'الكتاب ص 47 — الكثافة خاصية مميزة'),
('mcq', 4, 'لماذا تُستخدم الكثافة ودرجتا الانصهار والغليان في تعرّف المواد المجهولة؟', null, '["لأنها تتغير بتغير كتلة العينة المأخوذة","لأنها خواص مميزة لا تعتمد على كمية المادة الموجودة","لأنها تتغير عند تغير شكل العينة","لأنها خواص كيميائية لا تظهر إلا عند حدوث تفاعل"]'::jsonb, 'فهم', 'تعليل', 'سهل', 'الكتاب ص 47 و51 — الخواص المميزة وتعيين المواد المجهولة'),
('mcq', 5, 'سُخّنت عينتان من الماء عند ضغط 1 atm: حجم الأولى 250 mL وحجم الثانية 1000 mL. ماذا تتوقع بالنسبة إلى درجة غليان كل منهما؟', null, '["تغلي كلتاهما عند 100°C؛ لأن درجة الغليان خاصية مميزة لا تعتمد على الكمية","تغلي العينة الأكبر عند درجة أعلى؛ لأن كتلتها أكبر","تغلي العينة الأصغر عند درجة أعلى؛ لأنها تسخن أسرع","لا يمكن تحديد درجة الغليان؛ لأنها خاصية غير مميزة"]'::jsonb, 'تطبيق', 'تطبيق على خاصية مميزة', 'متوسط', 'الكتاب ص 69 — السؤال 40 (درجة غليان الماء)'),
('mcq', 6, 'لديك عينتان صلبتان بيضاوان إحداهما سكر والأخرى كلوريد الصوديوم. أيّ خاصية من الآتية تكفي وحدها للتمييز بينهما؟', '{"headers":["المادة","اللون","الحالة عند 25°C","درجة الانصهار (°C)","الكثافة (g/cm³)"],"rows":[["السكر","أبيض","صلب","185","1.59"],["كلوريد الصوديوم","أبيض","صلب","801","2.17"]]}'::jsonb, '["لون العينة","حالة العينة عند 25°C","كتلة العينة","درجة انصهار العينة"]'::jsonb, 'تحليل', 'اختيار الخاصية المناسبة للتمييز', 'صعب', 'الكتاب ص 47 و51 — الخواص المميزة وتعيين المواد المجهولة'),
('mcq', 7, 'ينصهر جسم مجهول عند -218°C. بالاعتماد على البيانات المعروضة، أيّ المواد الآتية هو؟', '{"headers":["المادة","درجة الانصهار (°C)","درجة الغليان (°C)"],"rows":[["الأكسجين","-218","-183"],["الزئبق","-39","357"],["الماء","0","100"],["كلوريد الصوديوم","801","1413"]]}'::jsonb, '["الزئبق السائل","الماء السائل","الأكسجين الغازي","كلوريد الصوديوم الصلب"]'::jsonb, 'تطبيق', 'تعرّف مادة بدرجة الانصهار', 'سهل', 'الكتاب ص 47 — الجدول 2-1 (درجات الانصهار)'),
('essay', 1, 'عينة مجهولة صلبة بيضاء كتلتها 43.4 g وحجمها 20.0 cm³، وتنصهر عند 801°C. علمًا بأن السكر كثافته 1.59 g/cm³ ودرجة انصهاره 185°C، وكلوريد الصوديوم كثافته 2.17 g/cm³ ودرجة انصهاره 801°C، والماء كثافته 1.00 g/cm³ ودرجة انصهاره 0°C: احسب كثافة العينة، ثم حدّد المادة مع ذكر الخاصيتين اللتين اعتمدت عليهما.', null, null, 'تطبيق', 'حساب وتعرّف مادة', 'متوسط', 'الكتاب ص 47 و51 — الخواص المميزة وتعيين المواد المجهولة'),
('essay', 2, 'سُخّن 250 mL من الماء وسُخّن 1000 mL منه عند ضغط 1 atm. عند أيّ درجة حرارة يغلي كل منهما؟ وهل درجة غليان الماء خاصية مميزة أم غير مميزة؟ علّل إجابتك.', null, null, 'فهم', 'تطبيق وتعليل', 'متوسط', 'الكتاب ص 69 — السؤال 40 (درجة غليان الماء خاصية مميزة)'),
('essay', 3, 'أُعطيت ثلاث عينات مجهولة: (أ) سائل فضي اللون يغلي عند 357°C؛ (ب) صلب أبيض ينصهر عند 185°C ويتحلل قبل أن يغلي؛ (ج) سائل عديم اللون ينصهر عند 0°C ويغلي عند 100°C وكثافته 1.00 g/cm³. مستعينًا بالمواد: الأكسجين والزئبق والماء والسكر وكلوريد الصوديوم، حدّد كل عينة، وبيّن لماذا لا يكفي اللون وحده لتعرّف العينة (ب).', null, null, 'تطبيق', 'تعرّف مواد مجهولة', 'صعب', 'الكتاب ص 47 و69 — الجدول 2-1 والسؤال 41')
) as v(type, number, stem, stimulus, options, tl, qk, diff, src)
