from (values
('mcq', 1, 2, 'درجتا الانصهار 801°C والغليان 1413°C تطابقان كلوريد الصوديوم، وهو صلب أبيض عند 25°C؛ فالعينة المجهولة كلوريد الصوديوم.', '["الزئبق سائل فضي ينصهر عند -39°C ويغلي عند 357°C، فلا يطابق العينة.","السكر ينصهر عند 185°C ويتحلل قبل أن يغلي، بينما تغلي العينة عند 1413°C.","","الماء سائل عديم اللون ينصهر عند 0°C ويغلي عند 100°C، فلا يطابق العينة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (15%)"}],"at":"2026-10-18T03:32:48.181Z"}'::jsonb),
('mcq', 2, 0, 'كثافة العينة = 31.8 g ÷ 20.0 cm³ = 1.59 g/cm³، وهي كثافة السكر، وهو صلب أبيض.', '["","كثافة كلوريد الصوديوم 2.17 g/cm³؛ ولو كانت العينة منه لكانت كتلتها 43.4 g لهذا الحجم.","الماء سائل كثافته 1.00 g/cm³، ولو كانت العينة منه لكانت كتلتها 20.0 g لهذا الحجم.","كثافة الزئبق 13.5 g/cm³، ولو كانت العينة منه لكانت كتلتها 270 g لهذا الحجم."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (21%)"}],"at":"2026-10-18T03:32:48.182Z"}'::jsonb),
('mcq', 3, 3, 'الكثافة = الكتلة ÷ الحجم = 67.5 g ÷ 5.00 cm³ = 13.5 g/cm³، وهي كثافة الزئبق.', '["هذه قيمة قلب النسبة (الحجم ÷ الكتلة = 5.00 ÷ 67.5).","هذه قيمة طرح الحجم من الكتلة (67.5 - 5.00)، والكثافة تُحسب بالقسمة.","هذه قيمة ضرب الكتلة في الحجم (67.5 × 5.00)، والكثافة تُحسب بقسمة الكتلة على الحجم.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (21%)"}],"at":"2026-10-18T03:32:48.182Z"}'::jsonb),
('mcq', 4, 1, 'الكثافة ودرجتا الانصهار والغليان خواص فيزيائية مميزة لا تعتمد على كمية المادة؛ لذلك يمكن استعمالها في تعيين المواد المجهولة.', '["الخاصية التي تتغير بتغير الكتلة غير مميزة ولا تصلح للتعرّف، والكثافة لا تتغير بتغير الكتلة.","","الكثافة ودرجتا الانصهار والغليان لا تتغير بتغير شكل العينة.","هي خواص فيزيائية تُقاس دون حدوث تفاعل، وليست كيميائية."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (6%)"}],"at":"2026-10-18T03:32:48.182Z"}'::jsonb),
('mcq', 5, 0, 'درجة غليان الماء خاصية مميزة لا تعتمد على كمية الماء، فتغلي العينتان عند 100°C عند ضغط 1 atm.', '["","درجة الغليان لا تزداد بزيادة الكتلة؛ فهي خاصية مميزة ثابتة للمادة.","سرعة التسخين لا تغيّر درجة الغليان، وهي ثابتة لا تتأثر بالكمية.","درجة الغليان خاصية مميزة، ولذلك يمكن تحديدها وتبقى واحدة مهما كانت الكمية."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (34%)"}],"at":"2026-10-18T03:32:48.183Z"}'::jsonb),
('mcq', 6, 3, 'للمادتين اللون نفسه والحالة نفسها، وكتلة العينة خاصية غير مميزة تعتمد على الكمية؛ أما درجة الانصهار فخاصية مميزة تختلف بين 185°C و801°C، فتكفي للتمييز.', '["كلتا المادتين بيضاء، فلا يمكن التمييز باللون.","كلتا المادتين صلبة عند 25°C، فلا يمكن التمييز بالحالة.","الكتلة خاصية غير مميزة تعتمد على كمية العينة، وقد تتساوى في المادتين.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (4%)"}],"at":"2026-10-18T03:32:48.183Z"}'::jsonb),
('mcq', 7, 2, 'درجة الانصهار -218°C تطابق الأكسجين فقط؛ إذ تختلف درجة انصهار كل مادة من المواد الأخرى.', '["الزئبق ينصهر عند -39°C، وليس عند -218°C.","الماء ينصهر عند 0°C، وليس عند -218°C.","","كلوريد الصوديوم ينصهر عند 801°C، وليس عند -218°C."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (14%)"}],"at":"2026-10-18T03:32:48.183Z"}'::jsonb),
('essay', 1, null::int, null, null, 'الكثافة = الكتلة ÷ الحجم = 43.4 g ÷ 20.0 cm³ = 2.17 g/cm³، وتنصهر العينة عند 801°C. تطابق الكثافة ودرجة الانصهار قيمتي كلوريد الصوديوم، ولا تطابقان السكر (1.59 g/cm³ و185°C) ولا الماء (1.00 g/cm³ و0°C)؛ فالعينة كلوريد الصوديوم. وقد اعتمدنا على الكثافة ودرجة الانصهار وهما خاصيتان مميزتان لا تعتمدان على كمية المادة.', '["قانون الكثافة: الكتلة ÷ الحجم","الكثافة = 43.4 ÷ 20.0 = 2.17 g/cm³","المطابقة مع كلوريد الصوديوم في الكثافة ودرجة الانصهار","استبعاد السكر والماء","الكثافة ودرجة الانصهار خاصيتان مميزتان"]'::jsonb, '["الكثافة = الكتلة ÷ الحجم","الكثافة = 43.4 g ÷ 20.0 cm³ = 2.17 g/cm³","مقارنة 2.17 g/cm³ و801°C مع بيانات المواد: تطابق كلوريد الصوديوم","استبعاد السكر (1.59 g/cm³ و185°C) والماء (1.00 g/cm³ و0°C)"]'::jsonb, '[{"element":"كتابة العلاقة الصحيحة للكثافة","marks":1},{"element":"الحساب الصحيح 2.17 g/cm³ مع الوحدة","marks":1},{"element":"تحديد المادة: كلوريد الصوديوم","marks":1},{"element":"ذكر الخاصيتين المميزتين المعتمد عليهما","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"علاقة وحساب صحيحان بالوحدة، وتحديد صحيح للمادة، وذكر الخاصيتين"},{"level":"2–3 درجات","description":"حساب صحيح مع نقص في التحديد أو التعليل، أو خطأ بسيط في الوحدة"},{"level":"1 درجة","description":"كتابة العلاقة الصحيحة فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["قسمة الحجم على الكتلة","إهمال الوحدة g/cm³","تحديد المادة بالاعتماد على اللون وحده"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (21%)"}],"at":"2026-10-18T03:32:48.184Z"}'::jsonb),
('essay', 2, null::int, null, null, 'يغلي كل من العينتين عند درجة 100°C عند ضغط 1 atm. درجة غليان الماء خاصية مميزة؛ لأنها لا تعتمد على كمية الماء الموجودة، فهي واحدة سواء كان الحجم 250 mL أو 1000 mL، ولذلك يمكن استعمالها في تعرّف الماء.', '["العينتان تغليان عند 100°C","درجة الغليان خاصية مميزة","لا تعتمد على كمية المادة","يمكن استعمالها في تعرّف المواد"]'::jsonb, '[]'::jsonb, '[{"element":"تحديد درجة الغليان 100°C للعينتين","marks":1},{"element":"الحكم بأنها خاصية مميزة","marks":1},{"element":"التعليل بعدم اعتمادها على الكمية","marks":2}]'::jsonb, '[{"level":"4 درجات","description":"درجة الغليان صحيحة، وحكم صحيح، وتعليل كامل"},{"level":"2–3 درجات","description":"حكم صحيح مع تعليل ناقص أو درجة غليان غير مذكورة"},{"level":"1 درجة","description":"ذكر 100°C فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["القول إن العينة الأكبر تغلي عند درجة أعلى","عدّ درجة الغليان خاصية غير مميزة لأنها تعتمد على الحجم","الخلط بين درجة الغليان وكمية الحرارة اللازمة للتسخين"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (34%)"}],"at":"2026-10-18T03:32:48.184Z"}'::jsonb),
('essay', 3, null::int, null, null, 'العينة (أ) هي الزئبق لأنه سائل فضي يغلي عند 357°C. العينة (ب) هي السكر لأنه صلب أبيض ينصهر عند 185°C ويتحلل قبل أن يغلي. العينة (ج) هي الماء لأنه سائل عديم اللون ينصهر عند 0°C ويغلي عند 100°C وكثافته 1.00 g/cm³. ولا يكفي اللون وحده لتعرّف (ب)؛ لأن كلوريد الصوديوم أيضًا صلب أبيض، والذي يميز السكر درجة انصهاره 185°C وتحلله قبل الغليان، وهي خواص مميزة.', '["(أ) الزئبق: سائل فضي يغلي عند 357°C","(ب) السكر: ينصهر عند 185°C ويتحلل قبل الغليان","(ج) الماء: ينصهر عند 0°C ويغلي عند 100°C وكثافته 1.00 g/cm³","اللون وحده لا يكفي لأن كلوريد الصوديوم أيضًا صلب أبيض","التمييز يتم بالخواص المميزة كدرجة الانصهار"]'::jsonb, '[]'::jsonb, '[{"element":"تحديد العينة (أ) مع الخاصية المستند إليها","marks":1},{"element":"تحديد العينة (ب) مع الخاصية المستند إليها","marks":1},{"element":"تحديد العينة (ج) مع الخاصية المستند إليها","marks":1},{"element":"بيان عدم كفاية اللون لوجود مادة بيضاء أخرى","marks":1},{"element":"ذكر الخاصية المميزة التي تحسم التمييز","marks":1}]'::jsonb, '[{"level":"5 درجات","description":"تحديد العينات الثلاث مع التبرير، وتفسير عدم كفاية اللون، وذكر الخاصية المميزة"},{"level":"3–4 درجات","description":"تحديد العينات الثلاث مع نقص في التبرير أو في تفسير اللون"},{"level":"1–2 درجة","description":"تحديد عينة أو عينتين فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["الخلط بين السكر وكلوريد الصوديوم لأن لونهما أبيض","الاعتماد على الحالة أو اللون دون درجة الانصهار أو الغليان","عدّ تحلل السكر دليلًا على أنه كلوريد الصوديوم"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (17%)"}],"at":"2026-10-18T03:32:48.185Z"}'::jsonb)
) as v(type, number, ci, ex, dn, ma, ae, ss, mk, rb, ce, ac)
