from (values
('mcq', 1, 'أيّ الخواص الآتية خاصية كيميائية؟', null, '["كثافة الذهب 19 g/cm³","تكوّن الصدأ عند اتحاد الحديد مع الأكسجين","سيولة الزئبق في درجات الحرارة العادية","غليان الماء عند 100°C"]'::jsonb, 'تطبيق', 'تصنيف خاصية', 'سهل', 'الكتاب ص 69 — السؤال 38 وص 48 الخواص الكيميائية'),
('mcq', 2, 'كيف تُصنَّف الخاصيتان: عدم امتزاج الزيت والماء، وانصهار الزئبق عند -39°C؟', null, '["الأولى فيزيائية والثانية كيميائية؛ لأن الانصهار يغيّر المادة","الأولى كيميائية والثانية فيزيائية؛ لأن الزيت والماء يتفاعلان","كلتاهما كيميائية؛ لأن المادتين تتغيران في الحالتين","كلتاهما فيزيائية؛ لأن تركيب المواد لا يتغير في أي منهما"]'::jsonb, 'تطبيق', 'تصنيف خاصيتين', 'سهل', 'الكتاب ص 49 — التقويم 2-1 السؤال 3'),
('mcq', 3, 'تكوّنت طبقة سوداء على سطح قطعة فضة تُركت في الهواء مدة طويلة. كيف تُصنَّف هذه الخاصية؟', null, '["كيميائية؛ لأن الفضة تتحد مع مواد في الجو فتتكون مادة جديدة","فيزيائية؛ لأن اللون صفة يمكن ملاحظتها بالعين","فيزيائية؛ لأن الفضة تبقى بالتركيب نفسه بعد التغير","غير مميزة؛ لأنها تعتمد على كمية الفضة الموجودة"]'::jsonb, 'تطبيق', 'تصنيف خاصية مع تعليل', 'متوسط', 'الكتاب ص 69 — السؤال 38 (e)'),
('mcq', 4, 'تُعطى فيما يأتي خمس خواص للنحاس. كم منها خاصية كيميائية؟', '{"headers":["الرقم","الخاصية"],"rows":[["1","لونه بني محمر لامع"],["2","قابل للسحب والطرق"],["3","يكوّن كربونات النحاس الأخضر عند تعرضه للهواء الرطب"],["4","يكوّن محلولًا شديد الزرقة عند تفاعله مع الأمونيا"],["5","درجة انصهاره 1085°C"]]}'::jsonb, '["1","2","3","4"]'::jsonb, 'تطبيق', 'تصنيف مجموعة خواص', 'متوسط', 'الكتاب ص 48 — الجدول 2-2 خواص النحاس'),
('mcq', 5, 'أيّ الأزواج الآتية يضم خاصية فيزيائية ثم خاصية كيميائية، بهذا الترتيب؟', null, '["يحترق المغنسيوم ويتوهج عند إشعاله؛ الحديد أكبر كثافة من الألومنيوم","الحديد والأكسجين يكوّنان الصدأ؛ يحترق المغنسيوم ويتوهج عند إشعاله","الحديد أكبر كثافة من الألومنيوم؛ يحترق المغنسيوم ويتوهج عند إشعاله","الزيت والماء لا يمتزجان؛ ينصهر الزئبق عند -39°C"]'::jsonb, 'تطبيق', 'تصنيف أزواج', 'متوسط', 'الكتاب ص 49 — التقويم 2-1 السؤال 3'),
('mcq', 6, 'صنّف العبارات الآتية بالترتيب إلى فيزيائية أو كيميائية: (1) يشتعل الصوديوم عند وضعه في الماء، (2) لون الألومنيوم فضي، (3) كثافة الذهب 19 g/cm³.', null, '["كيميائية، فيزيائية، فيزيائية","فيزيائية، كيميائية، فيزيائية","فيزيائية، فيزيائية، كيميائية","كيميائية، كيميائية، فيزيائية"]'::jsonb, 'تطبيق', 'تصنيف عبارات', 'متوسط', 'الكتاب ص 69 — السؤال 38 (a, b, c)'),
('mcq', 7, 'تُعطى فيما يأتي ثلاث عبارات عن الماء عند درجات حرارة أعلى من 100°C: (1) يكون غازًا، (2) يتفاعل بسرعة مع عدة مواد، (3) كثافته 0.0006 g/cm³. أيّ التصنيفات الآتية صحيح بالترتيب؟', null, '["فيزيائية، فيزيائية، كيميائية","كيميائية، فيزيائية، فيزيائية","فيزيائية، فيزيائية، فيزيائية","فيزيائية، كيميائية، فيزيائية"]'::jsonb, 'تحليل', 'تصنيف خواص مادة في ظرف معين', 'صعب', 'الكتاب ص 49 — خواص الماء عند ظروف مختلفة'),
('essay', 1, 'صنّف كلًّا من الخواص الآتية إلى فيزيائية أو كيميائية، مع ذكر المعيار الذي اعتمدت عليه في التصنيف: (أ) الحديد والأكسجين يكوّنان الصدأ، (ب) الحديد أكبر كثافة من الألومنيوم، (ج) يحترق المغنسيوم ويتوهج عند إشعاله، (د) الزيت والماء لا يمتزجان، (هـ) ينصهر الزئبق عند -39°C.', null, null, 'تطبيق', 'تصنيف مع معيار', 'متوسط', 'الكتاب ص 49 — التقويم 2-1 السؤال 3'),
('essay', 2, 'للنحاس الخواص الآتية: لونه بني محمر لامع، قابل للسحب والطرق، كثافته 8.96 g/cm³، يتحول لونه إلى الأخضر في الهواء الرطب، يكوّن محلولًا شديد الزرقة عند تفاعله مع الأمونيا، درجة انصهاره 1085°C. صنّفها إلى فيزيائية وكيميائية، ثم فسّر لماذا يُعدّ تغير لون النحاس إلى الأخضر خاصية كيميائية بينما تشكيله أسلاكًا خاصية فيزيائية.', null, null, 'تحليل', 'تصنيف وتفسير', 'صعب', 'الكتاب ص 48 — الشكل 2-6 والجدول 2-2'),
('essay', 3, 'كوّن جدولًا يقارن بين الخواص الفيزيائية والخواص الكيميائية للمادة من حيث التعريف وتأثرها بتركيب المادة، وأعطِ مثالين على كل نوع.', null, null, 'تحليل', 'مقارنة بجدول', 'متوسط', 'الكتاب ص 49 — التقويم 2-1 السؤال 4')
) as v(type, number, stem, stimulus, options, tl, qk, diff, src)
