from (values
('mcq', 1, 1, 'تكوّن الصدأ باتحاد الحديد مع الأكسجين يغيّر تركيب المادة وينتج مادة جديدة، فهو خاصية كيميائية؛ أما الكثافة والسيولة والغليان فخواص فيزيائية.', '["الكثافة تُقاس دون تغيير تركيب الذهب، فهي خاصية فيزيائية.","","السيولة حالة تُلاحَظ دون تغيير تركيب الزئبق، فهي خاصية فيزيائية.","الغليان تغير في الحالة دون تغير تركيب الماء، فهو خاصية فيزيائية."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (30%)"}],"at":"2026-10-18T03:32:48.186Z"}'::jsonb),
('mcq', 2, 3, 'عدم امتزاج الزيت والماء وانصهار الزئبق خاصيتان يمكن ملاحظتهما دون تغير في تركيب المادة، فهما فيزيائيتان.', '["الانصهار تغير في الحالة لا يغيّر تركيب الزئبق، فهو فيزيائي.","الزيت والماء لا يتفاعلان بل لا يمتزجان فقط، فالخاصية فيزيائية.","لا تتكوّن مادة جديدة في أي من الحالتين، فلا توجد خاصية كيميائية.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (13%)"}],"at":"2026-10-18T03:32:48.186Z"}'::jsonb),
('mcq', 3, 0, 'تكوّن الطبقة السوداء ناتج عن اتحاد الفضة مع مواد في الجو وتكوّن مادة جديدة، أي تغير في التركيب؛ فهي خاصية كيميائية.', '["","اللون هنا نتيجة مادة جديدة تكوّنت، فلا يكفي كونه يُلاحَظ بالعين لتصنيفه فيزيائيًّا.","تركيب الفضة تغيّر لأنها اتحدت مع مواد أخرى فتكوّنت مادة جديدة.","الخواص غير المميزة هي المعتمدة على الكمية كالكتلة والطول، وهذا ليس منها."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (9%)"}],"at":"2026-10-18T03:32:48.186Z"}'::jsonb),
('mcq', 4, 1, 'الخاصيتان 3 و4 كيميائيتان لأن كلًّا منهما تكوّن مادة جديدة؛ أما اللون والسحب والطرق ودرجة الانصهار فخواص فيزيائية، فعدد الخواص الكيميائية 2.', '["هذا يعدّ خاصية واحدة فقط، وتوجد خاصيتان كيميائيتان (3 و4).","","هذا يعدّ ثلاث خواص، وتوجد خاصيتان كيميائيتان فقط؛ فاللون والسحب والطرق ودرجة الانصهار فيزيائية.","هذا يعدّ أربع خواص، بينما اللون والسحب والطرق ودرجة الانصهار خواص فيزيائية."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (17%)"}],"at":"2026-10-18T03:32:48.186Z"}'::jsonb),
('mcq', 5, 2, 'كثافة الحديد خاصية فيزيائية، واحتراق المغنسيوم خاصية كيميائية؛ وهذا الترتيب مطلوب (فيزيائية ثم كيميائية).', '["الترتيب معكوس: الأولى كيميائية والثانية فيزيائية.","كلتاهما كيميائية، فلا توجد خاصية فيزيائية في الزوج.","","كلتاهما فيزيائية، فلا توجد خاصية كيميائية في الزوج."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (30%)"}],"at":"2026-10-18T03:32:48.187Z"}'::jsonb),
('mcq', 6, 0, 'اشتعال الصوديوم في الماء تفاعل تتكوّن فيه مواد جديدة فهو كيميائي، ولون الألومنيوم وكثافة الذهب خاصيتان فيزيائيتان.', '["","اشتعال الصوديوم في الماء خاصية كيميائية وليست فيزيائية، كما أن لون الألومنيوم فيزيائي.","كثافة الذهب تُقاس دون تغير تركيبه، فهي فيزيائية، واشتعال الصوديوم كيميائي.","لون الألومنيوم يُلاحَظ دون تغير تركيبه، فهو خاصية فيزيائية."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (18%)"}],"at":"2026-10-18T03:32:48.188Z"}'::jsonb),
('mcq', 7, 3, 'كون الماء غازًا وكثافته 0.0006 g/cm³ خاصيتان فيزيائيتان، أما تفاعله بسرعة مع عدة مواد فخاصية كيميائية.', '["كثافة الماء 0.0006 g/cm³ فيزيائية، وتفاعله مع المواد هو الكيميائي.","كون الماء غازًا حالة فيزيائية، والتفاعل مع مواد أخرى هو الخاصية الكيميائية.","الخاصية الثانية (التفاعل مع عدة مواد) تغيّر تركيب المادة، فهي كيميائية.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (13%)"}],"at":"2026-10-18T03:32:48.188Z"}'::jsonb),
('essay', 1, null::int, null, null, '(أ) كيميائية، (ب) فيزيائية، (ج) كيميائية، (د) فيزيائية، (هـ) فيزيائية. المعيار: الخاصية الفيزيائية يمكن ملاحظتها أو قياسها دون تغيير في تركيب المادة، أما الخاصية الكيميائية فتظهر عندما يتغير تركيب المادة باتحادها مع مادة أخرى أو بتعرضها لمؤثر كالحرارة فتتكوّن مادة جديدة؛ وهو ما يحدث في تكوّن الصدأ واحتراق المغنسيوم.', '["(أ) كيميائية","(ب) فيزيائية","(ج) كيميائية","(د) فيزيائية","(هـ) فيزيائية","المعيار: تغير تركيب المادة وتكوّن مادة جديدة (كيميائية) أو عدم تغيره (فيزيائية)"]'::jsonb, '[]'::jsonb, '[{"element":"تصنيف (أ) تصنيفًا صحيحًا","marks":1},{"element":"تصنيف (ب) تصنيفًا صحيحًا","marks":1},{"element":"تصنيف (ج) تصنيفًا صحيحًا","marks":1},{"element":"تصنيف (د) تصنيفًا صحيحًا","marks":1},{"element":"تصنيف (هـ) تصنيفًا صحيحًا","marks":1},{"element":"ذكر معيار التصنيف (تغير التركيب)","marks":1}]'::jsonb, '[{"level":"6 درجات","description":"خمسة تصنيفات صحيحة مع ذكر المعيار"},{"level":"4–5 درجات","description":"أربعة أو خمسة تصنيفات صحيحة مع معيار ناقص، أو خمسة دون معيار"},{"level":"2–3 درجات","description":"تصنيفان أو ثلاثة صحيحة"},{"level":"1 درجة","description":"تصنيف واحد صحيح"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["عدّ انصهار الزئبق خاصية كيميائية لأنه تغير يحدث بالحرارة","عدّ عدم امتزاج الزيت والماء خاصية كيميائية","عدّ مقارنة الكثافة خاصية كيميائية"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (6 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (18%)"}],"at":"2026-10-18T03:32:48.188Z"}'::jsonb),
('essay', 2, null::int, null, null, 'الخواص الفيزيائية: لونه بني محمر لامع، وقابليته للسحب والطرق، وكثافته 8.96 g/cm³، ودرجة انصهاره 1085°C. الخواص الكيميائية: تحول لونه إلى الأخضر في الهواء الرطب، وتكوينه محلولًا شديد الزرقة مع الأمونيا. تحول النحاس إلى الأخضر خاصية كيميائية لأنه يتفاعل مع مواد في الهواء فيتغير تركيبه وتتكوّن مادة جديدة، أما تشكيله أسلاكًا فيغيّر الشكل فقط ويبقى النحاس نحاسًا دون تغير في التركيب، فهو خاصية فيزيائية.', '["الفيزيائية: اللون، السحب والطرق، الكثافة، درجة الانصهار","الكيميائية: التحول إلى الأخضر في الهواء الرطب، التفاعل مع الأمونيا","التحول إلى الأخضر: تفاعل مع مواد الهواء وتكوّن مادة جديدة","التشكيل أسلاكًا: تغير في الشكل دون تغير التركيب"]'::jsonb, '[]'::jsonb, '[{"element":"تصنيف الخواص الفيزيائية الأربع","marks":2},{"element":"تصنيف الخاصيتين الكيميائيتين","marks":1},{"element":"تفسير كيميائية التحول إلى الأخضر (تكوّن مادة جديدة)","marks":1},{"element":"تفسير فيزيائية التشكيل أسلاكًا (شكل فقط دون تغير تركيب)","marks":1}]'::jsonb, '[{"level":"5 درجات","description":"تصنيف صحيح كامل وتفسير صحيح للحالتين"},{"level":"3–4 درجات","description":"تصنيف صحيح مع تفسير ناقص لإحدى الحالتين"},{"level":"1–2 درجة","description":"تصنيف جزئي دون تفسير"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["عدّ اللون خاصية كيميائية دائمًا، دون التمييز بين لون المادة وتغير لونها بتفاعل","عدّ قابلية السحب والطرق خاصية كيميائية","عدّ تحول النحاس إلى الأخضر تغيرًا في الحالة"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (11%)"}],"at":"2026-10-18T03:32:48.189Z"}'::jsonb),
('essay', 3, null::int, null, null, 'الخواص الفيزيائية: خاصية يمكن ملاحظتها أو قياسها دون تغيير في تركيب المادة؛ ومن أمثلتها الكثافة 19 g/cm³ للذهب، وسيولة الزئبق في درجات الحرارة العادية. الخواص الكيميائية: تظهر عندما يتغير تركيب المادة باتحادها مع مادة أخرى أو تعرضها لمؤثر كالحرارة، فتصف قدرتها على الاتحاد مع غيرها أو التحول إلى مادة أخرى؛ ومن أمثلتها تكوّن الصدأ عند اتحاد الحديد مع الأكسجين، واشتعال الصوديوم عند وضعه في الماء.', '["الفيزيائية: تُلاحَظ أو تُقاس دون تغير تركيب المادة","الكيميائية: تظهر عند تغير التركيب بالاتحاد مع مادة أخرى أو التعرض لمؤثر","مثالان فيزيائيان صحيحان","مثالان كيميائيان صحيحان"]'::jsonb, '[]'::jsonb, '[{"element":"تعريف الخواص الفيزيائية","marks":1},{"element":"تعريف الخواص الكيميائية","marks":1},{"element":"مثالان فيزيائيان صحيحان","marks":1},{"element":"مثالان كيميائيان صحيحان","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"تعريفان صحيحان ومثالان صحيحان لكل نوع"},{"level":"2–3 درجات","description":"تعريفان صحيحان مع أمثلة ناقصة أو العكس"},{"level":"1 درجة","description":"تعريف واحد أو مثال واحد صحيح"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["وضع مثال فيزيائي (كاللون أو الكثافة) في خانة الخواص الكيميائية","تعريف الخاصية الكيميائية بأنها تُقاس دون تغيير التركيب","عرض الأمثلة دون الربط بتغير التركيب"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (5%)"}],"at":"2026-10-18T03:32:48.189Z"}'::jsonb)
