('mcq', 5, 'تفاعلت عينة من الماغنسيوم كتلتها 10.0 g مع الأكسجين لتكوين 16.6 g من أكسيد الماغنسيوم. كم جرامًا من الأكسجين تفاعل؟', null, '["26.6 g","6.6 g","16.6 g","10.0 g"]'::jsonb, 'تطبيق', 'حساب كتلة متفاعل مجهول', 'سهل', 'الكتاب ص 52 — مسائل تدريبية، السؤال 8'),
