('mcq', 1, 1, 'كتلة المتفاعلات = كتلة النواتج؛ إذن كتلة الأكسجين = كتلة أكسيد الزئبق II − كتلة الزئبق = 10.00 g − 9.26 g = 0.74 g.', '["هذا ناتج جمع كتلة أكسيد الزئبق II وكتلة الزئبق، والصواب طرح كتلة الزئبق من كتلة المتفاعل.","","هذه كتلة الزئبق المعطاة وليست كتلة الأكسجين المطلوبة.","هذه كتلة أكسيد الزئبق II المتفاعل، وهي تساوي مجموع كتلتي الناتجين لا كتلة الأكسجين وحده."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (18%)"}],"at":"2026-10-18T03:32:48.190Z"}'::jsonb),
