('mcq', 3, 0, 'كتلة X + كتلة Y = كتلة XY، فكتلة Y = 78.9 g − 12.2 g = 66.7 g.', '["","هذا مجموع كتلة X وكتلة المركب، وهو خطأ؛ فالمطلوب طرح كتلة X من كتلة الناتج.","هذه كتلة المركب XY الناتج، وتساوي مجموع كتلتي X وY ولا تساوي كتلة Y وحدها.","هذه كتلة X المتفاعلة المعطاة وليست كتلة Y المطلوبة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (15%)"}],"at":"2026-10-18T03:32:48.191Z"}'::jsonb),
('mcq', 4, 2, 'وفق قانون حفظ الكتلة، مجموع كتل النواتج = كتلة المتفاعلات = 680.0 g؛ ولا يتغير ذلك لأن الوعاء مغلق فلا يفلت أي ناتج غازي.', '["هذا نصف الكتلة؛ أي تقسيم الكتلة على عنصرين وكأن الكتلة تتوزع فتنقص، والكتلة محفوظة كاملة.","هذا ضعف الكتلة؛ أي أن الكتلة تتضاعف عند التحلل، والكتلة لا تُستحدث.","","لا تنقص الكتلة الكلية؛ فلو كان الوعاء مفتوحًا لخرج الغاز وانخفضت الكتلة المقيسة، لكن الوعاء مغلق فتبقى 680.0 g."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (4%)"}],"at":"2026-10-18T03:32:48.191Z"}'::jsonb),
('mcq', 5, 1, 'كتلة Mg + كتلة O₂ = كتلة MgO، فكتلة الأكسجين = 16.6 g − 10.0 g = 6.6 g.', '["هذا مجموع كتلة الماغنسيوم وكتلة الناتج، والصواب هو الفرق بينهما.","","هذه كتلة أكسيد الماغنسيوم الناتج وليست كتلة الأكسجين وحده.","هذه كتلة الماغنسيوم المتفاعل وليست كتلة الأكسجين."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (18%)"}],"at":"2026-10-18T03:32:48.191Z"}'::jsonb),
('mcq', 6, 0, 'كتلة المتفاعلات = 180.0 g + 192.0 g = 372.0 g. وكتلة النواتج تساوي ذلك أيضًا، فكتلة CO₂ = 372.0 g − 108.0 g = 264.0 g.', '["","هذا مجموع كتل المتفاعلين، أي كتلة النواتج كلها؛ ولم تُطرح منه كتلة الماء للحصول على كتلة CO₂ وحده.","هذا ناتج جمع كتلة الماء إلى كتل المتفاعلين، والصواب طرحها من مجموع كتل المتفاعلات.","هذا فرق كتلة الأكسجين عن كتلة الماء (192.0 − 108.0)، ولا يعبر عن قانون حفظ الكتلة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (11%)"}],"at":"2026-10-18T03:32:48.192Z"}'::jsonb),
('mcq', 7, 3, 'كتلة الهيدروجين المتفاعل = 129.9 g − 123.9 g = 6.0 g. وكتلة الهيدروجين قبل التفاعل = المتفاعل + الباقي = 6.0 g + 310.0 g = 316.0 g.', '["هذه كتلة الهيدروجين المتفاعل فقط، ولم تُضف إليها كتلة الهيدروجين الباقي.","هذه كتلة الهيدروجين الباقي بعد التفاعل وليست كتلته قبل التفاعل.","هذا مجموع كتلة الفوسفور وكتلة الهيدروجين الباقي، وهو لا يمثل كتلة الهيدروجين الأصلية.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (15%)"}],"at":"2026-10-18T03:32:48.192Z"}'::jsonb),
('essay', 1, null::int, null, null, 'وفق قانون حفظ الكتلة: كتلة المتفاعلات = كتلة النواتج، أي كتلة الصوديوم + كتلة الكلور = كتلة كلوريد الصوديوم. إذن كتلة الكلور = 116.89 g − 45.98 g = 70.91 g. التحقق: 45.98 g + 70.91 g = 116.89 g، وهي كتلة كلوريد الصوديوم المعطاة، فالحل صحيح.', '["كتابة قانون حفظ الكتلة: كتلة المتفاعلات = كتلة النواتج","كتلة الصوديوم + كتلة الكلور = كتلة كلوريد الصوديوم","كتلة الكلور = 116.89 − 45.98 = 70.91 g","التحقق: 45.98 + 70.91 = 116.89 g"]'::jsonb, '["كتلة Na + كتلة Cl₂ = كتلة NaCl","كتلة Cl₂ = 116.89 g − 45.98 g","كتلة Cl₂ = 70.91 g","التحقق: 45.98 g + 70.91 g = 116.89 g"]'::jsonb, '[{"element":"كتابة العلاقة من قانون حفظ الكتلة","marks":1},{"element":"التعويض والحساب الصحيح (70.91 g مع الوحدة)","marks":1.5},{"element":"التحقق من الجواب بجمع كتل المتفاعلات","marks":0.5}]'::jsonb, '[{"level":"3 درجات","description":"علاقة صحيحة، وناتج 70.91 g بالوحدة، وتحقق من الجواب"},{"level":"2 درجتان","description":"علاقة صحيحة وناتج صحيح دون تحقق أو دون وحدة"},{"level":"1 درجة","description":"كتابة العلاقة الصحيحة فقط أو خطأ حسابي بسيط في الطرح"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["جمع كتلة الصوديوم وكتلة كلوريد الصوديوم بدل طرحها","اعتبار كتلة الكلور 116.89 g أو 45.98 g مباشرة","إهمال الوحدة أو الخطأ في الطرح العشري"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (3 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (29%)"}],"at":"2026-10-18T03:32:48.192Z"}'::jsonb),
('essay', 2, null::int, null, null, 'كتلة HCl + كتلة NH₃ = كتلة NH₄Cl. إذن كتلة NH₃ = 157.5 g − 106.5 g = 51.0 g. مجموع كتل المتفاعلين = 106.5 g + 51.0 g = 157.5 g، وهي تساوي كتلة الناتج تمامًا. فقانون حفظ الكتلة مطبّق؛ لأن كتلة المتفاعلات تساوي كتلة النواتج ولم تُفقد كتلة ولم تُستحدث.', '["كتلة HCl + كتلة NH₃ = كتلة NH₄Cl","كتلة NH₃ = 157.5 − 106.5 = 51.0 g","مجموع كتلتي المتفاعلين 157.5 g يساوي كتلة الناتج","نعم؛ القانون مطبق لتساوي كتلة المتفاعلات مع كتلة النواتج"]'::jsonb, '["كتلة NH₃ = كتلة NH₄Cl − كتلة HCl","كتلة NH₃ = 157.5 g − 106.5 g = 51.0 g","كتلة المتفاعلات = 106.5 g + 51.0 g = 157.5 g","كتلة المتفاعلات = كتلة النواتج = 157.5 g"]'::jsonb, '[{"element":"العلاقة الصحيحة من قانون حفظ الكتلة","marks":1},{"element":"حساب كتلة الأمونيا 51.0 g","marks":1},{"element":"الحكم بتطبيق القانون","marks":0.5},{"element":"تعليل الحكم بتساوي كتلتي المتفاعلات والنواتج","marks":1.5}]'::jsonb, '[{"level":"4 درجات","description":"علاقة صحيحة، وناتج 51.0 g، وحكم صحيح مع تعليل بتساوي الكتل"},{"level":"2–3 درجات","description":"حساب صحيح مع حكم دون تعليل كافٍ، أو تعليل صحيح مع خطأ حسابي بسيط"},{"level":"1 درجة","description":"كتابة العلاقة الصحيحة فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["جمع 106.5 و157.5 بدل طرحهما","القول إن القانون لم يطبق لأن المتفاعلات غازات والناتج صلب","الحكم بتطبيق القانون دون ذكر تساوي الكتل"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (20%)"}],"at":"2026-10-18T03:32:48.193Z"}'::jsonb),
('essay', 3, null::int, null, null, 'كتلة البروم المتفاعلة = كتلة البروم قبل التفاعل − كتلة البروم الباقي = 100.0 g − 8.5 g = 91.5 g. الألومنيوم تفاعل كله (10.3 g). كتلة المركب الناتج = كتلة المتفاعلات = 10.3 g + 91.5 g = 101.8 g. التحقق: الكتلة الكلية قبل التفاعل = 10.3 + 100.0 = 110.3 g، وبعد التفاعل = 101.8 g (مركب) + 8.5 g (بروم باقٍ) = 110.3 g، فالكتلة محفوظة.', '["كتلة البروم المتفاعلة = 100.0 − 8.5 = 91.5 g","الألومنيوم تفاعل كله: 10.3 g","كتلة المركب = 10.3 + 91.5 = 101.8 g","الكتلة الكلية قبل التفاعل 110.3 g تساوي بعده 101.8 + 8.5 = 110.3 g"]'::jsonb, '["كتلة Br₂ المتفاعل = 100.0 g − 8.5 g = 91.5 g","كتلة المركب = كتلة Al المتفاعل + كتلة Br₂ المتفاعل = 10.3 g + 91.5 g = 101.8 g","الكتلة قبل التفاعل = 10.3 g + 100.0 g = 110.3 g","الكتلة بعد التفاعل = 101.8 g + 8.5 g = 110.3 g، فالكتلة محفوظة"]'::jsonb, '[{"element":"كتلة البروم المتفاعلة 91.5 g","marks":1.5},{"element":"كتلة المركب الناتج 101.8 g","marks":1.5},{"element":"التحقق بمقارنة الكتلة الكلية قبل التفاعل وبعده (110.3 g)","marks":2}]'::jsonb, '[{"level":"5 درجات","description":"حساب صحيح لكتلتي البروم المتفاعل والمركب مع تحقق كامل بمقارنة الكتلتين الكليتين"},{"level":"3–4 درجات","description":"حساب صحيح لكتلة واحدة من الكتلتين مع تحقق، أو الكتلتان صحيحتان دون تحقق"},{"level":"1–2 درجة","description":"حساب كتلة البروم المتفاعلة فقط أو الجمع الكلي قبل التفاعل فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["عدّ كتلة المركب 100.0 + 10.3 دون طرح البروم الباقي","اعتبار كتلة البروم المتفاعلة 8.5 g","نسيان إضافة البروم الباقي عند التحقق من الكتلة بعد التفاعل"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (15%)"}],"at":"2026-10-18T03:32:48.193Z"}'::jsonb)
