from (values
('mcq', 1, 2, 'تكوّن راسب صلب عند خلط محلولين يدل على تكوّن مادة جديدة، وهو من أدلة حدوث التفاعل الكيميائي؛ أما الانصهار والكسر وتغيير الشكل فتغيرات فيزيائية لا تتكون فيها مادة جديدة.', '["الانصهار تغير في الحالة فقط، ويبقى تركيب الماء كما هو، فهو تغير فيزيائي.","كسر الزجاج يغير الشكل والحجم فقط دون تغير تركيب الزجاج.","","تغيير شكل الألومنيوم لا يغير تركيبه، فلا يدل على تفاعل."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (50%)"}],"at":"2026-10-18T03:32:48.194Z"}'::jsonb),
('mcq', 2, 0, 'الصدأ مسحوق بني مائل إلى البرتقالي لا ينجذب إلى المغناطيس بينما ينجذب الحديد؛ واختلاف خواصه عن خواص الحديد دليل على تكوّن مادة جديدة أي حدوث تفاعل كيميائي.', '["","الصدأ يتكوّن من تفاعل الحديد مع أكسجين الهواء، فهو ليس حديدًا وحده.","الصدأ لا ينجذب إلى المغناطيس، وهذا الاختلاف عن الحديد هو الدليل.","الصدأ بني مائل إلى البرتقالي وليس فضيًا لامعًا، وتغير اللون يدل على التفاعل."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (6%)"}],"at":"2026-10-18T03:32:48.194Z"}'::jsonb),
('mcq', 3, 3, 'الفقاعات المتصاعدة من سطح الفلز غاز جديد يتكوّن في أثناء التفاعل، فالدليل هو تصاعد غاز.', '["لم يرد في الملاحظة تغير لون، بل ظهور فقاعات.","الراسب مادة صلبة تتكوّن في المحلول، وهي غير مذكورة في الملاحظة.","لم يُذكر انطلاق ضوء، والملاحظة هي فقاعات غازية.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (18%)"}],"at":"2026-10-18T03:32:48.194Z"}'::jsonb),
('mcq', 4, 1, 'تحوّل الصلب الأحمر إلى سائل فضي تغير في اللون، وتكوّن الغاز عديم اللون (الأكسجين) هو تصاعد غاز؛ فالدليلان هما تغير اللون وتصاعد غاز.', '["لم يتكوّن راسب صلب في المحلول، ولم يذكر انطلاق ضوء في الملاحظة.","","لم يتغير الحال فقط؛ فقد تكوّنت مادتان جديدتان هما الزئبق والأكسجين.","تكوّنت مواد جديدة (الزئبق والأكسجين) ولم يقتصر التغير على الشكل."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (28%)"}],"at":"2026-10-18T03:32:48.195Z"}'::jsonb),
('mcq', 5, 2, 'الفقاعات في الغليان بخار ماء، أي الماء نفسه بحالة غازية؛ فلم تتكوّن مادة جديدة، والغليان تغير فيزيائي. والدليل الأساسي على التفاعل هو تكوّن مادة جديدة بخواص مختلفة.', '["تصاعد الغاز قد يدل على تفاعل إذا كان الغاز مادة جديدة، كالغاز الناتج من تفاعل الخارصين مع الحمض.","الماء لا يتحلل عند غليانه؛ فبخار الماء ما زال H₂O.","","ارتفاع درجة الحرارة وحده لا يفسر عدم حدوث التفاعل؛ فالسبب أن البخار هو الماء نفسه."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (22%)"}],"at":"2026-10-18T03:32:48.195Z"}'::jsonb),
('mcq', 6, 3, 'تصاعد الغاز وتكوّن الراسب وتغير اللون من الأدلة على تكوّن مواد جديدة، أما بقية المجموعات فتغيرات فيزيائية.', '["هذه تغيرات في حالة المادة وهي تغيرات فيزيائية.","هذه تغيرات في الشكل أو الحجم فقط وهي فيزيائية.","هذه تغيرات فيزيائية لا تتكوّن فيها مادة جديدة.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (21%)"}],"at":"2026-10-18T03:32:48.195Z"}'::jsonb),
('mcq', 7, 0, 'قد يظهر تغير اللون أو الفقاعات في تغيرات فيزيائية، أما الدليل القاطع فهو تكوّن مادة جديدة بخواص مختلفة عن خواص المتفاعلات.', '["","قد تظهر الفقاعات عند الغليان وهو تغير فيزيائي، فلا تكفي وحدها دليلًا قاطعًا.","قد يتغير اللون دون تكوّن مادة جديدة، فلا يكفي وحده للحكم.","تغير الحجم يحدث في تغيرات فيزيائية كالتمدد، فلا يدل على تفاعل."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (50%)"}],"at":"2026-10-18T03:32:48.196Z"}'::jsonb),
('essay', 1, null::int, null, null, 'من الأدلة: (1) تغير اللون، كتحول أكسيد الزئبق II الأحمر إلى زئبق فضي. (2) تصاعد غاز على هيئة فقاعات، كتصاعد الغاز عند إضافة حمض الهيدروكلوريك إلى الخارصين. (3) تكوّن راسب صلب عند خلط محلولين. (4) تغير الطعم أو الرائحة، كتعفن الطعام. ويمكن أيضًا ذكر انطلاق حرارة أو ضوء كاحتراق الخشب، أو تكوّن مادة لها خواص مختلفة كالصدأ الذي لا ينجذب إلى المغناطيس.', '["تغير اللون مع مثال","تصاعد غاز مع مثال","تكوّن راسب مع مثال","تغير الطعم أو الرائحة أو انطلاق حرارة وضوء أو تكوّن مادة بخواص مختلفة مع مثال"]'::jsonb, '[]'::jsonb, '[{"element":"الدليل الأول مع مثال صحيح","marks":1},{"element":"الدليل الثاني مع مثال صحيح","marks":1},{"element":"الدليل الثالث مع مثال صحيح","marks":1},{"element":"الدليل الرابع مع مثال صحيح","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"أربعة أدلة صحيحة مع مثال مناسب لكل دليل"},{"level":"2–3 درجات","description":"دليلان أو ثلاثة صحيحة مع أمثلتها، أو أربعة أدلة دون أمثلة كافية"},{"level":"1 درجة","description":"دليل واحد صحيح مع مثاله"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["ذكر تغيرات فيزيائية (كالانصهار أو تغير الشكل) على أنها أدلة","ذكر الدليل دون مثال","تكرار الدليل نفسه بأسماء مختلفة"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (21%)"}],"at":"2026-10-18T03:32:48.196Z"}'::jsonb),
('essay', 2, null::int, null, null, 'الأدلة: تغير اللون من الأحمر إلى الفضي، وتصاعد غاز عديم اللون هو الأكسجين. وتكفي للحكم لأن المادتين الناتجتين، الزئبق السائل الفضي والأكسجين الغازي، لهما خواص وتراكيب مختلفة عن أكسيد الزئبق II الأحمر الصلب؛ أي تكوّنت مواد جديدة، وتكوّن المواد الجديدة هو الدليل الأساسي على التفاعل الكيميائي.', '["تغير اللون من الأحمر إلى الفضي","تصاعد غاز (الأكسجين)","تكوّن مادتين جديدتين بخواص مختلفة","تكوّن المواد الجديدة هو الدليل الأساسي"]'::jsonb, '[]'::jsonb, '[{"element":"ذكر دليل تغير اللون","marks":1},{"element":"ذكر دليل تصاعد الغاز","marks":1},{"element":"التفسير بتكوّن مواد جديدة مختلفة الخواص","marks":1}]'::jsonb, '[{"level":"3 درجات","description":"ذكر الدليلين وتفسير الكفاية بتكوّن مواد جديدة"},{"level":"2 درجتان","description":"ذكر الدليلين دون تفسير، أو دليل واحد مع تفسير"},{"level":"1 درجة","description":"ذكر دليل واحد فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["عدّ تغير الحالة من صلب إلى سائل دليلًا بمفرده","عدم ذكر الغاز المتصاعد","تفسير الحكم بالتسخين وحده دون تكوّن مواد جديدة"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (3 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (28%)"}],"at":"2026-10-18T03:32:48.196Z"}'::jsonb),
('essay', 3, null::int, null, null, 'الفقاعات عند غليان الماء هي بخار ماء، أي الماء نفسه بحالة غازية، فلم تتكوّن مادة جديدة؛ والغليان تغير فيزيائي لا يدل على تفاعل. أما الفقاعات عند إضافة الحمض إلى الخارصين فهي غاز جديد (الهيدروجين) يتصاعد وتتكوّن معه مواد أخرى جديدة، فهذا تفاعل كيميائي. والفرق أن ظهور الفقاعات وحده لا يكفي للحكم، والمعيار هو تكوّن مادة جديدة بخواص مختلفة عن المتفاعلات.', '["فقاعات الغليان بخار ماء ولا تتكون مادة جديدة (تغير فيزيائي)","فقاعات الخارصين مع الحمض غاز جديد (تفاعل كيميائي)","الفقاعات وحدها لا تكفي دليلًا","المعيار هو تكوّن مادة جديدة بخواص مختلفة"]'::jsonb, '[]'::jsonb, '[{"element":"تفسير فقاعات غليان الماء بأنها بخار ماء وتغير فيزيائي","marks":1.5},{"element":"تفسير فقاعات الخارصين مع الحمض بأنها غاز جديد وتفاعل كيميائي","marks":1.5},{"element":"ذكر معيار تكوّن مادة جديدة وأن الفقاعات وحدها لا تكفي","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"تفسير صحيح للحالتين مع تحديد معيار تكوّن مادة جديدة"},{"level":"2–3 درجات","description":"تفسير صحيح لإحدى الحالتين مع المعيار، أو الحالتان دون المعيار"},{"level":"1 درجة","description":"تحديد أي الحالتين تفاعل دون تعليل"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["القول إن غليان الماء تفاعل كيميائي لأن فقاعات تظهر فيه","القول إن الماء يتحلل إلى هيدروجين وأكسجين عند الغليان","الحكم دون الإشارة إلى تكوّن مادة جديدة"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (20%)"}],"at":"2026-10-18T03:32:48.196Z"}'::jsonb)
) as v(type, number, ci, ex, dn, ma, ae, ss, mk, rb, ce, ac)
