('mcq', 4, 'يتحول الجليد إلى ماء سائل عند تسخينه. لماذا يُعدّ هذا التغير فيزيائيًا؟', null, '["لأن الجليد يتحول إلى هيدروجين وأكسجين","لأن درجة الحرارة تتغير في أثناء التسخين","لأن تركيب الماء يبقى واحدًا رغم اختلاف المظهر","لأن الماء السائل أخف من الجليد دائمًا"]'::jsonb, 'فهم', 'تعليل نوع التغير', 'متوسط', 'الكتاب ص 50 — دورة الماء'),
('mcq', 5, 'ما الذي يحدث للمادة في التغير الفيزيائي؟', null, '["يتغير تركيبها وتبقى خواصها الفيزيائية كما هي","تتغير خواصها الفيزيائية ويبقى تركيبها ثابتًا","يتغير تركيبها وخواصها الفيزيائية معًا","لا يتغير شيء من خواصها أو تركيبها"]'::jsonb, 'فهم', 'تذكر خلاصة', 'متوسط', 'الكتاب ص 53 — خلاصة 2-2'),
('mcq', 6, 'أيّ زوج من التغيرات الآتية فيزيائي بكامله؟', null, '["كسر لوح زجاجي وتكثّف بخار الماء","تجمد الماء وصدأ الحديد","تعفّن الطعام وانصهار الجليد","احتراق الخشب وتقطيع ورقة"]'::jsonb, 'تذكر', 'اختيار أمثلة صحيحة', 'متوسط', 'الكتاب ص 50 — التغيرات الفيزيائية وتغير الحالة'),
('mcq', 7, 'شُكّلت صفيحة ألومنيوم مستوية على هيئة كرة فاختلف مظهرها. ماذا حدث لتركيبها وما نوع التغير؟', null, '["تغير تركيبها لأن مظهرها اختلف، والتغير كيميائي","تغير تركيبها لأنها صارت مادة جديدة، والتغير كيميائي","لم يتغير تركيبها، والتغير كيميائي لأن الشكل تغير","لم يتغير تركيبها لأنها ما زالت ألومنيومًا، والتغير فيزيائي"]'::jsonb, 'فهم', 'تفسير موقف', 'صعب', 'الكتاب ص 50 — التغيرات الفيزيائية؛ ص 53 — السؤال 14'),
('essay', 1, 'عرّف التغير الفيزيائي، ثم اذكر ثلاثة أمثلة عليه.', null, null, 'تذكر', 'تعريف مع أمثلة', 'سهل', 'الكتاب ص 50 — التغيرات الفيزيائية؛ ص 53 — السؤال 11'),
('essay', 2, 'صف التغيرات التي تحدث للماء عند تسخين قطعة جليد حتى يتحول إلى بخار، ثم بيّن لماذا تُعدّ هذه التغيرات فيزيائية.', null, null, 'فهم', 'وصف وتفسير', 'متوسط', 'الكتاب ص 50 — دورة الماء'),
('essay', 3, 'قال طالب: «إذا تغير مظهر المادة فقد تكوّنت مادة جديدة». قوّم هذه العبارة مستعينًا بمثالين من التغيرات الفيزيائية، وبيّن ما المعيار الصحيح لتمييز التغير الفيزيائي.', null, null, 'تقويم', 'تقويم عبارة', 'صعب', 'الكتاب ص 50 — التغيرات الفيزيائية؛ ص 53 — السؤال 14')
) as v(type, number, stem, stimulus, options, tl, qk, diff, src)
