from (values
('mcq', 1, 1, 'التغير الفيزيائي هو التغير الذي يحدث دون أن يغير تركيب المادة، فقد يتغير مظهرها أو حالتها لكن تركيبها ثابت.', '["هذا تعريف التغير الكيميائي الذي تتحول فيه المواد إلى مواد جديدة.","","المواد الجديدة ذات الخواص المختلفة تنتج في التغير الكيميائي لا الفيزيائي.","تغير التركيب وتكوّن نواتج جديدة من خصائص التغير الكيميائي."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (13%)"}],"at":"2026-10-18T03:32:48.197Z"}'::jsonb),
('mcq', 2, 3, 'عند تشكيل صفيحة الألومنيوم في صورة كرة يتغير الشكل فقط، ويبقى التركيب ألومنيومًا؛ فهو تغير فيزيائي.', '["الصدأ مادة جديدة تتكوّن من تفاعل الحديد مع الأكسجين، فهو تغير كيميائي.","التعفن يغير طعم الخبز وقابليته للهضم ويكوّن مواد جديدة، فهو تغير كيميائي.","الاحتراق يكوّن مواد جديدة مثل ثاني أكسيد الكربون، فهو تغير كيميائي.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (25%)"}],"at":"2026-10-18T03:32:48.197Z"}'::jsonb),
('mcq', 3, 0, 'تقطيع الورقة يغير حجم القطع وشكلها فقط، وتبقى المادة ورقًا دون تغير في تركيبها؛ فهو تغير فيزيائي.', '["","التعفن تغير كيميائي يغير الطعم وقابلية الهضم.","الصدأ مادة جديدة مختلفة الخواص عن الحديد، فهو تغير كيميائي.","الاحتراق ينتج مواد جديدة كالرماد وثاني أكسيد الكربون، فهو تغير كيميائي."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (25%)"}],"at":"2026-10-18T03:32:48.197Z"}'::jsonb),
('mcq', 4, 2, 'الجليد والماء السائل مختلفان في المظهر لكن تركيبهما واحد (H₂O)، فلم تتكوّن مادة جديدة؛ لذلك يُعدّ الانصهار تغيرًا فيزيائيًا.', '["الماء لا يتحلل عند الانصهار؛ فتركيبه يبقى H₂O.","تغير درجة الحرارة لا يحدد نوع التغير؛ والمعيار هو بقاء التركيب.","","المقارنة بين الكثافتين لا تحدد نوع التغير، والمعيار هو بقاء التركيب."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (14%)"}],"at":"2026-10-18T03:32:48.197Z"}'::jsonb),
('mcq', 5, 1, 'التغير الفيزيائي يغير الخواص الفيزيائية للمادة (كالشكل والحالة) دون أن يغير تركيبها.', '["هذا معكوس الصواب؛ فالتركيب هو الذي يبقى ثابتًا في التغير الفيزيائي.","","تغير التركيب يحدث في التغير الكيميائي لا الفيزيائي.","الخواص الفيزيائية تتغير في التغير الفيزيائي، كالشكل أو الحالة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (25%)"}],"at":"2026-10-18T03:32:48.198Z"}'::jsonb),
('mcq', 6, 0, 'كسر الزجاج وتكثف بخار الماء تغيران فيزيائيان؛ الأول يغير الشكل والثاني يغير الحالة دون تغير في التركيب.', '["","صدأ الحديد تغير كيميائي، وإن كان تجمد الماء فيزيائيًا.","تعفن الطعام تغير كيميائي، وإن كان انصهار الجليد فيزيائيًا.","احتراق الخشب تغير كيميائي، وإن كان تقطيع الورقة فيزيائيًا."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (25%)"}],"at":"2026-10-18T03:32:48.198Z"}'::jsonb),
('mcq', 7, 3, 'رغم اختلاف المظهر يبقى تركيب الصفيحة ألومنيومًا؛ فالتغير فيزيائي لأن التركيب لم يتغير.', '["اختلاف المظهر لا يعني تغير التركيب؛ فقد يتغير المظهر في التغير الفيزيائي.","لم تتكوّن مادة جديدة؛ فالكرة ما زالت ألومنيومًا.","تغير الشكل وحده لا يجعل التغير كيميائيًا؛ فالمعيار هو تغير التركيب وتكوّن مادة جديدة.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (6%)"}],"at":"2026-10-18T03:32:48.198Z"}'::jsonb),
('essay', 1, null::int, null, null, 'التغير الفيزيائي هو التغير الذي يحدث دون أن يغير تركيب المادة؛ فتتغير خواصها الفيزيائية كالشكل أو الحالة ويبقى تركيبها ثابتًا. ومن أمثلته: تشكيل صفيحة ألومنيوم في صورة كرة، وتقطيع ورقة، وكسر لوح زجاجي، وانصهار الجليد، وغليان الماء، وتكثف بخار الماء.', '["التغير الذي يحدث دون أن يغير تركيب المادة","تتغير الخواص الفيزيائية ويبقى التركيب ثابتًا","ثلاثة أمثلة صحيحة على تغيرات فيزيائية"]'::jsonb, '[]'::jsonb, '[{"element":"تعريف التغير الفيزيائي","marks":1},{"element":"الإشارة إلى بقاء التركيب وتغير الخواص الفيزيائية","marks":1},{"element":"ثلاثة أمثلة صحيحة","marks":2}]'::jsonb, '[{"level":"4 درجات","description":"تعريف صحيح مع بقاء التركيب وثلاثة أمثلة صحيحة"},{"level":"2–3 درجات","description":"تعريف صحيح مع مثالين، أو ثلاثة أمثلة مع تعريف ناقص"},{"level":"1 درجة","description":"تعريف جزئي أو مثال واحد فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["ذكر تغيرات كيميائية كالصدأ أو الاحتراق مثالًا","تعريف التغير الفيزيائي بأنه ما لا يغير المظهر","الاكتفاء بمثال أو مثالين"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (18%)"}],"at":"2026-10-18T03:32:48.198Z"}'::jsonb),
('essay', 2, null::int, null, null, 'عند تسخين الجليد يبدأ في الانصهار ويصبح ماء سائلًا، وعند رفع درجة حرارة الماء إلى 100°C يبدأ بالغليان ويتحول إلى بخار. وهذه التغيرات فيزيائية لأن المظهر والحالة يختلفان لكن تركيب الماء واحد (H₂O) في الجليد والماء السائل والبخار، ولم تتكوّن مادة جديدة.', '["انصهار الجليد وتحوله إلى ماء سائل","غليان الماء عند 100°C وتحوله إلى بخار","تركيب الماء ثابت في الحالات الثلاث","لم تتكوّن مادة جديدة فالتغير فيزيائي"]'::jsonb, '[]'::jsonb, '[{"element":"وصف الانصهار","marks":1},{"element":"وصف الغليان عند 100°C","marks":1},{"element":"تعليل كون التغيرين فيزيائيين بثبات التركيب","marks":2}]'::jsonb, '[{"level":"4 درجات","description":"وصف صحيح للتغيرين وتعليل بثبات تركيب الماء"},{"level":"2–3 درجات","description":"وصف صحيح للتغيرين مع تعليل ناقص، أو تعليل صحيح مع وصف تغير واحد"},{"level":"1 درجة","description":"وصف أحد التغيرين دون تعليل"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["القول إن الماء تحول إلى مادة جديدة عند الغليان","تعليل الحكم باختلاف المظهر وحده","نسيان ذكر درجة الغليان 100°C"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (12%)"}],"at":"2026-10-18T03:32:48.198Z"}'::jsonb),
('essay', 3, null::int, null, null, 'العبارة غير صحيحة؛ فالمظهر قد يتغير كثيرًا في التغير الفيزيائي دون أن يتغير التركيب. فصفيحة الألومنيوم التي تتحول إلى كرة تختلف في شكلها وتبقى ألومنيومًا، والجليد حين ينصهر يختلف عن الماء السائل في مظهره ويبقى تركيبهما واحدًا. والمعيار الصحيح هو تركيب المادة: إن بقي تركيبها ثابتًا فالتغير فيزيائي، وإن تكوّنت مواد جديدة فالتغير كيميائي.', '["العبارة غير صحيحة","مثال أول: تغير شكل الألومنيوم دون تغير تركيبه","مثال ثانٍ: انصهار الجليد دون تغير تركيب الماء","المعيار هو بقاء تركيب المادة أو تغيره"]'::jsonb, '[]'::jsonb, '[{"element":"الحكم على العبارة بأنها غير صحيحة","marks":1},{"element":"مثالان صحيحان مع توضيح بقاء التركيب","marks":1.5},{"element":"ذكر معيار التركيب في التمييز","marks":0.5}]'::jsonb, '[{"level":"3 درجات","description":"حكم صحيح، ومثالان صحيحان، وذكر معيار التركيب"},{"level":"2 درجتان","description":"حكم صحيح مع مثال واحد ومعيار، أو مثالان دون معيار"},{"level":"1 درجة","description":"حكم صحيح دون تعليل"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["الموافقة على العبارة لأن المظهر يختلف","ذكر أمثلة لا تُظهر بقاء التركيب","عدم ذكر معيار التركيب"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (3 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (8%)"}],"at":"2026-10-18T03:32:48.199Z"}'::jsonb)
) as v(type, number, ci, ex, dn, ma, ae, ss, mk, rb, ce, ac)
