('mcq', 5, 'أيّ المصطلحات الآتية تشير إلى تفاعل كيميائي؟', null, '["الانصهار","التبخر","التكثف","الاحتراق"]'::jsonb, 'تذكر', 'تذكر مصطلحات', 'متوسط', 'الكتاب ص 51 — مصطلحات التفاعل الكيميائي'),
('mcq', 6, 'عند تسخين أكسيد الزئبق II الأحمر يتحلل إلى زئبق وأكسجين. لماذا يُعدّ ذلك تغيرًا كيميائيًا؟', null, '["لأن مادة جديدة اختلفت خواصها عن المتفاعلة قد تكوّنت","لأن المادة الحمراء انصهرت بالتسخين","لأن حجم المادة تغير فقط","لأن التسخين يغير الحالة الفيزيائية فقط"]'::jsonb, 'فهم', 'تعليل نوع التغير', 'متوسط', 'الكتاب ص 53 — تحلل أكسيد الزئبق II بالحرارة'),
('mcq', 7, 'يتكوّن صدأ الحديد من تفاعل الحديد مع أكسجين الهواء. لماذا يُعدّ ذلك تغيرًا كيميائيًا؟', null, '["لأن الصدأ يتكوّن بتأثير الهواء الجوي فقط","لأن الصدأ مادة جديدة تختلف تركيبًا وخواصًا عن الحديد والأكسجين","لأن الحديد يبقى حديدًا ويتغير لونه فقط","لأن الحديد يغير شكله بتأثير الأكسجين"]'::jsonb, 'فهم', 'تعليل نوع التغير', 'صعب', 'الكتاب ص 51 — التغيرات الكيميائية (صدأ الحديد)'),
('essay', 1, 'عرّف التغير الكيميائي، ثم اذكر ثلاثة أمثلة عليه.', null, null, 'تذكر', 'تعريف مع أمثلة', 'سهل', 'الكتاب ص 51 — التغيرات الكيميائية'),
('essay', 2, 'يتكوّن الصدأ عندما يتفاعل الحديد مع أكسجين الهواء. وضّح لماذا يُعدّ ذلك تغيرًا كيميائيًا بمقارنة خواص الصدأ بخواص الحديد.', null, null, 'فهم', 'تفسير مع مقارنة', 'متوسط', 'الكتاب ص 51 — دلائل حدوث التفاعلات الكيميائية'),
('essay', 3, 'عند تسخين أكسيد الزئبق II، وهو مادة صلبة حمراء، يتكوّن زئبق فضي سائل وغاز الأكسجين. حدّد المتفاعلات والنواتج، وبيّن لماذا يُعدّ ذلك تغيرًا كيميائيًا وليس فيزيائيًا.', null, null, 'تطبيق', 'تطبيق مع تعليل', 'صعب', 'الكتاب ص 53 — تحلل أكسيد الزئبق II بالحرارة')
) as v(type, number, stem, stimulus, options, tl, qk, diff, src)
