from (values
('mcq', 1, 2, 'التغير الكيميائي عملية تتضمن تغيّر مادة أو أكثر إلى مواد جديدة، ويسمى أيضًا التفاعل الكيميائي.', '["هذا وصف تغير الحالة، وهو تغير فيزيائي لا يغير التركيب.","تغير الشكل أو الحجم تغير فيزيائي ولا تتكوّن فيه مواد جديدة.","","هذا وصف للتغير الفيزيائي الذي لا تتكوّن فيه مواد جديدة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (13%)"}],"at":"2026-10-18T03:32:48.200Z"}'::jsonb),
('mcq', 2, 0, 'يسمى التغير الكيميائي أيضًا التفاعل الكيميائي، وفيه تتحول المتفاعلات إلى نواتج.', '["","تغير الحالة تغير فيزيائي لا تتكوّن فيه مواد جديدة.","التغير الفيزيائي مقابل التغير الكيميائي وليس اسمًا آخر له.","الخاصية الكيميائية صفة للمادة تصف قابليتها للتفاعل، وليست اسمًا للعملية نفسها."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (22%)"}],"at":"2026-10-18T03:32:48.200Z"}'::jsonb),
('mcq', 3, 3, 'تعفّن الطعام تغير كيميائي؛ لأنه يكوّن مواد جديدة يختلف طعمها وقابليتها للهضم عن الطعام الطازج.', '["كسر الزجاج يغير الشكل فقط فهو تغير فيزيائي.","التجمد تغير في الحالة فقط فهو تغير فيزيائي.","تقطيع الورقة يغير الحجم والشكل فقط فهو تغير فيزيائي.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (22%)"}],"at":"2026-10-18T03:32:48.200Z"}'::jsonb),
('mcq', 4, 1, 'في التفاعل الكيميائي تتكوّن مواد جديدة لها تراكيب وخواص مختلفة عن تراكيب وخواص المواد قبل التفاعل.', '["التركيب يتغير أيضًا؛ فالمادة الجديدة لا تحتفظ بتركيب المتفاعلة.","","الخواص تتغير مع التركيب؛ فلا تبقى الخواص نفسها.","هذا وصف لتغير الحالة (تغير فيزيائي) وليس التفاعل الكيميائي."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (18%)"}],"at":"2026-10-18T03:32:48.200Z"}'::jsonb),
('mcq', 5, 3, 'الاحتراق من المصطلحات التي تشير إلى التفاعل الكيميائي (مع التحلل والانفجار والصدأ والتأكسد والتآكل والتخمر والتعفن)، أما الانصهار والتبخر والتكثف فمن تغيرات الحالة الفيزيائية.', '["الانصهار تغير في الحالة من صلب إلى سائل وهو فيزيائي.","التبخر تغير في الحالة من سائل إلى غاز وهو فيزيائي.","التكثف تغير في الحالة من غاز إلى سائل وهو فيزيائي.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (6%)"}],"at":"2026-10-18T03:32:48.200Z"}'::jsonb),
('mcq', 6, 0, 'تحلل أكسيد الزئبق II الأحمر الصلب أنتج مادتين جديدتين هما الزئبق السائل الفضي والأكسجين الغازي، لهما تراكيب وخواص مختلفة؛ لذلك فالتغير كيميائي.', '["","لم يحدث انصهار فقط، بل تكوّنت مادتان جديدتان هما الزئبق والأكسجين.","لم يتغير الحجم فقط؛ بل تغير التركيب بتكوّن مواد جديدة.","التغير ليس في الحالة فقط، فقد نتجت مواد لها تراكيب وخواص مختلفة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (38%)"}],"at":"2026-10-18T03:32:48.201Z"}'::jsonb),
('mcq', 7, 1, 'الصدأ مادة بنية مائلة إلى البرتقالي لا تنجذب إلى المغناطيس، تختلف في تركيبها وخواصها عن الحديد والأكسجين؛ فتكوّنها تغير كيميائي.', '["المهم تكوّن مادة جديدة وليس مجرد وجود الهواء، فالأكسجين يتفاعل مع الحديد.","","الحديد لا يبقى حديدًا؛ فقد تحول إلى مادة جديدة هي الصدأ.","التغير ليس في الشكل فقط؛ فقد تكوّنت مادة جديدة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (53%)"}],"at":"2026-10-18T03:32:48.201Z"}'::jsonb),
('essay', 1, null::int, null, null, 'التغير الكيميائي عملية تتضمن تغيّر مادة أو أكثر إلى مواد جديدة، ويسمى أيضًا التفاعل الكيميائي، وللمواد الجديدة تراكيب وخواص مختلفة عن المواد قبل التفاعل. ومن أمثلته: تكوّن صدأ الحديد، وتعفّن الطعام، وتحلل أكسيد الزئبق II بالحرارة إلى زئبق وأكسجين، واحتراق الخشب.', '["عملية تتغير فيها مادة أو أكثر إلى مواد جديدة","يسمى التفاعل الكيميائي","المواد الجديدة لها تراكيب وخواص مختلفة","ثلاثة أمثلة صحيحة"]'::jsonb, '[]'::jsonb, '[{"element":"تعريف التغير الكيميائي","marks":1},{"element":"ذكر أن للمواد الجديدة تراكيب وخواص مختلفة","marks":1},{"element":"ثلاثة أمثلة صحيحة","marks":2}]'::jsonb, '[{"level":"4 درجات","description":"تعريف كامل مع خواص المواد الجديدة وثلاثة أمثلة صحيحة"},{"level":"2–3 درجات","description":"تعريف صحيح مع مثالين، أو ثلاثة أمثلة مع تعريف ناقص"},{"level":"1 درجة","description":"تعريف جزئي أو مثال واحد"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["ذكر تغيرات فيزيائية كالانصهار أو التقطيع مثالًا","تعريف التغير الكيميائي بتغير الشكل أو اللون فقط","نسيان أن التغير الكيميائي يسمى أيضًا التفاعل الكيميائي"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (18%)"}],"at":"2026-10-18T03:32:48.201Z"}'::jsonb),
('essay', 2, null::int, null, null, 'الصدأ مادة بنية مائلة إلى البرتقالي وتكون في صورة مسحوق، أما الحديد فصلب ينجذب إلى المغناطيس بخلاف الصدأ الذي لا ينجذب إليه. فاختلاف خواص الصدأ كثيرًا عن خواص الحديد والأكسجين يدل على تكوّن مادة جديدة لها تركيب مختلف، وهذا هو التغير الكيميائي.', '["الصدأ بني مائل إلى البرتقالي ومسحوق","الصدأ لا ينجذب إلى المغناطيس والحديد ينجذب","الصدأ مادة جديدة مختلفة التركيب والخواص","تكوّن مادة جديدة يعني تغيرًا كيميائيًا"]'::jsonb, '[]'::jsonb, '[{"element":"وصف خواص الصدأ ومقارنتها بالحديد","marks":1.5},{"element":"ذكر عدم انجذاب الصدأ إلى المغناطيس","marks":0.5},{"element":"الاستنتاج بتكوّن مادة جديدة وأن التغير كيميائي","marks":2}]'::jsonb, '[{"level":"4 درجات","description":"مقارنة صحيحة للخواص مع استنتاج تكوّن مادة جديدة"},{"level":"2–3 درجات","description":"مقارنة صحيحة مع استنتاج ناقص، أو استنتاج دون مقارنة كافية"},{"level":"1 درجة","description":"ذكر خاصية واحدة فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["القول إن الحديد تغير لونه فقط","عدم الإشارة إلى المغناطيس أو إلى اختلاف الخواص","الاكتفاء بالحكم دون تعليل"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (53%)"}],"at":"2026-10-18T03:32:48.201Z"}'::jsonb),
('essay', 3, null::int, null, null, 'المتفاعل: أكسيد الزئبق II، والنواتج: الزئبق والأكسجين. ويُعدّ ذلك تغيرًا كيميائيًا لأن مادة واحدة تحولت إلى مادتين جديدتين مختلفتين في التركيب والخواص عنها: فالزئبق سائل فضي والأكسجين غاز عديم اللون، بينما أكسيد الزئبق II صلب أحمر. ولو كان التغير فيزيائيًا لبقي التركيب نفسه ولم تتكوّن مواد جديدة.', '["المتفاعل: أكسيد الزئبق II","النواتج: الزئبق والأكسجين","تكوّنت مواد جديدة مختلفة التركيب والخواص","في التغير الفيزيائي يبقى التركيب ثابتًا"]'::jsonb, '[]'::jsonb, '[{"element":"تحديد المتفاعل والنواتج","marks":1},{"element":"مقارنة خواص النواتج بخواص المتفاعل","marks":1},{"element":"التعليل بتكوّن مواد جديدة وأن التركيب لم يبقَ ثابتًا","marks":1},{"element":"التمييز عن التغير الفيزيائي","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"تحديد صحيح للمتفاعل والنواتج، ومقارنة خواص، وتعليل مع تمييز عن التغير الفيزيائي"},{"level":"2–3 درجات","description":"تحديد صحيح مع تعليل ناقص أو بلا تمييز"},{"level":"1 درجة","description":"تحديد المتفاعل والنواتج فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["عدّ الأكسجين متفاعلًا","عدّ التغير فيزيائيًا لأن الحرارة مصدره","عدم المقارنة بين خواص النواتج والمتفاعل"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (38%)"}],"at":"2026-10-18T03:32:48.201Z"}'::jsonb)
) as v(type, number, ci, ex, dn, ma, ae, ss, mk, rb, ce, ac)
