('mcq', 3, 'يتساقط ماء من حافة سقف في ليلة شديدة البرودة فتتكوّن منه إبر جليدية. ما اسم هذا التغير في الحالة؟', null, '["التجمد","الانصهار","التكثف","الغليان"]'::jsonb, 'فهم', 'تسمية تغير حالة', 'سهل', 'الكتاب ص 50 — الشكل (التجمد)'),
('mcq', 4, 'بخار الماء الناتج من غليان الماء يختلف في مظهره عن الماء السائل. لماذا يُعدّ الغليان تغيرًا فيزيائيًا؟', null, '["لأن الماء يتحول إلى هيدروجين وأكسجين","لأن بخار الماء له خواص كيميائية مختلفة","لأن تركيب الماء H₂O يبقى ثابتًا وتتغير حالته فقط","لأن الغليان يحتاج إلى حرارة عالية"]'::jsonb, 'فهم', 'تعليل التصنيف', 'متوسط', 'الكتاب ص 50 — دورة الماء (الغليان)'),
('mcq', 5, 'أيّ مجموعة من التغيرات الآتية تضم تغيرات في الحالة فقط؟', null, '["الصدأ والغليان والتكثف","الانصهار والتجمد والتكثف","الاحتراق والتبخر والتجمد","التعفن والانصهار والتبخر"]'::jsonb, 'فهم', 'تصنيف مجموعة', 'متوسط', 'الكتاب ص 50 — مصطلحات تغير الحالة'),
('mcq', 6, 'أيّ العبارات الآتية تصف تغير الحالة وصفًا صحيحًا؟', null, '["تحول المادة إلى مادة جديدة عند تغير درجة الحرارة","تحول المادة من حالة إلى أخرى مع تغير في تركيبها","تغير في الخواص الكيميائية للمادة عند الغليان فقط","تحول المادة من حالة إلى أخرى دون تغير تركيبها"]'::jsonb, 'فهم', 'فهم تعريف', 'متوسط', 'الكتاب ص 50 — تغير الحالة'),
('mcq', 7, 'سُخّنت قطعة جليد درجة حرارتها دون 0°C حتى صارت ماء سائلًا ثم بخارًا عند 100°C، ثم لامس البخار سطحًا باردًا فتكونت قطرات ماء. ما تسلسل أسماء التغيرات الحادثة؟', null, '["انصهار ثم غليان ثم تكثف","تجمد ثم تبخر ثم انصهار","تكثف ثم انصهار ثم غليان","انصهار ثم تجمد ثم تكثف"]'::jsonb, 'تطبيق', 'ترتيب تغيرات الحالة', 'صعب', 'الكتاب ص 50 — دورة الماء'),
('essay', 1, 'صف دورة تحولات الماء حين تسخن قطعة جليد حتى تتحول إلى بخار ثم يبرد البخار، مع تسمية كل تغير في الحالة وتصنيفه.', null, null, 'فهم', 'وصف وتصنيف', 'متوسط', 'الكتاب ص 50 — دورة الماء'),
('essay', 2, 'بيّن لماذا يُعدّ كلٌّ من التجمد والتكثف تغيرًا فيزيائيًا، وأعطِ مثالًا واقعيًا على كل منهما.', null, null, 'فهم', 'تفسير مع أمثلة', 'متوسط', 'الكتاب ص 50 — التكثف والتجمد'),
('essay', 3, 'في مطبخ لوحظت الأحداث الآتية: (1) ذاب مكعب ثلج في كأس عصير. (2) تكوّنت قطرات ماء على غطاء قدر بارد فوق ماء ساخن. (3) بخار يتصاعد من ماء يغلي عند 100°C. (4) تحول ماء في المجمد إلى مكعبات صلبة. سمِّ تغير الحالة في كل حدث، ثم بيّن نوع هذه التغيرات جميعها ولماذا.', null, null, 'تطبيق', 'تسمية وتصنيف مواقف', 'صعب', 'الكتاب ص 50-51 — تغيرات الحالة (الانصهار، الغليان، التكثف، التجمد)')
) as v(type, number, stem, stimulus, options, tl, qk, diff, src)
