from (values
('mcq', 1, 1, 'تحول المادة من الحالة الصلبة إلى السائلة هو الانصهار؛ وهو تغير في الحالة وبالتالي تغير فيزيائي.', '["التجمد عكس الانصهار؛ إذ يتحول فيه السائل إلى صلب.","","التكثف تحول الغاز إلى سائل، وليس الصلب إلى سائل.","التبخر تحول السائل إلى غاز، وليس الصلب إلى سائل."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (25%)"}],"at":"2026-10-18T03:32:48.202Z"}'::jsonb),
('mcq', 2, 3, 'يحدث التكثف عندما يلامس الغاز سطحًا باردًا فيتحول إلى سائل على شكل قطرات؛ وهو تغير في الحالة، أي تغير فيزيائي.', '["الانصهار تحول الصلب إلى سائل، ولا يوجد هنا مادة صلبة تنصهر.","التجمد تحول السائل إلى صلب، أما هنا فالغاز يتحول إلى سائل.","الغليان تحول السائل إلى بخار عند درجة الغليان، وهو عكس ما يحدث في الملاحظة.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (20%)"}],"at":"2026-10-18T03:32:48.202Z"}'::jsonb),
('mcq', 3, 0, 'يتجمد الماء حين تنخفض درجة حرارته عن 0°C فيتحول من سائل إلى صلب مكوّنًا الإبر الجليدية، وهو تغير فيزيائي.', '["","الانصهار تحول الصلب إلى سائل، وهو عكس ما حدث.","التكثف تحول الغاز إلى سائل، والماء هنا سائل وتحول إلى صلب.","الغليان تحول السائل إلى بخار وليس إلى صلب."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (25%)"}],"at":"2026-10-18T03:32:48.203Z"}'::jsonb),
('mcq', 4, 2, 'في الغليان يتحول الماء السائل إلى بخار هو الماء نفسه (H₂O)؛ فتتغير الحالة ويبقى التركيب، وهذا هو التغير الفيزيائي.', '["الماء لا يتحلل عند الغليان؛ فالبخار هو الماء نفسه.","بخار الماء له التركيب نفسه H₂O ولا تتكوّن مادة جديدة.","","الحرارة المطلوبة لا تحدد نوع التغير؛ فالمعيار هو بقاء التركيب."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (20%)"}],"at":"2026-10-18T03:32:48.203Z"}'::jsonb),
('mcq', 5, 1, 'الانصهار والتجمد والتكثف كلها تحولات للمادة من حالة إلى أخرى، فهي تغيرات في الحالة وتغيرات فيزيائية.', '["الصدأ تغير كيميائي وليس تغيرًا في الحالة.","","الاحتراق تغير كيميائي وليس تغيرًا في الحالة.","التعفن تغير كيميائي وليس تغيرًا في الحالة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (17%)"}],"at":"2026-10-18T03:32:48.203Z"}'::jsonb),
('mcq', 6, 3, 'تغير الحالة هو تحول المادة من حالة إلى أخرى، وهو تغير فيزيائي لأن تركيب المادة لا يتغير.', '["تكوّن مادة جديدة يحدث في التغير الكيميائي، أما تغير الحالة فتبقى فيه المادة نفسها.","تركيب المادة لا يتغير في تغير الحالة.","تغير الحالة لا يغير الخواص الكيميائية، ولا يقتصر على الغليان.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (17%)"}],"at":"2026-10-18T03:32:48.203Z"}'::jsonb),
('mcq', 7, 0, 'يتحول الجليد إلى ماء سائل بالانصهار، ثم يتحول الماء إلى بخار بالغليان عند 100°C، ثم يتحول البخار إلى قطرات ماء بالتكثف؛ وهي كلها تغيرات فيزيائية.', '["","التجمد تحول سائل إلى صلب، أما الجليد هنا فصلب في البداية فينصهر أولًا.","الترتيب خاطئ؛ فالتكثف يحدث في النهاية عندما يلامس البخار السطح البارد.","لا يحدث تجمد في المراحل المذكورة؛ فالتسخين المستمر لا يحول الماء السائل إلى صلب."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (13%)"}],"at":"2026-10-18T03:32:48.203Z"}'::jsonb),
('essay', 1, null::int, null, null, 'دون 0°C يكون الماء صلبًا (جليدًا)، وعند تسخينه ينصهر ويصبح ماء سائلًا (انصهار). وعند رفع درجة حرارته إلى 100°C يبدأ بالغليان ويتحول إلى بخار (غليان أو تبخر). وعندما يلامس البخار سطحًا باردًا يتحول إلى قطرات سائلة (تكثف)، وعندما يبرد الماء السائل إلى ما دون 0°C يتحول إلى جليد (تجمد). وكلها تغيرات فيزيائية؛ لأن تركيب الماء H₂O لا يتغير فيها.', '["الانصهار: صلب إلى سائل","الغليان أو التبخر عند 100°C: سائل إلى بخار","التكثف: بخار إلى سائل","التجمد: سائل إلى صلب","كلها تغيرات فيزيائية لأن التركيب ثابت"]'::jsonb, '[]'::jsonb, '[{"element":"الانصهار","marks":1},{"element":"الغليان أو التبخر","marks":1},{"element":"التكثف","marks":1},{"element":"التجمد","marks":1},{"element":"التصنيف فيزيائيًا مع التعليل بثبات التركيب","marks":1}]'::jsonb, '[{"level":"5 درجات","description":"تسمية صحيحة للتغيرات الأربعة مع التصنيف الفيزيائي وتعليله"},{"level":"3–4 درجات","description":"تسمية صحيحة لثلاثة أو أربعة تغيرات مع تصنيف أو تعليل ناقص"},{"level":"1–2 درجة","description":"تسمية تغير أو تغيرين فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["الخلط بين التكثف والتجمد أو بين الانصهار والتبخر","عدّ الغليان تغيرًا كيميائيًا لأن الماء يتحول إلى بخار","نسيان التعليل ببقاء تركيب الماء"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (13%)"}],"at":"2026-10-18T03:32:48.204Z"}'::jsonb),
('essay', 2, null::int, null, null, 'التجمد تحول المادة من الحالة السائلة إلى الصلبة، كتحول الماء المتساقط إلى إبر جليدية عندما يبرد. والتكثف تحول الغاز إلى سائل عندما يلامس سطحًا باردًا، كتكوّن قطرات الماء على سطح بارد من بخار الماء. وكلاهما تغير فيزيائي لأنه تغير في حالة المادة فقط، أما تركيب المادة (H₂O في المثالين) فلا يتغير ولا تتكوّن مادة جديدة.', '["التجمد: سائل إلى صلب","مثال على التجمد","التكثف: غاز إلى سائل","مثال على التكثف","كل منهما تغير فيزيائي لأن التركيب لا يتغير"]'::jsonb, '[]'::jsonb, '[{"element":"التجمد مع مثال صحيح","marks":1},{"element":"التكثف مع مثال صحيح","marks":1},{"element":"تعليل كونهما فيزيائيين ببقاء التركيب","marks":2}]'::jsonb, '[{"level":"4 درجات","description":"تعريف التجمد والتكثف بمثالين صحيحين وتعليل بثبات التركيب"},{"level":"2–3 درجات","description":"تعريف ومثال صحيحان مع تعليل ناقص"},{"level":"1 درجة","description":"تعريف أحدهما فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["عكس تعريفي التجمد والتكثف","القول إن تكوّن القطرات مادة جديدة","التعليل بتغير درجة الحرارة وحدها"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (20%)"}],"at":"2026-10-18T03:32:48.204Z"}'::jsonb),
('essay', 3, null::int, null, null, '(1) انصهار: الصلب إلى سائل. (2) تكثف: البخار إلى قطرات سائلة. (3) غليان (تبخر): السائل إلى بخار عند 100°C. (4) تجمد: السائل إلى صلب. وكل هذه التغيرات فيزيائية؛ لأنها تحول للمادة من حالة إلى أخرى دون أن يتغير تركيبها، فالماء يبقى H₂O ولا تتكوّن مادة جديدة.', '["(1) انصهار","(2) تكثف","(3) غليان أو تبخر","(4) تجمد","جميعها فيزيائية لأن التركيب لا يتغير"]'::jsonb, '[]'::jsonb, '[{"element":"تسمية كل حدث تسمية صحيحة (0.75 درجة لكل حدث)","marks":3},{"element":"الحكم بأنها تغيرات فيزيائية","marks":1},{"element":"التعليل ببقاء التركيب وعدم تكوّن مادة جديدة","marks":1}]'::jsonb, '[{"level":"5 درجات","description":"تسمية صحيحة للأحداث الأربعة، وحكم فيزيائي، وتعليل ببقاء التركيب"},{"level":"3–4 درجات","description":"تسمية صحيحة لثلاثة أحداث على الأقل مع حكم أو تعليل"},{"level":"1–2 درجة","description":"تسمية حدث أو حدثين صحيحين"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["تسمية القطرات على الغطاء تبخرًا بدل تكثف","الخلط بين الانصهار والتجمد","عدّ هذه التغيرات كيميائية لأن المظهر يتغير"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (11%)"}],"at":"2026-10-18T03:32:48.204Z"}'::jsonb)
) as v(type, number, ci, ex, dn, ma, ae, ss, mk, rb, ce, ac)
