('mcq', 1, 'أيّ التغيرات الآتية يُصنَّف تغيرًا فيزيائيًا؟', null, '["قلي بيضة","سحق علبة ألومنيوم","احتراق الجازولين","تعفّن الخبز"]'::jsonb, 'تطبيق', 'تصنيف تغير', 'سهل', 'الكتاب ص 53 — التقويم 2-2، السؤال 10'),
('mcq', 2, 'اتحد الألومنيوم مع الأكسجين لإنتاج أكسيد الألومنيوم. كيف يُصنَّف هذا التغير ولماذا؟', null, '["فيزيائي؛ لأن الألومنيوم يبقى موجودًا في الناتج","فيزيائي؛ لأن الأكسجين غاز يلامس الفلز فقط","كيميائي؛ لأن مادة جديدة هي أكسيد الألومنيوم تكوّنت","كيميائي؛ لأن حالة الألومنيوم الصلبة تغيرت"]'::jsonb, 'تطبيق', 'تصنيف مع تعليل', 'سهل', 'الكتاب ص 53 — التقويم 2-2، السؤال 10'),
('mcq', 3, 'عند قلي بيضة يتغير لونها وقوامها وطعمها. كيف يُصنَّف هذا التغير ولماذا؟', null, '["كيميائي؛ لأن مواد جديدة بخواص مختلفة تكوّنت","فيزيائي؛ لأن البيض انتقل من حالة سائلة إلى صلبة فقط","فيزيائي؛ لأن الحرارة لا تغير تركيب المواد","كيميائي؛ لأن شكل البيض تغير فقط"]'::jsonb, 'تطبيق', 'تصنيف مع تعليل', 'متوسط', 'الكتاب ص 69 — التقويم 2-2، السؤال 42'),
('mcq', 4, 'عند فتح عبوة مشروب غازي يخرج الغاز المذاب فيه على هيئة فقاعات. كيف يُصنَّف هذا التغير ولماذا؟', null, '["كيميائي؛ لأن فقاعات الغاز دليل قاطع على التفاعل","كيميائي؛ لأن المشروب يفقد جزءًا من كتلته","فيزيائي؛ لأن الغاز يتحول إلى سائل","فيزيائي؛ لأن الغاز المذاب يخرج دون تغير تركيبه ولا تتكوّن مادة جديدة"]'::jsonb, 'تحليل', 'تصنيف مع تعليل', 'صعب', 'الكتاب ص 72 — مراجعة تقويم الفصل، السؤال 87'),
('mcq', 5, 'أيّ المجموعات الآتية تضم تغيرين كيميائيين فقط؟', null, '["تجمد الماء وكسر قلم","حرق الخشب وتغير لون ورق الشجر في فصل الخريف","سحق علبة وقلي بيضة","تبخر الماء وحرق الخشب"]'::jsonb, 'تطبيق', 'تصنيف مجموعات', 'متوسط', 'الكتاب ص 69 — التقويم 2-2، السؤال 42'),
('mcq', 6, 'سُخّنت قطعة شمع دون اشتعالها فانصهرت، ثم تُركت لتبرد فعادت صلبة بخواصها الأولى. كيف يُصنَّف هذا التغير ولماذا؟', null, '["كيميائي؛ لأن الشمع تحول إلى مادة جديدة عند التسخين","كيميائي؛ لأن الحرارة لازمة لحدوثه","فيزيائي؛ لأن حالة الشمع تغيرت فقط وتركيبه ثابت","فيزيائي؛ لأن الشمع لا يتفاعل مع أي مادة مطلقًا"]'::jsonb, 'تحليل', 'تحليل موقف جديد', 'صعب', 'الكتاب ص 50 — التغيرات الفيزيائية (تغير الحالة)'),
('mcq', 7, 'يُسخَّن الخشب بمعزل عن الهواء فيتحول إلى فحم وتنتج مواد أخرى. كيف يُصنَّف هذا التغير ولماذا؟', null, '["فيزيائي؛ لأن الخشب يبقى صلبًا قبل التسخين وبعده","فيزيائي؛ لأن الحرارة تغير الحالة الفيزيائية للخشب","كيميائي؛ لأن لون الخشب تغير إلى الأسود فقط","كيميائي؛ لأن الفحم مادة جديدة تختلف في تركيبها وخواصها عن الخشب"]'::jsonb, 'تحليل', 'تصنيف مع تعليل', 'صعب', 'الكتاب ص 72 — مراجعة تقويم الفصل، السؤال 94'),
('essay', 1, 'صنّف كلًّا من التغيرات الآتية إلى فيزيائي أو كيميائي مع تعليل موجز لكل منها: (أ) كسر قلم جزأين. (ب) تجمد الماء وتكوّن الجليد. (ج) قلي البيض. (د) حرق الخشب. (هـ) تغير لون ورق الشجر في فصل الخريف.', null, null, 'تطبيق', 'تصنيف مع تبرير', 'متوسط', 'الكتاب ص 69 — التقويم 2-2، السؤال 42'),
('essay', 2, 'يتغير لون الموز وطعمه ورائحته عند تخمره، وفي مطبخ ساخن تذوب قطعة زبدة ثم تتجمد عند التبريد، وعند سلق بيضة يتحول بياضها من سائل شفاف إلى صلب أبيض لا يعود كما كان بالتبريد. صنّف كل تغير من الثلاثة إلى فيزيائي أو كيميائي وعلّل بالدليل المناسب.', null, null, 'تحليل', 'تحليل ملاحظات وتصنيف', 'صعب', 'الكتاب ص 69 و71 — التقويم 2-2 (السؤال 43) وتقويم الفصل (السؤال 81)'),
('essay', 3, 'قوّم العبارة الآتية: «كل تغير في مظهر المادة هو تغير كيميائي». استعمل مثالين مناسبين لتبيان صحة العبارة أو خطئها، ثم اذكر المعيار الصحيح لتصنيف التغير.', null, null, 'تقويم', 'تقويم عبارة بأمثلة', 'صعب', 'الكتاب ص 53 — التقويم 2-2، السؤال 14؛ ص 69 — السؤال 48')
) as v(type, number, stem, stimulus, options, tl, qk, diff, src)
