from (values
('mcq', 1, 1, 'سحق علبة الألومنيوم يغير شكلها وحجمها فقط ويبقى الألومنيوم ألومنيومًا، فهو تغير فيزيائي؛ أما قلي البيض واحتراق الجازولين والتعفن فتغيرات كيميائية.', '["قلي البيض يكوّن مواد جديدة يختلف طعمها وقوامها، فهو تغير كيميائي.","","احتراق الجازولين تفاعل كيميائي ينتج مواد جديدة.","التعفن يكوّن مواد جديدة تختلف في الطعم وقابلية الهضم، فهو تغير كيميائي."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (10%)"}],"at":"2026-10-18T03:32:48.205Z"}'::jsonb),
('mcq', 2, 2, 'اتحاد الألومنيوم مع الأكسجين ينتج أكسيد الألومنيوم وهو مادة جديدة مختلفة التركيب والخواص؛ لذلك فالتغير كيميائي.', '["الألومنيوم يتحد مع الأكسجين ولا يبقى فلزًا حرًّا؛ فقد تكوّن مركب جديد.","الأكسجين يتفاعل مع الألومنيوم ولا يكتفي بملامسته، فتتكوّن مادة جديدة.","","لم تتغير الحالة؛ والسبب الصحيح هو تكوّن مادة جديدة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (28%)"}],"at":"2026-10-18T03:32:48.205Z"}'::jsonb),
('mcq', 3, 0, 'تغير اللون والقوام والطعم عند قلي البيض يدل على تكوّن مواد جديدة بخواص مختلفة عن المواد الأولى؛ لذلك فهو تغير كيميائي.', '["","لو كان التغير في الحالة فقط لبقي الطعم واللون، لكن الطعم تغير، مما يدل على تكوّن مواد جديدة.","الحرارة قد تسبب تغيرات كيميائية كما في قلي البيض؛ فالمعيار هو تكوّن مواد جديدة.","تغير الشكل وحده لا يجعل التغير كيميائيًا، والسبب الصحيح تغير الطعم واللون وتكوّن مواد جديدة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (28%)"}],"at":"2026-10-18T03:32:48.205Z"}'::jsonb),
('mcq', 4, 3, 'الغاز المذاب (ثاني أكسيد الكربون) يخرج من المشروب كما هو دون أن يتغير تركيبه، فلا تتكوّن مادة جديدة؛ فالتغير فيزيائي.', '["ظهور الفقاعات وحده لا يكفي، والمهم تكوّن مادة جديدة وهي لم تتكوّن هنا.","فقدان الغاز لا يعني تفاعلًا؛ فهو تغير فيزيائي، ولا يتعلق الحكم بنقص الكتلة.","الغاز يخرج من السائل ولا يتحول إلى سائل.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (27%)"}],"at":"2026-10-18T03:32:48.206Z"}'::jsonb),
('mcq', 5, 1, 'حرق الخشب تفاعل كيميائي ينتج مواد جديدة، وتغير لون ورق الشجر في الخريف تغير كيميائي؛ فهما تغيران كيميائيان.', '["تجمد الماء تغير في الحالة وكسر القلم تغير في الشكل، وكلاهما فيزيائي.","","سحق العلبة تغير فيزيائي، وإن كان قلي البيض كيميائيًا.","تبخر الماء تغير فيزيائي، وإن كان حرق الخشب كيميائيًا."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (10%)"}],"at":"2026-10-18T03:32:48.206Z"}'::jsonb),
('mcq', 6, 2, 'الانصهار ثم التجمد تغيران في الحالة، وعودة الشمع بخواصه الأولى تدل على أن تركيبه لم يتغير؛ فالتغير فيزيائي.', '["لم تتكوّن مادة جديدة؛ فالشمع المتجمد له خواص الشمع الأصلي نفسها.","الحاجة إلى الحرارة لا تحدد نوع التغير؛ فانصهار الجليد يحتاج حرارة وهو فيزيائي.","","الشمع قد يحترق (تفاعل كيميائي)، لكنه هنا لم يحترق؛ فالمعيار بقاء التركيب."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (21%)"}],"at":"2026-10-18T03:32:48.206Z"}'::jsonb),
('mcq', 7, 3, 'الفحم مادة جديدة تختلف عن الخشب في التركيب والخواص، وتنتج معه مواد أخرى؛ فالتغير كيميائي.', '["بقاء الحالة الصلبة لا يعني بقاء التركيب؛ فقد تكوّنت مواد جديدة.","الخشب لا يتغير حالته فقط، بل يتحول إلى فحم ومواد أخرى مختلفة.","تغير اللون وحده لا يكفي تعليلًا؛ فالسبب الصحيح هو تكوّن مواد جديدة.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (25%)"}],"at":"2026-10-18T03:32:48.207Z"}'::jsonb),
('essay', 1, null::int, null, null, '(أ) فيزيائي؛ لأن شكل القلم فقط تغير ولم يتغير تركيبه. (ب) فيزيائي؛ لأنه تغير في الحالة من سائل إلى صلب والماء ما زال H₂O. (ج) كيميائي؛ لأن البيض يتغير لونه وقوامه وطعمه وتتكوّن مواد جديدة. (د) كيميائي؛ لأن الخشب يحترق وتتكوّن مواد جديدة كالرماد وثاني أكسيد الكربون والماء. (هـ) كيميائي؛ لأن تغير لون الورق يدل على تكوّن مواد جديدة.', '["كسر القلم: فيزيائي (تغير الشكل)","تجمد الماء: فيزيائي (تغير الحالة)","قلي البيض: كيميائي (مواد جديدة)","حرق الخشب: كيميائي (مواد جديدة)","تغير لون ورق الشجر: كيميائي"]'::jsonb, '[]'::jsonb, '[{"element":"(أ) التصنيف مع التعليل","marks":1},{"element":"(ب) التصنيف مع التعليل","marks":1},{"element":"(ج) التصنيف مع التعليل","marks":1},{"element":"(د) التصنيف مع التعليل","marks":1},{"element":"(هـ) التصنيف مع التعليل","marks":1}]'::jsonb, '[{"level":"5 درجات","description":"تصنيف صحيح للتغيرات الخمسة مع تعليل صحيح لكل منها"},{"level":"3–4 درجات","description":"تصنيف صحيح لثلاثة أو أربعة تغيرات مع تعليلها"},{"level":"1–2 درجة","description":"تصنيف صحيح لتغير أو تغيرين، أو تصنيف دون تعليل"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["عدّ قلي البيض تغيرًا فيزيائيًا لأن الحرارة هي السبب","تعليل التصنيف بتغير المظهر وحده","عدّ تجمد الماء تغيرًا كيميائيًا لأن الحالة تغيرت"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (9%)"}],"at":"2026-10-18T03:32:48.207Z"}'::jsonb),
('essay', 2, null::int, null, null, 'تخمر الموز: كيميائي؛ لأن اللون والطعم والرائحة تتغير وتتكوّن مواد جديدة. ذوبان الزبدة ثم تجمدها: فيزيائي؛ لأنه تغير في الحالة وتعود الزبدة بخواصها الأولى عند التبريد، فلم تتكوّن مادة جديدة. سلق البيضة: كيميائي؛ لأن بياض البيضة تحول إلى مادة بخواص جديدة لا تعود إلى حالتها الأولى بالتبريد، مما يدل على تكوّن مادة جديدة.', '["تخمر الموز كيميائي مع دليل تغير الطعم والرائحة واللون","ذوبان الزبدة وتجمدها فيزيائي مع دليل عودتها بالخواص نفسها","سلق البيضة كيميائي مع دليل عدم رجوع المادة بالتبريد","ربط كل تصنيف بتكوّن مادة جديدة أو عدم تكوّنها"]'::jsonb, '[]'::jsonb, '[{"element":"تخمر الموز: التصنيف مع دليله","marks":1},{"element":"الزبدة: التصنيف مع دليله","marks":1},{"element":"سلق البيضة: التصنيف مع دليله","marks":1},{"element":"الربط بمعيار تكوّن مادة جديدة","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"تصنيف صحيح للتغيرات الثلاثة مع دليل مناسب لكل منها وربطها بمعيار المادة الجديدة"},{"level":"2–3 درجات","description":"تصنيف صحيح لتغيرين أو ثلاثة مع أدلة ناقصة"},{"level":"1 درجة","description":"تصنيف تغير واحد صحيح مع دليله"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["عدّ ذوبان الزبدة تغيرًا كيميائيًا لأن الحرارة تسبب التغير","عدم الاستشهاد بدليل لتكوّن مادة جديدة","عدّ سلق البيضة تغيرًا فيزيائيًا لأن البيضة تبقى بيضة"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (9%)"}],"at":"2026-10-18T03:32:48.207Z"}'::jsonb),
('essay', 3, null::int, null, null, 'العبارة خاطئة؛ فقد يتغير المظهر في التغير الفيزيائي دون تغير التركيب. فسحق علبة الألومنيوم يغير شكلها فقط، وانصهار الجليد يغير حالته ويبقى الماء H₂O؛ وكلاهما تغير فيزيائي. بينما تغير المظهر في الصدأ أو في حرق الخشب كيميائي لأنه يصاحبه تكوّن مواد جديدة. والمعيار الصحيح هو: هل تكوّنت مادة جديدة مختلفة التركيب والخواص؟ فإن لم تتكوّن فالتغير فيزيائي، وإن تكوّنت فهو كيميائي.', '["العبارة خاطئة","مثال لتغير مظهر فيزيائي (سحق العلبة أو انصهار الجليد)","مثال لتغير مظهر كيميائي مصحوب بمادة جديدة","المعيار هو تكوّن مادة جديدة أو بقاء التركيب"]'::jsonb, '[]'::jsonb, '[{"element":"الحكم بخطأ العبارة","marks":1},{"element":"مثالان صحيحان","marks":2},{"element":"ذكر معيار تكوّن مادة جديدة","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"حكم صحيح، ومثالان صحيحان، ومعيار واضح"},{"level":"2–3 درجات","description":"حكم صحيح مع مثال واحد ومعيار، أو مثالان دون معيار"},{"level":"1 درجة","description":"حكم صحيح دون تعليل"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["الموافقة على العبارة","استعمال أمثلة كيميائية فقط","عدم ذكر معيار تكوّن مادة جديدة"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (9%)"}],"at":"2026-10-18T03:32:48.208Z"}'::jsonb)
