('mcq', 2, 0, 'النواتج هي المواد الجديدة المتكوّنة، وهي الزئبق والأكسجين؛ أما أكسيد الزئبق II فهو المتفاعل الذي بدأ به التفاعل.', '["","أكسيد الزئبق II هو المتفاعل ويتحلل، وليس ناتجًا.","أكسيد الزئبق II هو المتفاعل وليس الناتج.","الأكسجين ناتج أيضًا، فالتفاعل ينتج مادتين لا مادة واحدة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (14%)"}],"at":"2026-10-18T03:32:48.209Z"}'::jsonb),
