('mcq', 4, 1, 'النواتج هي المواد الجديدة المتكوّنة في التفاعل، وهي الماء وثاني أكسيد الكربون؛ أما الجلوكوز والأكسجين فمتفاعلان.', '["الجلوكوز والأكسجين هما المتفاعلان اللذان يبدأ بهما التفاعل.","","الجلوكوز متفاعل، وهو لا يُعدّ ناتجًا.","الأكسجين متفاعل ويُستهلك، وليس ناتجًا."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (30%)"}],"at":"2026-10-18T03:32:48.209Z"}'::jsonb),
('mcq', 5, 3, 'المواد الواقعة قبل السهم NH₃ وHCl هي المتفاعلات، والمادة الجديدة NH₄Cl الواقعة بعده هي الناتج.', '["NH₄Cl هو المادة المتكوّنة (الناتج)، وNH₃ متفاعل.","HCl متفاعل، وNH₄Cl ناتج؛ والعبارة تعكسهما.","NH₄Cl ناتج وليس متفاعلًا.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (18%)"}],"at":"2026-10-18T03:32:48.209Z"}'::jsonb),
('mcq', 6, 0, 'الماغنسيوم والأكسجين هما المادتان اللتان بدأ بهما التفاعل، وأكسيد الماغنسيوم هو المادة الجديدة المتكوّنة؛ فهو الناتج، وكتلته 16.6 g تساوي مجموع كتلتي المتفاعلين (10.0 g + 6.6 g).', '["","أكسيد الماغنسيوم هو الناتج وليس متفاعلًا، والأكسجين متفاعل لا ناتج.","هذا يعكس التفاعل؛ فأكسيد الماغنسيوم هو الناتج لا المتفاعل، والمادتان الأخريان متفاعلتان.","الماغنسيوم متفاعل لا ناتج؛ وهو يُستهلك ليكوّن أكسيد الماغنسيوم."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (15%)"}],"at":"2026-10-18T03:32:48.210Z"}'::jsonb),
('mcq', 7, 2, 'المتفاعلات هي المواد التي استُهلكت في التفاعل، وهي الفوسفور والجزء المستهلك من الهيدروجين، والناتج الوحيد هو الفوسفين؛ أما الهيدروجين الباقي فلم يتفاعل فلا يُعدّ ناتجًا.', '["الفوسفين مادة جديدة متكوّنة، فهو ناتج وليس متفاعلًا، والهيدروجين الباقي لم يتفاعل أصلًا.","الفوسفين ناتج؛ والمتفاعلان هما الفوسفور والهيدروجين المستهلك.","","الهيدروجين الباقي لم يتفاعل ولم يتكوّن في التفاعل، فلا يُعدّ ناتجًا."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (18%)"}],"at":"2026-10-18T03:32:48.210Z"}'::jsonb),
('essay', 1, null::int, null, null, 'المتفاعلات: الحديد والأكسجين وبخار الماء، وهي المواد التي بدأ بها التفاعل. الناتج: أكسيد الحديد (الصدأ)، وهو المادة الجديدة المتكوّنة. وعرفنا ذلك لأن الصدأ مادة بنية مائلة إلى البرتقالي لها تركيب وخواص مختلفة عن الحديد والأكسجين؛ فهو المادة الجديدة، والمتفاعلات هي ما بدأنا به قبل التفاعل.', '["المتفاعلات: الحديد والأكسجين وبخار الماء","الناتج: أكسيد الحديد (الصدأ)","المتفاعلات هي المواد التي يبدأ بها التفاعل","الناتج هو المادة الجديدة المتكوّنة بخواص مختلفة"]'::jsonb, '[]'::jsonb, '[{"element":"تحديد المتفاعلات الثلاثة","marks":1.5},{"element":"تحديد الناتج","marks":0.5},{"element":"التوضيح بأن المتفاعلات هي ما يبدأ به التفاعل والناتج مادة جديدة","marks":1}]'::jsonb, '[{"level":"3 درجات","description":"تحديد صحيح للمتفاعلات والناتج مع توضيح الأساس"},{"level":"2 درجتان","description":"تحديد صحيح مع توضيح ناقص أو متفاعل مفقود"},{"level":"1 درجة","description":"تحديد الناتج أو بعض المتفاعلات فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["إغفال بخار الماء من المتفاعلات","عدّ الصدأ متفاعلًا","عدّ الأكسجين ناتجًا"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (3 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (40%)"}],"at":"2026-10-18T03:32:48.210Z"}'::jsonb),
('essay', 2, null::int, null, null, 'المتفاعلات: الجلوكوز والأكسجين، وكتلتاهما 180.0 g و192.0 g، ومجموعهما 372.0 g. النواتج: الماء وثاني أكسيد الكربون. ووفق قانون حفظ الكتلة فمجموع كتل النواتج يساوي مجموع كتل المتفاعلات، أي 372.0 g.', '["المتفاعلات: الجلوكوز والأكسجين","النواتج: الماء وثاني أكسيد الكربون","مجموع كتل المتفاعلات = 180.0 + 192.0 = 372.0 g","مجموع كتل النواتج = مجموع كتل المتفاعلات = 372.0 g"]'::jsonb, '["كتلة المتفاعلات = 180.0 g + 192.0 g = 372.0 g","كتلة النواتج = كتلة المتفاعلات = 372.0 g"]'::jsonb, '[{"element":"تحديد المتفاعلين","marks":1},{"element":"تحديد الناتجين","marks":1},{"element":"حساب مجموع كتل المتفاعلات 372.0 g","marks":1},{"element":"ربطه بكتلة النواتج وفق حفظ الكتلة","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"تحديد صحيح للمتفاعلات والنواتج مع حساب المجموع وربطه بكتلة النواتج"},{"level":"2–3 درجات","description":"تحديد صحيح مع حساب أو ربط ناقص"},{"level":"1 درجة","description":"تحديد المتفاعلات أو النواتج فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["عدّ الأكسجين ناتجًا لأنه غاز","جمع كتل النواتج مع كتل المتفاعلات معًا","نسيان ربط النتيجة بقانون حفظ الكتلة"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (30%)"}],"at":"2026-10-18T03:32:48.211Z"}'::jsonb),
('essay', 3, null::int, null, null, 'المعادلة اللفظية: الأمونيا + كلوريد الهيدروجين → كلوريد الأمونيوم. المتفاعلات: الأمونيا NH₃ وكلوريد الهيدروجين HCl. الناتج: كلوريد الأمونيوم NH₄Cl. ويُعدّ ما حدث تغيرًا كيميائيًا لأن غازين تحولا إلى مادة جديدة صلبة بيضاء مختلفة التركيب والخواص عنهما.', '["معادلة لفظية: الأمونيا + كلوريد الهيدروجين → كلوريد الأمونيوم","المتفاعلات: NH₃ وHCl","الناتج: NH₄Cl","تكوّن مادة جديدة مختلفة التركيب والخواص يعني تغيرًا كيميائيًا"]'::jsonb, '[]'::jsonb, '[{"element":"كتابة المعادلة اللفظية بسهم من المتفاعلات إلى الناتج","marks":1},{"element":"تحديد المتفاعلات","marks":1},{"element":"تحديد الناتج","marks":0.5},{"element":"التعليل بتكوّن مادة جديدة","marks":1.5}]'::jsonb, '[{"level":"4 درجات","description":"معادلة لفظية صحيحة، وتحديد المتفاعلات والناتج، وتعليل بتكوّن مادة جديدة"},{"level":"2–3 درجات","description":"معادلة أو تحديد صحيح مع تعليل ناقص"},{"level":"1 درجة","description":"تحديد المتفاعلات أو الناتج فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["كتابة السهم بالاتجاه المعاكس","عدّ كلوريد الأمونيوم متفاعلًا","تعليل الحكم بتغير الحالة فقط"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (10%)"}],"at":"2026-10-18T03:32:48.212Z"}'::jsonb)
