('mcq', 1, 1, 'ينص القانون على أن الكتلة لا تفنى ولا تستحدث في أثناء التفاعل الكيميائي، أي أنها محفوظة؛ فكتلة المتفاعلات تساوي كتلة النواتج.', '["الكتلة لا تُستحدث، فلا تزداد الكتلة الكلية في التفاعل.","","كتلة النواتج تساوي كتلة المتفاعلات ولا تقل عنها.","الكتلة لا تفنى في التفاعل الكيميائي، بل تبقى محفوظة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (27%)"}],"at":"2026-10-18T03:32:48.212Z"}'::jsonb),
('mcq', 2, 3, 'كان الكيميائي الفرنسي أنطوان لافوازييه (1743–1794م) أول من استعمل الميزان الحساس في التفاعلات الكيميائية، فلاحظ ثبات الكتلة الكلية.', '["مندليف اشتهر بإسهاماته في الجدول الدوري ولم يكن أول من استعمل الميزان الحساس في التفاعلات.","دالتون اشتهر بنظريته الذرية وليس باستعمال الميزان الحساس لأول مرة في التفاعلات.","رذرفورد اشتهر بنموذجه الذري، وليس باستعمال الميزان في التفاعلات.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (0%)"}],"at":"2026-10-18T03:32:48.212Z"}'::jsonb),
('mcq', 3, 0, 'تأخر استعمال الأدوات الكمية في دراسة التفاعلات حتى طُوّر الميزان الحساس، وعند قياس كتل المتفاعلات والنواتج لوحظ أن الكتلة الكلية تبقى ثابتة.', '["","الكتلة لا تتغير في التفاعلات، وإنما تعذّر قياسها بدقة لعدم وجود ميزان حساس.","التفاعلات كانت معروفة، لكن قياسها الكمي بالميزان الحساس تأخر.","للغازات كتلة، وهي ما يجعل قياس الكتلة داخل وعاء مغلق ضروريًا."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (25%)"}],"at":"2026-10-18T03:32:48.213Z"}'::jsonb),
('mcq', 4, 2, 'يتفاعل الشمع مع أكسجين الهواء لينتج ثاني أكسيد الكربون وبخار الماء، وهما غازان ينطلقان في الهواء؛ فلا تُحسب كتلتهما مع الشمع المتبقي، وكتلة المتفاعلات (الشمع + الأكسجين) تساوي كتلة النواتج.', '["الكتلة لا تفنى، وإنما انتقلت إلى نواتج غازية.","الكتلة لا تتحول إلى طاقة فقط؛ فقد انتقلت الكتلة إلى نواتج غازية.","","الفتيل لا يستقبل كتلة الشمع؛ والكتلة انتقلت إلى نواتج غازية."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (48%)"}],"at":"2026-10-18T03:32:48.213Z"}'::jsonb),
('mcq', 5, 2, 'في الوعاء المغلق لا تخرج الغازات (كالأكسجين)، فيمكن قياس كتلة المواد قبل التفاعل وبعده وتكون الكتلتان نفسيهما.', '["سرعة التفاعل لا علاقة لها بالتحقق من حفظ الكتلة، والكتلة لا تتغير.","الكتلة لا تتحول من نوع إلى آخر؛ وإنما تقاس لإثبات تساوي كتلتي المتفاعلات والنواتج.","","الوعاء المغلق لا يضيف كتلة إلى المتفاعلات؛ وإنما يمنع خروج الغازات."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (44%)"}],"at":"2026-10-18T03:32:48.213Z"}'::jsonb),
('mcq', 6, 1, 'الوعاء مغلق فلا يخرج الأكسجين، وتبقى الكتلة الكلية للمحتويات كما كانت: كتلة النواتج = كتلة المتفاعلات = 10.0 g.', '["الأكسجين لا يستطيع الخروج من الوعاء المغلق؛ فكتلة المحتويات لا تنقص إلى كتلة الزئبق وحده.","","0.74 g هي كتلة الأكسجين الناتج فقط، لكن المحتويات تشمل الزئبق أيضًا.","الكتلة لا تُستحدث؛ فلا تزيد على كتلة المتفاعلات مهما اختلف الحجم."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (31%)"}],"at":"2026-10-18T03:32:48.213Z"}'::jsonb),
('mcq', 7, 3, 'في الاحتراق في وعاء مفتوح تنطلق نواتج غازية (ثاني أكسيد الكربون وبخار الماء) إلى الهواء، فلا تُقاس كتلتها مع الرماد؛ ولو جُمعت كل النواتج مع الرماد لساوت كتلة الخشب مع كتلة الأكسجين المتفاعل.', '["الكتلة لا تفنى، وإنما انتقلت إلى نواتج غازية.","الرماد ليس الناتج الوحيد؛ فهناك نواتج غازية تشاركه في الكتلة.","الكتلة لا تتحول إلى طاقة كلها؛ فقد انتقلت إلى نواتج غازية مع الرماد.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (18%)"}],"at":"2026-10-18T03:32:48.214Z"}'::jsonb),
('essay', 1, null::int, null, null, 'ينص قانون حفظ الكتلة على أن الكتلة لا تفنى ولا تستحدث في أثناء التفاعل الكيميائي (إلا بقدرة الله تعالى)، أي أنها محفوظة؛ فكتلة المتفاعلات تساوي كتلة النواتج. وللتحقق منه نقيس بالميزان الحساس كتلة المواد قبل التفاعل وبعده ونقارن بينهما، كما فعل لافوازييه. ويُجرى التفاعل في وعاء مغلق حتى لا تخرج الغازات (كالأكسجين)، فتبقى الكتلة الكلية للمواد قبل التفاعل وبعده هي نفسها.', '["الكتلة لا تفنى ولا تستحدث في التفاعل الكيميائي","كتلة المتفاعلات = كتلة النواتج","قياس الكتلة قبل التفاعل وبعده بالميزان الحساس","وعاء مغلق لمنع خروج الغازات"]'::jsonb, '[]'::jsonb, '[{"element":"نص القانون (الكتلة محفوظة)","marks":1},{"element":"العلاقة: كتلة المتفاعلات = كتلة النواتج","marks":1},{"element":"طريقة التحقق بالقياس قبل التفاعل وبعده","marks":1},{"element":"تعليل استعمال الوعاء المغلق","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"نص صحيح وعلاقة صحيحة وطريقة تحقق وتعليل للوعاء المغلق"},{"level":"2–3 درجات","description":"نص صحيح مع طريقة أو تعليل واحد صحيح"},{"level":"1 درجة","description":"نص القانون فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["القول إن الكتلة تتحول إلى طاقة في التفاعل الكيميائي","نسيان سبب منع خروج الغازات","ذكر قانون آخر مثل قانون النسب الثابتة"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (44%)"}],"at":"2026-10-18T03:32:48.214Z"}'::jsonb),
('essay', 2, null::int, null, null, 'لا يخالف المثال قانون حفظ الكتلة؛ لأن الشمع تفاعل مع أكسجين الهواء في أثناء الاحتراق فتكوّنت نواتج غازية هي ثاني أكسيد الكربون وبخار الماء، وانطلقت في الهواء فلم تُحسب كتلتها مع الشمع المتبقي. وكتلة الشمع المحترق مع كتلة الأكسجين المتفاعل تساوي كتلة النواتج الغازية؛ فالكتلة لم تفنَ وإنما انتقلت إلى النواتج. ولو جمعنا النواتج كلها في وعاء مغلق لوجدنا الكتلة الكلية ثابتة.', '["الشمع تفاعل مع أكسجين الهواء","تكوّنت نواتج غازية (CO₂ وبخار الماء) انطلقت في الهواء","كتلة الشمع المحترق + كتلة الأكسجين = كتلة النواتج","الكتلة لم تفنَ بل انتقلت إلى النواتج"]'::jsonb, '[]'::jsonb, '[{"element":"ذكر أن الشمع يتفاعل مع أكسجين الهواء","marks":1},{"element":"ذكر النواتج الغازية وانطلاقها في الهواء","marks":1},{"element":"العلاقة بين كتلة المتفاعلات وكتلة النواتج","marks":1},{"element":"الاستنتاج بأن الكتلة لم تفنَ","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"تفسير كامل يشمل الأكسجين والنواتج الغازية والعلاقة والاستنتاج"},{"level":"2–3 درجات","description":"ذكر النواتج الغازية مع نقص في الأكسجين أو العلاقة"},{"level":"1 درجة","description":"القول إن الكتلة لم تفنَ دون تفسير"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["القول إن الشمع تحول إلى طاقة فقط","إهمال دور أكسجين الهواء كمتفاعل","القول إن الكتلة فُنيت وإنه استثناء من القانون"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (48%)"}],"at":"2026-10-18T03:32:48.214Z"}'::jsonb),
('essay', 3, null::int, null, null, 'في الوعاء المغلق: لا يخرج الأكسجين، فتبقى كتلة المحتويات 10.0 g (9.26 g زئبق + 0.74 g أكسجين) وهي تساوي كتلة المتفاعل، فتظهر حفظ الكتلة بوضوح. في الكأس المفتوحة: يخرج الأكسجين (0.74 g) إلى الهواء، فتكون الكتلة المقيسة للمتبقي في الكأس 9.26 g فقط، وتبدو كأن كتلة قد فُقدت؛ لكن الكتلة لم تفنَ وإنما انتقلت إلى الغاز المنطلق، وإذا جُمعت كتلته (0.74 g) إلى كتلة الزئبق عاد المجموع إلى 10.0 g. لذلك تُظهر التجربة في الوعاء المغلق حفظ الكتلة بوضوح.', '["الوعاء المغلق: الكتلة 10.0 g","تعليل: الأكسجين لا يخرج","الكأس المفتوحة: المقيس 9.26 g","الفرق 0.74 g هو كتلة الأكسجين المنطلق","الوعاء المغلق يُظهر حفظ الكتلة بوضوح"]'::jsonb, '["كتلة الأكسجين الناتج = 10.00 g − 9.26 g = 0.74 g","الوعاء المغلق: 9.26 g + 0.74 g = 10.0 g","الكأس المفتوحة: المتبقي 9.26 g لأن 0.74 g من الأكسجين خرج"]'::jsonb, '[{"element":"حساب كتلة الأكسجين 0.74 g","marks":1},{"element":"الوعاء المغلق: 10.0 g مع التعليل","marks":1.5},{"element":"الكأس المفتوحة: 9.26 g مع التعليل بخروج الأكسجين","marks":1.5},{"element":"تحديد التجربة التي تُظهر حفظ الكتلة بوضوح","marks":1}]'::jsonb, '[{"level":"5 درجات","description":"حساب صحيح للأكسجين، وتوقع صحيح للتجربتين مع تعليل، وتحديد الوعاء المغلق"},{"level":"3–4 درجات","description":"توقع صحيح لتجربة واحدة مع التعليل ونقص في الأخرى"},{"level":"1–2 درجة","description":"حساب الأكسجين أو توقع بلا تعليل"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["توقع انخفاض الكتلة في الوعاء المغلق أيضًا","القول إن الكتلة فُنيت في الكأس المفتوحة","نسيان حساب كتلة الأكسجين 0.74 g"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (31%)"}],"at":"2026-10-18T03:32:48.215Z"}'::jsonb)
