('essay', 1, 'عرّف المخلوط، ثم وضّح بمثال حشوة الأسنان (الزئبق والفضة) كيف يدل فصل مكوناتها بالتسخين على احتفاظ كل مكوّن بخواصه.', null, null, 'فهم', 'تعريف وتوضيح بمثال', 'متوسط', 'الكتاب ص 54 — مخلوط الزئبق-الفضة'),
('essay', 2, 'صِف خواص المخلوط، ثم فسّر لماذا يمكن تحضير عدد لا نهائي من المخاليط من المواد النقية نفسها.', null, null, 'فهم', 'وصف وتفسير', 'متوسط', 'الكتاب ص 54 — المخاليط'),
('essay', 3, 'قال طالب: «المخلوط مادة ناتجة عن اتحاد مادتين أو أكثر كيميائيًّا». صحّح هذه العبارة، وفسّر خطأها بالرجوع إلى تعريف المخلوط.', null, null, 'تقويم', 'تصحيح عبارة', 'صعب', 'الكتاب ص 54، 70 — المخاليط')
