from (values
('mcq', 1, 1, 'المخلوط مزيج مكوّن من مادتين نقيتين أو أكثر مع احتفاظ كل من هذه المواد بخواصها الأصلية.', '["هذا وصف المادة النقية، فتركيبها منتظم وثابت أما المخلوط فيختلف تركيبه بحسب نسب مكوناته.","","اتحاد المواد كيميائيًّا ينتج مادة جديدة (مركبًا)، أما المخلوط فمكوناته لا تتحد كيميائيًّا.","مكونات المخلوط لا تفقد خواصها الأصلية بل تحتفظ بها."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (0%)"}],"at":"2026-10-18T03:32:48.215Z"}'::jsonb),
('mcq', 2, 3, 'في المخلوط تحتفظ كل مادة بخواصها الأصلية لأن المواد تمتزج دون أن تتحد كيميائيًّا.', '["تكوّن مركب جديد بخواص مختلفة يحدث عند الاتحاد الكيميائي لا عند تكوين المخلوط.","لا تختفي خواص مكونات المخلوط، فهي تبقى كما هي.","لا تكتسب المادة خواص غيرها؛ فكل مكوّن يحتفظ بخواصه مهما كانت كميته.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (12%)"}],"at":"2026-10-18T03:32:48.215Z"}'::jsonb),
('mcq', 3, 0, 'المخلوط مزيج من مادتين نقيتين أو أكثر؛ لذا فأقل عدد لازم لتكوينه مادتان نقيتان.', '["","المادة النقية الواحدة ليست مخلوطًا، فالمخلوط يحتاج مادتين على الأقل.","قد يتكون المخلوط من ثلاث مواد، لكنها ليست الحد الأدنى.","قد يتكون المخلوط من أربع مواد، لكن مادتين تكفيان لتكوينه."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (21%)"}],"at":"2026-10-18T03:32:48.215Z"}'::jsonb),
('mcq', 4, 2, 'يختلف تركيب المخلوط بحسب نسب مكوناته، وبتغيير هذه النسب نحصل على مخاليط مختلفة بلا حدود.', '["النسبة الكتلية الثابتة صفة المركبات لا المخاليط.","التركيب المنتظم والثابت صفة المادة النقية، أما تركيب المخلوط فيتغير بتغير نسب مكوناته.","","المكونات تحتفظ بخواصها ولا تفقدها، وهذا لا يفسّر تعدد المخاليط."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (67%)"}],"at":"2026-10-18T03:32:48.216Z"}'::jsonb),
('mcq', 5, 3, 'حشوة الأسنان مزيج من مادتين نقيتين هما الزئبق والفضة، فهي مخلوط، أما الماء المقطر والأكسجين النقي وكلوريد الصوديوم النقي فكل منها مادة نقية.', '["الماء المقطر مادة نقية واحدة (H₂O) وليس مزيجًا.","الأكسجين النقي عنصر، أي مادة نقية واحدة.","كلوريد الصوديوم النقي مركب واحد، أي مادة نقية.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (0%)"}],"at":"2026-10-18T03:32:48.216Z"}'::jsonb),
('mcq', 6, 1, 'احتفاظ الحديد بخاصية الانجذاب إلى المغناطيس وبقاء الرمل دون تغيّر يدلان على أن كل مادة احتفظت بخواصها الأصلية، وهذا ما يميز المخلوط.', '["لو تكوّن مركب جديد لتغيرت الخواص ولما انجذب الحديد وحده.","","وجود المواد في وعاء واحد لا يجعلها مادة نقية، فهما مادتان محتفظتان بخواصهما.","الخليط يحتوي مادتين مختلفتين فليس عنصرًا، والمغناطيس يجذب الحديد فقط لاحتفاظه بخاصيته."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (8%)"}],"at":"2026-10-18T03:32:48.216Z"}'::jsonb),
('mcq', 7, 0, 'معظم المواد في الطبيعة توجد في صورة مخاليط، ومن الصعب إبقاء أي مادة نقية تمامًا.', '["","من الصعب إبقاء أي مادة نقية تمامًا في الطبيعة.","المواد الطبيعية ليست عناصر منفردة فقط، بل تغلب عليها المخاليط.","المركبات النقية نادرة في الطبيعة، والغالب أن توجد المواد ضمن مخاليط."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (8%)"}],"at":"2026-10-18T03:32:48.216Z"}'::jsonb),
('essay', 1, null::int, null, null, 'المخلوط مزيج مكوّن من مادتين نقيتين أو أكثر مع احتفاظ كل من هذه المواد بخواصها الأصلية. في حشوة الأسنان لا يمكن تمييز الزئبق من الفضة بالعين، لكن عند التسخين يتبخر الزئبق أولًا فنحصل على بخار الزئبق وحده، وتبقى الفضة صلبة وحدها؛ أي أن كلًّا منهما احتفظ بخواصه (الزئبق يتبخر بسهولة والفضة تبقى صلبة)، ولم تتكوّن مادة جديدة.', '["المخلوط مزيج من مادتين نقيتين أو أكثر","تحتفظ كل مادة بخواصها الأصلية","عند التسخين يتبخر الزئبق أولًا وتبقى الفضة صلبة","إمكان الفصل يدل على أن كل مكوّن احتفظ بخواصه ولم تتكوّن مادة جديدة"]'::jsonb, '[]'::jsonb, '[{"element":"تعريف المخلوط كاملًا","marks":2},{"element":"وصف ما يحدث عند التسخين","marks":1},{"element":"الربط باحتفاظ المكونات بخواصها","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"تعريف كامل، ووصف صحيح للتسخين، وربط واضح باحتفاظ المكونات بخواصها"},{"level":"2–3 درجات","description":"تعريف صحيح مع نقص في وصف التسخين أو الربط"},{"level":"1 درجة","description":"ذكر جزء من التعريف فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["إغفال عبارة «مادتين نقيتين أو أكثر»","القول إن الزئبق والفضة اتحدا كيميائيًّا","عدم الربط بين إمكان الفصل واحتفاظ المكونات بخواصها"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (6%)"}],"at":"2026-10-18T03:32:48.216Z"}'::jsonb),
('essay', 2, null::int, null, null, 'المخلوط مزيج من مادتين نقيتين أو أكثر، وتحتفظ مكوناته بخواصها الأصلية، ويختلف تركيبه بحسب نسب مكوناته (فتركيبه غير ثابت كالمادة النقية). ولأن نسب المكونات يمكن تغييرها بلا حدود، فإن مزج المادتين نفسيهما بنسب مختلفة ينتج مخاليط مختلفة، ولذلك يمكن تحضير عدد لا نهائي من المخاليط. ومعظم المواد في الطبيعة توجد في صورة مخاليط.', '["المخلوط مزيج من مادتين نقيتين أو أكثر","المكونات تحتفظ بخواصها الأصلية","تركيب المخلوط يختلف بحسب نسب مكوناته","تغيير النسب بلا حدود ينتج مخاليط لا نهائية"]'::jsonb, '[]'::jsonb, '[{"element":"ذكر أن المخلوط مزيج من مادتين نقيتين أو أكثر","marks":1},{"element":"احتفاظ المكونات بخواصها","marks":1},{"element":"اختلاف التركيب بحسب النسب","marks":1},{"element":"ربط تغيّر النسب بعدد لا نهائي من المخاليط","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"ذكر الخواص الثلاث وتفسير العدد اللانهائي بتغير النسب"},{"level":"2–3 درجات","description":"ذكر بعض الخواص أو تفسير ناقص"},{"level":"1 درجة","description":"ذكر خاصية واحدة فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["القول إن المخلوط له تركيب ثابت كالمادة النقية","القول إن المكونات تفقد خواصها عند المزج","عدم ذكر دور نسب المكونات في اختلاف المخاليط"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (67%)"}],"at":"2026-10-18T03:32:48.217Z"}'::jsonb),
('essay', 3, null::int, null, null, 'العبارة خاطئة. المخلوط مزيج من مادتين نقيتين أو أكثر لا تتحد كيميائيًّا، وتحتفظ كل مادة فيه بخواصها الأصلية، ولا تتكوّن مادة جديدة. أما الاتحاد الكيميائي فينتج مركبًا بخواص مختلفة عن خواص مكوناته. والصحيح أن يقال: المخلوط مزيج من مادتين نقيتين أو أكثر تحتفظ فيه كل مادة بخواصها الأصلية.', '["الحكم بأن العبارة خاطئة","المخلوط مزيج لا اتحاد كيميائي","المكونات تحتفظ بخواصها ولا تتكوّن مادة جديدة","صياغة العبارة الصحيحة"]'::jsonb, '[]'::jsonb, '[{"element":"الحكم بخطأ العبارة","marks":1},{"element":"تفسير الخطأ: لا اتحاد كيميائي في المخلوط","marks":1},{"element":"احتفاظ المكونات بخواصها","marks":1},{"element":"صياغة العبارة الصحيحة","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"حكم صحيح وتفسير كامل وصياغة صحيحة للعبارة"},{"level":"2–3 درجات","description":"حكم صحيح مع نقص في التفسير أو الصياغة"},{"level":"1 درجة","description":"الحكم بالخطأ دون تفسير"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["الخلط بين المخلوط والمركب","تصحيح العبارة دون تفسير","القول إن المخلوط تتغير فيه خواص مكوناته"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (4%)"}],"at":"2026-10-18T03:32:48.217Z"}'::jsonb)
) as v(type, number, ci, ex, dn, ma, ae, ss, mk, rb, ce, ac)
