('mcq', 3, 'أُخذت قطعتان مختلفتان في الحجم من مملغم الفضة والزئبق (سبيكة معدنية) وحُلّل تركيب كل منهما. ما النتيجة المتوقعة؟', null, '["تحتوي القطعة الأكبر نسبة أعلى من الفضة","تحتوي القطعة الأصغر نسبة أعلى من الزئبق","يختلف تركيب القطعتين لأن المخلوط غير منتظم","يكون تركيب القطعتين واحدًا مهما اختلف الحجم"]'::jsonb, 'فهم', 'استنتاج', 'متوسط', 'الكتاب ص 55 — المخلوط المتجانس'),
('mcq', 4, 'أيّ الصفات الآتية تميّز المخلوط غير المتجانس من المخلوط المتجانس؟', null, '["إمكان فصل مكوناته بطرائق فيزيائية","تركيبه غير منتظم وتبقى مكوناته متمايزة","تكوّنه من مادتين نقيتين أو أكثر","احتفاظ مكوناته بخواصها الأصلية"]'::jsonb, 'فهم', 'مقارنة', 'متوسط', 'الكتاب ص 55 — المخلوط المتجانس وغير المتجانس'),
('mcq', 5, 'خُلط الزيت والتوابل والخل في إناء، وبعد تركه من دون تحريك مدة كافية تكوّنت طبقة زيت فوق الخل. كيف يُصنَّف هذا المخلوط ولماذا؟', null, '["غير متجانس، لأن مكوناته لم تمتزج تمامًا وبقيت متمايزة","متجانس، لأن مكوناته جميعها سائلة","متجانس، لأن تركيبه ثابت في جميع أجزائه","مادة نقية، لأنه وُضع في إناء واحد"]'::jsonb, 'تطبيق', 'تصنيف موقف', 'متوسط', 'الكتاب ص 54، 55 — الشكل 2-11 والمخلوط غير المتجانس'),
('mcq', 6, 'أُخذت عينتان صغيرتان من موضعين مختلفين في مخلوط X فوُجد تركيبهما متطابقًا، وأُخذت عينتان من موضعين مختلفين في مخلوط Y فوُجد تركيبهما مختلفًا. ماذا تستنتج؟', null, '["X غير متجانس وY متجانس","كلاهما مخلوط متجانس","X متجانس وY غير متجانس","كلاهما مخلوط غير متجانس"]'::jsonb, 'تحليل', 'استنتاج من بيانات', 'صعب', 'الكتاب ص 55 — المخلوط المتجانس'),
('mcq', 7, 'أيّ العبارات الآتية صحيحة عن العلاقة بين المحلول والمخلوط المتجانس؟', null, '["المحاليل مخاليط غير متجانسة سائلة فقط","المحاليل مواد نقية سائلة تذوب فيها مواد أخرى","المحاليل مخاليط متجانسة سائلة فقط دون الصلبة والغازية","المحلول اسم آخر للمخلوط المتجانس وقد يكون صلبًا أو سائلًا أو غازيًّا"]'::jsonb, 'فهم', 'تمييز عبارة صحيحة', 'متوسط', 'الكتاب ص 55 — المحاليل'),
('essay', 1, 'قارن بين المخلوط المتجانس والمخلوط غير المتجانس من حيث: انتظام التركيب، وامتزاج المكونات أو تمايزها، مع ذكر مثال واحد لكل نوع.', null, null, 'فهم', 'مقارنة', 'متوسط', 'الكتاب ص 55 — المخلوط المتجانس وغير المتجانس'),
('essay', 2, 'أُخذت ثلاث عينات متساوية الكتلة من مواضع مختلفة (أعلى ووسط وأسفل) من كل من المخلوطين A وB، وحُدّدت النسبة المئوية بالكتلة للمكوّن الأول فيها:
المخلوط A: 25% و25% و25%.
المخلوط B: 8% و31% و60%.
صنّف كل مخلوط إلى متجانس أو غير متجانس مع التعليل، ثم توقّع تركيب عينة رابعة تؤخذ من A.', null, null, 'تحليل', 'تحليل بيانات وتصنيف', 'صعب', 'الكتاب ص 55 — المخلوط المتجانس وغير المتجانس'),
('essay', 3, 'جاء في إجابة طالب: «عندما تذوب كمية من السكر كليًّا في الماء ينتج محلول غير متجانس». هل العبارة صحيحة؟ صحّحها مع التعليل.', null, null, 'تقويم', 'تصحيح عبارة', 'متوسط', 'الكتاب ص 55، 70 — المحاليل')
) as v(type, number, stem, stimulus, options, tl, qk, diff, src)
where not exists (select 1 from public.questions x where x.objective_id = (select id from public.objectives where code = 'K1-C2-L3-O02') and x.type = v.type and x.number = v.number);
insert into public.question_answers (question_id, correct_index, explanation, distractor_notes, model_answer, answer_elements, solution_steps, marks, rubric, common_errors, auto_check)
select x.id, v.ci::int, v.ex::text, v.dn::jsonb, v.ma::text, v.ae::jsonb, v.ss::jsonb, v.mk::jsonb, v.rb::jsonb, v.ce::jsonb, v.ac::jsonb
from (values
('mcq', 1, 2, 'في المخلوط غير المتجانس لا تمتزج المواد تمامًا بل تظل متمايزة وتركيبه غير منتظم.', '["هذا وصف المخلوط المتجانس لا غير المتجانس.","المحلول هو اسم المخلوط المتجانس، وليس غير المتجانس.","","مكونات المخاليط جميعها يمكن فصلها بطرائق فيزيائية، ومنها غير المتجانسة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (50%)"}],"at":"2026-10-18T03:32:48.217Z"}'::jsonb),
('mcq', 2, 0, 'الشاي محلول سائل تمتزج مكوناته بانتظام ولا تتمايز، فهو مخلوط متجانس، أما سلطة الخضار وعصير البرتقال بلبّه والماء الموحل فمكوناتها متمايزة، وهي غير متجانسة.', '["","مكونات السلطة متمايزة وتركيبها غير منتظم، فهي مخلوط غير متجانس.","اللب يبقى متمايزًا ويطفو على سطح العصير، فهو مخلوط غير متجانس.","الطين يبقى متمايزًا عن الماء وقد يترسب، فهو مخلوط غير متجانس."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (0%)"}],"at":"2026-10-18T03:32:48.218Z"}'::jsonb),
('mcq', 3, 3, 'المملغم مخلوط متجانس تمتزج مكوناته بانتظام وله تركيب ثابت، فيكون تركيب أي قطعتين منه واحدًا مهما اختلف حجمهما.', '["حجم القطعة لا يغيّر نسب المكونات في المخلوط المتجانس.","نسب المكونات واحدة في القطعتين مهما كان الحجم.","عدم انتظام التركيب صفة المخلوط غير المتجانس، والمملغم مخلوط متجانس.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (6%)"}],"at":"2026-10-18T03:32:48.218Z"}'::jsonb),
('mcq', 4, 1, 'الصفة التي تنفرد بها المخاليط غير المتجانسة أن تركيبها غير منتظم وتبقى مكوناتها متمايزة، أما الصفات الأخرى فمشتركة بين النوعين.', '["يمكن فصل مكونات كل من النوعين فيزيائيًّا، فلا تميز بينهما.","","كل مخلوط، متجانسًا كان أو غير متجانس، يتكون من مادتين نقيتين أو أكثر.","تحتفظ مكونات كل المخاليط بخواصها الأصلية، فلا تميز بين النوعين."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (50%)"}],"at":"2026-10-18T03:32:48.218Z"}'::jsonb),
('mcq', 5, 0, 'ظهور طبقة الزيت فوق الخل يدل على أن المواد لم تمتزج تمامًا وبقيت متمايزة، فهو مخلوط غير متجانس.', '["","كون المكونات سائلة لا يعني التجانس؛ فالمعيار هو الامتزاج المنتظم، والزيت والخل متمايزان.","التركيب هنا غير ثابت في أجزاء الإناء؛ فالطبقة العليا زيت والسفلى خل.","وجود المواد في إناء واحد لا يجعلها مادة نقية، والمخلوط مزيج من مواد متعددة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (4%)"}],"at":"2026-10-18T03:32:48.219Z"}'::jsonb),
('mcq', 6, 2, 'ثبات التركيب في أي جزء من المخلوط X يدل على أنه متجانس، واختلافه بين موضعين في Y يدل على أن تركيبه غير منتظم، فهو غير متجانس.', '["هذا عكس الاستنتاج الصحيح؛ فتطابق التركيب صفة المخلوط المتجانس.","اختلاف تركيب عينتي Y يمنع عدّه متجانسًا.","","تطابق تركيب عينتي X يدل على تجانسه، فلا يكون غير متجانس."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (4%)"}],"at":"2026-10-18T03:32:48.219Z"}'::jsonb),
('mcq', 7, 3, 'يُطلق على المخاليط المتجانسة اسم المحاليل، وقد تكون المحاليل صلبة أو سائلة أو غازية.', '["المحاليل مخاليط متجانسة وليست غير متجانسة، وليست سائلة فقط.","المحلول مخلوط من مادتين نقيتين أو أكثر وليس مادة نقية.","المحاليل متجانسة فعلًا، لكنها لا تقتصر على السوائل؛ فهناك محاليل صلبة (كالسبائك) وغازية (كالهواء).",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (27%)"}],"at":"2026-10-18T03:32:48.219Z"}'::jsonb),
('essay', 1, null::int, null, null, 'المخلوط المتجانس له تركيب ثابت ومنتظم، وتمتزج مكوناته امتزاجًا تامًّا فلا تتمايز، مثل الشاي أو مملغم الفضة والزئبق. أما المخلوط غير المتجانس فتركيبه غير منتظم، ولا تمتزج مكوناته بل تبقى متمايزة بعضها من بعض، مثل سلطة الخضار أو عصير البرتقال الطبيعي الذي يطفو لبّه على سطحه.', '["المتجانس: تركيب ثابت ومنتظم","المتجانس: تمتزج المكونات ولا تتمايز، مع مثال صحيح","غير المتجانس: تركيب غير منتظم","غير المتجانس: المكونات تبقى متمايزة، مع مثال صحيح"]'::jsonb, '[]'::jsonb, '[{"element":"انتظام التركيب في المتجانس وعدم انتظامه في غير المتجانس","marks":1},{"element":"امتزاج المكونات في المتجانس وتمايزها في غير المتجانس","marks":1},{"element":"مثال صحيح للمتجانس","marks":1},{"element":"مثال صحيح لغير المتجانس","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"مقارنة صحيحة في الجانبين مع مثالين صحيحين"},{"level":"2–3 درجات","description":"مقارنة صحيحة في جانب واحد أو أحد المثالين ناقص أو خاطئ"},{"level":"1 درجة","description":"ذكر خاصية واحدة صحيحة فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["عدّ الشاي أو الهواء مخلوطًا غير متجانس لأنه مزيج","الخلط بين الامتزاج الكامل والاتحاد الكيميائي","ذكر مثال دون بيان سبب تصنيفه"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (14%)"}],"at":"2026-10-18T03:32:48.219Z"}'::jsonb),
('essay', 2, null::int, null, null, 'المخلوط A متجانس، لأن تركيب العينات الثلاث متطابق (25%) أي أن مكوناته ممتزجة بانتظام وله تركيب ثابت. المخلوط B غير متجانس، لأن تركيب العينات يختلف من موضع إلى آخر (8% و31% و60%) أي أن تركيبه غير منتظم ومكوناته متمايزة. وبما أن A متجانس فالعينة الرابعة المأخوذة منه ستحتوي أيضًا على 25% من المكوّن الأول، مهما اختلف موضعها أو حجمها.', '["A متجانس لتطابق تركيب العينات","تعليل: التركيب ثابت ومكوناته ممتزجة بانتظام","B غير متجانس لاختلاف تركيب العينات","تعليل: التركيب غير منتظم ومكوناته متمايزة","العينة الرابعة من A تحتوي 25% من المكوّن الأول"]'::jsonb, '[]'::jsonb, '[{"element":"تصنيف A متجانسًا مع التعليل","marks":2},{"element":"تصنيف B غير متجانس مع التعليل","marks":2},{"element":"توقع تركيب العينة الرابعة (25%) مع التبرير","marks":1}]'::jsonb, '[{"level":"5 درجات","description":"تصنيف صحيح للمخلوطين مع تعليل، وتوقع صحيح للعينة الرابعة مع التبرير"},{"level":"3–4 درجات","description":"تصنيف صحيح للمخلوطين مع نقص في التعليل أو التوقع"},{"level":"1–2 درجة","description":"تصنيف صحيح لمخلوط واحد فقط أو تصنيف دون تعليل"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["عكس التصنيف بين A وB","الحكم بالتجانس من المظهر دون النظر إلى انتظام التركيب","توقع تركيب مختلف للعينة الرابعة من المخلوط المتجانس"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (8%)"}],"at":"2026-10-18T03:32:48.220Z"}'::jsonb),
('essay', 3, null::int, null, null, 'العبارة غير صحيحة. عند ذوبان السكر كليًّا في الماء تمتزج مكوناته بانتظام ويصبح تركيب المحلول ثابتًا في أي جزء منه، ولا تتمايز مكوناته؛ لذلك ينتج مخلوط متجانس، والمخلوط المتجانس يسمى محلولًا. والصحيح أن يقال: ينتج محلول متجانس.', '["الحكم بأن العبارة خاطئة","امتزاج السكر بالماء بانتظام وثبات التركيب","المحلول مخلوط متجانس","الصياغة الصحيحة: ينتج محلول متجانس"]'::jsonb, '[]'::jsonb, '[{"element":"الحكم بخطأ العبارة","marks":1},{"element":"تعليل التجانس بالامتزاج المنتظم وثبات التركيب","marks":1},{"element":"ذكر أن المحلول مخلوط متجانس","marks":1},{"element":"صياغة العبارة الصحيحة","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"حكم صحيح مع تعليل كامل وصياغة صحيحة"},{"level":"2–3 درجات","description":"حكم صحيح مع تعليل أو صياغة ناقصة"},{"level":"1 درجة","description":"الحكم بالخطأ دون تعليل"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["الظن أن المحلول لا يكون مخلوطًا","عدّ المحلول غير متجانس لأنه يحتوي مادتين","الاكتفاء بقول «العبارة خاطئة» دون تعليل"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (8%)"}],"at":"2026-10-18T03:32:48.220Z"}'::jsonb)
) as v(type, number, ci, ex, dn, ma, ae, ss, mk, rb, ce, ac)
