select (select id from public.objectives where code = 'K1-C2-L3-O03'), v.type, v.number, v.stem, v.stimulus::jsonb, v.options::jsonb, v.tl, v.qk, v.diff, v.src, 'generated', 'ai_generated'
from (values
('mcq', 1, 'أيّ طرائق الفصل الآتية تناسب فصل الرمل عن الماء في مخلوط غير متجانس من مادة صلبة وسائل؟', null, '["التقطير","التسامي","التبلور","الترشيح"]'::jsonb, 'فهم', 'اختيار الطريقة المناسبة', 'سهل', 'الكتاب ص 56 — الترشيح'),
('mcq', 2, 'أيّ طرائق الفصل تعتمد على تبخّر المادة الصلبة دون أن تتصهر، أي دون أن تمر بالحالة السائلة؟', null, '["الترشيح","التسامي","التبلور","التقطير"]'::jsonb, 'تذكر', 'تعريف طريقة', 'سهل', 'الكتاب ص 56 — التسامي'),
('mcq', 3, 'يراد فصل مخلوط متجانس من سائلين تختلف درجتا غليانهما. أيّ الطرائق الآتية أنسب لذلك؟', null, '["الترشيح بورقة الترشيح","التبلور من محلول مشبع","التقطير بتسخين المخلوط","الفصل بالمغناطيس"]'::jsonb, 'فهم', 'اختيار الطريقة المناسبة', 'متوسط', 'الكتاب ص 56 — التقطير'),
('mcq', 4, 'محلول مشبع من السكر في الماء، تُرك الماء يتبخر منه تدريجيًّا فتكوّنت بلورات صلبة. ما اسم طريقة الفصل المستعملة؟', null, '["التبلور","الترشيح","التسامي","الكروماتوجرافيا"]'::jsonb, 'فهم', 'تمييز طريقة من الوصف', 'متوسط', 'الكتاب ص 56 — التبلور'),
('mcq', 5, 'أُريد فصل الأصباغ المكوّنة لحبر أسود إلى مكوناتها الملونة. أيّ الطرائق الآتية أنسب؟', null, '["التقطير","الكروماتوجرافيا","التسامي","الترشيح"]'::jsonb, 'تطبيق', 'اختيار الطريقة المناسبة', 'متوسط', 'الكتاب ص 56، 57 — الكروماتوجرافيا'),
('mcq', 6, 'مخلوط من الرمل وملح الطعام والماء، يُراد فصل مكوناته الثلاثة. أيّ التسلسلات الآتية أنسب؟', null, '["التقطير أولًا ثم الترشيح","التسامي أولًا ثم التبلور","التبلور أولًا ثم الترشيح","الترشيح لفصل الرمل ثم التبلور لفصل الملح"]'::jsonb, 'تطبيق', 'تخطيط تسلسل فصل', 'صعب', 'الكتاب ص 56 — الترشيح والتبلور'),
('mcq', 7, 'أيّ الاقترانات الآتية بين طريقة الفصل والخاصية الفيزيائية التي تعتمد عليها صحيح؟', null, '["الترشيح: اختلاف درجات غليان المكونات","التقطير: اختلاف قابلية الانجذاب للمغناطيس","الكروماتوجرافيا: اختلاف قابلية انجذاب المكونات للطور الثابت","التبلور: قدرة أحد المكونات على التسامي"]'::jsonb, 'تحليل', 'ربط طريقة بأساسها الفيزيائي', 'صعب', 'الكتاب ص 56 — طرائق الفصل'),
('essay', 1, 'سمِّ طريقة الفصل الأنسب لكل مخلوط مما يأتي، واذكر الخاصية الفيزيائية التي تعتمد عليها:
(أ) برادة الحديد والرمل.
(ب) الرمل والماء.
(ج) سائلان ممتزجان تختلف درجتا غليانهما.
(د) الأصباغ المكوّنة لحبر.', null, null, 'تطبيق', 'اختيار طريقة الفصل مع التعليل', 'متوسط', 'الكتاب ص 56، 70 — طرائق فصل المخاليط'),
('essay', 2, 'فسّر كيف يمكن الحصول على بلورات السكر الصلبة من محلوله المائي المشبع بطريقة التبلور، مبينًا دور تبخر الماء.', null, null, 'فهم', 'تفسير عملية', 'متوسط', 'الكتاب ص 56 — التبلور'),
('essay', 3, 'اقترح طالب فصل السكر عن محلوله المائي بالترشيح باستعمال ورقة ترشيح. قيّم هذا الاقتراح، ثم اقترح طريقتين مناسبتين وبيّن ما يُحصل عليه بكل منهما.', null, null, 'تقويم', 'تقويم اقتراح', 'صعب', 'الكتاب ص 56 — الترشيح والتبلور والتقطير')
) as v(type, number, stem, stimulus, options, tl, qk, diff, src)
