insert into public.question_answers (question_id, correct_index, explanation, distractor_notes, model_answer, answer_elements, solution_steps, marks, rubric, common_errors, auto_check)
select x.id, v.ci::int, v.ex::text, v.dn::jsonb, v.ma::text, v.ae::jsonb, v.ss::jsonb, v.mk::jsonb, v.rb::jsonb, v.ce::jsonb, v.ac::jsonb
from (values
('mcq', 1, 3, 'الترشيح طريقة تستعمل حاجزًا مساميًّا (ورقة الترشيح) يحبس المادة الصلبة ويمرّر السائل، فيناسب فصل المخلوط غير المتجانس من مادة صلبة وسائل.', '["التقطير يعتمد على اختلاف درجات الغليان ويستعمل لفصل المخاليط المتجانسة.","التسامي يفصل مادتين صلبتين إحداهما تتسامى، وليس صلبًا عن سائل.","التبلور يعطي مادة صلبة نقية من محلولها المشبع، والرمل لا يذوب في الماء.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (19%)"}],"at":"2026-10-18T03:32:48.220Z"}'::jsonb),
('mcq', 2, 1, 'التسامي عملية تتبخر فيها المادة الصلبة دون أن تتصهر، ويستعمل لفصل مادتين صلبتين إحداهما قادرة على التسامي والأخرى لا.', '["الترشيح يفصل المواد الصلبة عن السوائل بحاجز مسامي ولا يحتاج إلى تبخر.","","التبلور يعتمد على ترسيب بلورات المادة الصلبة من محلولها بعد تبخر المذيب.","التقطير يعتمد على غليان السائل وتكثيف بخاره، فتمرّ المادة بالحالة السائلة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (10%)"}],"at":"2026-10-18T03:32:48.221Z"}'::jsonb),
('mcq', 3, 2, 'التقطير يعتمد على الاختلاف في درجات الغليان؛ إذ يُسخَّن المخلوط حتى تغلي المادة الأقل درجة غليان فتتحول إلى بخار يُكثَّف ويُجمع سائلًا.', '["الترشيح لا يفصل السوائل الممتزجة لأنها كلها تمر عبر الحاجز المسامي.","التبلور يعطي مادة صلبة من محلولها المشبع، وليس مناسبًا لفصل سائلين.","","المغناطيس يفصل المواد التي ينجذب بعضها إليه، ولا تأثير له في السوائل."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (26%)"}],"at":"2026-10-18T03:32:48.221Z"}'::jsonb),
('mcq', 4, 0, 'عند تبخر الماء من المحلول المشبع يصبح المحلول أكثر تركيزًا فيترسب السكر على هيئة بلورات صلبة نقية، وهذه هي طريقة التبلور.', '["","الترشيح يفصل مادة صلبة غير ذائبة عن سائل ولا ينتج بلورات من محلول.","التسامي يخص تحول المادة الصلبة مباشرة إلى بخار، وليس ترسيب بلورات من محلول.","الكروماتوجرافيا تفصل المكونات بحسب انجذابها لسطح الطور الثابت ولا تعتمد على تبخر المذيب."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (12%)"}],"at":"2026-10-18T03:32:48.221Z"}'::jsonb),
('mcq', 5, 1, 'تفصل الكروماتوجرافيا مكونات المخلوط بحسب اختلاف انجذابها لسطح الطور الثابت (ورق الكروماتوجرافيا)، فتتباعد أصباغ الحبر على الورقة.', '["التقطير يحتاج إلى غليان المخلوط واختلاف درجات الغليان، ولا يستعمل لفصل أصباغ الحبر على ورقة.","","التسامي يخص فصل مادتين صلبتين إحداهما تتسامى، والأصباغ هنا ليست كذلك.","الترشيح يفصل صلبًا غير ذائب عن سائل، أما الأصباغ فذائبة في الحبر."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (21%)"}],"at":"2026-10-18T03:32:48.221Z"}'::jsonb),
('mcq', 6, 3, 'يُرشَّح المخلوط أولًا فيبقى الرمل على ورقة الترشيح ويمر محلول الملح، ثم يُبخَّر الماء من المحلول فيتبلور الملح.', '["بعد التقطير الأول يبقى الرمل والملح الصلبان معًا، ولا يفصلهما الترشيح لأنه لا يوجد سائل يذيب الملح.","لا يتسامى الرمل ولا الملح، ولا يناسب التسامي مخلوطًا يحتوي ماء.","التبلور قبل إزالة الرمل يترك الرمل مختلطًا بالبلورات الناتجة.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (26%)"}],"at":"2026-10-18T03:32:48.222Z"}'::jsonb),
('mcq', 7, 2, 'تعتمد الكروماتوجرافيا على اختلاف قابلية انجذاب كل مكوّن لسطح الطور الثابت، وهذا هو الاقتران الصحيح.', '["الترشيح يعتمد على حجم الجسيمات وقدرتها على المرور من الحاجز المسامي، أما اختلاف درجات الغليان فأساس التقطير.","التقطير يعتمد على اختلاف درجات الغليان، أما الانجذاب للمغناطيس فيُستعمل في فصل الحديد.","","التبلور يعتمد على ترسيب بلورات المادة الذائبة من المحلول المشبع، أما التسامي فطريقة مستقلة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (19%)"}],"at":"2026-10-18T03:32:48.222Z"}'::jsonb),
('essay', 1, null::int, null, null, '(أ) الفصل بالمغناطيس: لأن المغناطيس يجذب برادة الحديد فقط ولا يجذب الرمل. (ب) الترشيح: لأن ورقة الترشيح حاجز مساميّ يحبس الرمل الصلب ويمرّر الماء. (ج) التقطير: لاختلاف درجتي غليان السائلين؛ إذ يغلي الأقل غليانًا أولًا فيتحول إلى بخار يُكثَّف ويُجمع سائلًا. (د) الكروماتوجرافيا: لاختلاف قابلية انجذاب كل صبغ لسطح الطور الثابت (ورق الكروماتوجرافيا) فتتباعد الأصباغ على الورقة.', '["(أ) المغناطيس وانجذاب الحديد وحده","(ب) الترشيح وحاجز مسامي يحبس الصلب","(ج) التقطير واختلاف درجات الغليان","(د) الكروماتوجرافيا واختلاف قابلية الانجذاب للطور الثابت"]'::jsonb, '[]'::jsonb, '[{"element":"(أ) الطريقة والخاصية","marks":2},{"element":"(ب) الطريقة والخاصية","marks":2},{"element":"(ج) الطريقة والخاصية","marks":2},{"element":"(د) الطريقة والخاصية","marks":2}]'::jsonb, '[{"level":"8 درجات","description":"تسمية صحيحة للطرائق الأربع مع الخاصية الفيزيائية لكل منها"},{"level":"5–7 درجات","description":"تسمية صحيحة للطرائق الأربع مع نقص في بعض الخواص، أو ثلاث طرائق كاملة"},{"level":"2–4 درجات","description":"تسمية صحيحة لطريقتين أو ثلاث دون خواص"},{"level":"1 درجة","description":"تسمية طريقة واحدة صحيحة فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["استعمال الترشيح لفصل سائلين ممتزجين","الخلط بين التبلور والتقطير","ذكر الطريقة دون الخاصية الفيزيائية المعتمَد عليها"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (8 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (19%)"}],"at":"2026-10-18T03:32:48.222Z"}'::jsonb),
('essay', 2, null::int, null, null, 'المحلول المشبع يحتوي أكبر قدر ممكن من السكر المذاب، لذلك فإن إضافة أي كمية أخرى من السكر مهما قلّت تترسب وتكوّن بلورات على أي سطح متوافر. وعند تبخر الماء من المحلول يقل المذيب ويصبح المحلول أكثر تركيزًا، وهذا يشبه إضافة المزيد من السكر إلى المحلول، فيترسب السكر ويتكوّن بلورات صلبة نقية (كما على خيط يوضع في المحلول). وهكذا نحصل على السكر صلبًا نقيًّا من محلوله.', '["المحلول المشبع يحتوي أكبر قدر ممكن من المذاب","تبخر الماء يجعل المحلول أكثر تركيزًا","ذلك يشبه إضافة المزيد من المذاب فيترسب السكر","تتكوّن بلورات صلبة نقية على سطح متوافر"]'::jsonb, '[]'::jsonb, '[{"element":"معنى المحلول المشبع","marks":1},{"element":"أثر تبخر الماء في زيادة التركيز","marks":1},{"element":"ترسب السكر وتكوّن البلورات","marks":1},{"element":"ذكر أن الناتج مادة صلبة نقية","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"تفسير كامل يربط التشبع وتبخر الماء وزيادة التركيز بتكوّن البلورات"},{"level":"2–3 درجات","description":"تفسير صحيح مع إغفال أحد العناصر"},{"level":"1 درجة","description":"ذكر أن البلورات تتكوّن دون تفسير"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["القول إن السكر يتبخر مع الماء","الخلط بين التبلور والترشيح","إغفال أثر زيادة التركيز بعد تبخر الماء"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (11%)"}],"at":"2026-10-18T03:32:48.223Z"}'::jsonb),
('essay', 3, null::int, null, null, 'الاقتراح غير مناسب؛ لأن الترشيح يفصل المخاليط غير المتجانسة المكوّنة من مادة صلبة وسائل، أما محلول السكر فمخلوط متجانس تمتزج فيه جسيمات السكر مع الماء ويمر السكر مع الماء عبر الحاجز المسامي، فلا يُفصل. والطريقتان المناسبتان: التبلور، إذ يتبخر الماء ويترسب السكر بلورات صلبة نقية. والتقطير، إذ يُسخَّن المحلول فيتبخر الماء ويُكثَّف ويُجمع ماءً سائلًا نقيًّا ويبقى السكر.', '["الترشيح غير مناسب لأن المحلول مخلوط متجانس","السكر يمر مع الماء عبر الحاجز المسامي","التبلور يعطي السكر بلورات صلبة","التقطير يعطي الماء سائلًا مكثفًا ويبقى السكر"]'::jsonb, '[]'::jsonb, '[{"element":"الحكم بعدم مناسبة الترشيح مع التعليل","marks":2},{"element":"التبلور والناتج","marks":1},{"element":"التقطير والناتج","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"تقييم صحيح مع تعليل، وطريقتان صحيحتان مع الناتج"},{"level":"2–3 درجات","description":"تقييم صحيح مع طريقة واحدة، أو طريقتان دون تعليل كافٍ"},{"level":"1 درجة","description":"الحكم بعدم المناسبة دون تعليل أو بديل"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["الظن أن الترشيح يفصل المواد الذائبة عن مذيبها","اقتراح التسامي لفصل السكر عن الماء","ذكر الطريقة البديلة دون بيان الناتج"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (9%)"}],"at":"2026-10-18T03:32:48.223Z"}'::jsonb)
