('mcq', 4, 3, 'مكونات الأسطوانة معادن صلبة ممتزجة بانتظام، فالمحلول من نوع صلب - صلب (سبيكة).', '["هذا النوع يتضمن مادة صلبة ذائبة في سائل، وهنا لا يوجد سائل.","هذا النوع يتضمن غازًا ذائبًا في سائل، ولا غاز ولا سائل في المعادن.","المعادن في الأسطوانة صلبة وليست سوائل.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (25%)"}],"at":"2026-10-18T03:32:48.225Z"}'::jsonb),
