('mcq', 6, 0, 'المحاليل مخاليط متجانسة قد تكون صلبة أو سائلة أو غازية، وتُصنَّف بحسب حالتي المادتين الممتزجتين.', '["","هناك محاليل غازية (كالهواء) وصلبة (كالسبائك)، فلا تقتصر على السائلة.","المحاليل الصلبة مخاليط متجانسة (مثل السبائك) وليست مواد نقية.","المحاليل الغازية مخاليط متجانسة، فالغازات تمتزج بانتظام."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (10%)"}],"at":"2026-10-18T03:32:48.225Z"}'::jsonb),
('mcq', 7, 1, 'الفولاذ مخلوط متجانس صلب من الحديد والكربون، أي محلول صلب يسمى سبيكة.', '["الفولاذ مخلوط متجانس لأن ذرات الكربون تمتزج بانتظام مع الحديد.","","الفولاذ مخلوط تحتفظ مكوناته بخواصها وليس مركبًا.","الفولاذ صلب في الظروف العادية ولا سائل فيه، فلا يكون محلولًا سائلًا."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (4%)"}],"at":"2026-10-18T03:32:48.226Z"}'::jsonb),
('essay', 1, null::int, null, null, '(أ) غاز - غاز. (ب) غاز - سائل. (ج) سائل - غاز. (د) سائل - سائل. (هـ) صلب - سائل. (و) صلب - صلب (سبيكة)، لأنه مزيج من الحديد والكربون الصلبين.', '["(أ) غاز - غاز","(ب) غاز - سائل","(ج) سائل - غاز","(د) سائل - سائل","(هـ) صلب - سائل","(و) صلب - صلب"]'::jsonb, '[]'::jsonb, '[{"element":"(أ) غاز - غاز","marks":1},{"element":"(ب) غاز - سائل","marks":1},{"element":"(ج) سائل - غاز","marks":1},{"element":"(د) سائل - سائل","marks":1},{"element":"(هـ) صلب - سائل","marks":1},{"element":"(و) صلب - صلب","marks":1}]'::jsonb, '[{"level":"6 درجات","description":"تصنيف جميع الأمثلة الستة تصنيفًا صحيحًا"},{"level":"4–5 درجات","description":"تصنيف أربعة أو خمسة أمثلة تصنيفًا صحيحًا"},{"level":"2–3 درجات","description":"تصنيف مثالين أو ثلاثة أمثلة تصنيفًا صحيحًا"},{"level":"1 درجة","description":"تصنيف مثال واحد صحيح"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["الخلط بين غاز - سائل وسائل - غاز","عدّ الفولاذ سائلًا أو مركبًا","ذكر الحالة الفيزيائية لمادة واحدة فقط من المادتين"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (6 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (16%)"}],"at":"2026-10-18T03:32:48.226Z"}'::jsonb),
('essay', 2, null::int, null, null, 'من الأنواع الموجودة في ماء البحر: (1) غاز - سائل، مثل الأكسجين وثاني أكسيد الكربون الذائبين في الماء. (2) صلب - سائل، مثل الأملاح الصلبة الذائبة في الماء. (3) سائل - سائل، مثل امتزاج ماء المطر بماء البحر. وتُعدّ جميعها محاليل لأن كلًّا منها مخلوط متجانس، أي أن مكوناته تمتزج بانتظام وله تركيب ثابت، والمخلوط المتجانس يسمى محلولًا.', '["غاز - سائل مع مثال صحيح","صلب - سائل مع مثال صحيح","سائل - سائل مع مثال صحيح","كلها مخاليط متجانسة (محاليل) لأن مكوناتها تمتزج بانتظام"]'::jsonb, '[]'::jsonb, '[{"element":"نوع أول مع مثال صحيح","marks":1},{"element":"نوع ثانٍ مع مثال صحيح","marks":1},{"element":"نوع ثالث مع مثال صحيح","marks":1},{"element":"تعليل كونها محاليل (مخاليط متجانسة)","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"ثلاثة أنواع صحيحة بأمثلتها مع تعليل التجانس"},{"level":"2–3 درجات","description":"نوعان أو ثلاثة أنواع دون تعليل كافٍ"},{"level":"1 درجة","description":"نوع واحد صحيح فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["ذكر المثال دون تسمية نوع المحلول","عدّ ماء البحر مادة نقية","عدم ربط كونها محاليل بتجانس المخلوط"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (15%)"}],"at":"2026-10-18T03:32:48.226Z"}'::jsonb),
('essay', 3, null::int, null, null, 'ثاني أكسيد الكربون في الماء محلول من نوع غاز - سائل لأن المذاب غاز والمذيب ماء سائل. والسكر في الماء محلول من نوع صلب - سائل لأن المذاب صلب والمذيب ماء سائل. وعند تسرب معظم غاز ثاني أكسيد الكربون يزول المحلول من النوع غاز - سائل ويبقى المحلول من النوع صلب - سائل (السكر في الماء)، ولهذا يبقى المشروب حلوًا مهما تركت العلبة مفتوحة.', '["ثاني أكسيد الكربون في الماء: غاز - سائل","السكر في الماء: صلب - سائل","بعد تسرب الغاز يبقى صلب - سائل","المشروب يبقى حلوًا لأن السكر لم يتسرب"]'::jsonb, '[]'::jsonb, '[{"element":"تصنيف ثاني أكسيد الكربون في الماء","marks":1},{"element":"تصنيف السكر في الماء","marks":1},{"element":"نوع المحلول الباقي بعد تسرب الغاز","marks":1},{"element":"تعليل بقاء المشروب حلوًا","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"تصنيف صحيح للمحلولين، وتوقع صحيح للمحلول الباقي مع التعليل"},{"level":"2–3 درجات","description":"تصنيف صحيح مع نقص في التوقع أو التعليل"},{"level":"1 درجة","description":"تصنيف واحد صحيح فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["عدّ المشروب كله من نوع غاز - سائل","القول إن المشروب يصبح مادة نقية بعد فقدان الغاز","عكس ترتيب حالتي المادتين في الاسم"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (15%)"}],"at":"2026-10-18T03:32:48.227Z"}'::jsonb)
