('mcq', 2, 0, 'مكونات المخلوط تحتفظ بخواصها ولا تتحد كيميائيًّا، فيمكن فصلها بطرائق فيزيائية تعتمد على اختلاف خواصها، وهذا ما ينطبق على المخاليط.', '["","المادة النقية ذات تركيب ثابت، ولا تُفصل مكوناتها بهذه الطرائق الفيزيائية.","العنصر النقي لا يمكن تجزئته إلى مواد أبسط بطرائق فيزيائية.","مكونات المركب متحدة كيميائيًّا، ولا تفصلها الطرائق الفيزيائية."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (13%)"}],"at":"2026-10-18T03:32:48.228Z"}'::jsonb),
('mcq', 3, 3, 'المخلوط مزيج من مادتين نقيتين أو أكثر تحتفظ كل منها بخواصها الأصلية، وتُفصل مكوناته بطرائق فيزيائية.', '["الاتحاد الكيميائي ينتج مادة جديدة، أما المخلوط فمزيج لا تتحد مكوناته.","مكونات المخلوط تحتفظ بخواصها ولا تفقدها.","المادة النقية ثابتة التركيب في جميع العينات.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (18%)"}],"at":"2026-10-18T03:32:48.228Z"}'::jsonb),
('mcq', 4, 2, 'ملح الطعام النقي مركب واحد أي مادة نقية، والعصير الطبيعي مزيج من العصير واللب أي مخلوط، فالزوج المطلوب.', '["الفولاذ والهواء مخلوطان كلاهما، فليس بينهما مادة نقية.","الماء المقطر والأكسجين النقي مادتان نقيتان كلتاهما، فليس بينهما مخلوط.","","الزوج صحيح المحتوى لكن ترتيبه معكوس؛ إذ يبدأ بالمخلوط ثم المادة النقية."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (10%)"}],"at":"2026-10-18T03:32:48.228Z"}'::jsonb),
('mcq', 5, 1, 'ملح الطعام النقي مادة نقية ثابتة التركيب، أما مخلوط الملح والرمل فيتغير تركيبه بتغير نسبتي مكونيه مع احتفاظ كل مكوّن بخواصه.', '["فصل مكونات المخلوط فيزيائي ولا تنتج عنه مادة جديدة، كما أن الملح النقي لا يُفصل فيزيائيًّا أصلًا.","","تركيب المخلوط ليس ثابتًا؛ فنسبة الملح إلى الرمل قابلة للتغيير.","الملح والرمل يحتفظان بخواصهما عند المزج؛ فلا تتغير خواصهما."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (18%)"}],"at":"2026-10-18T03:32:48.228Z"}'::jsonb),
('mcq', 6, 3, 'المواد في المخلوط مختلطة فيزيائيًّا، لذا تُفصل مكوناته النقية بطرائق فيزيائية تعتمد على اختلاف خواصها كالترشيح والتقطير.', '["التفاعل الكيميائي يُنتج مواد جديدة ولا يفصل المكونات الأصلية.","إضافة مادة ثالثة تزيد المخلوط تعقيدًا ولا تفصل مكوناته.","اتحاد المكونات بالتسخين يكوّن مادة جديدة، وهذا يعاكس الفصل.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (13%)"}],"at":"2026-10-18T03:32:48.228Z"}'::jsonb),
('mcq', 7, 0, 'المادة س ثابتة التركيب ولا تُفصل مكوناتها فيزيائيًّا، فهي مادة نقية، والمادة ص يتغير تركيبها وتُفصل مكوناتها فيزيائيًّا، فهي مخلوط.', '["","هذا عكس ما تدل عليه البيانات؛ فتغير التركيب وإمكان الفصل الفيزيائي صفتان للمخلوط.","ثبات تركيب س وعدم إمكان فصلها فيزيائيًّا يدلان على أنها ليست مخلوطًا.","تغير تركيب ص بين العينات يدل على أنها ليست مادة نقية."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (0%)"}],"at":"2026-10-18T03:32:48.229Z"}'::jsonb),
('essay', 1, null::int, null, null, 'المادة النقية ذات تركيب منتظم وثابت، أما المخلوط فيختلف تركيبه بحسب نسب مكوناته. وتحتفظ مكونات المخلوط بخواصها الأصلية لأنها لا تتحد كيميائيًّا، أما المادة النقية فمادة واحدة ذات خواص مميزة. ويمكن فصل مكونات المخلوط بطرائق فيزيائية كالترشيح والتقطير، أما المادة النقية فلا يمكن فصلها بهذه الطرائق. مثال المادة النقية: ملح الطعام (كلوريد الصوديوم) أو الماء المقطر، ومثال المخلوط: ماء البحر أو الهواء.', '["المادة النقية تركيبها ثابت، والمخلوط يختلف تركيبه بحسب النسب","مكونات المخلوط تحتفظ بخواصها الأصلية","مكونات المخلوط تُفصل بطرائق فيزيائية ولا تُفصل المادة النقية بها","مثال صحيح لكل من المادة النقية والمخلوط"]'::jsonb, '[]'::jsonb, '[{"element":"المقارنة في ثبات التركيب","marks":1},{"element":"المقارنة في خواص المكونات","marks":1},{"element":"المقارنة في إمكان الفصل الفيزيائي","marks":1},{"element":"مثال صحيح لكل منهما","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"مقارنة صحيحة في الجوانب الثلاثة مع مثالين صحيحين"},{"level":"2–3 درجات","description":"مقارنة صحيحة في جانبين أو جانب واحد مع مثالين"},{"level":"1 درجة","description":"مقارنة صحيحة في جانب واحد فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["القول إن تركيب المخلوط ثابت","الخلط بين المخلوط والمركب","ذكر مثال خاطئ كعدّ الهواء مادة نقية"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (12%)"}],"at":"2026-10-18T03:32:48.229Z"}'::jsonb),
('essay', 2, null::int, null, null, 'المحلولان ليسا مادة واحدة؛ فكل منهما مخلوط من مادتين نقيتين هما السكر والماء، لكن تركيبهما مختلف لاختلاف نسبة السكر إلى الماء، وتحتفظ مكونات كل منهما بخواصها (كالطعم الحلو للسكر). أما الماء النقي فمادة نقية ذات تركيب ثابت لا يختلف من عينة إلى أخرى. ولأن تركيب المخلوط يتغير بتغير نسب مكوناته فيمكن تحضير عدد لا نهائي من محاليل السكر المختلفة من المادتين النقيتين نفسيهما.', '["كل محلول مخلوط من مادتين نقيتين","تركيب المحلولين مختلف لاختلاف نسبة السكر","الماء النقي مادة نقية ثابتة التركيب","تغير النسب ينتج مخاليط مختلفة من المادتين نفسيهما"]'::jsonb, '[]'::jsonb, '[{"element":"الحكم بأنهما ليسا مادة واحدة مع بيان أنهما مخلوطان","marks":1},{"element":"تعليل اختلاف التركيب بنسبة السكر","marks":1},{"element":"مقارنة بالماء النقي ثابت التركيب","marks":1},{"element":"ربط تغير النسب بتعدد المخاليط","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"حكم صحيح مع تعليل كامل ومقارنة بالماء النقي"},{"level":"2–3 درجات","description":"حكم صحيح مع نقص في التعليل أو المقارنة"},{"level":"1 درجة","description":"الحكم الصحيح دون تعليل"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["عدّ المحلولين المتجانسين مادتين نقيتين","القول إن السكر لا يحتفظ بخواصه بعد الذوبان","عدم بيان أن النسب تحدد تركيب المخلوط"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (5%)"}],"at":"2026-10-18T03:32:48.229Z"}'::jsonb),
('essay', 3, null::int, null, null, 'الاستنتاج غير صحيح؛ فانتظام المظهر لا يكفي للحكم بأن المادة نقية، فالمخلوط المتجانس (المحلول) يبدو منتظمًا أيضًا. والمعياران: (1) ثبات التركيب: المادة النقية تركيبها ثابت، أما الشاي فيختلف تركيبه بحسب كمية الشاي والماء والسكر فيه. (2) إمكان الفصل بطرائق فيزيائية: يمكن فصل مكونات الشاي فيزيائيًّا (كالتقطير لفصل الماء) وتحتفظ مكوناته بخواصها، وهذا لا ينطبق على المادة النقية. لذلك فالشاي مخلوط متجانس (محلول) وليس مادة نقية.', '["الاستنتاج خاطئ لأن التجانس في المظهر لا يعني أنه مادة نقية","معيار ثبات التركيب: تركيب الشاي يختلف بحسب النسب","معيار الفصل الفيزيائي: يمكن فصل مكوناته مع احتفاظها بخواصها","الشاي مخلوط متجانس (محلول)"]'::jsonb, '[]'::jsonb, '[{"element":"الحكم بخطأ الاستنتاج وبيان سببه","marks":1},{"element":"معيار ثبات التركيب مطبقًا على الشاي","marks":1},{"element":"معيار الفصل الفيزيائي مطبقًا على الشاي","marks":1},{"element":"الحكم النهائي: مخلوط متجانس","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"حكم صحيح، ومعياران مطبقان تطبيقًا صحيحًا، وخلاصة صحيحة"},{"level":"2–3 درجات","description":"حكم صحيح مع معيار واحد أو معيارين ناقصين"},{"level":"1 درجة","description":"الحكم الصحيح دون معايير"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["الخلط بين التجانس والنقاء","الاكتفاء بالمظهر في الحكم على المادة","القول إن الشاي لا يمكن فصل مكوناته"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (7%)"}],"at":"2026-10-18T03:32:48.229Z"}'::jsonb)
