from (values
('mcq', 1, 2, 'النحاس الأصفر سبيكة تمتزج فيها فلزات الخارصين والنحاس بانتظام ولها تركيب ثابت، فهو مخلوط متجانس (محلول صلب).', '["مكونات الفطيرة (العجين والزبيب) متمايزة وتركيبها غير منتظم، فهي مخلوط غير متجانس.","مكونات السلطة ظاهرة ومتمايزة، فهي مخلوط غير متجانس.","","الدم مخلوط غير متجانس لأن مكوناته متمايزة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (57%)"}],"at":"2026-10-18T03:32:48.230Z"}'::jsonb),
('mcq', 2, 3, 'الماء الموحل مزيج يبقى فيه الطين متمايزًا عن الماء ويترسب، وتركيبه غير منتظم، فهو مخلوط غير متجانس.', '["الهواء محلول غازي تمتزج مكوناته بانتظام، فهو متجانس.","الشاي محلول سائل تمتزج مكوناته بانتظام، فهو متجانس.","الجازولين مخلوط متجانس تمتزج مكوناته بانتظام.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (57%)"}],"at":"2026-10-18T03:32:48.230Z"}'::jsonb),
('mcq', 3, 0, 'ذوبان المسحوق يجعل مكوناته ممتزجة بانتظام وتركيبه ثابتًا في كل جزء، فالناتج مخلوط متجانس (محلول).', '["","كون المسحوق صلبًا قبل الذوبان لا يجعل الناتج غير متجانس، فالمعيار هو الامتزاج المنتظم بعد الذوبان.","اللون لا يحدد التجانس، والشراب الملوّن منتظم التركيب.","اختفاء المسحوق لا يعني أنه تحوّل مادة نقية، فالسكر والماء والصبغة ما زالت موجودة في مزيج."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (21%)"}],"at":"2026-10-18T03:32:48.231Z"}'::jsonb),
('mcq', 4, 1, 'مكونات البيتزا (العجين والجبن والخضار وغيرها) ظاهرة ومتمايزة وتركيبها يختلف من قطعة إلى أخرى، فهي مخلوط غير متجانس.', '["الخبز معًا لا يجعل المكونات تمتزج بانتظام، فهي تبقى متمايزة.","","كون المادة صلبة لا يعني تجانسها، فالسبائك الصلبة متجانسة والبيتزا الصلبة غير متجانسة.","تقديمها في طبق واحد لا يجعلها مادة نقية، فهي مزيج من مواد كثيرة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (33%)"}],"at":"2026-10-18T03:32:48.231Z"}'::jsonb),
('mcq', 5, 3, 'الفولاذ (محلول صلب) والجازولين (محلول سائل) والشاي (محلول سائل) كلها مخاليط متجانسة، وفي المجموعات الأخرى مخاليط غير متجانسة.', '["الدم والحليب مخلوطان غير متجانسين، وإن كان الهواء متجانسًا.","سلطة الخضار مخلوط غير متجانس تتمايز مكوناته.","الماء الموحل مخلوط غير متجانس يترسب فيه الطين.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (10%)"}],"at":"2026-10-18T03:32:48.231Z"}'::jsonb),
('mcq', 6, 2, 'انتظام التركيب يدل على التجانس، وإمكان فصل مكوناتها بالتقطير (طريقة فيزيائية) يدل على أنها مخلوط وليست مادة نقية، فهي مخلوط متجانس.', '["المادة النقية لا تُفصل مكوناتها بطرائق فيزيائية كالتقطير، وثبات التركيب وحده لا يكفي.","تساوي التركيب في الموضعين يدل على التجانس لا على عدمه.","","العنصر لا يتجزأ إلى مواد أبسط، أما هذه العينة فتتجزأ إلى سائلين."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (9%)"}],"at":"2026-10-18T03:32:48.231Z"}'::jsonb),
('mcq', 7, 0, 'الدم مخلوط غير متجانس لأن مكوناته متمايزة وتركيبه غير منتظم.', '["","اللون الموحد في المظهر لا يعني تجانس التركيب، فمكونات الدم متمايزة.","ليست مكونات الدم كلها ذائبة، فبعضها خلايا وأجزاء متمايزة.","مكان تكوّن الدم لا يحدد نقاءه، وهو مزيج من مواد كثيرة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (33%)"}],"at":"2026-10-18T03:32:48.232Z"}'::jsonb),
('essay', 1, null::int, null, null, 'النحاس الأصفر: مخلوط متجانس (سبيكة) لامتزاج الخارصين والنحاس بانتظام. سلطة الخضار: غير متجانس لأن مكوناتها متمايزة. مسحوق الشراب المذاب في الماء: متجانس لأن المسحوق ذاب وامتزج بانتظام. الدم: غير متجانس لأن مكوناته متمايزة. الهواء: متجانس لأنه محلول غازي تمتزج غازاته بانتظام. البيتزا: غير متجانسة لأن مكوناتها متمايزة وتركيبها غير منتظم.', '["النحاس الأصفر متجانس","سلطة الخضار غير متجانسة","الشراب المذاب متجانس","الدم غير متجانس","الهواء متجانس","البيتزا غير متجانسة","تعليل كل تصنيف بانتظام التركيب أو تمايز المكونات"]'::jsonb, '[]'::jsonb, '[{"element":"النحاس الأصفر مع التعليل","marks":1},{"element":"سلطة الخضار مع التعليل","marks":1},{"element":"مسحوق الشراب المذاب مع التعليل","marks":1},{"element":"الدم مع التعليل","marks":1},{"element":"الهواء مع التعليل","marks":1},{"element":"البيتزا مع التعليل","marks":1}]'::jsonb, '[{"level":"6 درجات","description":"تصنيف صحيح للمواد الست مع تعليل لكل منها"},{"level":"4–5 درجات","description":"تصنيف صحيح لأربع أو خمس مواد مع تعليلها"},{"level":"2–3 درجات","description":"تصنيف صحيح لمادتين أو ثلاث"},{"level":"1 درجة","description":"تصنيف صحيح لمادة واحدة"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["عدّ السبيكة مخلوطًا غير متجانس لأنها من فلزين","عدّ الدم مخلوطًا متجانسًا لأن مظهره موحد","التصنيف دون تعليل"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (6 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (15%)"}],"at":"2026-10-18T03:32:48.232Z"}'::jsonb),
('essay', 2, null::int, null, null, 'العينة 1: مخلوط متجانس (محلول)؛ لأن تركيب أي جزء منها متطابق وتمتزج مكوناتها بانتظام، ويدل فصل مكوناتها بالتسخين على أنها مخلوط. العينة 2: مخلوط غير متجانس؛ لأن المادة الصلبة تبقى متمايزة وترسب في القاع، فتركيبه غير منتظم. العينة 3: مخلوط متجانس (سبيكة)؛ لأن تركيب أي قطعتين منها واحد ومكوناتها فلزان ممتزجان بانتظام.', '["العينة 1 متجانسة لتطابق التركيب وامتزاج المكونات","العينة 2 غير متجانسة لترسب مادة صلبة متمايزة","العينة 3 متجانسة (سبيكة) لثبات التركيب","ربط كل حكم بدليل من الوصف"]'::jsonb, '[]'::jsonb, '[{"element":"العينة 1 مع الدليل","marks":2},{"element":"العينة 2 مع الدليل","marks":2},{"element":"العينة 3 مع الدليل","marks":2}]'::jsonb, '[{"level":"6 درجات","description":"تصنيف صحيح للعينات الثلاث مع دليل صحيح لكل منها"},{"level":"4–5 درجات","description":"تصنيف صحيح للثلاث مع نقص في الأدلة"},{"level":"2–3 درجات","description":"تصنيف صحيح لعينة أو عينتين مع دليلهما"},{"level":"1 درجة","description":"تصنيف صحيح دون دليل"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["عدّ العينة 1 مادة نقية لأنها صافية","عدّ السبيكة غير متجانسة لأنها من فلزين","عدم الاستشهاد بالدليل من الوصف"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (6 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (7%)"}],"at":"2026-10-18T03:32:48.233Z"}'::jsonb),
('essay', 3, null::int, null, null, 'رأي الطالب الثاني هو الصحيح. فالفولاذ مخلوط متجانس (محلول صلب أو سبيكة) من فلز الحديد ولافلز الكربون، تمتزج مكوناته بانتظام ويكون تركيبه ثابتًا في أي قطعة منه. أما قول الطالب الأول إن اختلاف المادتين يجعله غير متجانس فخطأ؛ لأن كل المخاليط تتكون من مادتين مختلفتين على الأقل، والتجانس يتعلق بانتظام الامتزاج وثبات التركيب لا بكون المكونات مختلفة.', '["رأي الطالب الثاني صحيح","الفولاذ مخلوط متجانس (محلول صلب/سبيكة)","المكونات تمتزج بانتظام والتركيب ثابت","خطأ تعليل الأول: تعدد المكونات لا يعني عدم التجانس"]'::jsonb, '[]'::jsonb, '[{"element":"تحديد الرأي الصحيح","marks":1},{"element":"تعليل التجانس بالامتزاج المنتظم وثبات التركيب","marks":1},{"element":"بيان أن الفولاذ سبيكة (محلول صلب)","marks":1},{"element":"تفنيد تعليل الطالب الأول","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"تحديد صحيح مع تعليل كامل وتفنيد لرأي الأول"},{"level":"2–3 درجات","description":"تحديد صحيح مع تعليل ناقص"},{"level":"1 درجة","description":"تحديد صحيح دون تعليل"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["الربط بين اختلاف المكونات وعدم التجانس","عدّ الفولاذ مركبًا","الاكتفاء بالحكم دون تعليل"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (9%)"}],"at":"2026-10-18T03:32:48.233Z"}'::jsonb)
) as v(type, number, ci, ex, dn, ma, ae, ss, mk, rb, ce, ac)
