from (values
('mcq', 1, 0, 'تعتمد الكروماتوجرافيا على اختلاف قابلية انجذاب كل مكوّن من مكونات المخلوط لسطح مادة أخرى هي الطور الثابت.', '["","اختلاف درجات الغليان أساس التقطير لا الكروماتوجرافيا.","اختلاف حجم الجسيمات يرتبط بالترشيح عبر حاجز مسامي.","الانجذاب للمغناطيس يُستعمل لفصل برادة الحديد من الرمل، وليس أساس الكروماتوجرافيا."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (38%)"}],"at":"2026-10-18T03:32:48.234Z"}'::jsonb),
('mcq', 2, 1, 'يكون الطور المتحرك غالبًا مادة سائلة أو غازية تحمل مكونات المخلوط، أما الطور الثابت فمادة صلبة.', '["الطور الصلب هو الطور الثابت (كورق الكروماتوجرافيا)، لا الطور المتحرك.","","الطور المتحرك الصلب غير شائع، فهو غالبًا سائل أو غاز.","الطور المتحرك قد يكون سائلًا أيضًا كالماء، فلا يقتصر على الغاز."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (16%)"}],"at":"2026-10-18T03:32:48.234Z"}'::jsonb),
('mcq', 3, 2, 'الطور الثابت مادة صلبة تنجذب إليها المكونات بدرجات مختلفة، وهو هنا ورقة الكروماتوجرافيا، أما الماء فهو الطور المتحرك.', '["الماء يتحرك على الورقة حاملًا الأصباغ، فهو الطور المتحرك.","الحبر هو المخلوط المراد فصله وليس الطور الثابت.","","بخار الماء ليس جزءًا من الفصل على الورقة، ولا يمثل الطور الثابت."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (14%)"}],"at":"2026-10-18T03:32:48.234Z"}'::jsonb),
('mcq', 4, 3, 'يتباعد أولًا على ورقة الكروماتوجرافيا المكوّن الذي قوى تماسك جزيئاته أقل، ثم يليه المكوّن الذي قوى تماسك جزيئاته أكبر.', '["الكتلة ليست أساس ترتيب التباعد في الكروماتوجرافيا.","درجة الغليان لا تتحكم في الكروماتوجرافيا الورقية بل في التقطير.","المكوّن الذي قوى تماسك جزيئاته أكبر يتباعد متأخرًا بعد المكوّن الأقل تماسكًا.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (38%)"}],"at":"2026-10-18T03:32:48.234Z"}'::jsonb),
('mcq', 5, 0, 'المكوّن الذي قوى تماسك جزيئاته أقل يتباعد أولًا على الورقة فيقطع أكبر مسافة، والصبغة C قطعت 8.0 cm وهي الأكبر.', '["","الصبغة A قطعت أقل مسافة (2.0 cm) فهي الأكثر تماسكًا وانجذابًا للورقة.","الصبغة B قطعت مسافة متوسطة (5.0 cm)، فتماسكها بين A وC وليس الأقل.","اختلاف المسافات المقطوعة يدل على اختلاف قوى التماسك بين الأصباغ."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (10%)"}],"at":"2026-10-18T03:32:48.235Z"}'::jsonb),
('mcq', 6, 1, 'تنجذب كل صبغة إلى ورقة الكروماتوجرافيا (الطور الثابت) بدرجة مختلفة، فتتحرك مع الماء (الطور المتحرك) مسافات مختلفة وتظهر في أماكن مختلفة.', '["الكروماتوجرافيا فصل فيزيائي لا يكوّن مواد جديدة.","","الماء لا يغلي في هذه التجربة، ولا يعتمد الفصل على التبخر.","الأصباغ لا تتسامى؛ فهي تتحرك ذائبة في الماء على الورقة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (14%)"}],"at":"2026-10-18T03:32:48.236Z"}'::jsonb),
('mcq', 7, 2, 'الكروماتوجرافيا طريقة فصل فيزيائية تفصل المكونات بحسب انجذابها للطور الثابت دون أن تتحول إلى مواد جديدة.', '["هذا أساس التقطير لا الكروماتوجرافيا.","طرائق فصل المخاليط فيزيائية ولا تنتج مواد جديدة.","","هذا وصف الترشيح لا الكروماتوجرافيا."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (9%)"}],"at":"2026-10-18T03:32:48.236Z"}'::jsonb),
('essay', 1, null::int, null, null, 'الكروماتوجرافيا (التحليل الاستشرابي) طريقة لفصل مكونات المخلوط بالاعتماد على قابلية انجذاب كل مكوّن لسطح مادة أخرى. يحمل الطور المتحرك (غالبًا مادة سائلة أو غازية، كالماء) مكونات المخلوط على الطور الثابت وهو مادة صلبة كورق الكروماتوجرافيا. ولأن المكونات تنجذب إلى الطور الثابت بدرجات مختلفة، يتباعد أولًا المكوّن الذي قوى تماسك جزيئاته أقل، ثم يليه المكوّن الذي قوى تماسك جزيئاته أكبر، فتنفصل المكونات في أماكن مختلفة على الورقة.', '["تعريف الكروماتوجرافيا: فصل المكونات بحسب انجذابها لسطح مادة أخرى","الطور المتحرك: مادة سائلة أو غازية غالبًا","الطور الثابت: مادة صلبة كورق الكروماتوجرافيا","يتباعد أولًا المكوّن الأقل قوى تماسك ثم الأكبر"]'::jsonb, '[]'::jsonb, '[{"element":"تعريف الكروماتوجرافيا وأساسها","marks":1},{"element":"تحديد الطور المتحرك","marks":1},{"element":"تحديد الطور الثابت","marks":1},{"element":"ترتيب تباعد المكونات بحسب قوى التماسك","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"تعريف صحيح، وتحديد الطورين، وتفسير ترتيب التباعد"},{"level":"2–3 درجات","description":"تعريف صحيح مع نقص في تحديد الطورين أو تفسير الترتيب"},{"level":"1 درجة","description":"ذكر جزء من الفكرة فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["عدّ ورقة الكروماتوجرافيا الطور المتحرك","الخلط بين أساس الكروماتوجرافيا وأساس التقطير","عكس ترتيب تباعد المكونات"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (16%)"}],"at":"2026-10-18T03:32:48.236Z"}'::jsonb),
('essay', 2, null::int, null, null, 'الماء هو الطور المتحرك لأنه سائل يحمل مكونات الحبر، وورقة الترشيح هي الطور الثابت لأنها مادة صلبة. تنجذب كل صبغة في الحبر إلى سطح الورقة بدرجة مختلفة بحسب قوى تماسك جزيئاتها؛ فالصبغة ذات قوى التماسك الأقل تتباعد أولًا وتصل إلى مسافة أبعد، والصبغة ذات التماسك الأكبر تبقى أقرب إلى المركز، فتظهر الألوان في أماكن مختلفة. وهذا يدل على أن الحبر الأسود مخلوط من عدة أصباغ وليس مادة نقية.', '["الماء هو الطور المتحرك","ورقة الترشيح هي الطور الثابت","كل صبغة تنجذب للورقة بدرجة مختلفة (قوى تماسك مختلفة)","الأقل تماسكًا يتباعد أبعد","الحبر الأسود مخلوط من أصباغ"]'::jsonb, '[]'::jsonb, '[{"element":"تحديد الطور المتحرك والثابت","marks":1},{"element":"تفسير ظهور الألوان باختلاف الانجذاب للورقة","marks":2},{"element":"ترتيب التباعد بحسب قوى التماسك","marks":1},{"element":"استنتاج أن الحبر مخلوط","marks":1}]'::jsonb, '[{"level":"5 درجات","description":"تحديد الطورين، وتفسير كامل لاختلاف الألوان، واستنتاج صحيح"},{"level":"3–4 درجات","description":"تفسير صحيح مع نقص في تحديد الطورين أو الاستنتاج"},{"level":"1–2 درجة","description":"ذكر جزء صحيح من الفكرة"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["القول إن الألوان تنتج عن تفاعل كيميائي مع الماء","عدّ الحبر الأسود مادة نقية","الخلط بين الطور المتحرك والثابت"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (12%)"}],"at":"2026-10-18T03:32:48.236Z"}'::jsonb),
('essay', 3, null::int, null, null, 'العبارة غير صحيحة؛ فالتبخر عند درجات غليان مختلفة هو أساس التقطير. أما الكروماتوجرافيا فتعتمد على اختلاف قابلية انجذاب كل صبغة لسطح الطور الثابت (ورق الكروماتوجرافيا) بينما يحملها الطور المتحرك (كالماء). والتصحيح: تفصل الكروماتوجرافيا مكونات الحبر لأن كل صبغة تنجذب إلى الورقة بدرجة مختلفة، فيتباعد أولًا المكوّن الذي قوى تماسك جزيئاته أقل.', '["العبارة خاطئة","درجات الغليان أساس التقطير","أساس الكروماتوجرافيا اختلاف الانجذاب للطور الثابت","التصحيح مع ذكر الطورين أو ترتيب التباعد"]'::jsonb, '[]'::jsonb, '[{"element":"الحكم بخطأ العبارة","marks":1},{"element":"نسبة درجات الغليان إلى التقطير","marks":1},{"element":"ذكر أساس الكروماتوجرافيا الصحيح","marks":1},{"element":"صياغة العبارة الصحيحة","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"حكم صحيح، وتمييز من التقطير، وأساس صحيح، وصياغة صحيحة"},{"level":"2–3 درجات","description":"حكم صحيح مع نقص في التمييز أو التصحيح"},{"level":"1 درجة","description":"الحكم بالخطأ دون تعليل"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["الخلط بين الكروماتوجرافيا والتقطير","الاعتقاد أن الفصل يتطلب التسخين","ذكر الأساس دون ذكر الطور الثابت"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (13%)"}],"at":"2026-10-18T03:32:48.237Z"}'::jsonb)
