('essay', 1, null::int, null, null, 'السبيكة مخلوط متجانس (محلول صلب) من الفلزات، أو من فلز ولافلز يكون فيه الفلز هو المكوّن الأساسي. من أمثلتها: الفولاذ، وهو مخلوط من فلز الحديد ولافلز الكربون. والنحاس الأصفر، وهو سبيكة من فلزي الخارصين والنحاس. ومن أمثلتها أيضًا البرونز والذهب الأبيض.', '["السبيكة مخلوط متجانس (محلول صلب)","من فلزات أو من فلز ولافلز يكون الفلز المكوّن الأساسي","الفولاذ: الحديد والكربون","النحاس الأصفر: الخارصين والنحاس"]'::jsonb, '[]'::jsonb, '[{"element":"تعريف السبيكة كمخلوط متجانس صلب","marks":1},{"element":"ذكر تركيبها من فلزات أو فلز ولافلز","marks":1},{"element":"مثال أول مع مكوّناته","marks":1},{"element":"مثال ثانٍ مع مكوّناته","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"تعريف كامل ومثالان صحيحان مع المكوّنات"},{"level":"2–3 درجات","description":"تعريف ناقص أو مثال واحد كامل"},{"level":"1 درجة","description":"ذكر جزء من التعريف أو مثال دون مكوّنات"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["عدّ السبيكة مركبًا كيميائيًّا","القول إن السبائك تتكون من لافلزات فقط","ذكر مثال دون بيان مكوّناته"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (10%)"}],"at":"2026-10-18T03:32:48.238Z"}'::jsonb),
('essay', 2, null::int, null, null, 'الفولاذ سبيكة لأنه مخلوط متجانس (محلول صلب) من فلز الحديد ولافلز الكربون، ويكون الحديد فيه المكوّن الأساسي. ووجود ذرات الكربون في المخلوط يزيد من صلابة الفلز. وتمزج المصانع أنواعًا مختلفة من الفلزات في سبائك للحصول على مواد أكثر قوة ومقاومة، ولهذا تُصنع منها أدوات كثيرة ومجوهرات كالبرونز والذهب الأبيض.', '["الفولاذ مخلوط متجانس من الحديد والكربون","الحديد المكوّن الأساسي","الكربون يزيد الصلابة","السبائك تعطي مواد أكثر قوة ومقاومة"]'::jsonb, '[]'::jsonb, '[{"element":"تعليل كون الفولاذ سبيكة (مخلوط من فلز ولافلز)","marks":1},{"element":"ذكر أن الحديد المكوّن الأساسي","marks":1},{"element":"أثر الكربون في الصلابة","marks":1},{"element":"سبب مزج الفلزات في سبائك","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"تعليل صحيح كامل مع الأثر والسبب"},{"level":"2–3 درجات","description":"تعليل صحيح مع إغفال أحد العناصر"},{"level":"1 درجة","description":"ذكر عنصر واحد صحيح"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["القول إن الكربون يقلل صلابة الحديد","عدّ الفولاذ عنصرًا أو مركبًا","إغفال أن الفلز هو المكوّن الأساسي"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (26%)"}],"at":"2026-10-18T03:32:48.239Z"}'::jsonb),
('essay', 3, null::int, null, null, 'العبارة غير صحيحة. الذهب الأبيض سبيكة، أي مخلوط متجانس (محلول صلب) من الفلزات تحتفظ فيه المكونات بخواصها، وليس مركبًا ولا مادة نقية. والتصحيح: الذهب الأبيض سبيكة تُصنع منها المجوهرات. ومن السبائك الأخرى البرونز، والفولاذ (حديد وكربون)، والنحاس الأصفر (خارصين ونحاس).', '["العبارة خاطئة","الذهب الأبيض سبيكة أي مخلوط متجانس","ليس مركبًا ولا مادة نقية","مثالان صحيحان آخران على السبائك"]'::jsonb, '[]'::jsonb, '[{"element":"الحكم بخطأ العبارة","marks":1},{"element":"تصحيح: الذهب الأبيض سبيكة (مخلوط متجانس)","marks":1},{"element":"نفي كونه مركبًا أو مادة نقية مع تعليل","marks":1},{"element":"مثالان صحيحان آخران","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"حكم صحيح وتصحيح وتعليل ومثالان صحيحان"},{"level":"2–3 درجات","description":"حكم صحيح مع نقص في التعليل أو الأمثلة"},{"level":"1 درجة","description":"الحكم بالخطأ دون تعليل"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["الخلط بين السبيكة والمركب","عدّ السبيكة مادة نقية لأنها صلبة متجانسة","ذكر أمثلة ليست سبائك"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (10%)"}],"at":"2026-10-18T03:32:48.239Z"}'::jsonb)
