('mcq', 5, 'عناصر الليثيوم Li والصوديوم Na والبوتاسيوم K والسيزيوم Cs متشابهة في خواصها الكيميائية. ما الذي يجمع هذه العناصر في الجدول الدوري؟', null, '["تقع جميعها في دورة واحدة","كتلها الذرية متساوية","تقع جميعها في عمودين متجاورين","تقع جميعها في مجموعة واحدة"]'::jsonb, 'تطبيق', 'تطبيق على أمثلة', 'متوسط', 'الكتاب ص 59، 73 — الجدول الدوري'),
('mcq', 6, 'اكتُشف عنصر جديد تشبه خواصه الفيزيائية والكيميائية خواص الصوديوم Na والبوتاسيوم K. أين يُتوقع أن يوضع هذا العنصر في الجدول الدوري؟', null, '["في المجموعة نفسها (العمود نفسه) التي يقع فيها Na وK","في الدورة نفسها (الصف الأفقي) التي يقع فيها Na فقط","في صف أفقي مستقل خارج الدورات","في أي عمود يناسب كتلته بغض النظر عن خواصه"]'::jsonb, 'تطبيق', 'التنبؤ بموضع عنصر', 'صعب', 'الكتاب ص 59 — الجدول الدوري'),
('mcq', 7, 'يبيّن الجدول موقع أربعة عناصر في الجدول الدوري. أيّ زوج من هذه العناصر يُتوقع أن تكون خواصه الكيميائية أكثر تشابهًا؟', '{"headers":["العنصر","الدورة","المجموعة"],"rows":[["الليثيوم Li","2","1"],["الصوديوم Na","3","1"],["المغنيسيوم Mg","3","2"],["الكلور Cl","3","17"]]}'::jsonb, '["Na وMg","Na وCl","Li وNa","Li وMg"]'::jsonb, 'تحليل', 'تحليل بيانات الموقع', 'صعب', 'الكتاب ص 59 — الدورات والمجموعات'),
('essay', 1, 'صف ترتيب العناصر في الجدول الدوري، مبيّنًا المقصود بكل من الدورات والمجموعات.', null, null, 'فهم', 'وصف الترتيب', 'سهل', 'الكتاب ص 59 — الجدول الدوري'),
('essay', 2, 'فسّر سبب تسمية الجدول الدوري بهذا الاسم، ثم اذكر الأساس الذي رتّب عليه مندليف العناصر في جدوله الأول.', null, null, 'فهم', 'تفسير وذكر أساس', 'متوسط', 'الكتاب ص 59 — الجدول الدوري ومندليف'),
('essay', 3, 'يقع الليثيوم Li والصوديوم Na في المجموعة 1، ويقع الصوديوم Na والمغنيسيوم Mg في الدورة 3. أيّ العنصرين Li أم Mg يُتوقع أن تكون خواصه أقرب إلى خواص Na؟ فسّر إجابتك.', null, null, 'تطبيق', 'تنبؤ وتفسير', 'صعب', 'الكتاب ص 59 — الدورات والمجموعات')
