('mcq', 1, 1, 'ينظم الجدول الدوري العناصر في شبكة تسمى صفوفها الأفقية «الدورات»، بينما تسمى أعمدتها «المجموعات» أو «العائلات».', '["المجموعات هي الأعمدة الرأسية في الجدول وليست صفوفه الأفقية.","","العائلات اسم آخر للمجموعات، أي للأعمدة الرأسية.","«الأنماط» ليس اسمًا لصفوف الجدول ولا لأعمدته؛ وإنما يقصد به تكرار الخواص المتشابهة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (20%)"}],"at":"2026-10-18T03:32:48.240Z"}'::jsonb),
('mcq', 2, 3, 'العناصر الموجودة في مجموعة واحدة (عمود واحد) لها خواص فيزيائية وكيميائية متشابهة، وهذا أساس ترتيبها في العمود نفسه.', '["كتل عناصر المجموعة الواحدة مختلفة؛ والذي يجمعها هو تشابه الخواص.","الصف الأفقي الواحد يمثل دورة وليس مجموعة؛ أما المجموعة فعمود رأسي.","ليست كل عناصر المجموعة غازات؛ فالعناصر توجد في حالات فيزيائية مختلفة، والمجموعة تجمع العناصر المتشابهة في الخواص.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (17%)"}],"at":"2026-10-18T03:32:48.240Z"}'::jsonb),
('mcq', 3, 0, 'سُمّي الجدول دوريًّا لأن نمط الخواص المتشابهة بين العناصر يتكرر من دورة إلى أخرى.', '["","عدد العناصر ليس سبب التسمية؛ فالتسمية تعود إلى تكرار نمط الخواص لا إلى تساوي أعداد العناصر.","ترتيب اكتشاف العناصر لا علاقة له بالتسمية؛ فالجدول رُتبت عناصره على أساس تشابه الخواص والكتل.","الذي يتكرر هو نمط الخواص المتشابهة وليس الكتل؛ فكتل العناصر مختلفة ولا تتكرر."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (21%)"}],"at":"2026-10-18T03:32:48.240Z"}'::jsonb),
('mcq', 4, 2, 'نظّم مندليف جميع العناصر المعروفة في زمنه في جدول كان تصنيفه قائمًا على التشابهات بين العناصر وكتلها.', '["الألوان والحالات الفيزيائية ليست أساس الترتيب، فالعناصر في المجموعة الواحدة قد تختلف في حالتها.","تاريخ الاكتشاف لم يكن معيار الترتيب في جدول مندليف.","","وفرة العناصر في القشرة الأرضية تتفاوت كثيرًا ولم تكن أساس ترتيب جدول مندليف."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (24%)"}],"at":"2026-10-18T03:32:48.240Z"}'::jsonb),
('mcq', 5, 3, 'تشابه الخواص الكيميائية يدل على أن هذه العناصر تنتمي إلى مجموعة واحدة (عمود واحد)، فعناصر المجموعة الواحدة لها خواص متشابهة.', '["الدورة صف أفقي، وعناصر الدورة الواحدة لا تتشابه في خواصها بالضرورة؛ فالتشابه يميز عناصر المجموعة الواحدة.","كتل هذه العناصر مختلفة؛ وتشابهها في الخواص ناتج عن وقوعها في المجموعة نفسها.","العناصر المتشابهة في الخواص توضع في عمود واحد وليس في عمودين.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (23%)"}],"at":"2026-10-18T03:32:48.240Z"}'::jsonb),
('mcq', 6, 0, 'العناصر ذات الخواص المتشابهة توضع في المجموعة الواحدة؛ ولأن خواص العنصر الجديد تشبه خواص Na وK فمكانه المتوقع في العمود الذي يضمهما.', '["","وقوع العنصر في دورة Na لا يعني تشابه الخواص؛ فتشابه الخواص يميز عناصر المجموعة الواحدة، و K يقع في دورة أخرى.","ليس للجدول صف مستقل خارج الدورات يضم العناصر المتشابهة؛ فتنظيمه شبكة من دورات ومجموعات.","الكتلة وحدها لا تحدد موضع العنصر؛ فالترتيب قائم على تشابه الخواص مع الكتل معًا."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (15%)"}],"at":"2026-10-18T03:32:48.241Z"}'::jsonb),
('mcq', 7, 2, 'Li وNa يقعان في المجموعة نفسها (المجموعة 1)، وعناصر المجموعة الواحدة لها خواص متشابهة؛ أما Na وMg وCl فتشترك في الدورة 3 لكنها في مجموعات مختلفة.', '["Na وMg في الدورة نفسها لكنهما في مجموعتين مختلفتين، فلا يُتوقع تشابه خواصهما.","Na وCl في الدورة نفسها لكن مجموعتيهما مختلفتان (1 و17)، فخواصهما مختلفة.","","Li في المجموعة 1 وMg في المجموعة 2، فهما في مجموعتين ودورتين مختلفتين."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (23%)"}],"at":"2026-10-18T03:32:48.241Z"}'::jsonb),
('essay', 1, null::int, null, null, 'ينظم الجدول الدوري العناصر في شبكة؛ تسمى صفوفها الأفقية «الدورات»، وتسمى أعمدتها الرأسية «المجموعات» أو «العائلات». والعناصر الموجودة في المجموعة الواحدة لها خواص فيزيائية وكيميائية متشابهة.', '["العناصر مرتبة في شبكة","الصفوف الأفقية تسمى الدورات","الأعمدة تسمى المجموعات أو العائلات","عناصر المجموعة الواحدة لها خواص فيزيائية وكيميائية متشابهة"]'::jsonb, '[]'::jsonb, '[{"element":"ذكر أن العناصر مرتبة في شبكة","marks":1},{"element":"الصفوف الأفقية هي الدورات","marks":1},{"element":"الأعمدة هي المجموعات (العائلات)","marks":1},{"element":"تشابه خواص عناصر المجموعة الواحدة","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"وصف الشبكة وتحديد الدورات والمجموعات وذكر تشابه خواص عناصر المجموعة"},{"level":"2–3 درجات","description":"تحديد صحيح لبعض العناصر المطلوبة مع إغفال عنصر أو عنصرين"},{"level":"1 درجة","description":"ذكر عنصر واحد صحيح فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["الخلط بين الدورات والمجموعات (عدّ الدورات أعمدة)","عدم ذكر أن عناصر المجموعة الواحدة متشابهة الخواص","القول إن العناصر في الدورة الواحدة هي المتشابهة"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (14%)"}],"at":"2026-10-18T03:32:48.241Z"}'::jsonb),
('essay', 2, null::int, null, null, 'سُمّي الجدول دوريًّا لأن نمط الخواص المتشابهة بين العناصر يتكرر من دورة إلى أخرى. أما مندليف فقد رتّب جميع العناصر المعروفة في وقته على أساس التشابهات بين العناصر وكتلها، ويُعدّ جدوله النسخة الأولى لما سُمّي بعد ذلك الجدول الدوري.', '["نمط الخواص المتشابهة يتكرر","التكرار يحدث من دورة إلى أخرى","مندليف رتّب العناصر على أساس تشابهاتها","ورتّبها أيضًا على أساس كتلها"]'::jsonb, '[]'::jsonb, '[{"element":"تكرار نمط الخواص المتشابهة","marks":1},{"element":"التكرار من دورة إلى أخرى","marks":1},{"element":"الترتيب على أساس التشابهات","marks":1},{"element":"الترتيب على أساس الكتل","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"تفسير صحيح للتسمية وذكر أساسي الترتيب: التشابهات والكتل"},{"level":"2–3 درجات","description":"تفسير صحيح للتسمية مع ذكر أحد أساسي الترتيب، أو العكس"},{"level":"1 درجة","description":"ذكر عنصر صحيح واحد فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["القول إن الاسم يعود إلى اكتشاف العناصر على فترات","ذكر الكتل فقط أو التشابهات فقط في أساس الترتيب","القول إن مندليف رتّب العناصر بحسب ألوانها"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (24%)"}],"at":"2026-10-18T03:32:48.241Z"}'::jsonb),
('essay', 3, null::int, null, null, 'العنصر الأقرب إلى Na في خواصه هو Li؛ لأنه يقع في المجموعة نفسها (المجموعة 1)، وعناصر المجموعة الواحدة لها خواص فيزيائية وكيميائية متشابهة. أما Mg فيشترك مع Na في الدورة (الصف الأفقي) فقط، وهو في مجموعة مختلفة؛ ووجود العنصرين في دورة واحدة لا يعني تشابه خواصهما.', '["اختيار Li","Li وNa في المجموعة نفسها","عناصر المجموعة الواحدة متشابهة الخواص","Mg مع Na في الدورة نفسها لكن في مجموعة مختلفة فلا يُتوقع تشابه"]'::jsonb, '[]'::jsonb, '[{"element":"اختيار Li","marks":1},{"element":"ربط الاختيار بوقوع Li وNa في مجموعة واحدة وتشابه خواص المجموعة","marks":2},{"element":"بيان أن Mg مع Na في الدورة نفسها فقط ولا يُتوقع التشابه","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"اختيار Li مع تفسير بالمجموعة وتوضيح سبب استبعاد Mg"},{"level":"2–3 درجات","description":"اختيار Li مع تفسير بالمجموعة دون توضيح سبب استبعاد Mg"},{"level":"1 درجة","description":"اختيار Li دون تفسير"},{"level":"صفر","description":"اختيار Mg أو إجابة خاطئة أو لا إجابة"}]'::jsonb, '["اختيار Mg لأنه في الدورة نفسها مع Na","الخلط بين الصف الأفقي (الدورة) والعمود (المجموعة)","الاختيار الصحيح دون تعليل"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (15%)"}],"at":"2026-10-18T03:32:48.242Z"}'::jsonb)
