('mcq', 1, 'عند تكوين مركبات مختلفة من اتحاد العناصر نفسها، تكون النسبة بين كتل أحد العناصر التي تتحد مع كتلة ثابتة من عنصر آخر، وفق قانون النسب المتضاعفة:', null, '["نسبة ثابتة في جميع المركبات","نسبة كسرية غير منتظمة","نسبة عددية بسيطة وصحيحة","نسبة تساوي 1:1 دائمًا"]'::jsonb, 'تذكر', 'تذكر نص القانون', 'سهل', 'الكتاب ص 63 — قانون النسب المتضاعفة'),
('mcq', 2, 'يتكون الماء H₂O وفوق أكسيد الهيدروجين H₂O₂ من العنصرين نفسيهما. لماذا يوضح هذان المركبان قانون النسب المتضاعفة؟', null, '["لأن كتلة الأكسجين المتحدة مع كتلة ثابتة من الهيدروجين في H₂O₂ ضعف كتلته في H₂O","لأن لهما الخواص نفسها بسبب تكوّنهما من العنصرين نفسيهما","لأن كتلة H₂O₂ تساوي ضعف كتلة H₂O","لأن نسبة الهيدروجين إلى الأكسجين فيهما واحدة"]'::jsonb, 'فهم', 'تفسير مثال', 'متوسط', 'الكتاب ص 63 — الماء وفوق أكسيد الهيدروجين'),
('mcq', 3, 'أيّ أزواج المواد الآتية يوضح قانون النسب المتضاعفة؟', null, '["عينتان من كلوريد الصوديوم إحداهما من ماء البحر والأخرى من منجم","عينتان من الماء إحداهما من مطر والأخرى من بئر","الماء H₂O وكلوريد الصوديوم NaCl","أول أكسيد الكربون CO وثاني أكسيد الكربون CO₂"]'::jsonb, 'فهم', 'تمييز مثال على القانون', 'متوسط', 'الكتاب ص 63، 71 — قانون النسب المتضاعفة'),
('mcq', 4, 'ما الفرق بين قانون النسب الثابتة وقانون النسب المتضاعفة؟', null, '["الثابتة تخص المركبات المختلفة، والمتضاعفة تخص المركب الواحد","الثابتة: للمركب نفسه نسب كتلية ثابتة دائمًا، والمتضاعفة: مقارنة مركبات مختلفة من العناصر نفسها","الثابتة تقرر أن كتلة المركب أكبر من مجموع كتل عناصره، والمتضاعفة أنها أقل منه","لا فرق بينهما؛ فهما صيغتان مختلفتان للقانون نفسه"]'::jsonb, 'فهم', 'مقارنة قانونين', 'متوسط', 'الكتاب ص 61، 63 — قانونا النسب الثابتة والمتضاعفة'),
('mcq', 5, 'يبيّن الجدول النسبة المئوية بالكتلة لعنصري النحاس والكلور في مركبين مختلفين. ما نسبة (كتلة Cu ÷ كتلة Cl) في المركب I إلى نظيرتها في المركب II؟', '{"headers":["المركب","Cu (%)","Cl (%)"],"rows":[["I","64.20","35.80"],["II","47.27","52.73"]]}'::jsonb, '["1.36:1","1:2","2:1","0.68:1"]'::jsonb, 'تطبيق', 'حساب نسبة كتلية', 'صعب', 'الكتاب ص 63 — مركبات النحاس والكلور'),
('mcq', 6, 'يتحد النيتروجين مع الأكسجين لتكوين المركبين X وY. يحتوي X على 28.0 g نيتروجين لكل 16.0 g أكسجين، ويحتوي Y على 14.0 g نيتروجين لكل 32.0 g أكسجين. ما نسبة كتلة النيتروجين في X إلى كتلته في Y عند كتلة ثابتة من الأكسجين؟', null, '["2:1","4:1","1:4","1:2"]'::jsonb, 'تطبيق', 'تثبيت كتلة عنصر وحساب النسبة', 'صعب', 'الكتاب ص 63 — قانون النسب المتضاعفة'),
('mcq', 7, 'حُلّلت عينتان من مركبين يتكوّنان من الحديد والأكسجين فكانت النتائج كما في الجدول. أيّ العبارات الآتية تصف العينتين وصفًا صحيحًا؟', '{"headers":["العينة","كتلة Fe (g)","كتلة O (g)"],"rows":[["I","52.46","22.54"],["II","43.53","12.47"]]}'::jsonb, '["مركبان مختلفان؛ لأن نسبة كتلتي الحديد المتحدة مع كتلة ثابتة من الأكسجين 3:2 تقريبًا","مركب واحد؛ لأنهما يتكونان من العنصرين نفسيهما","مركبان مختلفان لكنهما لا يخضعان لقانون النسب المتضاعفة","مركب واحد؛ لأن مجموع كتلتي العنصرين فيهما متقارب"]'::jsonb, 'تحليل', 'تحليل بيانات مركبين', 'صعب', 'الكتاب ص 64 — التقويم (السؤال 28)'),
('essay', 1, 'اكتب نص قانون النسب المتضاعفة بكلماتك، ثم اشرح كيف يوضحه مثال الماء H₂O وفوق أكسيد الهيدروجين H₂O₂.', null, null, 'فهم', 'نص القانون وتفسير مثال', 'متوسط', 'الكتاب ص 63 — قانون النسب المتضاعفة'),
('essay', 2, 'يتكوّن المركبان I وII من الكربون والأكسجين. حُلّلت عينة من المركب I فوُجد أنها تحتوي على 3.00 g كربون و4.00 g أكسجين، وعينة من المركب II تحتوي على 6.00 g كربون و16.0 g أكسجين. بيّن بالحساب أن المركبين يخضعان لقانون النسب المتضاعفة.', null, null, 'تطبيق', 'حل مسألة وإثبات القانون', 'متوسط', 'الكتاب ص 63، 71 — قانون النسب المتضاعفة'),
('essay', 3, 'حُلّلت عينتان: العينة X تحتوي على 79.9% نحاس و20.1% أكسجين بالكتلة، والعينة Y تحتوي على 88.8% نحاس و11.2% أكسجين. قال طالب: «العينتان من المركب نفسه لأن كلتيهما نحاس وأكسجين». قيّم قول الطالب بالحساب، واذكر القانون الذي تخضع له العينتان.', null, null, 'تقويم', 'تقويم ادعاء بالحساب', 'صعب', 'الكتاب ص 63، 64 — قانون النسب المتضاعفة')
) as v(type, number, stem, stimulus, options, tl, qk, diff, src)
