from (values
('mcq', 1, 2, 'ينص قانون النسب المتضاعفة على أن النسبة بين كتل أحد العناصر المتحدة مع كتلة ثابتة من عنصر آخر هي نسبة عددية بسيطة وصحيحة، مثل 2:1 أو 3:2.', '["النسبة الثابتة هي ما ينص عليه قانون النسب الثابتة للمركب الواحد؛ أما المركبات المختلفة فتختلف نسبها.","النسبة في القانون عددية بسيطة وصحيحة وليست كسرية غير منتظمة.","","النسبة لا تساوي 1:1 دائمًا؛ فقد تكون 2:1 أو 3:2 أو غيرهما من النسب البسيطة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (15%)"}],"at":"2026-10-18T03:32:48.243Z"}'::jsonb),
('mcq', 2, 0, 'في H₂O ذرتا هيدروجين وذرة أكسجين، وفي H₂O₂ ذرتا هيدروجين وذرتا أكسجين؛ فكتلة الأكسجين مع كتلة ثابتة من الهيدروجين في H₂O₂ ضعفها في H₂O، أي بنسبة 1:2 وهي نسبة عددية بسيطة.', '["","المركبان مختلفان في خواصهما رغم تكوّنهما من العنصرين نفسيهما، لاختلاف نسبة اتحاد العنصرين.","لا يعتمد القانون على كتلتي المركبين، بل على نسبة كتل أحد العنصرين المتحدة مع كتلة ثابتة من العنصر الآخر.","نسبة الهيدروجين إلى الأكسجين مختلفة في المركبين؛ ولو كانت واحدة لكانا المركب نفسه."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (38%)"}],"at":"2026-10-18T03:32:48.243Z"}'::jsonb),
('mcq', 3, 3, 'CO وCO₂ مركبان مختلفان من العنصرين نفسيهما (الكربون والأكسجين)، وتكون نسبة كتلتي الأكسجين المتحدتين مع كتلة ثابتة من الكربون فيهما عددية بسيطة (1:2)؛ لذلك يوضحان قانون النسب المتضاعفة.', '["العينتان من المركب نفسه، ونسبهما الكتلية ثابتة؛ وهذا ما يوضحه قانون النسب الثابتة.","العينتان من المركب نفسه، فتتطابق نسبهما الكتلية؛ وهذا مثال على قانون النسب الثابتة.","المركبان مكوّنان من عناصر مختلفة؛ والقانون يتطلب مركبين من العناصر نفسها.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (27%)"}],"at":"2026-10-18T03:32:48.243Z"}'::jsonb),
('mcq', 4, 1, 'قانون النسب الثابتة يتعلق بالمركب الواحد الذي تتحد عناصره دائمًا بنسب كتلية ثابتة، أما قانون النسب المتضاعفة فيقارن مركبات مختلفة من العناصر نفسها فتكون النسبة بين كتل أحد العناصر المتحدة مع كتلة ثابتة من الآخر عددية بسيطة.', '["العكس هو الصحيح؛ فالنسب الثابتة تخص المركب الواحد، والمتضاعفة تقارن بين مركبات مختلفة.","","كتلة المركب تساوي مجموع كتل عناصره المكونة له، وليست أكبر أو أقل منه.","القانونان مختلفان؛ أحدهما يتعلق بمركب واحد والآخر بمقارنة مركبات مختلفة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (27%)"}],"at":"2026-10-18T03:32:48.243Z"}'::jsonb),
('mcq', 5, 2, 'كتلة Cu لكل كتلة Cl في I تساوي 64.20 ÷ 35.80 = 1.793، وفي II تساوي 47.27 ÷ 52.73 = 0.8965؛ ونسبتهما 1.793 ÷ 0.8965 = 2.00، أي 2:1، وهي نسبة عددية بسيطة وصحيحة.', '["هذه نسبة النحاس المئوية فقط (64.20 ÷ 47.27)، دون تثبيت كتلة الكلور؛ والقانون يقارن عند كتلة ثابتة من أحد العنصرين.","هذه النسبة مقلوبة؛ فالمركب I هو الأعلى في نسبة Cu إلى Cl، فنسبته إلى المركب II أكبر من 1.","","هذه نسبة الكلور المئوية فقط (35.80 ÷ 52.73)، دون تثبيت كتلة النحاس أو الكلور في المقارنة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (6%)"}],"at":"2026-10-18T03:32:48.244Z"}'::jsonb),
('mcq', 6, 1, 'عند تثبيت كتلة الأكسجين على 16.0 g تكون كتلة النيتروجين في X هي 28.0 g، وفي Y هي 14.0 g × 16.0 ÷ 32.0 = 7.0 g؛ فالنسبة 28.0 : 7.0 = 4:1.', '["هذه نسبة كتلتي النيتروجين الأصليتين (28.0 : 14.0) دون تثبيت كتلة الأكسجين، فكتلتا الأكسجين مختلفتان في المركبين.","","هذه النسبة مقلوبة؛ فالنيتروجين في X أكبر منه في Y عند كتلة الأكسجين نفسها.","هذه مقلوب النسبة الخام 2:1، وفيها خطآن: عدم تثبيت كتلة الأكسجين وقلب النسبة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (10%)"}],"at":"2026-10-18T03:32:48.244Z"}'::jsonb),
('mcq', 7, 0, 'كتلة Fe لكل 1 g أكسجين: 52.46 ÷ 22.54 = 2.327 في I و43.53 ÷ 12.47 = 3.491 في II؛ ونسبة II إلى I تساوي 1.50 أي 3:2. وهي نسبة عددية بسيطة، فالمركبان مختلفان ويخضعان لقانون النسب المتضاعفة.', '["","تكوّن عينتين من العنصرين نفسيهما لا يعني أنهما المركب نفسه؛ فالمركب الواحد له نسب كتلية ثابتة، وهنا النسبة بين Fe وO مختلفة.","المركبان مختلفان من العنصرين نفسيهما ونسبتهما عددية بسيطة (3:2)، فهما يخضعان للقانون.","مجموع الكتلتين (75.00 g و56.00 g) لا يحدد هوية المركب؛ فالمعيار هو نسبة العنصرين في كل عينة، وهي مختلفة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (6%)"}],"at":"2026-10-18T03:32:48.244Z"}'::jsonb),
('essay', 1, null::int, null, null, 'ينص القانون على أنه عند تكوين مركبات مختلفة من اتحاد العناصر نفسها، فإن النسبة بين كتل أحد العناصر التي تتحد مع كتلة ثابتة من عنصر آخر هي نسبة عددية بسيطة وصحيحة. والماء وفوق أكسيد الهيدروجين مركبان من الهيدروجين والأكسجين: الماء من ذرتي هيدروجين وذرة أكسجين، وفوق أكسيد الهيدروجين من ذرتي هيدروجين وذرتي أكسجين؛ فمع كتلة ثابتة من الهيدروجين تكون كتلة الأكسجين في فوق أكسيد الهيدروجين ضعف كتلته في الماء، أي بنسبة 1:2 وهي نسبة عددية بسيطة وصحيحة.', '["مركبات مختلفة من العناصر نفسها","النسبة بين كتل أحد العناصر المتحدة مع كتلة ثابتة من عنصر آخر","النسبة عددية بسيطة وصحيحة","الماء: ذرتا H وذرة O، وفوق الأكسيد: ذرتا H وذرتا O","كتلة O في H₂O₂ ضعف كتلته في H₂O (1:2) عند كتلة ثابتة من H"]'::jsonb, '[]'::jsonb, '[{"element":"نص القانون: مركبات مختلفة من العناصر نفسها وكتلة ثابتة من أحد العنصرين","marks":1},{"element":"النسبة عددية بسيطة وصحيحة","marks":1},{"element":"تحديد تركيب H₂O وH₂O₂","marks":1},{"element":"نسبة كتلتي الأكسجين 1:2 عند كتلة ثابتة من الهيدروجين","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"نص كامل للقانون وتفسير صحيح بالمثال مع النسبة 1:2"},{"level":"2–3 درجات","description":"نص صحيح مع نقص في تفسير المثال، أو العكس"},{"level":"1 درجة","description":"ذكر جزء من النص فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["الخلط بين قانون النسب المتضاعفة وقانون النسب الثابتة","عدم تثبيت كتلة أحد العنصرين عند المقارنة","عكس النسبة (2:1 بدل 1:2) دون تحديد أي المركبين يُذكر أولًا"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (38%)"}],"at":"2026-10-18T03:32:48.245Z"}'::jsonb),
('essay', 2, null::int, null, null, 'نثبّت كتلة الكربون عند 1.00 g. في المركب I: كتلة الأكسجين لكل 1.00 g كربون = 4.00 ÷ 3.00 = 1.33 g. في المركب II: كتلة الأكسجين لكل 1.00 g كربون = 16.0 ÷ 6.00 = 2.67 g. النسبة بين كتلتي الأكسجين = 1.33 : 2.67 = 1:2، وهي نسبة عددية بسيطة وصحيحة؛ فالمركبان يخضعان لقانون النسب المتضاعفة.', '["تثبيت كتلة الكربون","كتلة O لكل 1.00 g C في I تساوي 1.33 g","كتلة O لكل 1.00 g C في II تساوي 2.67 g","النسبة 1:2 عددية بسيطة وصحيحة"]'::jsonb, '["نثبّت كتلة الكربون عند 1.00 g","المركب I: 4.00 g ÷ 3.00 g = 1.33 g أكسجين لكل 1.00 g كربون","المركب II: 16.0 g ÷ 6.00 g = 2.67 g أكسجين لكل 1.00 g كربون","النسبة = 1.33 : 2.67 = 1:2","النسبة عددية بسيطة وصحيحة، فالقانون منطبق"]'::jsonb, '[{"element":"تثبيت كتلة الكربون وحساب كتلة الأكسجين في I","marks":1},{"element":"حساب كتلة الأكسجين في II عند الكتلة الثابتة نفسها","marks":1},{"element":"حساب النسبة 1:2","marks":1},{"element":"الاستنتاج أن النسبة عددية بسيطة وصحيحة","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"حل كامل بتثبيت كتلة الكربون وحساب النسبة 1:2 مع الاستنتاج"},{"level":"2–3 درجات","description":"تثبيت صحيح وحساب كتلتي الأكسجين مع خطأ في النسبة أو غياب الاستنتاج"},{"level":"1 درجة","description":"محاولة دون تثبيت كتلة أحد العنصرين"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["مقارنة كتلتي الأكسجين الأصليتين (4.00 و16.0) دون تثبيت كتلة الكربون","قسمة كتلة الكربون على كتلة الأكسجين بدل العكس دون ثبات في المقارنة","عدم ذكر الاستنتاج المتعلق بالقانون"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (11%)"}],"at":"2026-10-18T03:32:48.245Z"}'::jsonb),
('essay', 3, null::int, null, null, 'قول الطالب غير صحيح. المركب الواحد له نسب كتلية ثابتة، لكن النسبة المئوية للنحاس تختلف في العينتين (79.9% و88.8%)، فهما من مركبين مختلفين. نثبّت كتلة الأكسجين عند 1.00 g: في X كتلة النحاس = 79.9 ÷ 20.1 = 3.98 g، وفي Y = 88.8 ÷ 11.2 = 7.93 g. النسبة بين كتلتي النحاس = 3.98 : 7.93، أي تقريبًا 1:2، وهي نسبة عددية بسيطة وصحيحة؛ فالعينتان تخضعان لقانون النسب المتضاعفة.', '["رفض قول الطالب","النسب المئوية مختلفة فالمركبان مختلفان","كتلة Cu لكل 1.00 g O في X تساوي 3.98 g","كتلة Cu لكل 1.00 g O في Y تساوي 7.93 g","النسبة تقريبًا 1:2 فالقانون هو النسب المتضاعفة"]'::jsonb, '["المركب الواحد له نسب مئوية ثابتة، والنسبتان مختلفتان (79.9% و88.8%) فالمركبان مختلفان","نثبّت كتلة الأكسجين عند 1.00 g","العينة X: 79.9 ÷ 20.1 = 3.98 g نحاس","العينة Y: 88.8 ÷ 11.2 = 7.93 g نحاس","النسبة = 3.98 : 7.93 ≈ 1:2، فهي عددية بسيطة وصحيحة"]'::jsonb, '[{"element":"رفض قول الطالب مع تعليل باختلاف النسب المئوية","marks":1},{"element":"حساب كتلة النحاس لكل 1.00 g أكسجين في X","marks":1},{"element":"حساب كتلة النحاس لكل 1.00 g أكسجين في Y","marks":1},{"element":"النسبة 1:2 تقريبًا","marks":1},{"element":"ذكر قانون النسب المتضاعفة","marks":1}]'::jsonb, '[{"level":"5 درجات","description":"رفض القول بتعليل صحيح، وحسابات صحيحة للعينتين، والنسبة 1:2، وذكر القانون"},{"level":"3–4 درجات","description":"رفض القول وحسابات صحيحة مع نقص في النسبة أو في ذكر القانون"},{"level":"1–2 درجة","description":"رفض القول دون حساب، أو حساب جزئي"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["تأييد قول الطالب لأن العنصرين نفسهما","ذكر قانون النسب الثابتة بدل المتضاعفة","مقارنة النسبتين المئويتين للنحاس مباشرة (79.9 : 88.8) دون تثبيت كتلة الأكسجين"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (10%)"}],"at":"2026-10-18T03:32:48.246Z"}'::jsonb)
