('mcq', 2, 1, 'كلوريد الصوديوم NaCl مركب يتكون من عنصرين مختلفين هما الصوديوم والكلور متحدين كيميائيًّا، أما النحاس والذهب والأكسجين فعناصر.', '["النحاس Cu عنصر يتكون من نوع واحد من الذرات ولا يمكن تجزئته.","","الذهب Au عنصر ولا يمكن تجزئته إلى مواد أبسط.","الأكسجين عنصر يتكون من نوع واحد من الذرات، وليس مركبًا."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (11%)"}],"at":"2026-10-18T03:32:48.246Z"}'::jsonb),
('mcq', 3, 0, 'يمكن تجزئة المركب بطرائق كيميائية إلى العناصر المكونة له، أما العنصر فلا يمكن تجزئته إلى مواد أبسط بطرائق فيزيائية أو كيميائية.', '["","العكس هو الصحيح؛ فالعنصر لا يتجزأ إلى مواد أبسط، أما المركب فيمكن تحليله كيميائيًّا.","المركب هو الذي يتكون من عنصرين مختلفين أو أكثر، أما العنصر فمن نوع واحد من الذرات.","خواص المركب تختلف عن خواص العناصر المكونة له، وليست مماثلة لها."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (9%)"}],"at":"2026-10-18T03:32:48.247Z"}'::jsonb),
('mcq', 4, 2, 'اختلاف خواص KI (ملح أبيض) عن خواص K (فلز فضي) وI₂ (مادة صلبة سوداء) يدل على أن خواص المركب تختلف عن خواص العناصر المكونة له، بسبب التفاعل الكيميائي بينها.', '["لو احتفظ المركب بخواص عنصريه لبقي فضيًّا أو أسود، لكنه ملح أبيض.","لا يتبع لون المركب كتلة أحد عنصريه؛ فخواص المركب جديدة تمامًا.","","المخلوط تحتفظ مكوناته بخواصها، أما KI فخواصه جديدة لأن العنصرين اتحدا كيميائيًّا."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (9%)"}],"at":"2026-10-18T03:32:48.247Z"}'::jsonb),
('mcq', 5, 0, 'الأكسجين والذهب والحديد عناصر لا يمكن تجزئتها إلى مواد أبسط؛ أما الملح والسكر والماء فمركبات.', '["","الملح والسكر مركبان، وفي هذه المجموعة عنصر واحد فقط هو الذهب.","الماء والملح والسكر جميعها مركبات وليست عناصر.","الماء مركب، ولذلك لا تتكون هذه المجموعة من عناصر فقط."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (11%)"}],"at":"2026-10-18T03:32:48.247Z"}'::jsonb),
('mcq', 6, 3, 'تجزئة الماء بالتيار الكهربائي (تغير كيميائي) إلى الهيدروجين والأكسجين تدل على أنه مركب مكوَّن من عنصرين متحدين كيميائيًّا.', '["العنصر لا يمكن تجزئته إلى مواد أبسط، أما الماء فقد تجزّأ إلى مادتين فهو مركب.","الماء مادة نقية وليس مخلوطًا؛ وقد تجزّأ بتغير كيميائي لا بفصل فيزيائي.","الهيدروجين والأكسجين عنصران لا يمكن تجزئتهما، وكونهما غازين لا يجعلهما مركبين.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (6%)"}],"at":"2026-10-18T03:32:48.248Z"}'::jsonb),
('mcq', 7, 1, 'X وZ تجزّأتا كيميائيًّا إلى مادتين مختلفتين فهما مركبان، أما Y فلا تتجزأ بأي طريقة فهي عنصر.', '["X تجزّأت إلى غازين مختلفين فلا يمكن أن تكون عنصرًا، كما أن Y لم تتجزأ فهي عنصر لا مركب.","","Z تجزّأت بالتسخين إلى مادتين مختلفتين فهي مركب، وY لم تتجزأ فهي عنصر لا مركب.","X تجزّأت إلى مادتين مختلفتين فهي مركب لا عنصر."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (9%)"}],"at":"2026-10-18T03:32:48.248Z"}'::jsonb),
('essay', 1, null::int, null, null, 'العنصر مادة كيميائية نقية لا يمكن تجزئتها إلى أجزاء أصغر منها بطرائق فيزيائية أو كيميائية، مثل النحاس Cu والأكسجين O والذهب Au. أما المركب فيتكون من عنصرين مختلفين أو أكثر متحدين كيميائيًّا، ويمكن تجزئته إلى مواد أبسط (عناصره) بطرائق كيميائية كالتحليل الكهربائي، مثل ملح الطعام NaCl والماء H₂O.', '["تعريف العنصر","تعريف المركب: عنصران أو أكثر متحدان كيميائيًّا","العنصر لا يتجزأ والمركب يتجزأ كيميائيًّا إلى عناصره","مثال صحيح للعنصر ومثال صحيح للمركب"]'::jsonb, '[]'::jsonb, '[{"element":"تعريف العنصر","marks":1},{"element":"تعريف المركب","marks":1},{"element":"المقارنة في إمكانية التجزئة","marks":1},{"element":"مثالان صحيحان (عنصر ومركب)","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"تعريفان صحيحان ومقارنة التجزئة ومثالان صحيحان"},{"level":"2–3 درجات","description":"ذكر معظم العناصر المطلوبة مع نقص في واحد أو اثنين"},{"level":"1 درجة","description":"ذكر عنصر واحد صحيح فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["القول إن العنصر مزيج من مادتين أو أكثر","عدّ الماء أو الملح عنصرًا","القول إن المركب لا يمكن تجزئته"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (6%)"}],"at":"2026-10-18T03:32:48.248Z"}'::jsonb),
('essay', 2, null::int, null, null, 'يتكون يوديد البوتاسيوم KI من البوتاسيوم K وهو فلز فضي، واليود I₂ وهو مادة صلبة سوداء (يعطي بخارًا بنفسجيًّا عند تسخينه)، أما KI نفسه فملح أبيض؛ أي أن خواصه تختلف عن خواص عنصريه. ويعود هذا الاختلاف إلى التفاعل الكيميائي بين العنصرين واتحادهما لتكوين مادة جديدة.', '["البوتاسيوم فلز فضي","اليود مادة صلبة سوداء","KI ملح أبيض","السبب: التفاعل الكيميائي بين العنصرين"]'::jsonb, '[]'::jsonb, '[{"element":"وصف البوتاسيوم","marks":1},{"element":"وصف اليود","marks":1},{"element":"وصف KI والمقارنة","marks":1},{"element":"تعليل الاختلاف بالتفاعل الكيميائي","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"وصف العنصرين والمركب ومقارنتها وتعليل الاختلاف"},{"level":"2–3 درجات","description":"وصف صحيح مع غياب التعليل أو نقص في الوصف"},{"level":"1 درجة","description":"ذكر خاصية واحدة صحيحة فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["القول إن KI يحتفظ بخواص عنصريه","عدّ KI مخلوطًا من K وI₂","ذكر الأوصاف دون تعليل الاختلاف"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (9%)"}],"at":"2026-10-18T03:32:48.248Z"}'::jsonb),
('essay', 3, null::int, null, null, 'القول غير صحيح. فالمادة النقية قد تكون عنصرًا أو مركبًا، وكونها نقية لا يجعلها عنصرًا. ملح الطعام (كلوريد الصوديوم NaCl) مركب لأنه يتكون من عنصرين مختلفين هما الصوديوم والكلور متحدين كيميائيًّا، ويمكن تجزئته إلى مكوناته بطرائق كيميائية تتطلب طاقة كالحرارة أو الكهرباء. أما العنصر فلا يمكن تجزئته إلى مواد أبسط بطرائق فيزيائية أو كيميائية.', '["رفض القول","المادة النقية قد تكون عنصرًا أو مركبًا","NaCl مركب من عنصرين مختلفين (Na وCl) متحدين كيميائيًّا","يمكن تجزئته كيميائيًّا بينما العنصر لا يتجزأ"]'::jsonb, '[]'::jsonb, '[{"element":"رفض القول","marks":1},{"element":"بيان أن النقاء لا يعني أن المادة عنصر","marks":1},{"element":"تحديد أن NaCl مركب من Na وCl","marks":1},{"element":"التمييز بإمكانية التجزئة الكيميائية","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"رفض القول مع تعليل كامل: النقاء، تركيب NaCl، إمكانية التجزئة"},{"level":"2–3 درجات","description":"رفض القول مع تعليل جزئي"},{"level":"1 درجة","description":"رفض القول دون تعليل"},{"level":"صفر","description":"تأييد القول أو إجابة خاطئة أو لا إجابة"}]'::jsonb, '["الخلط بين المادة النقية والعنصر","عدّ NaCl عنصرًا لأنه يُكتب بصيغة واحدة","القول إن المركب لا يمكن تجزئته بأي طريقة"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (9%)"}],"at":"2026-10-18T03:32:48.249Z"}'::jsonb)
