('mcq', 2, 2, 'الصيغة الكيميائية لملح الطعام (كلوريد الصوديوم) هي NaCl، لأنه مكوَّن من ذرة واحدة من الصوديوم وذرة واحدة من الكلور.', '["هذه الصيغة تعني ذرتي صوديوم وذرة كلور، والملح يحتوي ذرة صوديوم واحدة.","هذه الصيغة تعني ذرة صوديوم وذرتي كلور، والملح يحتوي ذرة كلور واحدة.","","KCl صيغة كلوريد البوتاسيوم وليست صيغة ملح الطعام."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (33%)"}],"at":"2026-10-18T03:32:48.249Z"}'::jsonb),
('mcq', 3, 1, 'تدل الصيغة NaCl على ذرة واحدة من الصوديوم Na وذرة واحدة من الكلور Cl؛ فغياب الرقم السفلي يعني ذرة واحدة من العنصر.', '["لو كانت ذرتا صوديوم لكُتب الرقم 2 أسفل رمز Na، ولا يوجد في الصيغة.","","لو كانت ذرتا كلور لكُتب الرقم 2 أسفل رمز Cl، ولا يوجد في الصيغة.","الرمز Na يدل على الصوديوم وليس النيتروجين الذي رمزه N."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (25%)"}],"at":"2026-10-18T03:32:48.250Z"}'::jsonb),
('mcq', 4, 3, 'ملح الطعام (كلوريد الصوديوم NaCl) مكوّن من العنصرين الصوديوم Na والكلور Cl.', '["الأكسجين لا يدخل في تركيب ملح الطعام؛ فالعنصر الثاني هو الكلور.","البوتاسيوم يدخل في كلوريد البوتاسيوم لا في ملح الطعام؛ فالعنصر الأول هو الصوديوم.","الهيدروجين لا يدخل في ملح الطعام، والعنصر الأول فيه هو الصوديوم.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (33%)"}],"at":"2026-10-18T03:32:48.250Z"}'::jsonb),
('mcq', 5, 2, 'كلوريد الصوديوم صيغته NaCl (ذرة Na وذرة Cl)، والماء صيغته H₂O (ذرتا هيدروجين وذرة أكسجين)؛ وهذا الزوج الوحيد الذي صيغتاه صحيحتان.', '["الصيغتان خاطئتان: Na₂Cl تعني ذرتي صوديوم، وHO₂ تعني ذرة هيدروجين وذرتي أكسجين.","صيغة الماء صحيحة لكن NaCl₂ خاطئة؛ فملح الطعام فيه ذرة كلور واحدة.","","صيغة الملح صحيحة لكن HO خاطئة؛ فالماء فيه ذرتا هيدروجين وليس ذرة واحدة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (11%)"}],"at":"2026-10-18T03:32:48.250Z"}'::jsonb),
('mcq', 6, 0, 'عدم وجود رقم سفلي بعد الرمز يعني وجود ذرة واحدة من ذلك العنصر؛ فملح الطعام مكوّن من ذرة Na وذرة Cl، بخلاف الماء H₂O الذي يشير الرقم 2 فيه إلى ذرتي هيدروجين.', '["","عدد الذرات معروف؛ فعدم كتابة الرقم يعني ذرة واحدة من العنصر.","الصيغة مكتملة؛ فالرقم لا يُكتب إلا إذا زاد عدد الذرات عن واحدة.","ذرتان من العنصر تُكتبان برقم سفلي 2 كما في H₂O، ولا يوجد ذلك في NaCl."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (29%)"}],"at":"2026-10-18T03:32:48.250Z"}'::jsonb),
('mcq', 7, 3, 'ملح الطعام مركب وليس عنصرًا؛ اسمه كلوريد الصوديوم وصيغته NaCl، ويتكون من ذرة صوديوم وذرة كلور.', '["العبارة خاطئة؛ فالصوديوم Na عنصر، أما ملح الطعام فمركب يحتوي أيضًا على الكلور.","ملح الطعام ليس عنصر الكلور؛ فهو مركب يتكون من الصوديوم والكلور معًا.","الاسم والصيغة خاطئان؛ فملح الطعام لا يحتوي على الكبريت.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (18%)"}],"at":"2026-10-18T03:32:48.250Z"}'::jsonb),
('essay', 1, null::int, null, null, 'الاسم العلمي لملح الطعام هو كلوريد الصوديوم، وصيغته الكيميائية NaCl، ويتكون من العنصرين الصوديوم Na والكلور Cl.', '["الاسم العلمي: كلوريد الصوديوم","الصيغة الكيميائية: NaCl","العنصران: الصوديوم والكلور"]'::jsonb, '[]'::jsonb, '[{"element":"الاسم العلمي","marks":1},{"element":"الصيغة الكيميائية","marks":1},{"element":"العنصران المكوّنان","marks":1}]'::jsonb, '[{"level":"3 درجات","description":"ذكر الاسم والصيغة والعنصرين ذكرًا صحيحًا"},{"level":"2 درجتان","description":"ذكر اثنين من الثلاثة ذكرًا صحيحًا"},{"level":"1 درجة","description":"ذكر واحد من الثلاثة ذكرًا صحيحًا"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["كتابة الصيغة NaCl₂ أو Na₂Cl","الخلط مع كلوريد البوتاسيوم","ذكر الاسم دون العنصرين"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (3 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (36%)"}],"at":"2026-10-18T03:32:48.251Z"}'::jsonb),
('essay', 2, null::int, null, null, 'يدل الرقم السفلي في الصيغة على عدد ذرات العنصر الذي قبله في المركب، وعدم كتابة رقم يعني وجود ذرة واحدة من العنصر. لذلك تدل NaCl على أن ملح الطعام مكوّن من ذرة واحدة من الصوديوم وذرة واحدة من الكلور. أما الرقم 2 في H₂O فيشير إلى أن ذرتين من الهيدروجين تتحدان مع ذرة واحدة من الأكسجين.', '["الرقم السفلي يدل على عدد الذرات","غياب الرقم يعني ذرة واحدة","NaCl: ذرة Na وذرة Cl","H₂O: ذرتا هيدروجين وذرة أكسجين"]'::jsonb, '[]'::jsonb, '[{"element":"معنى الرقم السفلي","marks":1},{"element":"غياب الرقم يعني ذرة واحدة","marks":1},{"element":"تفسير NaCl","marks":1},{"element":"تفسير H₂O","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"تفسير كامل لمعنى الرقم السفلي ولكلتا الصيغتين"},{"level":"2–3 درجات","description":"تفسير صحيح لإحدى الصيغتين مع نقص في الأخرى أو في معنى الرقم"},{"level":"1 درجة","description":"ذكر عنصر واحد صحيح فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["القول إن غياب الرقم يعني صفر ذرات أو عددًا غير معروف","الاعتقاد أن الرقم 2 يخص ذرة الأكسجين","عدّ H₂O ذرتين من الأكسجين"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (29%)"}],"at":"2026-10-18T03:32:48.251Z"}'::jsonb),
('essay', 3, null::int, null, null, 'في العبارة ثلاثة أخطاء: (1) اسم ملح الطعام الصحيح كلوريد الصوديوم وليس كلوريد البوتاسيوم؛ (2) صيغته الصحيحة NaCl وليست KCl؛ (3) يتكون من ذرة واحدة من الصوديوم وذرة واحدة من الكلور، وليس من ذرتين من البوتاسيوم وذرة كلور. فالعنصران المكونان له هما الصوديوم والكلور.', '["الاسم الصحيح: كلوريد الصوديوم","الصيغة الصحيحة: NaCl","التركيب: ذرة Na وذرة Cl","العنصران: الصوديوم والكلور وليس البوتاسيوم"]'::jsonb, '[]'::jsonb, '[{"element":"تصحيح الاسم","marks":1},{"element":"تصحيح الصيغة","marks":1},{"element":"تصحيح عدد الذرات","marks":1},{"element":"تحديد العنصرين الصحيحين","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"اكتشاف الأخطاء الثلاثة وتصحيحها مع ذكر العنصرين الصحيحين"},{"level":"2–3 درجات","description":"تصحيح اثنين أو ثلاثة من العناصر المطلوبة"},{"level":"1 درجة","description":"تصحيح عنصر واحد فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["تصحيح الاسم دون الصيغة أو عدد الذرات","كتابة الصيغة Na₂Cl بدل NaCl","عدم الانتباه إلى أن ذرة الكلور واحدة وكذلك ذرة الصوديوم"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (18%)"}],"at":"2026-10-18T03:32:48.251Z"}'::jsonb)
