('mcq', 1, 1, 'يُحلَّل الماء إلى الهيدروجين والأكسجين بعملية تسمى التحليل الكهربائي، يقوم فيها التيار الكهربائي بتفكيك الماء.', '["الترشيح طريقة فيزيائية لفصل المخاليط ولا تفكك المركبات إلى عناصرها.","","التقطير طريقة فيزيائية لفصل المخاليط ولا تفكك الماء إلى عنصريه.","التبخر تغير فيزيائي تتحول فيه حالة الماء إلى بخار دون أن يتفكك إلى عنصريه."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (14%)"}],"at":"2026-10-18T03:32:48.252Z"}'::jsonb),
('mcq', 2, 0, 'يتجمع غاز الهيدروجين H₂ عند الكاثود (المهبط)، ويتجمع غاز الأكسجين O₂ عند الأنود (المصعد).', '["","الأكسجين يتجمع عند الأنود (المصعد) وليس عند الكاثود.","بخار الماء لا يُعدّ ناتجًا من تحليل الماء؛ فالناتجان هما الهيدروجين والأكسجين.","النيتروجين لا يدخل في تركيب الماء فلا يتكون في التحليل الكهربائي له."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (19%)"}],"at":"2026-10-18T03:32:48.252Z"}'::jsonb),
('mcq', 3, 3, 'الماء H₂O يتكون من ذرتي هيدروجين وذرة أكسجين، فيكون حجم غاز الهيدروجين H₂ الناتج ضعف حجم غاز الأكسجين O₂.', '["الاختلاف في الحجم سببه نسبة ذرات العنصرين في الماء وليس خفة الغاز.","حجم القطبين لا علاقة له بحجم الغازين؛ فالنسبة 2:1 مصدرها تركيب الماء.","هذا التركيب معكوس؛ فلو كان هذا تركيب الماء لكان الأكسجين هو الأكبر حجمًا.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (22%)"}],"at":"2026-10-18T03:32:48.252Z"}'::jsonb),
('mcq', 4, 2, 'المركبات المستقرة كالماء تحتاج إلى طاقة كالحرارة أو الكهرباء لتتفكك إلى عناصرها؛ ويوفر التيار الكهربائي هذه الطاقة فيحلل الماء إلى الهيدروجين والأكسجين.', '["الهيدروجين والأكسجين ليسا غازين مذابين في الماء؛ بل هما عنصرا مركب الماء ويتكونان بتفكيكه.","التيار لا يبخّر الماء؛ والتبخر تغير فيزيائي لا ينتج عنصري الماء.","","التيار لا يضيف شيئًا إلى الماء، بل يفككه فيتكون الغازان من مادة الماء نفسها."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (19%)"}],"at":"2026-10-18T03:32:48.253Z"}'::jsonb),
('mcq', 5, 1, 'حجم الهيدروجين ضعف حجم الأكسجين؛ لذا حجم الأكسجين = 24 mL ÷ 2 = 12 mL.', '["هذا ضرب الحجم في 2 بدل قسمته، أي عكس النسبة؛ فالأكسجين هو الأقل حجمًا.","","هذا يفترض تساوي الحجمين، وهو خطأ؛ فحجم الهيدروجين ضعف حجم الأكسجين.","هذا ناتج قسمة 24 mL على 3، ولا تدل عليه النسبة 2:1."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (22%)"}],"at":"2026-10-18T03:32:48.253Z"}'::jsonb),
('mcq', 6, 3, 'يتجمع الهيدروجين عند الكاثود (القطب السالب) والأكسجين عند الأنود (القطب الموجب)؛ وهذا يتفق مع الحجمين لأن حجم الهيدروجين 20 mL ضعف حجم الأكسجين 10 mL.', '["العكس هو الصحيح؛ فالأكسجين يتجمع عند الأنود لا عند الكاثود، كما أن الأكبر حجمًا هو الهيدروجين.","الماء يتكون من الهيدروجين والأكسجين معًا، ولو كان الأنبوبان هيدروجين لما اختلف الحجمان.","التحليل الكهربائي لا ينتج بخار ماء؛ فالأنبوب أ يحتوي الهيدروجين.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (14%)"}],"at":"2026-10-18T03:32:48.253Z"}'::jsonb),
('mcq', 7, 2, 'ينتج عن تحليل الماء غازان هما الهيدروجين والأكسجين، وهما يختلفان كثيرًا عن الماء (غازان عديما اللون والرائحة ويتفاعلان بشدة مع عدة عناصر)؛ فتكوّن مادتين جديدتين يعني أن التغير كيميائي.', '["تغير الحالة الفيزيائية وحده تغير فيزيائي؛ أما الناتج هنا فمادتان جديدتان مختلفتان في تركيبهما عن الماء.","لا يعود الغازان إلى ماء بالتبريد وحده؛ فهما عنصران ناتجان عن تفكك الماء.","","تناقص حجم الماء لا يدل على تغير كيميائي، بينما هنا يتغير تركيب المادة إلى عنصرين."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (19%)"}],"at":"2026-10-18T03:32:48.253Z"}'::jsonb),
('essay', 1, null::int, null, null, 'التحليل الكهربائي عملية يقوم فيها التيار الكهربائي (من بطارية) بتحليل الماء H₂O إلى عنصريه. يوفر التيار الطاقة اللازمة لتفكيك مركب الماء المستقر، فينتج غاز الهيدروجين H₂ عند الكاثود (المهبط)، وغاز الأكسجين O₂ عند الأنود (المصعد). والتغير الحادث كيميائي؛ لأن المركب تفكك إلى عنصرين تختلف خواصهما عن خواص الماء.', '["التيار الكهربائي يحلل الماء إلى عنصريه","التيار يوفر الطاقة اللازمة للتفكيك","H₂ عند الكاثود","O₂ عند الأنود","التغير كيميائي لأن الناتجين يختلفان عن الماء"]'::jsonb, '[]'::jsonb, '[{"element":"تحليل الماء إلى عنصريه بالتيار","marks":1},{"element":"دور التيار: توفير الطاقة","marks":1},{"element":"الهيدروجين عند الكاثود","marks":1},{"element":"الأكسجين عند الأنود","marks":1},{"element":"تحديد التغير الكيميائي مع تعليل","marks":1}]'::jsonb, '[{"level":"5 درجات","description":"شرح كامل يشمل دور التيار والغازين وموضعيهما ونوع التغير"},{"level":"3–4 درجات","description":"شرح صحيح مع إغفال عنصر أو عنصرين"},{"level":"1–2 درجة","description":"ذكر عنصر أو عنصرين صحيحين فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["عكس موضع الغازين (الأكسجين عند الكاثود)","عدّ العملية فصلًا فيزيائيًّا","عدم ذكر دور التيار الكهربائي"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (19%)"}],"at":"2026-10-18T03:32:48.254Z"}'::jsonb),
('essay', 2, null::int, null, null, 'نسبة حجم الهيدروجين إلى الأكسجين 2:1، فإذا كان حجم الأكسجين V فحجم الهيدروجين 2V؛ والمجموع 3V = 45 mL، ومنه V = 15 mL. حجم الأكسجين 15 mL وحجم الهيدروجين 30 mL. وتفسير النسبة أن الماء يتكون من ذرتي هيدروجين وذرة أكسجين، فيكون حجم الهيدروجين ضعف حجم الأكسجين.', '["النسبة 2:1 بين حجمي H₂ وO₂","المجموع 3 أجزاء يساوي 45 mL","حجم O₂ يساوي 15 mL","حجم H₂ يساوي 30 mL","التفسير: ذرتا هيدروجين وذرة أكسجين في الماء"]'::jsonb, '["حجم الهيدروجين = 2 × حجم الأكسجين؛ نفرض حجم الأكسجين V","V + 2V = 45 mL، أي 3V = 45 mL","V = 45 mL ÷ 3 = 15 mL (الأكسجين)","حجم الهيدروجين = 2 × 15 mL = 30 mL","السبب: الماء من ذرتي هيدروجين وذرة أكسجين"]'::jsonb, '[{"element":"استعمال النسبة 2:1 بين الحجمين","marks":1},{"element":"حجم الأكسجين 15 mL","marks":1},{"element":"حجم الهيدروجين 30 mL","marks":1},{"element":"تفسير النسبة بتركيب الماء","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"حساب الحجمين حسابًا صحيحًا مع التفسير بتركيب الماء"},{"level":"2–3 درجات","description":"حساب صحيح لأحد الحجمين أو الحجمين دون التفسير"},{"level":"1 درجة","description":"ذكر النسبة 2:1 فقط دون حساب"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["قسمة 45 mL على 2 وعدّ الحجمين متساويين","عكس النسبة فيكون الأكسجين 30 mL","قسمة 45 mL على 2 ثم أخذ 2:1 من الناتج"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (21%)"}],"at":"2026-10-18T03:32:48.254Z"}'::jsonb),
('essay', 3, null::int, null, null, 'الماء مركب مستقر وهو سائل في درجات الحرارة العادية، أما الهيدروجين والأكسجين الناتجان عن تحليله فغازان عديما اللون والرائحة ويتفاعلان بشدة مع عدة عناصر؛ فخواصهما تختلف كثيرًا عن خواص الماء. ولا يمكن فصل الماء إلى عنصريه بالتبخير لأنه تغير فيزيائي يغيّر الحالة فقط ويبقى المركب ماءً؛ أما تجزئة المركبات إلى عناصرها فتتم بطرائق كيميائية وتحتاج إلى طاقة كالحرارة أو الكهرباء.', '["الماء مركب مستقر وسائل","الهيدروجين والأكسجين غازان عديما اللون والرائحة","يتفاعلان بشدة مع عدة عناصر","التبخير تغير فيزيائي لا يفكك المركب","تفكيك المركب يحتاج إلى طريقة كيميائية وطاقة"]'::jsonb, '[]'::jsonb, '[{"element":"وصف الماء","marks":1},{"element":"وصف الغازين الناتجين","marks":1},{"element":"بيان أن التبخير تغير فيزيائي لا يفكك الماء","marks":1},{"element":"الإشارة إلى أن تفكيك المركب يتطلب طريقة كيميائية وطاقة","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"مقارنة صحيحة بين الماء والغازين وتفسير صحيح لعجز الطريقة الفيزيائية"},{"level":"2–3 درجات","description":"مقارنة صحيحة دون تفسير كامل، أو العكس"},{"level":"1 درجة","description":"ذكر عنصر واحد صحيح فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["القول إن الغازين يشبهان الماء في خواصه","القول إن تبخير الماء ينتج الهيدروجين والأكسجين","عدم ذكر الحاجة إلى طاقة لتفكيك المركب"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (7%)"}],"at":"2026-10-18T03:32:48.254Z"}'::jsonb)
) as v(type, number, ci, ex, dn, ma, ae, ss, mk, rb, ce, ac)
join public.questions x on x.objective_id = (select id from public.objectives where code = 'K1-C2-L4-O05') and x.type = v.type and x.number = v.number
on conflict (question_id) do nothing;

