select (select id from public.objectives where code = 'K1-C2-L4-O06'), v.type, v.number, v.stem, v.stimulus::jsonb, v.options::jsonb, v.tl, v.qk, v.diff, v.src, 'generated', 'ai_generated'
from (values
('mcq', 1, 'تحتوي عينة كتلتها 50.0 g من مركب على 12.0 g من الكربون. ما النسبة المئوية بالكتلة للكربون في المركب؟', null, '["0.240%","76.0%","24.0%","417%"]'::jsonb, 'تطبيق', 'تطبيق قانون النسبة المئوية', 'سهل', 'الكتاب ص 61 — النسبة المئوية بالكتلة'),
('mcq', 2, 'يتفاعل 2.00 g من الهيدروجين كليًّا مع 16.0 g من الأكسجين فيتكوّن الماء. ما النسبة المئوية بالكتلة للهيدروجين في الماء الناتج؟', null, '["12.5%","88.9%","10.0%","11.1%"]'::jsonb, 'تطبيق', 'حساب نسبة مئوية بعد إيجاد كتلة المركب', 'متوسط', 'الكتاب ص 61، 62 — النسبة المئوية بالكتلة'),
('mcq', 3, 'حُلّلت عينة كتلتها 80.0 g من مركب فنتج 33.9 g كربون و5.20 g هيدروجين، وكانت بقية الكتلة أكسجين. ما النسبة المئوية بالكتلة للأكسجين في المركب؟', null, '["48.9%","51.1%","42.4%","6.50%"]'::jsonb, 'تطبيق', 'حساب نسبة عنصر ثالث بالفرق', 'متوسط', 'الكتاب ص 62 — الجدول 2-4'),
('mcq', 4, 'يحتوي أحد المركبات على 35.0% نيتروجين بالكتلة. ما كتلة النيتروجين في عينة من هذا المركب كتلتها 80.0 g؟', null, '["28.0 g","229 g","2.80 g","52.0 g"]'::jsonb, 'تطبيق', 'حساب كتلة عنصر من النسبة', 'سهل', 'الكتاب ص 61، 62 — النسبة المئوية بالكتلة'),
('mcq', 5, 'يتحد 6.54 g من الخارصين تمامًا مع 1.60 g من الأكسجين لتكوين أكسيد الخارصين. ما النسبة المئوية بالكتلة للأكسجين في أكسيد الخارصين؟', null, '["24.5%","80.3%","409%","19.7%"]'::jsonb, 'تطبيق', 'حساب نسبة مئوية من كتل المتفاعلات', 'متوسط', 'الكتاب ص 70، 71 — مسائل التقويم'),
('mcq', 6, 'حُلّلت ثلاث عينات فكانت كتل الكربون فيها كما في الجدول. أيّ العينات الآتية يُرجّح أنها من المركب نفسه؟', '{"headers":["العينة","كتلة العينة (g)","كتلة الكربون (g)"],"rows":[["A","36.0","12.0"],["B","54.0","18.0"],["C","75.0","30.0"]]}'::jsonb, '["A وC","A وB","B وC","A وB وC"]'::jsonb, 'تحليل', 'تحليل نسب مئوية لتحديد المركب', 'صعب', 'الكتاب ص 62 — مسائل تدريبية 22 و23'),
('mcq', 7, 'يبيّن الجدول كتلة الأكسجين وكتلة المركب في عينتين من مركبين مختلفين. أيّ العبارات الآتية صحيحة؟', '{"headers":["المركب","كتلة O (g)","كتلة العينة (g)"],"rows":[["P","32.0","84.0"],["Q","16.0","40.0"]]}'::jsonb, '["المركب Q أعلى نسبة مئوية بالكتلة للأكسجين؛ لأن نسبته 40.0% مقابل 38.1% في المركب P","المركب P أعلى نسبة مئوية بالكتلة للأكسجين؛ لأن كتلة الأكسجين فيه أكبر","المركبان متساويان في النسبة المئوية؛ لأن كلًّا منهما يحتوي على الأكسجين","لا يمكن المقارنة بينهما دون معرفة اسمي المركبين"]'::jsonb, 'تحليل', 'مقارنة نسب مئوية', 'صعب', 'الكتاب ص 71 — السؤال 73'),
('essay', 1, 'حُلّلت عينة كتلتها 50.0 g من مركب فوُجد أنها تحتوي على 18.0 g كربون و3.0 g هيدروجين و29.0 g أكسجين. احسب النسبة المئوية بالكتلة لكل عنصر، ثم تحقق من أن مجموعها 100%.', null, null, 'تطبيق', 'حل مسألة بالخطوات', 'متوسط', 'الكتاب ص 61، 62 — الجدول 2-4'),
('essay', 2, 'يحتوي السكر على 42.20% كربون و6.50% هيدروجين و51.30% أكسجين بالكتلة. احسب كتلة كل عنصر في عينة من السكر كتلتها 400.0 g، ثم تحقق من أن مجموع الكتل يساوي كتلة العينة.', null, null, 'تطبيق', 'حل مسألة عكسية بالخطوات', 'متوسط', 'الكتاب ص 62 — الجدول 2-4'),
('essay', 3, 'حُلّلت ثلاث عينات من مركبات النحاس والكلور: العينة 1 كتلتها 20.0 g وتحتوي على 12.84 g نحاس، والعينة 2 كتلتها 50.0 g وتحتوي على 32.1 g نحاس، والعينة 3 كتلتها 30.0 g وتحتوي على 14.18 g نحاس. احسب النسبة المئوية بالكتلة للنحاس في كل عينة، ثم حدّد أيّ العينات من المركب نفسه وأيّها من مركب مختلف، مفسّرًا إجابتك.', null, null, 'تحليل', 'تحليل عينات وتحديد المركب', 'صعب', 'الكتاب ص 61، 62 — قانون النسب الثابتة والنسبة المئوية بالكتلة')
) as v(type, number, stem, stimulus, options, tl, qk, diff, src)
