('mcq', 1, 2, 'النسبة المئوية بالكتلة = (كتلة العنصر ÷ كتلة المركب) × 100 = (12.0 g ÷ 50.0 g) × 100 = 24.0%.', '["هذه القيمة 0.240 دون ضرب الناتج في 100 للتعبير عنه بنسبة مئوية.","هذه نسبة بقية المركب (100% − 24.0%) وليست نسبة الكربون.","","هذه نتيجة قسمة كتلة المركب على كتلة العنصر (50.0 ÷ 12.0) أي قلب القانون."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (29%)"}],"at":"2026-10-18T03:32:48.255Z"}'::jsonb),
('mcq', 2, 3, 'كتلة الماء الناتج = 2.00 g + 16.0 g = 18.0 g؛ فالنسبة المئوية للهيدروجين = (2.00 g ÷ 18.0 g) × 100 = 11.1%.', '["هذه نتيجة قسمة كتلة الهيدروجين على كتلة الأكسجين فقط (2.00 ÷ 16.0)، والمطلوب القسمة على كتلة المركب.","هذه النسبة المئوية للأكسجين (16.0 ÷ 18.0) وليست للهيدروجين.","هذه نتيجة قسمة 2.00 على 20.0 أي إضافة كتلة الهيدروجين مرتين إلى كتلة المركب.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (23%)"}],"at":"2026-10-18T03:32:48.255Z"}'::jsonb),
('mcq', 3, 1, 'كتلة الأكسجين = 80.0 − 33.9 − 5.20 = 40.9 g؛ فالنسبة المئوية = (40.9 ÷ 80.0) × 100 = 51.1%.', '["هذه النسبة المئوية المجموعة للكربون والهيدروجين معًا (39.1 ÷ 80.0) وليست للأكسجين.","","هذه النسبة المئوية للكربون وحده (33.9 ÷ 80.0).","هذه النسبة المئوية للهيدروجين وحده (5.20 ÷ 80.0)."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (29%)"}],"at":"2026-10-18T03:32:48.256Z"}'::jsonb),
('mcq', 4, 0, 'كتلة العنصر = النسبة المئوية × كتلة المركب = 0.350 × 80.0 g = 28.0 g.', '["","هذه نتيجة قسمة 80.0 على 0.350، أي استعمال القانون بصورة معكوسة.","هذه نتيجة ضرب 80.0 في 0.0350 أي خطأ في تحويل النسبة المئوية إلى كسر.","هذه كتلة بقية المركب (80.0 − 28.0) وليست كتلة النيتروجين."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (19%)"}],"at":"2026-10-18T03:32:48.256Z"}'::jsonb),
('mcq', 5, 3, 'كتلة أكسيد الخارصين = 6.54 g + 1.60 g = 8.14 g؛ فالنسبة المئوية للأكسجين = (1.60 ÷ 8.14) × 100 = 19.7%.', '["هذه نتيجة قسمة كتلة الأكسجين على كتلة الخارصين فقط (1.60 ÷ 6.54)، والمطلوب القسمة على كتلة المركب.","هذه النسبة المئوية للخارصين (6.54 ÷ 8.14) وليست للأكسجين.","هذه نتيجة قسمة كتلة الخارصين على كتلة الأكسجين، أي قلب القانون.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (23%)"}],"at":"2026-10-18T03:32:48.256Z"}'::jsonb),
('mcq', 6, 1, 'النسبة المئوية للكربون في A تساوي (12.0 ÷ 36.0) × 100 = 33.3%، وفي B تساوي (18.0 ÷ 54.0) × 100 = 33.3%، وفي C تساوي (30.0 ÷ 75.0) × 100 = 40.0%؛ والعينات المتماثلة في النسب المئوية فقط هي المرجحة من المركب نفسه، أي A وB.', '["نسبة الكربون في A تساوي 33.3% وفي C تساوي 40.0% فهما مختلفتان.","","نسبة الكربون في B تساوي 33.3% وفي C تساوي 40.0% فهما مختلفتان.","العينة C نسبتها 40.0% تختلف عن نسبة A وB (33.3%)، فلا يمكن أن تكون الثلاث من المركب نفسه."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (13%)"}],"at":"2026-10-18T03:32:48.257Z"}'::jsonb),
('mcq', 7, 0, 'النسبة المئوية للأكسجين في P تساوي (32.0 ÷ 84.0) × 100 = 38.1%، وفي Q تساوي (16.0 ÷ 40.0) × 100 = 40.0%؛ فالمركب Q هو الأعلى نسبة رغم أن كتلة الأكسجين فيه أقل.', '["","كتلة الأكسجين وحدها لا تحدد النسبة المئوية؛ فيجب قسمتها على كتلة العينة، وعندها يكون P أقل نسبة (38.1%).","وجود الأكسجين في المركبين لا يعني تساوي النسبتين؛ فالنسبتان 38.1% و40.0%.","يمكن المقارنة بالحساب من كتلة الأكسجين وكتلة العينة دون معرفة الاسمين."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (13%)"}],"at":"2026-10-18T03:32:48.257Z"}'::jsonb),
('essay', 1, null::int, null, null, 'النسبة المئوية بالكتلة = (كتلة العنصر ÷ كتلة المركب) × 100. الكربون: (18.0 ÷ 50.0) × 100 = 36.0%. الهيدروجين: (3.0 ÷ 50.0) × 100 = 6.0%. الأكسجين: (29.0 ÷ 50.0) × 100 = 58.0%. المجموع = 36.0 + 6.0 + 58.0 = 100%، فالحل صحيح.', '["قانون النسبة المئوية بالكتلة","الكربون 36.0%","الهيدروجين 6.0%","الأكسجين 58.0%","المجموع 100%"]'::jsonb, '["النسبة المئوية بالكتلة = (كتلة العنصر ÷ كتلة المركب) × 100","الكربون: (18.0 g ÷ 50.0 g) × 100 = 36.0%","الهيدروجين: (3.0 g ÷ 50.0 g) × 100 = 6.0%","الأكسجين: (29.0 g ÷ 50.0 g) × 100 = 58.0%","المجموع: 36.0% + 6.0% + 58.0% = 100%"]'::jsonb, '[{"element":"كتابة القانون وتعويض صحيح","marks":1},{"element":"نسبة الكربون","marks":1},{"element":"نسبة الهيدروجين","marks":1},{"element":"نسبة الأكسجين","marks":1},{"element":"التحقق من أن المجموع 100%","marks":1}]'::jsonb, '[{"level":"5 درجات","description":"تعويض صحيح وثلاث نسب صحيحة والتحقق من المجموع"},{"level":"3–4 درجات","description":"نسبتان أو ثلاث صحيحة مع نقص في القانون أو في التحقق"},{"level":"1–2 درجة","description":"نسبة واحدة صحيحة أو تعويض صحيح فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["نسيان ضرب الناتج في 100","قسمة كتلة العنصر على كتلة عنصر آخر بدل كتلة المركب","عدم التحقق من أن المجموع 100%"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (29%)"}],"at":"2026-10-18T03:32:48.257Z"}'::jsonb),
('essay', 2, null::int, null, null, 'كتلة العنصر = النسبة المئوية × كتلة العينة. الكربون: 0.4220 × 400.0 g = 168.8 g. الهيدروجين: 0.0650 × 400.0 g = 26.0 g. الأكسجين: 0.5130 × 400.0 g = 205.2 g. المجموع = 168.8 + 26.0 + 205.2 = 400.0 g، وهو يساوي كتلة العينة.', '["تحويل النسبة المئوية إلى كسر","كتلة الكربون 168.8 g","كتلة الهيدروجين 26.0 g","كتلة الأكسجين 205.2 g","المجموع 400.0 g"]'::jsonb, '["كتلة العنصر = (النسبة المئوية ÷ 100) × كتلة العينة","الكربون: 0.4220 × 400.0 g = 168.8 g","الهيدروجين: 0.0650 × 400.0 g = 26.0 g","الأكسجين: 0.5130 × 400.0 g = 205.2 g","المجموع: 168.8 g + 26.0 g + 205.2 g = 400.0 g"]'::jsonb, '[{"element":"تحويل النسبة المئوية إلى كسر واستعمال القانون","marks":1},{"element":"كتلة الكربون","marks":1},{"element":"كتلة الهيدروجين","marks":1},{"element":"كتلة الأكسجين","marks":1},{"element":"التحقق من أن المجموع 400.0 g","marks":1}]'::jsonb, '[{"level":"5 درجات","description":"استعمال صحيح للقانون وثلاث كتل صحيحة والتحقق من المجموع"},{"level":"3–4 درجات","description":"كتلتان أو ثلاث صحيحة مع نقص في القانون أو في التحقق"},{"level":"1–2 درجة","description":"كتلة واحدة صحيحة أو استعمال القانون فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["ضرب كتلة العينة في النسبة المئوية دون تحويلها إلى كسر","قسمة كتلة العينة على النسبة بدل ضربها","عدم التحقق من المجموع"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (29%)"}],"at":"2026-10-18T03:32:48.258Z"}'::jsonb),
('essay', 3, null::int, null, null, 'النسبة المئوية للنحاس في العينة 1 = (12.84 ÷ 20.0) × 100 = 64.2%. وفي العينة 2 = (32.1 ÷ 50.0) × 100 = 64.2%. وفي العينة 3 = (14.18 ÷ 30.0) × 100 = 47.3%. العينتان 1 و2 لهما النسبة المئوية نفسها، فهما من المركب نفسه؛ إذ يتكون المركب دائمًا من العناصر نفسها بنسب كتلية ثابتة مهما اختلفت كتلتا العينتين. أما العينة 3 فنسبتها مختلفة (47.3%) فهي من مركب مختلف.', '["العينة 1: 64.2%","العينة 2: 64.2%","العينة 3: 47.3%","العينتان 1 و2 من المركب نفسه","العينة 3 من مركب مختلف مع التعليل بالنسب الكتلية الثابتة"]'::jsonb, '["العينة 1: (12.84 g ÷ 20.0 g) × 100 = 64.2%","العينة 2: (32.1 g ÷ 50.0 g) × 100 = 64.2%","العينة 3: (14.18 g ÷ 30.0 g) × 100 = 47.3%","تساوي النسبتين في العينتين 1 و2 يدل على أنهما من المركب نفسه","اختلاف نسبة العينة 3 يدل على أنها من مركب مختلف"]'::jsonb, '[{"element":"نسبة النحاس في العينة 1","marks":1},{"element":"نسبة النحاس في العينة 2","marks":1},{"element":"نسبة النحاس في العينة 3","marks":1},{"element":"تحديد العينتين من المركب نفسه","marks":1},{"element":"تحديد العينة المختلفة مع التعليل بالنسب الكتلية الثابتة","marks":1}]'::jsonb, '[{"level":"5 درجات","description":"ثلاث نسب صحيحة وتحديد صحيح للعينات مع التعليل"},{"level":"3–4 درجات","description":"نسب صحيحة مع نقص في التحديد أو التعليل"},{"level":"1–2 درجة","description":"نسبة أو نسبتان صحيحتان فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["المقارنة بين كتل النحاس مباشرة (12.84 و32.1 و14.18) دون حساب النسب","القول إن العينة الأكبر كتلة هي المركب المختلف","عدم تعليل الحكم بثبات النسب الكتلية"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (23%)"}],"at":"2026-10-18T03:32:48.258Z"}'::jsonb)
