('mcq', 1, 'ما نص قانون النسب الثابتة؟', null, '["تختلف النسب الكتلية للعناصر في المركب الواحد باختلاف مصدره","يتكون المركب دائمًا من العناصر نفسها بنسب كتلية ثابتة مهما اختلفت كمياته","كتلة المركب أكبر من مجموع كتل العناصر المكونة له","النسبة بين كتل عنصر يتحد مع كتلة ثابتة من عنصر آخر في مركبين نسبة عددية بسيطة"]'::jsonb, 'تذكر', 'تذكر نص القانون', 'سهل', 'الكتاب ص 61 — قانون النسب الثابتة'),
('mcq', 2, 'يبيّن الجدول نتائج تحليل عينتين من السكروز، إحداهما من سكر المائدة والأخرى من سكر القصب. أيّ الاستنتاجات الآتية ينسجم مع قانون النسب الثابتة؟', '{"headers":["العينة","كتلة العينة","كربون %","هيدروجين %","أكسجين %"],"rows":[["سكر المائدة","20.00 g","42.20","6.50","51.30"],["سكر القصب","500.0 g","42.20","6.50","51.30"]]}'::jsonb, '["النسب المئوية متساوية لأن كتلتي العينتين متساويتان","النسبة المئوية للكربون في العينة الأكبر كتلة أكبر منها في العينة الأصغر","السكروز المستخلص من القصب مركب مختلف عن سكر المائدة","للسكروز النسب الكتلية نفسها مهما اختلف مصدره أو كتلة العينة"]'::jsonb, 'فهم', 'تفسير بيانات وفق القانون', 'متوسط', 'الكتاب ص 62 — الجدول 2-4 تحليل السكروز'),
('mcq', 3, 'نتج من تحليل 36.0 g من الماء 4.0 g من الهيدروجين و32.0 g من الأكسجين. وفق قانون النسب الثابتة، ما كتلة الأكسجين الناتجة من تحليل 90.0 g من الماء النقي؟', null, '["80.0 g","10.0 g","45.0 g","58.0 g"]'::jsonb, 'تطبيق', 'تطبيق النسبة الثابتة حسابيًّا', 'متوسط', 'الكتاب ص 61 — قانون النسب الثابتة'),
('mcq', 4, 'حُلِّلت عينة من مركب كتلتها 15.0 g فنتج 6.0 g من العنصر X والباقي من العنصر Y. ما كتلة العنصر Y في العينة؟', null, '["6.0 g","21.0 g","9.0 g","2.5 g"]'::jsonb, 'فهم', 'كتلة المركب تساوي مجموع كتل عناصره', 'سهل', 'الكتاب ص 61 — قانون النسب الثابتة'),
('mcq', 5, 'حُلِّلت ثلاث عينات من الماء النقي مأخوذة من مصادر مختلفة وكتلها مختلفة. ماذا نتوقع لنسبة كتلة الهيدروجين إلى كتلة الأكسجين في العينات الثلاث؟', null, '["تختلف النسبة لأن مصدر كل عينة مختلف","تزداد نسبة الهيدروجين في العينة الأكبر كتلة","تتغير النسبة بحسب الطريقة المستعملة في التحليل","تتساوى النسبة في العينات الثلاث لأن الماء مركب واحد"]'::jsonb, 'فهم', 'تفسير انطباق القانون على مركب', 'سهل', 'الكتاب ص 61 — قانون النسب الثابتة'),
('mcq', 6, 'تحتوي عينة من السكروز على 6.50% هيدروجين بالكتلة. ما كتلة الهيدروجين في 300.0 g من السكروز مهما كان مصدره؟', null, '["6.50 g","19.5 g","195 g","1.95 g"]'::jsonb, 'تطبيق', 'حساب كتلة عنصر من النسبة المئوية', 'متوسط', 'الكتاب ص 61، 62 — النسبة المئوية بالكتلة، الجدول 2-4'),
('mcq', 7, 'يتحد 1.0 g من الهيدروجين مع 8.0 g من الأكسجين تمامًا لتكوين 9.0 g من الماء. إذا تفاعل 1.0 g هيدروجين مع 10.0 g أكسجين تفاعلًا كاملًا، فما كتلة الماء الناتجة؟', null, '["9.0 g","11.0 g","10.0 g","8.0 g"]'::jsonb, 'تطبيق', 'تطبيق ثبات النسب على كميات غير متناسبة', 'صعب', 'الكتاب ص 61 — قانون النسب الثابتة'),
('essay', 1, 'اكتب نص قانون النسب الثابتة، ثم فسّر كيف ينطبق على السكروز علمًا بأن تحليل 20.00 g من سكر المائدة أعطى 8.44 g كربون و1.30 g هيدروجين و10.26 g أكسجين، وتحليل 500.0 g من سكر القصب أعطى 211.0 g كربون و32.50 g هيدروجين و256.5 g أكسجين.', null, null, 'فهم', 'نص القانون وتفسير انطباقه بحساب', 'متوسط', 'الكتاب ص 61، 62 — قانون النسب الثابتة، الجدول 2-4'),
('essay', 2, 'نتج من تحليل 18.0 g من الماء النقي 2.0 g هيدروجين و16.0 g أكسجين. استعمل قانون النسب الثابتة لحساب كتلة كل من الهيدروجين والأكسجين الناتجتين من تحليل 90.0 g من الماء النقي، وبيّن كيف تتحقق من صحة نتيجتك.', null, null, 'تطبيق', 'حساب بتطبيق قانون النسب الثابتة', 'صعب', 'الكتاب ص 61 — قانون النسب الثابتة'),
('essay', 3, 'قال طالب إن نسبة الكربون في سكروز مستخلص من قصب السكر أكبر منها في سكروز آخر من مصدر مختلف لأن لكل مصدر ظروفًا مختلفة. قيّم صحة هذا الادعاء مستندًا إلى قانون النسب الثابتة، ثم بيّن ما الذي يدل عليه اختلاف النسب الكتلية بين عينتين.', null, null, 'تقويم', 'تقويم ادعاء بالاستناد إلى القانون', 'صعب', 'الكتاب ص 62 — الجدول 2-4 وتحليل السكروز')
) as v(type, number, stem, stimulus, options, tl, qk, diff, src)
