from (values
('mcq', 1, 1, 'ينص قانون النسب الثابتة على أن المركب يتكون دائمًا من العناصر نفسها بنسب كتلية ثابتة مهما اختلفت كمياته.', '["عكس القانون؛ فنسب العناصر في المركب الواحد لا تتغير بتغير مصدره.","","كتلة المركب تساوي مجموع كتل عناصره تمامًا، فلا تزيد عنه ولا تنقص.","هذا نص قانون النسب المتضاعفة وليس قانون النسب الثابتة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (19%)"}],"at":"2026-10-18T03:32:48.259Z"}'::jsonb),
('mcq', 2, 3, 'العينتان مختلفتا الكتلة والمصدر، ومع ذلك تتساوى نسبها المئوية بالكتلة (42.20% كربون و6.50% هيدروجين و51.30% أكسجين)؛ وهذا ما ينص عليه قانون النسب الثابتة.', '["كتلتا العينتين مختلفتان (20.00 g و500.0 g)، والنسب متساوية رغم ذلك.","النسبة المئوية للكربون واحدة في العينتين (42.20%) ولا تتأثر بكتلة العينة.","لو كانا مركبين مختلفين لاختلفت نسبهما الكتلية؛ والنسب هنا متطابقة فهو المركب نفسه.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (19%)"}],"at":"2026-10-18T03:32:48.259Z"}'::jsonb),
('mcq', 3, 0, 'كتلة الأكسجين إلى كتلة الماء ثابتة: 32.0 ÷ 36.0، فكتلة الأكسجين في 90.0 g ماء = 90.0 × 32.0 ÷ 36.0 = 80.0 g.', '["","هذه كتلة الهيدروجين الناتجة (90.0 × 4.0 ÷ 36.0) وليست كتلة الأكسجين.","نصف كتلة الماء؛ وهذا افتراض خاطئ بأن العنصرين متساويان في الكتلة.","ناتج طرح 32.0 من 90.0 g؛ وهو خلط بين الكتلة الأصلية للأكسجين والنسبة الثابتة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (34%)"}],"at":"2026-10-18T03:32:48.260Z"}'::jsonb),
('mcq', 4, 2, 'كتلة المركب تساوي مجموع كتل العناصر المكونة له؛ فكتلة Y = 15.0 − 6.0 = 9.0 g.', '["افتراض خاطئ أن العنصرين متساويان في الكتلة.","جمع الكتلتين بدل طرح كتلة X من كتلة المركب.","","قسمة كتلة المركب على كتلة X (15.0 ÷ 6.0) وهو ليس كتلة Y."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (10%)"}],"at":"2026-10-18T03:32:48.261Z"}'::jsonb),
('mcq', 5, 3, 'الماء مركب واحد، وللمركب الواحد نسب كتلية ثابتة مهما كان مصدره أو كتلة العينة؛ لذا تتساوى النسبة في العينات الثلاث.', '["المصدر لا يغيّر النسب الكتلية للمركب الواحد.","تتساوى النسب المئوية مهما اختلفت كتل العينات.","النسب صفة للمركب نفسه ولا تتوقف على طريقة التحليل.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (19%)"}],"at":"2026-10-18T03:32:48.261Z"}'::jsonb),
('mcq', 6, 1, 'النسبة المئوية بالكتلة ثابتة للسكروز، فكتلة الهيدروجين = 300.0 × 6.50 ÷ 100 = 19.5 g.', '["أخذ النسبة المئوية على أنها كتلة بالجرام دون ضربها في كتلة العينة.","","ضرب الكتلة في 0.65 بدل 0.0650 (خطأ في موضع الفاصلة).","ضرب الكتلة في 0.00650 (خطأ في تحويل النسبة المئوية إلى كسر)."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (12%)"}],"at":"2026-10-18T03:32:48.261Z"}'::jsonb),
('mcq', 7, 0, 'يتحد الهيدروجين والأكسجين بنسبة كتلية ثابتة 1.0 : 8.0، فيستهلك 1.0 g هيدروجين 8.0 g أكسجين فقط وتبقى 2.0 g أكسجين دون تفاعل؛ وكتلة الماء الناتجة 9.0 g.', '["","جمع الكتلتين الابتدائيتين كلها، مع أن 2.0 g من الأكسجين لا تتفاعل.","هذه كتلة الأكسجين المتاح وليست كتلة الماء الناتج.","هذه كتلة الأكسجين المتفاعل فقط وليست كتلة الماء الناتج."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (19%)"}],"at":"2026-10-18T03:32:48.262Z"}'::jsonb),
('essay', 1, null::int, null, null, 'ينص قانون النسب الثابتة على أن المركب يتكون دائمًا من العناصر نفسها بنسب كتلية ثابتة مهما اختلفت كمياته، وأن كتلة المركب تساوي مجموع كتل عناصره. في سكر المائدة: C% = 8.44 ÷ 20.00 × 100 = 42.20%، وH% = 1.30 ÷ 20.00 × 100 = 6.50%، وO% = 10.26 ÷ 20.00 × 100 = 51.30%. وفي سكر القصب: C% = 211.0 ÷ 500.0 × 100 = 42.20%، وH% = 32.50 ÷ 500.0 × 100 = 6.50%، وO% = 256.5 ÷ 500.0 × 100 = 51.30%. النسب متطابقة رغم اختلاف المصدر والكتلة، وهذا ما يقتضيه القانون. كما أن مجموع كتل العناصر (8.44 + 1.30 + 10.26 = 20.00 g) يساوي كتلة العينة.', '["نص القانون: عناصر المركب نفسها بنسب كتلية ثابتة مهما اختلفت الكميات","كتلة المركب تساوي مجموع كتل عناصره","حساب النسب المئوية للعينة الأولى: 42.20% و6.50% و51.30%","حساب النسب المئوية للعينة الثانية وتطابقها مع الأولى","الاستنتاج: النسب ثابتة رغم اختلاف المصدر والكتلة"]'::jsonb, '["النسبة المئوية بالكتلة = (كتلة العنصر ÷ كتلة المركب) × 100","سكر المائدة: 8.44 ÷ 20.00 × 100 = 42.20% C؛ 1.30 ÷ 20.00 × 100 = 6.50% H؛ 10.26 ÷ 20.00 × 100 = 51.30% O","سكر القصب: 211.0 ÷ 500.0 × 100 = 42.20% C؛ 32.50 ÷ 500.0 × 100 = 6.50% H؛ 256.5 ÷ 500.0 × 100 = 51.30% O","مقارنة النتائج: النسب متساوية في العينتين"]'::jsonb, '[{"element":"نص القانون صحيحًا","marks":1},{"element":"حساب النسب المئوية للعينتين حسابًا صحيحًا","marks":2},{"element":"ملاحظة تطابق النسب رغم اختلاف المصدر والكتلة","marks":1},{"element":"ذكر أن مجموع كتل العناصر يساوي كتلة العينة","marks":1}]'::jsonb, '[{"level":"5 درجات","description":"نص صحيح للقانون، وحساب صحيح للنسب في العينتين، وتفسير تطابقها، وذكر مجموع الكتل"},{"level":"3–4 درجات","description":"نص صحيح مع حساب صحيح للنسب وإغفال التفسير أو مجموع الكتل"},{"level":"1–2 درجة","description":"نص القانون فقط أو حساب جزئي للنسب"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["القسمة على كتلة عنصر آخر بدل كتلة المركب","نسيان الضرب في 100","القول إن النسب مختلفة لأن كتلتي العينتين مختلفتان"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (19%)"}],"at":"2026-10-18T03:32:48.262Z"}'::jsonb),
('essay', 2, null::int, null, null, 'نسبة كتلة الهيدروجين إلى كتلة الماء ثابتة: 2.0 ÷ 18.0. كتلة الهيدروجين في 90.0 g ماء = 90.0 × 2.0 ÷ 18.0 = 10.0 g. كتلة الأكسجين = 90.0 × 16.0 ÷ 18.0 = 80.0 g. للتحقق: كتلة المركب تساوي مجموع كتل عناصره، 10.0 + 80.0 = 90.0 g، وهي كتلة العينة.', '["النسب الكتلية في الماء ثابتة مهما اختلفت كتلة العينة","كتلة الهيدروجين 10.0 g","كتلة الأكسجين 80.0 g","التحقق: مجموع كتلتي العنصرين يساوي كتلة الماء 90.0 g"]'::jsonb, '["كتلة H في 90.0 g ماء = 90.0 × (2.0 ÷ 18.0) = 10.0 g","كتلة O في 90.0 g ماء = 90.0 × (16.0 ÷ 18.0) = 80.0 g","التحقق: 10.0 g + 80.0 g = 90.0 g"]'::jsonb, '[{"element":"توظيف ثبات النسبة الكتلية في الحل","marks":1},{"element":"كتلة الهيدروجين 10.0 g","marks":1},{"element":"كتلة الأكسجين 80.0 g","marks":1},{"element":"التحقق بجمع الكتل","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"حل كامل بنسبة ثابتة وكتلتان صحيحتان مع تحقق بجمع الكتل"},{"level":"2–3 درجات","description":"كتلة واحدة صحيحة أو حلان صحيحان دون تحقق"},{"level":"1 درجة","description":"ذكر ثبات النسبة دون حساب صحيح"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["ضرب كتلة العينة في كتلة العنصر دون قسمتها على 18.0","اعتبار الكتلتين متساويتين (45.0 g لكل منهما)","عدم التحقق بأن المجموع يساوي كتلة الماء"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (34%)"}],"at":"2026-10-18T03:32:48.262Z"}'::jsonb),
('essay', 3, null::int, null, null, 'الادعاء غير صحيح؛ فوفق قانون النسب الثابتة يتكون المركب دائمًا من العناصر نفسها بنسب كتلية ثابتة مهما اختلفت كمياته أو مصدره. فالسكروز يحتوي دائمًا على 42.20% كربون و6.50% هيدروجين و51.30% أكسجين، من أي مصدر كان. أما إذا اختلفت النسب الكتلية بين عينتين فهذا يدل على أنهما مركبان مختلفان لا عينتان من المركب نفسه.', '["الحكم بأن الادعاء غير صحيح","نص القانون: النسب الكتلية ثابتة مهما اختلف المصدر أو الكمية","نسب السكروز: 42.20% كربون و6.50% هيدروجين و51.30% أكسجين","اختلاف النسب يدل على مركبين مختلفين"]'::jsonb, '[]'::jsonb, '[{"element":"الحكم على الادعاء بأنه غير صحيح","marks":1},{"element":"التعليل بقانون النسب الثابتة","marks":1},{"element":"ذكر نسب السكروز الثابتة","marks":1},{"element":"دلالة اختلاف النسب على مركبين مختلفين","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"حكم صحيح مع تعليل بالقانون وذكر النسب ودلالة الاختلاف"},{"level":"2–3 درجات","description":"حكم صحيح مع تعليل ناقص أو دون دلالة الاختلاف"},{"level":"1 درجة","description":"حكم صحيح دون تعليل"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["تأييد الادعاء بحجة اختلاف الظروف","الخلط بين اختلاف الكتلة واختلاف النسبة","عدّ العينتين المختلفتين في النسبة من المركب نفسه"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (9%)"}],"at":"2026-10-18T03:32:48.263Z"}'::jsonb)
