('mcq', 1, 2, 'الرمز N للنيتروجين ولا رقم سفلي بعده فهو ذرة واحدة، والرمز H يتبعه الرقم السفلي 3 فهو ثلاث ذرات هيدروجين.', '["الرقم السفلي 3 يخص الهيدروجين الذي يسبقه مباشرة وليس النيتروجين.","إهمال الرقم السفلي 3؛ فهو يدل على ثلاث ذرات هيدروجين.","","الرمز N ليس له رقم سفلي، فهو ذرة نيتروجين واحدة فقط."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (17%)"}],"at":"2026-10-18T03:32:48.264Z"}'::jsonb),
('mcq', 2, 0, 'الرقم السفلي 5 بعد H يدل على خمس ذرات، ويوجد H آخر واحد في المجموعة OH، فالمجموع 5 + 1 = 6 ذرات.', '["","عدّ الهيدروجين في H₅ فقط وإغفال الهيدروجين الموجود في OH.","عدّ الهيدروجين في OH فقط وإغفال H₅.","جمع كل الأرقام السفلية والرموز دون تمييز ذرات الهيدروجين."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (20%)"}],"at":"2026-10-18T03:32:48.264Z"}'::jsonb),
('mcq', 3, 3, 'يُكتب الحرف الأول من رمز العنصر كبيرًا والثاني صغيرًا؛ فـ Co رمز عنصر واحد هو الكوبالت، أما CO فحرفان كبيران هما رمزا عنصرين C وO، فهو صيغة مركب من الكربون والأكسجين.', '["حرف O الثاني في CO كبير فهو رمز عنصر آخر وليس جزءًا من رمز الكوبالت.","عكس الصحيح؛ فـ Co رمز عنصر واحد (حرف ثانٍ صغير) وCO مركب.","الحرف الثاني الصغير في Co يدل على أنه رمز عنصر واحد وليس عنصرين.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (4%)"}],"at":"2026-10-18T03:32:48.264Z"}'::jsonb),
('mcq', 4, 1, 'الرقم السفلي 2 بعد Fe يعني ذرتي حديد، والرقم 3 بعد O يعني ثلاث ذرات أكسجين؛ فالمجموع 2 + 3 = 5 ذرات.', '["عدّ الذرات على أساس ذرة واحدة من الحديد وذرتين من الأكسجين؛ وكل رقم سفلي يدل على عدد ذرات عنصره.","","هذا عدد ذرات الحديد فقط وليس المجموع الكلي.","ضرب الرقمين السفليين (2 × 3) بدل جمعهما."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (8%)"}],"at":"2026-10-18T03:32:48.264Z"}'::jsonb),
('mcq', 5, 0, 'يُكتب عدد ذرات كل عنصر رقمًا سفليًّا بعد رمزه: H₂ لذرتي الهيدروجين وO₂ لذرتي الأكسجين، فتكون الصيغة H₂O₂.', '["","هذه صيغة الماء وفيها ذرة أكسجين واحدة فقط.","الرقم السفلي 2 وُضع بعد الأكسجين وحُذف رقم الهيدروجين؛ فيدل على ذرة هيدروجين واحدة.","تضاعف عدد ذرات الهيدروجين إلى أربع، والمطلوب ذرتان."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (20%)"}],"at":"2026-10-18T03:32:48.264Z"}'::jsonb),
('mcq', 6, 2, 'C₂H₅OH فيه ثلاثة رموز مختلفة هي C وH وO، فهو مكوّن من ثلاثة عناصر. أما NaCl وNH₃ وH₂O فكل منها من عنصرين فقط.', '["يتكون من عنصرين فقط هما Na وCl.","يتكون من عنصرين هما N وH، وعدد ذراته أربع وليس عدد عناصره.","","يتكون من عنصرين هما H وO؛ وعدد ذراته ثلاث لكن عناصره اثنان."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (7%)"}],"at":"2026-10-18T03:32:48.264Z"}'::jsonb),
('mcq', 7, 3, 'كل جزيء ماء يحتاج ذرتي هيدروجين وذرة أكسجين؛ فتكفي 100 ذرة هيدروجين لتكوين 50 جزيئًا، وتستهلك 50 ذرة أكسجين، فتبقى 50 ذرة أكسجين.', '["كل جزيء يحتاج ذرتي هيدروجين، فلا تكفي 100 ذرة لـ 100 جزيء.","الهيدروجين هو الذي ينفد أولًا، فلا يتبقى منه شيء.","كل جزيء يستهلك ذرتي هيدروجين، وعدد الجزيئات لا يمكن أن يبلغ 100.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (13%)"}],"at":"2026-10-18T03:32:48.265Z"}'::jsonb),
('essay', 1, null::int, null, null, 'NaCl: مركب من الصوديوم Na والكلور Cl، ذرة واحدة من كل منهما. NH₃: مركب من النيتروجين N والهيدروجين H، ذرة نيتروجين واحدة وثلاث ذرات هيدروجين. C₂H₅OH: مركب من الكربون C والهيدروجين H والأكسجين O، ذرتا كربون وست ذرات هيدروجين (خمس في H₅ وواحدة في OH) وذرة أكسجين واحدة. Br₂: عنصر هو البروم، ذرتان منه في الجزيء ولا يتكون من عنصرين مختلفين.', '["NaCl: صوديوم وكلور، ذرة من كل منهما، مركب","NH₃: نيتروجين وهيدروجين، 1 و3، مركب","C₂H₅OH: كربون وهيدروجين وأكسجين، 2 و6 و1، مركب","Br₂: عنصر البروم، ذرتان، عنصر وليس مركبًا"]'::jsonb, '[]'::jsonb, '[{"element":"NaCl: العناصر وعدد الذرات والتصنيف","marks":1},{"element":"NH₃: العناصر وعدد الذرات والتصنيف","marks":1},{"element":"C₂H₅OH: العناصر وعدد الذرات (بما فيها 6 ذرات هيدروجين) والتصنيف","marks":2},{"element":"Br₂: العنصر وعدد الذرات والتصنيف","marks":1}]'::jsonb, '[{"level":"5 درجات","description":"الصيغ الأربع صحيحة في العناصر وأعداد الذرات والتصنيف"},{"level":"3–4 درجات","description":"ثلاث صيغ صحيحة، أو الصيغ الأربع مع خطأ في عدّ الهيدروجين في C₂H₅OH"},{"level":"1–2 درجة","description":"صيغة واحدة أو صيغتان صحيحتان"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["عدّ 5 ذرات هيدروجين في C₂H₅OH وإغفال هيدروجين OH","عدّ Br₂ مركبًا من عنصرين","إهمال الرقم السفلي وعدّ كل رمز ذرة واحدة"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (17%)"}],"at":"2026-10-18T03:32:48.265Z"}'::jsonb),
('essay', 2, null::int, null, null, 'في الصيغة H₂O₂ يدل الرقم السفلي 2 بعد H على ذرتي هيدروجين، والرقم 2 بعد O على ذرتي أكسجين، فالجزيء الواحد فيه 4 ذرات. في 30 جزيئًا: ذرات الهيدروجين = 30 × 2 = 60 ذرة، وذرات الأكسجين = 30 × 2 = 60 ذرة، والعدد الكلي = 60 + 60 = 120 ذرة.', '["قراءة الرقم السفلي: ذرتا هيدروجين وذرتا أكسجين في الجزيء","ذرات الهيدروجين 60","ذرات الأكسجين 60","العدد الكلي 120 ذرة"]'::jsonb, '["عدد ذرات H في الجزيء = 2، وعدد ذرات O في الجزيء = 2","ذرات H في 30 جزيئًا = 30 × 2 = 60","ذرات O في 30 جزيئًا = 30 × 2 = 60","العدد الكلي = 60 + 60 = 120 ذرة"]'::jsonb, '[{"element":"قراءة الرقمين السفليين قراءة صحيحة","marks":1},{"element":"عدد ذرات الهيدروجين 60","marks":1},{"element":"عدد ذرات الأكسجين 60","marks":1},{"element":"العدد الكلي 120","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"قراءة صحيحة للصيغة وحساب صحيح للأعداد الثلاثة"},{"level":"2–3 درجات","description":"حساب صحيح لعددين مع خطأ في الثالث أو في الشرح"},{"level":"1 درجة","description":"قراءة صحيحة للصيغة فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["عدّ ذرة واحدة من كل عنصر في الجزيء (30 + 30)","الاكتفاء بعدد الجزيئات 30 دون ضربها في عدد الذرات","إغفال العدد الكلي أو جمع 30 + 2 + 2"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (8%)"}],"at":"2026-10-18T03:32:48.265Z"}'::jsonb),
('essay', 3, null::int, null, null, 'يُكتب الحرف الأول من رمز العنصر كبيرًا وباقي الأحرف صغيرة. (a) الصحيح NaCl: كتب الطالب الحرفين A وL كبيرين، والصحيح أن يكون الحرف الثاني من كل رمز صغيرًا: Na رمز الصوديوم وCl رمز الكلور، وفي الصيغة ذرة صوديوم وذرة كلور. (b) الصحيح H₂O: كُتب رمز الهيدروجين بحرف صغير h والصحيح أن يكون الحرف الأول كبيرًا H، وتتكون الصيغة من ذرتي هيدروجين وذرة أكسجين. (c) الصحيح CO: رمز الكربون C ورمز الأكسجين O، كل منهما حرف واحد كبير، وفي الصيغة ذرة كربون وذرة أكسجين.', '["الحرف الأول كبير وباقي الأحرف صغيرة","NaCl: صوديوم وكلور، ذرة من كل منهما","H₂O: ذرتا هيدروجين وذرة أكسجين","CO: ذرة كربون وذرة أكسجين"]'::jsonb, '[]'::jsonb, '[{"element":"تحديد الخطأ في كل صيغة بقاعدة كتابة الرموز","marks":1},{"element":"NaCl الصحيحة مع العناصر وأعداد الذرات","marks":1},{"element":"H₂O الصحيحة مع العناصر وأعداد الذرات","marks":1},{"element":"CO الصحيحة مع العناصر وأعداد الذرات","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"تصحيح الصيغ الثلاث مع تعليل الخطأ وذكر العناصر وأعداد الذرات"},{"level":"2–3 درجات","description":"تصحيح صيغتين أو ثلاث صيغ دون ذكر أعداد الذرات"},{"level":"1 درجة","description":"تصحيح صيغة واحدة"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["كتابة رموز العناصر بأحرف كبيرة كلها","الخلط بين CO وCo","إهمال الرقم السفلي في H₂O"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (14%)"}],"at":"2026-10-18T03:32:48.266Z"}'::jsonb)
) as v(type, number, ci, ex, dn, ma, ae, ss, mk, rb, ce, ac)
