from (values
('mcq', 1, 'حُلِّلت عينتان من مادتين تتكون كل منهما من العنصرين X وY. العينة الأولى كتلتها 12.0 g وتحتوي على 3.0 g من X و9.0 g من Y، والعينة الثانية كتلتها 20.0 g وتحتوي على 5.0 g من X و15.0 g من Y. أيّ الحكمين الآتيين صحيح؟', null, '["مركبان مختلفان لأن كتلتي العينتين مختلفتان","مركبان مختلفان لأن كتلة X في العينتين مختلفة","لا يمكن الحكم دون معرفة اسمي العنصرين","المركب نفسه لأن النسبة المئوية بالكتلة لـ X هي 25.0% في العينتين"]'::jsonb, 'تطبيق', 'مقارنة عينتين بالنسبة المئوية', 'سهل', 'الكتاب ص 62 — مسائل تدريبية 22، 23'),
('mcq', 2, 'يبيّن الجدول كتلتي الكربون والأكسجين في عينتين مأخوذتين من مادتين. ما الحكم الصحيح على العينتين؟', '{"headers":["العينة","كتلة الكربون","كتلة الأكسجين"],"rows":[["الأولى","12.0 g","16.0 g"],["الثانية","6.0 g","16.0 g"]]}'::jsonb, '["من المركب نفسه لأن كتلة الأكسجين متساوية (16.0 g) في العينتين","من مركبين مختلفين لأن النسبة المئوية للكربون 42.86% في الأولى و27.27% في الثانية","من المركب نفسه لأن العنصرين نفسيهما موجودان في العينتين","من مركبين مختلفين لأن كتلة العينة الأولى (28.0 g) أكبر من كتلة الثانية (22.0 g)"]'::jsonb, 'تحليل', 'تحليل بيانات عينتين', 'سهل', 'الكتاب ص 62 — السؤال 22'),
('mcq', 3, 'عينة I من مركب كتلتها 50.0 g تحتوي على 35.0 g حديد و15.0 g أكسجين، وعينة II كتلتها 40.0 g تحتوي على 28.0 g حديد و12.0 g أكسجين. ما النسبة المئوية بالكتلة للحديد في العينة II، وهل العينتان من المركب نفسه؟', null, '["70.0%؛ لا، العينتان من مركبين مختلفين","30.0%؛ نعم، العينتان من المركب نفسه","70.0%؛ نعم، العينتان من المركب نفسه","28.0%؛ لا، العينتان من مركبين مختلفين"]'::jsonb, 'تحليل', 'حساب النسبة المئوية والحكم', 'سهل', 'الكتاب ص 64 — السؤال 28'),
('mcq', 4, 'أيّ الأزواج الآتية يمثل عينتين من المركب نفسه المكوّن من العنصرين X وY؟', null, '["عينة فيها 4.0 g من X مع 10.0 g من Y، وعينة فيها 6.0 g من X مع 15.0 g من Y","عينة فيها 5.0 g من X مع 10.0 g من Y، وعينة فيها 5.0 g من X مع 15.0 g من Y","عينة فيها 2.0 g من X مع 6.0 g من Y، وعينة فيها 3.0 g من X مع 6.0 g من Y","عينة فيها 3.0 g من X مع 9.0 g من Y، وعينة فيها 6.0 g من X مع 9.0 g من Y"]'::jsonb, 'تحليل', 'اختيار العينتين المتماثلتين', 'متوسط', 'الكتاب ص 62 — قانون النسب الثابتة'),
('mcq', 5, 'حُلِّلت أربع عينات من مركبات تحتوي على العنصرين X وY، وسُجلت كتلة كل عنصر في كل عينة في الجدول. أيّ العينات مأخوذة من مركب مختلف عن بقية العينات؟', '{"headers":["العينة","كتلة X","كتلة Y"],"rows":[["I","8.0 g","2.0 g"],["II","24.0 g","6.0 g"],["III","20.0 g","4.0 g"],["IV","28.0 g","7.0 g"]]}'::jsonb, '["العينة I","العينة II","العينة III","العينة IV"]'::jsonb, 'تحليل', 'تحليل بيانات أربع عينات', 'صعب', 'الكتاب ص 72 — السؤال 85'),
('mcq', 6, 'عينة كتلتها 9.00 g من مركب تحتوي على 7.20 g من الفلز M والباقي أكسجين، وعينة أخرى كتلتها 40.0 g تحتوي على 32.0 g من الفلز M والباقي أكسجين. ما الحكم الصحيح؟', null, '["مركبان مختلفان لأن كتلتي العينتين مختلفتان","المركب نفسه لأن النسبة المئوية لـ M هي 80.0% في العينتين","مركبان مختلفان لأن كتلتي M في العينتين مختلفتان","المركب نفسه لأن كتلة الأكسجين متساوية في العينتين"]'::jsonb, 'تحليل', 'مقارنة عينتين بحساب الكتلة المتبقية', 'متوسط', 'الكتاب ص 72 — السؤال 88'),
('mcq', 7, 'حُلِّلت عينتان تحتويان على الكلور والفلور: العينة I كتلتها 20.0 g وفيها 13.0 g كلور و7.0 g فلور، والعينة II كتلتها 15.0 g وفيها 5.8 g كلور و9.2 g فلور. ما النسبة المئوية بالكتلة للكلور في العينة II، وهل العينتان من المركب نفسه؟', null, '["38.7%؛ المركب نفسه","61.3%؛ مركبان مختلفان","65.0%؛ المركب نفسه","38.7%؛ مركبان مختلفان"]'::jsonb, 'تحليل', 'حساب النسبة المئوية واستنتاج', 'صعب', 'الكتاب ص 73 — الاختبار المقنن، السؤالان 1 و2'),
('essay', 1, 'حُلِّلت عينتان من مادتين تتكونان من الكبريت والأكسجين. العينة الأولى كتلتها 20.0 g وتحتوي على 10.0 g كبريت، والعينة الثانية كتلتها 30.0 g وتحتوي على 12.0 g كبريت. احسب النسبة المئوية بالكتلة للكبريت وللأكسجين في كل عينة، ثم حدد هل العينتان من المركب نفسه، وفسّر إجابتك.', null, null, 'تحليل', 'حساب النسب والحكم على العينتين', 'متوسط', 'الكتاب ص 62 — السؤال 22'),
('essay', 2, 'حُلِّلت ثلاث عينات من مركبات تحتوي على العنصرين X وY، فكانت النتائج: العينة I فيها 8.0 g من X و2.0 g من Y، والعينة II فيها 24.0 g من X و6.0 g من Y، والعينة III فيها 15.0 g من X و5.0 g من Y. احسب النسبة المئوية بالكتلة لـ X في كل عينة، وحدد أي العينتين من المركب نفسه وأيها من مركب مختلف، ثم بيّن ما سيتوقعه الطالب لنسبة كتلة X إلى كتلة Y في عينة رابعة من المركب نفسه الذي أُخذت منه العينتان المتشابهتان.', null, null, 'تحليل', 'تحليل بيانات عينات مع توقع', 'صعب', 'الكتاب ص 72 — السؤال 85'),
('essay', 3, 'عينة A تتكون من 6.0 g كربون و8.0 g أكسجين، وعينة B تتكون من 6.0 g كربون و1.0 g هيدروجين و7.0 g أكسجين. قال طالب: «العينتان من المركب نفسه لأن النسبة المئوية للكربون فيهما متساوية». قيّم هذا الاستنتاج بالحساب، ثم بيّن الشرط الذي يلزم تحققه للحكم بأن عينتين من المركب نفسه.', null, null, 'تقويم', 'تقويم استنتاج بالحساب', 'صعب', 'الكتاب ص 62 — السؤال 23')
) as v(type, number, stem, stimulus, options, tl, qk, diff, src)
