from (values
('mcq', 1, 3, 'النسبة المئوية لـ X في العينة الأولى 3.0 ÷ 12.0 × 100 = 25.0%، وفي الثانية 5.0 ÷ 20.0 × 100 = 25.0%. تتساوى النسب المئوية فالعينتان من المركب نفسه.', '["اختلاف كتلتي العينتين لا يدل على اختلاف المركب؛ فالعينات المختلفة الكتلة قد تكون من المركب نفسه.","كتلة X تختلف بحسب حجم العينة؛ والمعيار هو النسبة المئوية بالكتلة وهي متساوية.","يكفي حساب النسب المئوية بالكتلة للحكم، دون الحاجة إلى معرفة العنصرين.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (29%)"}],"at":"2026-10-18T03:32:48.267Z"}'::jsonb),
('mcq', 2, 1, 'النسبة المئوية للكربون في الأولى 12.0 ÷ 28.0 × 100 = 42.86%، وفي الثانية 6.0 ÷ 22.0 × 100 = 27.27%. اختلاف النسب المئوية يعني أن العينتين من مركبين مختلفين.', '["تساوي كتلة الأكسجين لا يدل على تساوي النسب؛ فالنسبة تُحسب إلى كتلة العينة كلها.","","وجود العنصرين نفسيهما لا يكفي؛ إذ قد يكوّن العنصران نفسهما مركبين مختلفين بنسب مختلفة.","النتيجة صحيحة (مركبان مختلفان) لكن التعليل خاطئ؛ فاختلاف كتلتي العينتين لا يثبت اختلاف المركب."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (8%)"}],"at":"2026-10-18T03:32:48.267Z"}'::jsonb),
('mcq', 3, 2, 'النسبة المئوية للحديد في العينة II = 28.0 ÷ 40.0 × 100 = 70.0%، وفي العينة I = 35.0 ÷ 50.0 × 100 = 70.0%. تتساوى النسبتان فالعينتان من المركب نفسه.', '["النسبة صحيحة (70.0%) لكن الاستنتاج خاطئ؛ فالنسبتان متساويتان في العينتين.","30.0% هي النسبة المئوية للأكسجين وليست للحديد.","","28.0 هي كتلة الحديد بالجرام وليست نسبة مئوية؛ ولم تُقسم على كتلة العينة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (26%)"}],"at":"2026-10-18T03:32:48.268Z"}'::jsonb),
('mcq', 4, 0, 'في الزوج الأول: 4.0 ÷ 14.0 × 100 = 28.57% من X، و6.0 ÷ 21.0 × 100 = 28.57% من X؛ فالنسبتان متساويتان والعينتان من المركب نفسه.', '["","النسبة المئوية لـ X: 33.3% في الأولى و25.0% في الثانية؛ تساوي كتلة X وحدها لا يكفي.","النسبة المئوية لـ X: 25.0% في الأولى و33.3% في الثانية؛ تساوي كتلة Y وحدها لا يكفي.","النسبة المئوية لـ X: 25.0% في الأولى و40.0% في الثانية؛ فالنسبتان مختلفتان."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (8%)"}],"at":"2026-10-18T03:32:48.268Z"}'::jsonb),
('mcq', 5, 2, 'نسبة كتلة X إلى كتلة Y: I تساوي 4.0، وII تساوي 4.0، وIV تساوي 4.0، أما III فتساوي 5.0. أي أن النسبة المئوية لـ X في III هي 83.3% بينما هي 80.0% في البقية؛ فالعينة III من مركب مختلف.', '["نسبة X إلى Y فيها 4.0 وتساوي نسبة العينتين II وIV؛ فهي من المركب نفسه.","نسبة X إلى Y فيها 4.0 وتساوي نسبة العينتين I وIV؛ فهي من المركب نفسه.","","نسبة X إلى Y فيها 4.0 (28.0 ÷ 7.0)، وتساوي نسبة I وII؛ فهي من المركب نفسه."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (21%)"}],"at":"2026-10-18T03:32:48.268Z"}'::jsonb),
('mcq', 6, 1, 'النسبة المئوية لـ M في العينة الأولى 7.20 ÷ 9.00 × 100 = 80.0%، وفي الثانية 32.0 ÷ 40.0 × 100 = 80.0%؛ فالعينتان من المركب نفسه.', '["اختلاف كتلة العينة لا يدل على اختلاف المركب؛ فالمقارنة تكون بالنسبة المئوية.","","كتلة M تختلف باختلاف كتلة العينة؛ والنسبة المئوية هي التي تُقارن وهي متساوية.","كتلتا الأكسجين غير متساويتين (1.80 g و8.0 g)؛ والمعيار هو النسبة المئوية لا الكتلة المطلقة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (23%)"}],"at":"2026-10-18T03:32:48.269Z"}'::jsonb),
('mcq', 7, 3, 'النسبة المئوية للكلور في العينة II = 5.8 ÷ 15.0 × 100 = 38.7%، وفي العينة I = 13.0 ÷ 20.0 × 100 = 65.0%. النسبتان مختلفتان فالعينتان من مركبين مختلفين.', '["النسبة صحيحة (38.7%) لكنها تختلف عن 65.0% في العينة I، فلا يصح القول إنهما المركب نفسه.","61.3% هي النسبة المئوية للفلور في العينة II وليست للكلور.","65.0% هي نسبة الكلور في العينة I وليست في II؛ ولو كانتا متساويتين لكانتا المركب نفسه.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (26%)"}],"at":"2026-10-18T03:32:48.269Z"}'::jsonb),
('essay', 1, null::int, null, null, 'العينة الأولى: كتلة الأكسجين = 20.0 − 10.0 = 10.0 g؛ S% = 10.0 ÷ 20.0 × 100 = 50.0% وO% = 50.0%. العينة الثانية: كتلة الأكسجين = 30.0 − 12.0 = 18.0 g؛ S% = 12.0 ÷ 30.0 × 100 = 40.0% وO% = 60.0%. النسبتان المئويتان مختلفتان (50.0% و40.0% للكبريت)، وبحسب قانون النسب الثابتة فإن عينات المركب الواحد لها نسب كتلية متساوية؛ لذا فالعينتان من مركبين مختلفين.', '["كتلة الأكسجين في العينتين 10.0 g و18.0 g","النسب في العينة الأولى: 50.0% كبريت و50.0% أكسجين","النسب في العينة الثانية: 40.0% كبريت و60.0% أكسجين","النسب مختلفة فالعينتان من مركبين مختلفين","التعليل بقانون النسب الثابتة"]'::jsonb, '["كتلة O في العينة الأولى = 20.0 − 10.0 = 10.0 g؛ وفي الثانية = 30.0 − 12.0 = 18.0 g","S% في الأولى = 10.0 ÷ 20.0 × 100 = 50.0%؛ O% = 50.0%","S% في الثانية = 12.0 ÷ 30.0 × 100 = 40.0%؛ O% = 60.0%","مقارنة النسب: 50.0% ≠ 40.0%"]'::jsonb, '[{"element":"حساب كتلة الأكسجين في العينتين","marks":1},{"element":"النسب المئوية في العينة الأولى","marks":1},{"element":"النسب المئوية في العينة الثانية","marks":1},{"element":"الحكم بأنهما مركبان مختلفان مع التعليل بالقانون","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"حساب صحيح لكل النسب وحكم صحيح معلل بقانون النسب الثابتة"},{"level":"2–3 درجات","description":"حساب صحيح للنسب مع حكم دون تعليل، أو حل جزئي"},{"level":"1 درجة","description":"حساب جزئي دون حكم صحيح"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["اعتبار كتلة الكبريت المعطاة نسبة مئوية","المقارنة بين كتلتي الكبريت (10.0 g و12.0 g) بدل المقارنة بالنسب المئوية","نسيان حساب كتلة الأكسجين بالطرح"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (29%)"}],"at":"2026-10-18T03:32:48.270Z"}'::jsonb),
('essay', 2, null::int, null, null, 'X% في I = 8.0 ÷ 10.0 × 100 = 80.0%، وفي II = 24.0 ÷ 30.0 × 100 = 80.0%، وفي III = 15.0 ÷ 20.0 × 100 = 75.0%. العينتان I وII من المركب نفسه لتساوي النسبتين، والعينة III من مركب مختلف لأن نسبتها 75.0% مختلفة. وفي أي عينة رابعة من المركب نفسه الذي أُخذت منه I وII تبقى نسبة كتلة X إلى كتلة Y ثابتة وتساوي 4.0 (أي 80.0% من X و20.0% من Y) مهما كانت كتلة العينة، وفق قانون النسب الثابتة.', '["X% في العينات الثلاث: 80.0% و80.0% و75.0%","العينتان I وII من المركب نفسه","العينة III من مركب مختلف","النسبة X:Y = 4.0 (80.0% و20.0%) في أي عينة أخرى من المركب نفسه","التعليل بثبات النسب الكتلية"]'::jsonb, '["X% في I = 8.0 ÷ (8.0 + 2.0) × 100 = 80.0%","X% في II = 24.0 ÷ (24.0 + 6.0) × 100 = 80.0%","X% في III = 15.0 ÷ (15.0 + 5.0) × 100 = 75.0%","النسبة X إلى Y في I وII = 8.0 ÷ 2.0 = 24.0 ÷ 6.0 = 4.0"]'::jsonb, '[{"element":"النسب المئوية الثلاث","marks":2},{"element":"تحديد العينتين المتماثلتين والعينة المختلفة","marks":1},{"element":"توقع النسبة 4.0 في عينة رابعة","marks":1},{"element":"التعليل بثبات النسب الكتلية","marks":1}]'::jsonb, '[{"level":"5 درجات","description":"نسب صحيحة، وتحديد صحيح، وتوقع صحيح للنسبة، وتعليل بالقانون"},{"level":"3–4 درجات","description":"نسب وتحديد صحيحان مع نقص في التوقع أو التعليل"},{"level":"1–2 درجة","description":"حساب جزئي للنسب أو تحديد دون حساب"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["القسمة على كتلة Y بدل كتلة العينة كلها عند حساب النسبة المئوية","الحكم باختلاف I وII لأن كتلتيهما مختلفتان","اعتبار العينة III من المركب نفسه لقرب نسبتها"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (21%)"}],"at":"2026-10-18T03:32:48.271Z"}'::jsonb),
('essay', 3, null::int, null, null, 'كتلة العينة A = 6.0 + 8.0 = 14.0 g، وكتلة العينة B = 6.0 + 1.0 + 7.0 = 14.0 g. C% في A = 6.0 ÷ 14.0 × 100 = 42.86%، وفي B = 42.86% أيضًا. لكن O% في A = 8.0 ÷ 14.0 × 100 = 57.14%، وفي B = 7.0 ÷ 14.0 × 100 = 50.0%، كما أن B فيها هيدروجين 7.14% وليس في A هيدروجين. إذن العينتان من مركبين مختلفين، واستنتاج الطالب غير صحيح. الشرط: يجب أن تتساوى النسب المئوية بالكتلة لجميع العناصر في العينتين، وأن يكونا من العناصر نفسها، لا لعنصر واحد فقط.', '["حساب كتلة كل عينة (14.0 g)","النسبة المئوية للكربون متساوية: 42.86%","نسبة الأكسجين مختلفة: 57.14% و50.0%، ووجود الهيدروجين في B فقط","الحكم بأن العينتين من مركبين مختلفين","الشرط: تساوي النسب المئوية لجميع العناصر"]'::jsonb, '["كتلة A = 6.0 + 8.0 = 14.0 g؛ كتلة B = 6.0 + 1.0 + 7.0 = 14.0 g","C% في A = 6.0 ÷ 14.0 × 100 = 42.86%؛ وفي B = 6.0 ÷ 14.0 × 100 = 42.86%","O% في A = 8.0 ÷ 14.0 × 100 = 57.14%؛ وفي B = 7.0 ÷ 14.0 × 100 = 50.0%","H% في B = 1.0 ÷ 14.0 × 100 = 7.14%، ولا هيدروجين في A"]'::jsonb, '[{"element":"حساب نسبة الكربون في العينتين","marks":1},{"element":"حساب نسبة الأكسجين والتنبه لوجود الهيدروجين في B","marks":1},{"element":"الحكم بأن العينتين مختلفتان","marks":1},{"element":"بيان أن الحكم يتطلب تساوي نسب جميع العناصر","marks":1},{"element":"التعليل بقانون النسب الثابتة","marks":1}]'::jsonb, '[{"level":"5 درجات","description":"حساب صحيح، وحكم صحيح بخطأ الاستنتاج، وبيان الشرط وتعليل بالقانون"},{"level":"3–4 درجات","description":"حساب صحيح وحكم صحيح مع نقص في بيان الشرط أو التعليل"},{"level":"1–2 درجة","description":"حساب جزئي أو حكم دون حساب"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["تأييد الطالب لتساوي نسبة الكربون فقط","إهمال وجود الهيدروجين في العينة B","المقارنة بين كتلتي الكربون (6.0 g) دون النسبة المئوية"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (17%)"}],"at":"2026-10-18T03:32:48.271Z"}'::jsonb)
