from (values
('mcq', 1, 'المركبان A وB يتكونان من العنصرين X وY. يتحد 3.0 g من X مع 4.0 g من Y في المركب A، ويتحد 3.0 g من X مع 8.0 g من Y في المركب B. ما نسبة كتلة Y في B إلى كتلة Y في A عند كتلة ثابتة من X؟', null, '["2:1","1:2","3:4","8:3"]'::jsonb, 'تطبيق', 'تطبيق قانون النسب المتضاعفة مع كتلة ثابتة', 'سهل', 'الكتاب ص 63 — قانون النسب المتضاعفة'),
('mcq', 2, 'يبيّن الجدول النسبتين المئويتين بالكتلة في مركبين للنحاس والكلور. ما كتلة النحاس المتحدة مع 1 g من الكلور في المركب I؟', '{"headers":["المركب","نحاس %","كلور %"],"rows":[["I","64.20","35.80"],["II","47.27","52.73"]]}'::jsonb, '["0.8964 g","0.5577 g","1.793 g","64.20 g"]'::jsonb, 'تطبيق', 'حساب كتلة عنصر لكل 1 g من عنصر آخر', 'متوسط', 'الكتاب ص 63 — مركبات النحاس والكلور، الجدول 5-2'),
('mcq', 3, 'في المركب I يتحد 32.0 g من الكبريت مع 32.0 g من الأكسجين، وفي المركب II يتحد 32.0 g من الكبريت مع 48.0 g من الأكسجين. ما نسبة كتلتي الأكسجين (المركب I إلى المركب II) المتحدتين مع كتلة ثابتة من الكبريت؟', null, '["3:2","2:3","1:1","2:5"]'::jsonb, 'تطبيق', 'نسبة كتلتي الأكسجين مع كبريت ثابت', 'سهل', 'الكتاب ص 63 — قانون النسب المتضاعفة'),
('mcq', 4, 'عينة من المركب I تحتوي على 2.80 g نيتروجين و1.60 g أكسجين، وعينة من المركب II تحتوي على 4.20 g نيتروجين و4.80 g أكسجين. ما نسبة كتلتي الأكسجين المتحدتين مع 1 g نيتروجين (المركب II إلى المركب I)؟', null, '["3:1","3:2","1:2","2:1"]'::jsonb, 'تطبيق', 'تطبيق القانون بتثبيت كتلة النيتروجين', 'صعب', 'الكتاب ص 71 — السؤال 71'),
('mcq', 5, 'يتحد 12.0 g من الكربون مع 16.0 g من الأكسجين في المركب I، ومع 32.0 g من الأكسجين في المركب II. ما كتلة الأكسجين التي تتحد مع 6.0 g من الكربون في المركب II؟', null, '["32.0 g","16.0 g","8.0 g","64.0 g"]'::jsonb, 'تطبيق', 'حساب كتلة بتناسب النسب', 'سهل', 'الكتاب ص 71 — السؤال 71'),
('mcq', 6, 'في المركب I يتحد 3.10 g من الفوسفور مع 10.63 g من الكلور، وفي المركب II يتحد 3.10 g من الفوسفور مع 17.72 g من الكلور. أيّ العبارات الآتية صحيحة؟', null, '["نسبة كتلتي الكلور مع كتلة ثابتة من الفوسفور تقارب 5:3، وهي نسبة عددية بسيطة فينطبق القانون","نسبة كتلتي الكلور 1.67:1 ليست عددًا صحيحًا فلا ينطبق قانون النسب المتضاعفة","لا ينطبق قانون النسب المتضاعفة لأن المركبين مكوّنان من العنصرين نفسيهما","لا ينطبق قانون النسب المتضاعفة لأن كتلتي الكلور في المركبين مختلفتان"]'::jsonb, 'تحليل', 'التحقق من انطباق القانون', 'متوسط', 'الكتاب ص 63 — قانون النسب المتضاعفة'),
('mcq', 7, 'في المركب I تتحد 7.00 g من الحديد مع 2.00 g من الأكسجين، وفي المركب II تتحد 14.0 g من الحديد مع 6.00 g من الأكسجين. ما نسبة كتلة الحديد المتحدة مع 1 g من الأكسجين في المركب I إلى نسبتها في المركب II؟', null, '["1:2","1:3","3:2","2:3"]'::jsonb, 'تطبيق', 'تثبيت كتلة الأكسجين وحساب النسبة', 'صعب', 'الكتاب ص 63 — قانون النسب المتضاعفة'),
('essay', 1, 'المركب I يحتوي على 75.0% كربون و25.0% هيدروجين بالكتلة، والمركب II يحتوي على 80.0% كربون و20.0% هيدروجين بالكتلة. احسب كتلة الكربون المتحدة مع 1 g من الهيدروجين في كل مركب، ثم احسب نسبتهما (I إلى II)، وبيّن هل تنطبق عليهما قاعدة النسب المتضاعفة.', null, null, 'تطبيق', 'حساب النسبة المتضاعفة من نسب مئوية', 'متوسط', 'الكتاب ص 63 — قانون النسب المتضاعفة'),
('essay', 2, 'تحتوي عينة كتلتها 36.0 g من الماء H₂O على 4.0 g هيدروجين والباقي أكسجين، وعينة كتلتها 34.0 g من فوق أكسيد الهيدروجين H₂O₂ على 2.0 g هيدروجين والباقي أكسجين. احسب كتلة الأكسجين المتحدة مع 1 g هيدروجين في كل مركب، ثم نسبتهما (H₂O₂ إلى H₂O)، وفسّر دلالة النتيجة.', null, null, 'تطبيق', 'تطبيق قانون النسب المتضاعفة على الماء وفوق الأكسيد', 'صعب', 'الكتاب ص 63 — الماء وفوق أكسيد الهيدروجين'),
('essay', 3, 'في المركب I يتحد 28.0 g نيتروجين مع 16.0 g أكسجين، وفي المركب II يتحد 14.0 g نيتروجين مع 16.0 g أكسجين. (أ) احسب نسبة كتلتي النيتروجين المتحدتين مع 16.0 g أكسجين (I إلى II). (ب) في مركب ثالث يتحد 14.0 g نيتروجين مع 32.0 g أكسجين؛ احسب كتلة النيتروجين المتحدة مع 16.0 g أكسجين فيه، ثم نسبتها إلى كتلة النيتروجين المتحدة في المركب I، وبيّن هل تتفق النتيجتان مع قانون النسب المتضاعفة.', null, null, 'تطبيق', 'حساب وتوقع نسب متضاعفة', 'صعب', 'الكتاب ص 63 — قانون النسب المتضاعفة، ص 71 — السؤال 74')
