('mcq', 4, 3, 'كتلة الأكسجين لكل 1 g نيتروجين: في I = 1.60 ÷ 2.80 = 0.571 g، وفي II = 4.80 ÷ 4.20 = 1.14 g. النسبة II إلى I = 1.14 ÷ 0.571 = 2:1.', '["هذه نسبة كتلتي الأكسجين الخام (4.80 ÷ 1.60) دون جعل كتلة النيتروجين ثابتة.","هذه نسبة كتلتي النيتروجين الخام (4.20 ÷ 2.80) وليست نسبة الأكسجين.","هذه النسبة معكوسة (I إلى II).",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (29%)"}],"at":"2026-10-18T03:32:48.274Z"}'::jsonb),
('mcq', 5, 1, 'في المركب II تتحد 32.0 g أكسجين مع 12.0 g كربون، فمع 6.0 g (نصف الكمية) تتحد نصف كتلة الأكسجين: 32.0 × 6.0 ÷ 12.0 = 16.0 g.', '["هذه كتلة الأكسجين مع 12.0 g كربون وليس مع 6.0 g.","","هذه كتلة الأكسجين مع 6.0 g كربون في المركب I وليس II.","ضُربت الكتلة في 2 بدل قسمتها؛ فالكربون أقل من 12.0 g."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (35%)"}],"at":"2026-10-18T03:32:48.275Z"}'::jsonb),
('mcq', 6, 0, 'كتلة الفوسفور ثابتة (3.10 g)، ونسبة كتلتي الكلور II إلى I = 17.72 ÷ 10.63 = 1.667 أي 5:3، وهي نسبة عددية بسيطة وصحيحة؛ فينطبق القانون.', '["","النسبة العددية البسيطة قد تُكتب بأعداد صحيحة 5:3، فالقيمة 1.67 تكافئها ولا تنفي القانون.","القانون ينطبق تحديدًا حين يتكون مركبان مختلفان من العنصرين نفسيهما.","اختلاف كتلتي الكلور هو الذي يُقارَن بنسبة بسيطة؛ ولا ينفي القانون."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (22%)"}],"at":"2026-10-18T03:32:48.275Z"}'::jsonb),
('mcq', 7, 2, 'كتلة الحديد لكل 1 g أكسجين: في I = 7.00 ÷ 2.00 = 3.50 g، وفي II = 14.0 ÷ 6.00 = 2.33 g. النسبة I إلى II = 3.50 ÷ 2.33 = 1.5 أي 3:2.', '["هذه نسبة كتلتي الحديد الخام (7.00 ÷ 14.0) دون تثبيت كتلة الأكسجين.","هذه نسبة كتلتي الأكسجين الخام (2.00 ÷ 6.00) وليست نسبة الحديد.","","هذه النسبة معكوسة (II إلى I)."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (35%)"}],"at":"2026-10-18T03:32:48.276Z"}'::jsonb),
('essay', 1, null::int, null, null, 'في المركب I: كتلة الكربون لكل 1 g هيدروجين = 75.0 ÷ 25.0 = 3.00 g. في المركب II: = 80.0 ÷ 20.0 = 4.00 g. النسبة I إلى II = 3.00 ÷ 4.00 = 0.750 أي 3:4. هذه نسبة عددية بسيطة وصحيحة بين كتلتي الكربون المتحدتين مع كتلة ثابتة (1 g) من الهيدروجين؛ فينطبق قانون النسب المتضاعفة.', '["كتلة C لكل 1 g H في I تساوي 3.00 g","كتلة C لكل 1 g H في II تساوي 4.00 g","النسبة I إلى II تساوي 3:4","النسبة عددية بسيطة وصحيحة فينطبق القانون"]'::jsonb, '["I: 75.0 g C ÷ 25.0 g H = 3.00 g C لكل 1 g H","II: 80.0 g C ÷ 20.0 g H = 4.00 g C لكل 1 g H","النسبة I : II = 3.00 : 4.00 = 3:4"]'::jsonb, '[{"element":"كتلة الكربون لكل 1 g هيدروجين في I","marks":1},{"element":"كتلة الكربون لكل 1 g هيدروجين في II","marks":1},{"element":"النسبة 3:4","marks":1},{"element":"الحكم بانطباق القانون مع التعليل","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"حساب صحيح للكتلتين والنسبة والحكم بالتعليل"},{"level":"2–3 درجات","description":"حساب صحيح لكتلة واحدة أو للكتلتين دون النسبة أو دون التعليل"},{"level":"1 درجة","description":"محاولة صحيحة الاتجاه دون نتيجة"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["قسمة النسبة المئوية للهيدروجين على الكربون (قلب النسبة)","مقارنة 75.0 و80.0 مباشرة دون تثبيت كتلة الهيدروجين","عدم التعبير عن النسبة بأعداد صحيحة بسيطة"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (26%)"}],"at":"2026-10-18T03:32:48.276Z"}'::jsonb),
('essay', 2, null::int, null, null, 'كتلة الأكسجين في عينة الماء = 36.0 − 4.0 = 32.0 g، فلكل 1 g هيدروجين: 32.0 ÷ 4.0 = 8.0 g أكسجين. كتلة الأكسجين في عينة فوق أكسيد الهيدروجين = 34.0 − 2.0 = 32.0 g، فلكل 1 g هيدروجين: 32.0 ÷ 2.0 = 16.0 g أكسجين. نسبة كتلتي الأكسجين (H₂O₂ إلى H₂O) = 16.0 ÷ 8.0 = 2:1. وهي نسبة عددية بسيطة وصحيحة؛ وهذا يوافق قانون النسب المتضاعفة، إذ يتكون المركبان من العنصرين نفسيهما بنسب كتلية مختلفة، وفي H₂O₂ ضعف كمية الأكسجين المتحدة مع كتلة ثابتة من الهيدروجين.', '["كتلة الأكسجين في العينتين 32.0 g","8.0 g أكسجين لكل 1 g هيدروجين في الماء","16.0 g أكسجين لكل 1 g هيدروجين في H₂O₂","النسبة 2:1","نسبة عددية بسيطة وفق قانون النسب المتضاعفة"]'::jsonb, '["O في الماء = 36.0 − 4.0 = 32.0 g؛ لكل 1 g H: 32.0 ÷ 4.0 = 8.0 g","O في H₂O₂ = 34.0 − 2.0 = 32.0 g؛ لكل 1 g H: 32.0 ÷ 2.0 = 16.0 g","النسبة H₂O₂ : H₂O = 16.0 ÷ 8.0 = 2:1"]'::jsonb, '[{"element":"كتلة الأكسجين في العينتين بالطرح","marks":1},{"element":"كتلة الأكسجين لكل 1 g هيدروجين في المركبين","marks":2},{"element":"النسبة 2:1","marks":1},{"element":"الدلالة وفق قانون النسب المتضاعفة","marks":1}]'::jsonb, '[{"level":"5 درجات","description":"كل الحسابات صحيحة، والنسبة 2:1، وتفسير صحيح بالقانون"},{"level":"3–4 درجات","description":"حسابات صحيحة مع نقص في النسبة أو التفسير"},{"level":"1–2 درجة","description":"حساب كتلة الأكسجين فقط أو حساب جزئي"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["نسيان طرح كتلة الهيدروجين لإيجاد كتلة الأكسجين","مقارنة كتلتي الأكسجين الخام (32.0 g و32.0 g) دون تثبيت كتلة الهيدروجين","قلب النسبة فتصبح 1:2"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (22%)"}],"at":"2026-10-18T03:32:48.277Z"}'::jsonb),
('essay', 3, null::int, null, null, '(أ) كتلة الأكسجين ثابتة (16.0 g)، فنسبة كتلتي النيتروجين I إلى II = 28.0 ÷ 14.0 = 2:1. (ب) في المركب الثالث تتحد 14.0 g نيتروجين مع 32.0 g أكسجين، فمع 16.0 g أكسجين (نصف الكمية) تتحد 14.0 × 16.0 ÷ 32.0 = 7.0 g نيتروجين. نسبة كتلة النيتروجين في I إلى الثالث = 28.0 ÷ 7.0 = 4:1. النسبتان 2:1 و4:1 عددان صحيحان بسيطان، فتتفقان مع قانون النسب المتضاعفة.', '["النسبة (أ) = 2:1","كتلة N مع 16.0 g أكسجين في المركب الثالث = 7.0 g","النسبة (ب) = 4:1","النسبتان عددان صحيحان بسيطان فيتفقان مع القانون"]'::jsonb, '["(أ) 28.0 g ÷ 14.0 g = 2، فالنسبة 2:1","(ب) كتلة N مع 16.0 g O في المركب الثالث = 14.0 × (16.0 ÷ 32.0) = 7.0 g","28.0 g ÷ 7.0 g = 4، فالنسبة 4:1"]'::jsonb, '[{"element":"النسبة 2:1 في الفرع (أ)","marks":1},{"element":"كتلة النيتروجين 7.0 g في المركب الثالث","marks":1},{"element":"النسبة 4:1","marks":1},{"element":"الحكم بالاتفاق مع القانون وتعليله","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"نسبتان صحيحتان وكتلة صحيحة وحكم معلل"},{"level":"2–3 درجات","description":"نسبة واحدة صحيحة أو كتلة صحيحة مع حكم ناقص"},{"level":"1 درجة","description":"خطوة واحدة صحيحة فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["قسمة 14.0 g على 32.0 g دون تثبيت كتلة الأكسجين عند 16.0 g","قلب النسبة فتصبح 1:2 أو 1:4","عدم الربط بين نتيجة النسبة وقانون النسب المتضاعفة"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (29%)"}],"at":"2026-10-18T03:32:48.277Z"}'::jsonb)
) as v(type, number, ci, ex, dn, ma, ae, ss, mk, rb, ce, ac)
